def manifest_capability_summary():
    """Short machine-readable capability summary for prompts/diagnostics."""
    return ", ".join(
        f"{name}:{'chat' if meta.get('natural_chat') else 'command'}:{meta.get('risk','unknown')}"
        for name, meta in MANIFEST_CAPABILITIES.items()
    )

def manifest_action_risk(action_name):
    """Return the declared risk class for an action/capability."""
    key=(action_name or "").strip().lower()
    aliases={
        "ban":"moderation","kick":"moderation","timeout":"moderation","warn":"moderation",
        "mute":"moderation","unban":"moderation",
        "role":"roles","create_role":"roles","delete_role":"roles","manage_role":"roles",
        "channel":"channels","create_channel":"channels","delete_channel":"channels",
        "lock":"channels","unlock":"channels",
        "remind":"reminders","reminder":"reminders",
        "birthday":"birthdays",
    }
    key=aliases.get(key,key)
    return MANIFEST_CAPABILITIES.get(key,{}).get("risk","unknown")

def manifest_action_receipt(action, *, success, target=None, detail=None):
    """Create a concise truthful receipt for deterministic actions."""
    mark="✅" if success else "❌"
    bits=[f"{mark} {action}"]
    if target:
        bits.append(f"Target: {target}")
    if detail:
        bits.append(str(detail))
    return " • ".join(bits)

