def manifest_global_role(user_or_id):
    try: uid=int(getattr(user_or_id,"id",user_or_id))
    except Exception: return "member"
    if uid==MAKER_USER_ID: return "creator_owner"
    if uid==CO_OWNER_ID: return "co_owner"
    if uid in DEV_USER_IDS: return "developer"
    return "member"

def manifest_has_global_capability(user_or_id, capability:str)->bool:
    role=manifest_global_role(user_or_id); cap=str(capability or "").strip().lower()
    if role=="creator_owner": return True
    if role=="co_owner": return cap in CO_OWNER_CAPABILITIES
    if role=="developer": return cap in DEVELOPER_CAPABILITIES
    return False

def manifest_authority_rank(user_or_id)->int:
    return {"creator_owner":100,"co_owner":80,"developer":60,"member":0}.get(manifest_global_role(user_or_id),0)
