async def send_manifest_help(message):
    """Professional, dynamic help/discovery response; generated from current commands."""
    groups={}
    for cmd in bot.tree.walk_commands():
        root=cmd.name.split()[0]
        groups.setdefault(root,[]).append(cmd.name)
    preferred=[
        ("🤖 AI & Chat", "Talk normally, ask questions, analyze server context, code, and images."),
        ("🏗️ Server Manager", "Channels, categories, roles, permissions, onboarding, and server setup."),
        ("🛡️ Moderation", "Warnings, timeouts, kicks, bans, purge, locks, slowmode, and logs."),
        ("🔐 Security", "Anti-raid, anti-nuke, lockdown, security scans, and incident logging."),
        ("⚙️ Autopilot", "Monitor the current server, identify needs, and apply safe authorized fixes."),
        ("🎫 Support & Community", "Tickets, events, giveaways, suggestions, reminders, waitlists, and more."),
    ]
    e=discord.Embed(title="⚡ Manifest • AI Server Manager",description=(
        "**Examples**\n"
        "`@Manifest scan this server`\n"
        "`@Manifest create a support channel`\n"
        "`@Manifest who has Moderator?`\n"
        "`@Manifest make the safe improvements`\n"
        "`@Manifest list commands`"),color=discord.Color.blurple())
    for title,desc in preferred:
        e.add_field(name=title,value=desc,inline=False)
    actual=sorted(groups)
    if actual:
        shown=', '.join(f"`/{x}`" for x in actual[:30])
        if len(actual)>30: shown += f" + {len(actual)-30} more"
        e.add_field(name="⌨️ Slash commands",value=shown,inline=False)
    e.set_footer(text=f"Manifest V{VERSION} • Commands are shortcuts, not the only way to use me")
    await manifest_reply(message,embed=e,allowed_mentions=discord.AllowedMentions.none())

