class Manifest(commands.Bot):
    async def close(self):
        # Stop Discord task loops first so they cannot enqueue new work during
        # shutdown, then cancel supervised one-shot tasks and close shared I/O.
        for loop in (reminder_loop,giveaway_loop,autopilot_loop,diagnostics_loop,quarantine_reconciliation_loop,silly_dev_scout_loop):
            try:
                if loop.is_running(): loop.cancel()
            except Exception: log.exception('Could not stop loop %s',getattr(loop,'coro',loop))
        try: await cancel_manifest_background_tasks()
        except Exception: log.exception('Could not cancel Manifest background tasks')
        try: await close_manifest_http_session()
        except Exception: log.exception('Could not close Manifest HTTP session')
        try: await db.close()
        except Exception: log.exception('Could not close Manifest database cleanly')
        await super().close()

    async def setup_hook(self):
        await db.open()
        try:
            applied_runtime_settings = await creator_control_load_runtime_settings()
            if applied_runtime_settings:
                log.info("Loaded %s Creator-approved runtime model preference(s).", applied_runtime_settings)
        except Exception:
            log.exception("Creator runtime settings could not be loaded; environment defaults remain active.")
        log.info("Manifest self-healing schema migration completed before background tasks.")
        if wavelink and lavalink_configured():
            try:
                node=wavelink.Node(uri=lavalink_uri(),password=LAVALINK_PASSWORD,retries=None,client=self)
                await wavelink.Pool.connect(nodes=[node],client=self,cache_capacity=100)
                global music_ready, music_last_error
                music_ready=True; music_last_error=""
                log.info("Lavalink/Wavelink music backend connected.")
            except Exception as ex:
                music_ready=False; music_last_error=f"{type(ex).__name__}: {str(ex)[:500]}"
                log.exception("Lavalink connection failed; Manifest will stay online.")
        else:
            log.warning("Lavalink/Wavelink music backend is not configured.")
        self.add_view(TicketView())
        self.add_view(TicketControlView())
        self.add_view(VerificationView())
        # Restore message-bound persistent giveaway controls after process restarts.
        # Each giveaway has a unique custom_id, so every active persisted message must
        # be re-registered rather than relying on one generic view.
        try:
            active_giveaways=await db.all("SELECT id,message_id,channel_id,created_at FROM giveaways WHERE status='active' AND ended=0")
            restored=0
            for gr in active_giveaways:
                try:
                    message_id=int(gr['message_id'] or 0)
                    if not message_id:
                        channel=self.get_channel(int(gr['channel_id']))
                        if not channel:
                            try: channel=await self.fetch_channel(int(gr['channel_id']))
                            except Exception: channel=None
                        if channel:
                            found,_,complete=await find_giveaway_message(channel,int(gr['id']),float(gr['created_at'] or time.time()))
                            if found:
                                message_id=int(found.id)
                                await db.execute("UPDATE giveaways SET message_id=? WHERE id=? AND message_id=0",(message_id,int(gr['id'])))
                            elif not complete:
                                await diag_issue('persistent_views',f"Giveaway #{gr['id']} message ID is missing and channel history could not be fully checked",'warning')
                    if message_id:
                        self.add_view(GiveawayEntryView(int(gr['id'])),message_id=message_id)
                        restored+=1
                except Exception as ex:
                    await diag_issue('persistent_views',ex,'warning')
            if restored: log.info("Restored %s active giveaway persistent view(s).",restored)
        except Exception as ex:
            log.exception("Persistent giveaway view restoration failed")
            try: await diag_issue('persistent_views',ex,'error')
            except Exception: pass
        # Restore Manifest-native community UI after restarts. These views use
        # stable custom IDs tied to persisted database rows.
        try:
            role_rows=await db.all("SELECT id,message_id FROM role_panels WHERE enabled=1 AND message_id>0")
            for rr in role_rows:self.add_view(await build_role_panel_view(int(rr['id'])),message_id=int(rr['message_id']))
            event_rows=await db.all("SELECT id,message_id FROM events WHERE status='scheduled' AND message_id>0 AND starts_at>?",(time.time()-86400,))
            for er in event_rows:self.add_view(EventRSVPView(int(er['id'])),message_id=int(er['message_id']))
            if role_rows or event_rows:log.info("Restored %s role panel(s) and %s event RSVP view(s).",len(role_rows),len(event_rows))
        except Exception as ex:
            log.exception("Persistent community view restoration failed")
            try: await diag_issue('persistent_views',ex,'warning')
            except Exception: pass
        for g in (help_group,info_group,mod_group,server_group,logs_group,ticket_group,economy_group,level_group,brain_group,utility_group,autopilot_group,activity_group,reminder_group,autoresponder_group,report_group,bug_group,submit_group,suggestion_group,waitlist_group,boost_group,custom_role_group,games_group,personality_group,owner_group,rules_group,community_group,creator_group,security_group,profile_group,automation_group,staff_group,privacy_group,music_group,manifest_group):
            try:self.tree.add_command(g)
            except app_commands.CommandAlreadyRegistered:pass
        synced=await self.tree.sync()
        reminder_loop.start()
        giveaway_loop.start()
        autopilot_loop.start()
        diagnostics_loop.start()
        quarantine_reconciliation_loop.start()
        silly_dev_scout_loop.change_interval(minutes=SILLY_DEV_INTERVAL_MINUTES)
        silly_dev_scout_loop.start()
        log.info("Synced %s top-level slash groups/commands.",len(synced))

