    @discord.ui.button(label="Close",emoji="✖️",style=discord.ButtonStyle.danger,row=1)
    async def close(self,i,button):
        self.stop()
        await i.response.edit_message(content="Manifest Operations Hub closed.",embed=None,view=None)

