def manifest_ui_embed(title,description="",*,status="info"):
    color={"good":discord.Color.green(),"warn":discord.Color.orange(),"bad":discord.Color.red()}.get(status,discord.Color.blurple())
    e=discord.Embed(title=title,description=description[:4000],color=color,timestamp=discord.utils.utcnow())
    e.set_footer(text=f"Manifest {VERSION} · {BUILD_LABEL}")
    return e

async def manifest_ui_preference(guild_id:int):
    if not guild_id:
        return {"home_mode":"adaptive","compact":0}
    row=await db.one("SELECT home_mode,compact FROM manifest_ui_preferences WHERE guild_id=?",(int(guild_id),))
    if not row:
        return {"home_mode":"adaptive","compact":0}
    return {"home_mode":str(row['home_mode'] or 'adaptive'),"compact":int(row['compact'] or 0)}

async def set_manifest_ui_compact(guild_id:int,compact:bool,actor_id:int):
    await db.execute("INSERT INTO manifest_ui_preferences(guild_id,home_mode,compact,updated_by,updated_at) VALUES(?,'adaptive',?,?,?) ON CONFLICT(guild_id) DO UPDATE SET compact=excluded.compact,updated_by=excluded.updated_by,updated_at=excluded.updated_at",(int(guild_id),int(bool(compact)),int(actor_id),time.time()))

async def manifest_home_embed(user,guild=None):
    identity=("thunderxstorms5_. · Creator & Owner" if user.id==MAKER_USER_ID else
              "alemorci · Co-Owner" if user.id==CO_OWNER_ID else
              "Configured Manifest Developer" if user.id in DEV_USER_IDS else
              (f"{user.display_name} · Server Owner" if guild and user.id==guild.owner_id else user.display_name))
