    e=manifest_ui_embed("Manifest · Home",f"**{identity}**\n{scope}\n\nA single place for what changed, capabilities, health and server operations.")
    role=manifest_global_role(user); rank=manifest_authority_rank(user)
    if role in {"creator_owner","co_owner","developer"}:
        label={"creator_owner":"Creator & Owner","co_owner":"Co-Owner","developer":"Developer"}[role]
        boundary=("Final Manifest authority · Creator-only production/infrastructure controls" if role=="creator_owner" else
                  "Bounded ownership capabilities · no Creator-only infrastructure/global settings" if role=="co_owner" else
                  "Developer capabilities · no ownership authority")
        e.add_field(name="Manifest authority",value=f"**{label}** · priority **{rank}**\n{boundary}",inline=False)
    prefs=await manifest_ui_preference(guild.id if guild else 0)
