    @discord.ui.button(label="All Systems",emoji="🧭",style=discord.ButtonStyle.secondary,row=1)
    async def all_systems(self,i,button):self.system_key=None;await i.response.edit_message(embed=manifest_command_center_embed(viewer_id=i.user.id),view=self)
    @discord.ui.button(label="Access",emoji="🔐",style=discord.ButtonStyle.secondary,row=1)
    async def access(self,i,button):
        if not i.guild:return await i.response.send_message("System access policies are configured inside a server.",ephemeral=True)
        if not server_manager(i.user):return await i.response.send_message("Manage Server or Administrator is required to inspect server-wide policies.",ephemeral=True)
