async def manifest_native_discord_advisor(guild):
    features={str(x).upper() for x in getattr(guild,'features',[]) or []}
    scheduled=len(getattr(guild,'scheduled_events',[]) or [])
    lines=[]
    lines.append("✅ Discord command permissions can be layered with Manifest Access policies under Server Settings → Integrations.")
    lines.append("✅ Discord AutoMod should remain the first-line content filter; Manifest Sentinel/Guardian cover broader server-security and evidence workflows.")
    if 'COMMUNITY' in features:
        lines.append("✅ Community features are enabled; use Discord Onboarding/Rules Screening where they fit instead of recreating native flows.")
        lines.append(f"{'✅' if scheduled else '○'} Native Scheduled Events currently visible to Manifest: **{scheduled}**.")
    else:
        lines.append("○ This server is not exposing Discord Community features; some native onboarding/event capabilities may therefore be unavailable.")
    lines.append("Manifest should complement native Discord controls, not duplicate them just to increase its feature count.")
    return lines

