async def manifest_notification_inbox_embed(user_id:int):
    rows=await db.all("SELECT kind,subject,status,created_at,error FROM manifest_notifications WHERE recipient_id=? ORDER BY created_at DESC LIMIT 12",(int(user_id),))
    lines=[]
    for r in rows:
        when=discord.utils.format_dt(datetime.datetime.fromtimestamp(float(r['created_at']),datetime.timezone.utc),'R')
        icon='✅' if r['status']=='delivered' else '○' if r['status'] in {'disabled','pending'} else '⚠️'
        lines.append(f"{icon} **{str(r['subject'] or r['kind'])[:90]}** · {str(r['status']).title()} · {when}")
    e=manifest_ui_embed("Manifest · Notifications","Your recent Manifest delivery history. Message bodies are not repeated in this overview.")
    e.add_field(name="Recent",value="\n".join(lines)[:3900] or "No Manifest notifications recorded for you.",inline=False)
    return e

class ManifestFeedbackModal(discord.ui.Modal,title="Send Manifest Feedback"):
    subject=discord.ui.TextInput(label="Short title",max_length=120,placeholder="What should Manifest improve?")
    details=discord.ui.TextInput(label="Details",style=discord.TextStyle.paragraph,max_length=1800,placeholder="Tell the team what felt wrong or what would make it better.")
    async def on_submit(self,i):
        now=time.time()
        cur=await db.execute("INSERT INTO submissions(kind,guild_id,user_id,name,description,created_at,updated_at) VALUES(?,?,?,?,?,?,?)",('suggestion',i.guild_id or 0,i.user.id,str(self.subject.value)[:120],str(self.details.value)[:1800],now,now))
        rid=cur.lastrowid
        await db.execute("INSERT INTO submission_events(submission_id,kind,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(rid,'suggestion',i.user.id,'created','home-panel',now))
        try:
            await manifest_notify_owners('feedback',f"Suggestion **#{rid}** from **{i.user}** (`{i.user.id}`)\n**{str(self.subject.value)[:120]}**\n{str(self.details.value)[:1500]}",subject='💡 Manifest Feedback',dedupe_key=f'feedback:{rid}',cooldown=0)
        except Exception:
            log.exception("Manifest Home feedback owner notification failed")
        await i.response.send_message(f"✅ Feedback saved as suggestion `#{rid}` and sent to the Manifest team.",ephemeral=True)

