def _external_manager(i):
    return bool(i.guild and manager(i.user))

@manifest_external_group.command(name="status",description="Show Manifest Intelligence health")
async def manifest_external_status(i:discord.Interaction):
    if not _external_manager(i):
        return await i.response.send_message("⚠️ Manage Server permission is required.",ephemeral=True)
    configured=sum(1 for ready in external_provider_status().values() if ready)
    used_routes=[]
    for h in _external_health.values():
        if h.get("ok") or h.get("fail"): used_routes.append(h)
    ai_states=list(_ai_provider_state.values())
    open_count=sum(1 for st in ai_states if float(st.get("opened_until",0) or 0)>time.time())
    fail_count=sum(int(h.get("fail",0) or 0) for h in used_routes)
    ok_count=sum(int(h.get("ok",0) or 0) for h in used_routes)
    health="Operational" if open_count==0 else "Degraded"
    e=manifest_ui_embed("Manifest · Intelligence",
        "Manifest keeps its underlying routing and infrastructure private. This panel reports product health without exposing vendors, models, endpoints, quotas, or credentials.")
    e.add_field(name="Status",value=f"**{health}**",inline=True)
    e.add_field(name="Available intelligence routes",value=f"**{configured}** configured",inline=True)
    e.add_field(name="Runtime routing",value=f"**{open_count}** temporarily isolated route(s)",inline=True)
    if ok_count or fail_count:
        e.add_field(name="Recent adapter activity",value=f"Successful operations: **{ok_count}** · Failed operations: **{fail_count}**",inline=False)
    e.set_footer(text="Infrastructure details are intentionally private. Creator diagnostics remain separate from server-facing health.")
    await i.response.send_message(embed=e,ephemeral=True)

@manifest_external_group.command(name="search",description="Search current information with Manifest Intelligence")
@app_commands.describe(query="What Manifest should search for")
async def manifest_external_search(i:discord.Interaction,query:str):
    if not _external_manager(i):
        return await i.response.send_message("⚠️ Manage Server permission is required.",ephemeral=True)
    await i.response.defer(ephemeral=True)
    try:
        provider,data=await external_research(query,num_results=5)
        rows=[]
        for r in (data.get("results") or data.get("data") or [])[:5]:
            title=str(r.get("title") or "Untitled")[:180]
            url=str(r.get("url") or "")
            highlights=r.get("highlights") or r.get("description") or r.get("snippet") or ""
            if isinstance(highlights,list): highlights=" ".join(map(str,highlights))
            rows.append(f"**{title}**\n{url}\n{str(highlights)[:450]}")
        text="\n\n".join(rows) if rows else "No results returned."
        await i.followup.send(fit_discord(text,3900),ephemeral=True)
    except Exception as exc:
        log.warning("Manifest Intelligence search failed: %s",exc); await i.followup.send("❌ Manifest Intelligence could not complete that search right now.",ephemeral=True)

