@manifest_external_group.command(name="ocr",description="Extract text from an attached image or PDF")
@app_commands.describe(attachment="Image or PDF to OCR",language="OCR language code, e.g. eng or auto",engine="OCR engine: 2 for general use, 3 for harder handwriting/stylized text")
@app_commands.choices(engine=[app_commands.Choice(name="Engine 2 — balanced",value=2),app_commands.Choice(name="Engine 3 — harder text",value=3)])
async def manifest_external_ocr(i:discord.Interaction,attachment:discord.Attachment,language:str="auto",engine:app_commands.Choice[int]=None):
    if not _external_manager(i):
        return await i.response.send_message("⚠️ Manage Server permission is required.",ephemeral=True)
    await i.response.defer(ephemeral=True)
    try:
        if attachment.size>OCR_MAX_BYTES:
            return await i.followup.send(f"⚠️ Attachment is too large for the configured OCR limit ({OCR_MAX_BYTES//1000} KB).",ephemeral=True)
        raw=await attachment.read()
        data=await ocr_space_image(image_bytes=raw,filename=attachment.filename,language=language,engine=(engine.value if engine else 2))
        parsed=data.get("ParsedResults") or []
        text="\n\n".join(str(x.get("ParsedText") or "") for x in parsed).strip()
        if data.get("IsErroredOnProcessing") and not text:
            raise RuntimeError(str(data.get("ErrorMessage") or data.get("ErrorDetails") or "OCR processing failed"))
        await i.followup.send(fit_discord(f"**Manifest · Extracted text**\n{text or 'No text detected.'}",3900),ephemeral=True)
    except Exception as exc:
        log.warning("Manifest text extraction failed: %s",exc); await i.followup.send("❌ Manifest could not extract text from that file right now.",ephemeral=True)

