# ========================= SILLY DEV / GROK DEVELOPMENT CONTROL PLANE ======
SILLY_DEV_DEFAULT_API_URL="https://sillydev.co.uk/panel/api/client"
SILLY_DEV_MAX_JSON_BYTES=1_000_000
SILLY_DEV_MAX_SOURCE_BYTES=4*1024*1024

def silly_dev_api_base():
    """Accept only the official HTTPS Silly Development panel API origin/path."""
    raw=(SILLY_DEV_API_URL or SILLY_DEV_DEFAULT_API_URL).strip().rstrip("/")
    parsed=urlsplit(raw)
    if (parsed.scheme!="https" or parsed.hostname!="sillydev.co.uk" or
        parsed.username or parsed.password or parsed.port or
        parsed.path.rstrip("/")!="/panel/api/client" or parsed.query or parsed.fragment):
        raise RuntimeError("SillyDev API URL must be the official HTTPS panel API endpoint.")
    return SILLY_DEV_DEFAULT_API_URL

def silly_dev_configured():
    try:
        silly_dev_api_base()
        return bool(SILLY_DEV_API_KEY)
    except Exception:
        return False

async def silly_dev_get(path,*,params=None,raw=False,max_bytes=None):
    """Bounded read-only SillyDev API GET. Never follows redirects or forwards the key."""
    if not silly_dev_configured():
        raise RuntimeError("SillyDev API key is missing or the API endpoint is not trusted.")
    if not isinstance(path,str) or not path.startswith("/") or ".." in path or "\\" in path or path.startswith("//"):
        raise ValueError("Invalid SillyDev API path.")
    base=silly_dev_api_base()
    limit=int(max_bytes or (SILLY_DEV_MAX_SOURCE_BYTES if raw else SILLY_DEV_MAX_JSON_BYTES))
    headers={"Authorization":f"Bearer {SILLY_DEV_API_KEY}","Accept":"text/plain" if raw else "application/json"}
    timeout=aiohttp.ClientTimeout(total=20,connect=7,sock_read=14)
    request_url=base if path=="/" else base+path
    async with aiohttp.ClientSession(timeout=timeout,trust_env=False) as session:
        async with session.get(request_url,params=params,headers=headers,allow_redirects=False) as response:
            if 300<=response.status<400:
                raise RuntimeError("SillyDev returned a redirect; it was refused to protect the API key.")
            payload=await response.content.read(limit+1)
            if len(payload)>limit:
                raise RuntimeError(f"SillyDev response exceeded the safe {limit} byte limit.")
            text=payload.decode(response.charset or "utf-8",errors="replace")
            if response.status>=400:
                detail=_safe_diag_text(text,500)
                raise RuntimeError(f"SillyDev HTTP {response.status}"+(f": {detail}" if detail else ""))
            if raw:
                return text
            try:
                data=json.loads(text or "{}")
            except json.JSONDecodeError as exc:
                raise RuntimeError("SillyDev returned invalid JSON.") from exc
            if not isinstance(data,dict):
                raise RuntimeError("SillyDev returned an unexpected response shape.")
            return data

def silly_dev_validate_server_id(server_id):
    value=str(server_id or "").strip()
    if not re.fullmatch(r"(?:[A-Fa-f0-9]{8}|[A-Fa-f0-9]{8}-[A-Fa-f0-9]{4}-[A-Fa-f0-9]{4}-[A-Fa-f0-9]{4}-[A-Fa-f0-9]{12})",value):
        raise ValueError("Enter the server's 8-character identifier or full UUID from SillyDev.")
    return value

async def silly_dev_list_servers():
    """Read the servers visible to the restricted API key; cap inventory at 500."""
    found=[]
    for page in range(1,6):
        payload=await silly_dev_get("/",params={"page":page,"per_page":100})
        rows=payload.get("data") or []
        if not isinstance(rows,list):
            raise RuntimeError("SillyDev server list did not contain a data array.")
        found.extend(x for x in rows if isinstance(x,dict))
        pagination=((payload.get("meta") or {}).get("pagination") or {})
        total_pages=pagination.get("total_pages") or pagination.get("totalPages")
        if total_pages is not None:
            if page>=int(total_pages):break
        elif len(rows)<100:
            break
    return found[:500]

async def silly_dev_inspect_server(server_id):
    """Read server metadata, resource state and deployed Python files without mutation."""
    sid=silly_dev_validate_server_id(server_id)
    server_payload=await silly_dev_get(f"/servers/{sid}")
    resource_payload=await silly_dev_get(f"/servers/{sid}/resources")
    server=(server_payload.get("attributes") or {})
    resources=(resource_payload.get("attributes") or {})
    source=await silly_dev_get(f"/servers/{sid}/files/contents",params={"file":"main.py"},raw=True)
    requirements=""
    requirements_error=""
    try:
        requirements=await silly_dev_get(f"/servers/{sid}/files/contents",params={"file":"requirements.txt"},raw=True,max_bytes=512_000)
    except Exception as exc:
        requirements_error=f"{type(exc).__name__}: {_safe_diag_text(exc,180)}"
    source_hash=hashlib.sha256(source.encode("utf-8")).hexdigest()
    try:
        tree=ast.parse(source,filename=f"sillydev:{sid}/main.py")
        compile(tree,f"sillydev:{sid}/main.py","exec")
        names=[n.name for n in tree.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef))]
        counts=defaultdict(int)
        for name in names:counts[name]+=1
        duplicates=sorted(name for name,count in counts.items() if count>1)
        syntax_ok=True; syntax_error=""
    except Exception as exc:
        syntax_ok=False; duplicates=[]; syntax_error=f"{type(exc).__name__}: {_safe_diag_text(exc,250)}"
    local_hash=manifest_source_sha256()
    requirement_lines=[x.strip() for x in requirements.splitlines() if x.strip() and not x.lstrip().startswith("#")]
    return {
        "server_id":sid,"name":str(server.get("name") or "Unknown server")[:100],
        "server":server,"resources":resources,"source_bytes":len(source.encode("utf-8")),
        "source_sha256":source_hash,"local_sha256":local_hash,
        "matches_local":bool(local_hash and source_hash==local_hash),
        "syntax_ok":syntax_ok,"syntax_error":syntax_error,"duplicate_definitions":duplicates[:30],
        "requirements_count":len(requirement_lines),"requirements_error":requirements_error
    }

def manifest_source_sha256():
    try: return hashlib.sha256(MANIFEST_SOURCE_PATH.read_bytes()).hexdigest()
    except Exception: return ""

def _dev_job_summary(row):
    if not row: return "No development job."
    return f"#{row['id']} · {row['status']} · {row['risk']} · {row['title'] or 'untitled'} · source {str(row['source_sha256'] or '')[:12]}"

async def manifest_dev_collect_evidence():
    """Collect bounded, redacted runtime evidence for the development control plane."""
    evidence=[]
    hr=await db.one("SELECT value FROM manifest_runtime_state WHERE key='last_health'")
    if hr:
        try:
            payload=json.loads(hr["value"] or "{}")
            integrity=payload.get("integrity",{}) or {}
            evidence += [redact_sensitive_text(x,limit=500) for x in (integrity.get("findings",[]) or [])[:12]]
            for k,v in (payload.get("health",{}) or {}).items():
                if isinstance(v,dict) and str(v.get("status","")).lower() not in {"ok","operational","healthy","configured"}:
                    evidence.append(redact_sensitive_text(f"health:{k}: {v}",limit=500))
        except Exception: pass
    for table, label, where in (
        ("runtime_incidents","runtime", "status='open'"),
        ("diagnostic_issues","diagnostic", "status='open'"),
    ):
        try:
            rows=await db.all(f"SELECT subsystem,severity,error_type,summary,occurrences,last_seen FROM {table} WHERE {where} ORDER BY last_seen DESC LIMIT 12")
            for r in rows:
                evidence.append(redact_sensitive_text(
                    f"{label}:{r['subsystem']}:{r['severity']}:{r['error_type']} x{r['occurrences']} {r['summary'][:300]}",
                    limit=700
                ))
        except Exception: pass
    try:
        rows=await db.all("SELECT action,COUNT(*) n FROM action_receipts WHERE verified=0 AND created_at>? GROUP BY action ORDER BY n DESC LIMIT 8",(time.time()-86400,))
        for r in rows: evidence.append(f"unverified_receipts:{r['action']} x{r['n']}")
    except Exception: pass
    try:
        rows=await db.all("SELECT action_type,COUNT(*) n FROM automation_runs WHERE status IN ('failed','error') AND created_at>? GROUP BY action_type ORDER BY n DESC LIMIT 8",(time.time()-86400,))
        for r in rows: evidence.append(f"automation_failures:{r['action_type']} x{r['n']}")
    except Exception: pass
    if not evidence: evidence=["No current diagnostic failure was detected."]
    # Never let secrets or giant trace text enter the planning prompt.
    redactions=(("DISCORD_TOKEN","[REDACTED]"),("Authorization:","Authorization:[REDACTED]"))
    cleaned=[]
    for item in evidence[:40]:
        value=redact_sensitive_text(item,limit=700)
        for a,b in redactions: value=value.replace(a,b)
        cleaned.append(value[:700])
    return cleaned

async def manifest_dev_scout():
    now=time.time()
    async with MANIFEST_DEV_LOCK:
        evidence=await manifest_dev_collect_evidence()
        await db.execute("""INSERT INTO manifest_dev_jobs
            (job_type,status,title,rationale,risk,source_path,source_sha256,evidence,created_at,updated_at)
            VALUES(?,?,?,?,?,?,?,?,?,?)""",
            ("scout","scouted","Manifest development scout",
             "Identify the smallest safe reliability improvement without changing Discord permissions, authority, security policy, or database schema.",
             "low",str(MANIFEST_SOURCE_PATH),manifest_source_sha256(),
             json.dumps(evidence[:24],separators=(",",":")),now,now))
        await db.conn.commit()
        return await db.one("SELECT * FROM manifest_dev_jobs WHERE id=last_insert_rowid()")

async def manifest_dev_propose(job_id:int):
    row=await db.one("SELECT * FROM manifest_dev_jobs WHERE id=?",(int(job_id),))
    if not row: return None
    stored_evidence=row["evidence"] or "[]"
    try:
        parsed_evidence=json.loads(stored_evidence)
        if isinstance(parsed_evidence,list):
            evidence=json.dumps([redact_sensitive_text(x,limit=700) for x in parsed_evidence[:24]],separators=(",",":"))
        else:
            evidence=redact_sensitive_text(stored_evidence,limit=12000)
    except Exception:
        evidence=redact_sensitive_text(stored_evidence,limit=12000)
    prompt=("You are Manifest's private development planner inside its controlled development workflow. The model provider is infrastructure; never claim to be a specific provider. Planner only, never executor. "
            "Return ONLY JSON: title,rationale,risk,search,replace. "
            "The patch must be one exact search/replace, <=1200 chars each, ideally <=6 changed lines. "
            "Do not touch tokens, API keys, owners, permissions, anti-nuke/quarantine, schema, imports, or deployment configuration. "
            "Do not invent source text. If unsafe or uncertain, return empty search/replace. "
            f"Current source SHA256: {row['source_sha256']} Evidence: {evidence}")
    raw=await xai_specialist_text([{"role":"system","content":prompt},{"role":"user","content":evidence}],700,18)
    if not raw:
        await db.execute("UPDATE manifest_dev_jobs SET status='needs_review',error=?,updated_at=? WHERE id=?",
                         ("Dedicated proposal intelligence route is unavailable; no generic fallback was used.",time.time(),int(job_id)))
        await db.conn.commit()
        return await db.one("SELECT * FROM manifest_dev_jobs WHERE id=?",(int(job_id),))
    try:
        mm=re.search(r'\{.*\}',raw,re.S); data=json.loads(mm.group(0)) if mm else {}
        title=redact_sensitive_text(data.get("title") or row["title"] or "",limit=180)
        rationale=redact_sensitive_text(data.get("rationale") or "",limit=700)
        risk=str(data.get("risk") or "high").lower()
        search=str(data.get("search") or ""); replace=str(data.get("replace") or "")
        candidate_text=search+"\n"+replace
        blocked=re.compile(r"(TOKEN|API_KEY|OWNER_IDS|MAKER_USER_ID|CO_OWNER_ID|anti.?nuke|quarantine|permission|guild_permissions|DISCORD_TOKEN|schema|CREATE TABLE|requirements\.txt|\.env|subprocess|os\.system|eval\(|exec\()",re.I)
        configured_secrets=[globals().get(name) for name in ("TOKEN","GROQ_API_KEY","XAI_API_KEY","CLOUDFLARE_API_TOKEN","OPENROUTER_API_KEY","SILLY_DEV_API_KEY","LAVALINK_PASSWORD","MUSIC_AI_API_KEY","EXA_API_KEY","JINA_API_KEY","VOYAGE_API_KEY","OCR_SPACE_API_KEY","ASSEMBLYAI_API_KEY")]
        leaks_secret=any(isinstance(secret,str) and len(secret)>=8 and secret in candidate_text for secret in configured_secrets)
        safe=(risk=="low" and bool(search and replace and search!=replace and len(search)<=1200 and len(replace)<=1200)
              and not blocked.search(candidate_text) and not leaks_secret)
        if not safe: search=replace=""; risk="high"
        await db.execute("UPDATE manifest_dev_jobs SET status=?,title=?,rationale=?,risk=?,patch_search=?,patch_replace=?,updated_at=? WHERE id=?",
                         ("proposed" if search else "needs_review",title,rationale,risk,search,replace,time.time(),int(job_id)))
        await db.conn.commit()
        return await db.one("SELECT * FROM manifest_dev_jobs WHERE id=?",(int(job_id),))
    except Exception as ex:
        await db.execute("UPDATE manifest_dev_jobs SET status='failed',error=?,updated_at=? WHERE id=?",(_safe_diag_text(f"{type(ex).__name__}: {ex}",700),time.time(),int(job_id)))
        await db.conn.commit()
        return None

async def manifest_dev_apply(job_id:int, approver_id:int):
    if int(approver_id) != MAKER_USER_ID or not _is_silly_dev_authorized(approver_id):
        raise PermissionError("Only the verified Creator & Owner with private development authorization may apply source changes.")
    if not silly_dev_configured(): raise RuntimeError("Silly Dev capability key is not configured.")
    async with MANIFEST_DEV_LOCK:
        row=await db.one("SELECT * FROM manifest_dev_jobs WHERE id=?",(int(job_id),))
        if not row or row["status"] != "approved": raise RuntimeError("Development job is not explicitly approved by the Creator & Owner.")
        if str(row["risk"]).lower()!="low": raise RuntimeError("Only low-risk patches can be applied.")
        if manifest_source_sha256()!=str(row["source_sha256"] or ""): raise RuntimeError("Source changed since proposal; patch refused.")
        old=row["patch_search"] or ""; new=row["patch_replace"] or ""
        source=MANIFEST_SOURCE_PATH.read_text()
        if source.count(old)!=1: raise RuntimeError("Patch anchor is missing or non-unique.")
        candidate=source.replace(old,new,1)
        compile(candidate,str(MANIFEST_SOURCE_PATH),"exec")
        tree=ast.parse(candidate)
        top_names=[n.name for n in tree.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef))]
        duplicates={name for name in top_names if top_names.count(name)>1}
        if duplicates: raise RuntimeError("Patch introduced duplicate top-level definitions: "+", ".join(sorted(duplicates))[:500])
        diff=list(difflib.unified_diff(source.splitlines(),candidate.splitlines(),lineterm=""))
        changed=sum(1 for line in diff if (line.startswith("+") or line.startswith("-")) and not line.startswith(("+++","---")))
        if changed>12: raise RuntimeError(f"Patch changed {changed} lines; low-risk development limit is 12.")
        checkpoint=MANIFEST_SOURCE_PATH.with_name(f"{MANIFEST_SOURCE_PATH.name}.devbak.{int(job_id)}")
        checkpoint.write_text(source)
        new_hash=""
        try:
            MANIFEST_SOURCE_PATH.write_text(candidate)
            new_hash=manifest_source_sha256()
            if new_hash!=hashlib.sha256(candidate.encode()).hexdigest():
                raise RuntimeError("Source read-back verification failed after the patch write.")
            if new_hash==str(row["source_sha256"]):
                raise RuntimeError("Patch produced no change.")
            validation={"compiled":True,"ast_checked":True,"old_sha256":row["source_sha256"],"new_sha256":new_hash,"checkpoint":str(checkpoint),"deployment":"not_deployed"}
            cur=await db.execute("UPDATE manifest_dev_jobs SET status='applied',approved_by=?,applied_at=?,updated_at=?,checkpoint_path=?,validation=?,error='' WHERE id=? AND status='approved'",(int(approver_id),time.time(),time.time(),str(checkpoint),json.dumps(validation,separators=(",",":")),int(job_id)))
            changed=int(getattr(cur,"rowcount",0) or 0)==1
            try: await cur.close()
            except Exception: pass
            if not changed:
                raise RuntimeError("Development job approval was no longer current; source change was cancelled.")
            await db.execute("INSERT INTO manifest_runtime_state(key,value,updated_at) VALUES('expected_source_sha256',?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at",(new_hash,time.time()))
            await db.conn.commit()
            return new_hash
        except Exception as exc:
            # The file and persisted approval record must not disagree after a failed
            # write/verification. Restore the exact source captured in the checkpoint.
            MANIFEST_SOURCE_PATH.write_text(source)
            restored=manifest_source_sha256()
            if restored!=str(row["source_sha256"]):
                raise RuntimeError("Patch failed and automatic source restoration could not be verified; stop further development actions and restore the checkpoint manually.") from exc
            try:
                await db.execute("UPDATE manifest_dev_jobs SET status='failed',error=?,updated_at=? WHERE id=? AND status IN ('approved','applied')",(_safe_diag_text(f"{type(exc).__name__}: {exc}",700),time.time(),int(job_id)))
                await db.execute("INSERT INTO manifest_runtime_state(key,value,updated_at) VALUES('expected_source_sha256',?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at",(restored,time.time()))
            except Exception:
                log.exception("Could not reconcile development job metadata after source rollback")
            raise

async def manifest_dev_rollback(job_id:int, approver_id:int):
    if int(approver_id) != MAKER_USER_ID or not _is_silly_dev_authorized(approver_id):
        raise PermissionError("Only the verified Creator & Owner with private development authorization may roll back source changes.")
    async with MANIFEST_DEV_LOCK:
        row=await db.one("SELECT * FROM manifest_dev_jobs WHERE id=?",(int(job_id),))
        if not row or row["status"]!="applied":
            raise RuntimeError("Only an applied development job can be rolled back.")
        checkpoint=Path(row["checkpoint_path"] or "")
        if not checkpoint.is_absolute(): checkpoint=MANIFEST_SOURCE_PATH.parent/checkpoint
        if not checkpoint.exists(): raise RuntimeError("Development checkpoint is missing; rollback refused.")
        current=MANIFEST_SOURCE_PATH.read_text()
        previous_hash=hashlib.sha256(current.encode()).hexdigest()
        backup_source=checkpoint.read_text()
        compile(backup_source,str(MANIFEST_SOURCE_PATH),"exec")
        MANIFEST_SOURCE_PATH.write_text(backup_source)
        restored_hash=manifest_source_sha256()
        if restored_hash!=hashlib.sha256(backup_source.encode()).hexdigest():
            MANIFEST_SOURCE_PATH.write_text(current)
            raise RuntimeError("Rollback read-back verification failed; current source restored.")
        try:
            await db.execute("INSERT INTO manifest_runtime_state(key,value,updated_at) VALUES('expected_source_sha256',?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at",(restored_hash,time.time()))
            await db.execute("UPDATE manifest_dev_jobs SET status='rolled_back',updated_at=?,error=? WHERE id=? AND status='applied'",
                             (time.time(),f"rolled back by {approver_id}; previous_sha={previous_hash[:16]}; restored_sha={restored_hash[:16]}",int(job_id)))
            check=await db.one("SELECT status FROM manifest_dev_jobs WHERE id=?",(int(job_id),))
            if not check or check["status"]!="rolled_back":
                raise RuntimeError("Rollback metadata could not be verified.")
            return restored_hash
        except Exception:
            # Compensate if metadata failed after the source was restored.
            MANIFEST_SOURCE_PATH.write_text(current)
            try:
                await db.execute("INSERT INTO manifest_runtime_state(key,value,updated_at) VALUES('expected_source_sha256',?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at",(previous_hash,time.time()))
                await db.execute("UPDATE manifest_dev_jobs SET status='applied',updated_at=? WHERE id=? AND status='rolled_back'",(time.time(),int(job_id)))
            except Exception:
                log.exception("Could not reconcile development rollback metadata after source restoration")
            raise

@tasks.loop(minutes=20)
async def silly_dev_scout_loop():
    if not SILLY_DEV_AUTOMATION or not silly_dev_configured(): return
    try:
        row=await manifest_dev_scout()
        if row: await manifest_dev_propose(int(row["id"]))
    except Exception: log.exception("Silly Dev scout failed")

# ========================= CREATOR CONTROL PLANE =========================
# The Creator Control Plane is intentionally distinct from server-manager tools.
# Only the immutable Creator & Owner can open it or perform infrastructure mutations.
# SillyDev permissions still enforce the API key's server/scope/IP/expiry limits.
# Raw terminal/console command execution is deliberately not exposed in Discord.

CREATOR_CONTROL_LAYOUTS = {
    "command": "Command-first · quick access to updates, server control and common actions",
    "operations": "Operations-first · health, resources, incidents and recovery first",
    "release": "Release-first · source validation, backups, deployments and rollback first",
    "compact": "Compact · fewer fields and a tighter control surface",
}
# Consent and its audio usage limits are protected deployment policy, not Discord-editable controls.
CREATOR_CONTROL_SECRET_HINTS = ("TOKEN", "SECRET", "PASSWORD", "PASSWD", "PRIVATE", "CREDENTIAL", "API_KEY", "ACCESS_KEY", "AUTH", "MUSIC_AI_GUARDIAN_CONSENT", "MUSIC_AI_DAILY_JOB_LIMIT", "MUSIC_AI_MAX_ACTIVE_JOBS")
CREATOR_CONTROL_SAFE_FILE_NAMES = {"main.py", "requirements.txt"}
CREATOR_CONTROL_MAX_SOURCE_BYTES = 4 * 1024 * 1024
CREATOR_CONTROL_MAX_REQUIREMENTS_BYTES = 100_000


def creator_control_is_owner(user_or_id) -> bool:
    try:
        return int(getattr(user_or_id, "id", user_or_id)) == MAKER_USER_ID
    except Exception:
        return False


def creator_control_masked_name(value: str) -> bool:
    key = str(value or "").upper()
    return any(marker in key for marker in CREATOR_CONTROL_SECRET_HINTS)


async def creator_control_preferences():
    row = await db.one("SELECT * FROM manifest_creator_control_preferences WHERE creator_id=?", (MAKER_USER_ID,))
    if row:
        try:
            order = json.loads(row["page_order_json"] or "[]")
            if not isinstance(order, list): order = []
        except Exception:
            order = []
        return {
            "selected_server_id": str(row["selected_server_id"] or ""),
            "layout_mode": str(row["layout_mode"] or "command"),
            "page_order": [x for x in order if x in {"overview", "hosting", "releases", "backups", "schedules", "integrations", "intelligence", "audio", "access"}],
            "compact": bool(row["compact"]),
        }
    return {"selected_server_id": "", "layout_mode": "command", "page_order": ["overview", "hosting", "releases"], "compact": False}


async def creator_control_save_preferences(*, selected_server_id=None, layout_mode=None, compact=None, page_order=None):
    current = await creator_control_preferences()
    if selected_server_id is not None:
        current["selected_server_id"] = silly_dev_validate_server_id(selected_server_id) if selected_server_id else ""
    if layout_mode is not None:
        if layout_mode not in CREATOR_CONTROL_LAYOUTS: raise ValueError("Unknown Creator Console layout.")
        current["layout_mode"] = layout_mode
    if compact is not None:
        current["compact"] = bool(compact)
    if page_order is not None:
        valid = [x for x in page_order if x in {"overview", "hosting", "releases", "backups", "schedules", "integrations", "intelligence", "audio", "access"}]
        if valid: current["page_order"] = list(dict.fromkeys(valid))
    await db.execute("""INSERT INTO manifest_creator_control_preferences(creator_id,selected_server_id,layout_mode,page_order_json,compact,updated_at)
        VALUES(?,?,?,?,?,?) ON CONFLICT(creator_id) DO UPDATE SET selected_server_id=excluded.selected_server_id,
        layout_mode=excluded.layout_mode,page_order_json=excluded.page_order_json,compact=excluded.compact,updated_at=excluded.updated_at""",
        (MAKER_USER_ID, current["selected_server_id"], current["layout_mode"], json.dumps(current["page_order"], separators=(",", ":")), int(current["compact"]), time.time()))
    return current


CREATOR_MODEL_SETTINGS = {
    "groq": {"setting": "groq_model", "variable": "GROQ_MODEL", "label": "Groq chat", "configured": lambda: bool(GROQ_API_KEY)},
    "xai": {"setting": "xai_model", "variable": "XAI_MODEL", "label": "xAI chat", "configured": lambda: bool(XAI_API_KEY)},
    "xai_image": {"setting": "xai_image_model", "variable": "XAI_IMAGE_MODEL", "label": "xAI image", "configured": lambda: bool(XAI_API_KEY)},
    "cloudflare": {"setting": "cloudflare_model", "variable": "CLOUDFLARE_AI_MODEL", "label": "Cloudflare fallback", "configured": lambda: bool(CLOUDFLARE_API_TOKEN and CLOUDFLARE_ACCOUNT_ID)},
    "openrouter": {"setting": "openrouter_model", "variable": "OPENROUTER_MODEL", "label": "OpenRouter reserve", "configured": lambda: bool(OPENROUTER_API_KEY)},
}


def creator_control_validate_model_id(value):
    value = str(value or "").strip()
    if not 1 <= len(value) <= 140 or not re.fullmatch(r"[A-Za-z0-9@._:/-]+", value):
        raise ValueError("Model identifier must be 1–140 characters using only letters, numbers, @ . _ : / and -.")
    if ".." in value or value.startswith("/") or value.endswith("/"):
        raise ValueError("Model identifier has an unsafe path form.")
    return value


async def creator_control_load_runtime_settings():
    rows = await db.all("SELECT setting_key,setting_value FROM manifest_creator_runtime_settings")
    applied = 0
    for row in rows:
        key = str(row["setting_key"] or "")
        spec = next((x for x in CREATOR_MODEL_SETTINGS.values() if x["setting"] == key), None)
        if not spec:
            continue
        try:
            value = creator_control_validate_model_id(row["setting_value"])
            globals()[spec["variable"]] = value
            applied += 1
        except Exception:
            log.warning("Ignored invalid Creator runtime setting: %s", key)
    if any(x["setting"] == "groq_model" for x in CREATOR_MODEL_SETTINGS.values()):
        global _groq_selected_model, _groq_models_checked_at
        _groq_selected_model = None
        _groq_models_checked_at = 0.0
    return applied


async def creator_control_set_runtime_model(route, model_id, actor_id):
    route = str(route or "").strip().lower()
    spec = CREATOR_MODEL_SETTINGS.get(route)
    if not spec:
        raise ValueError("Unknown model route.")
    if not spec["configured"]():
        raise RuntimeError(f"{spec['label']} is not configured. Add its protected key in the hosting panel first.")
    value = creator_control_validate_model_id(model_id)
    await db.execute("INSERT INTO manifest_creator_runtime_settings(setting_key,setting_value,updated_by,updated_at) VALUES(?,?,?,?) ON CONFLICT(setting_key) DO UPDATE SET setting_value=excluded.setting_value,updated_by=excluded.updated_by,updated_at=excluded.updated_at",
        (spec["setting"], value, int(actor_id), time.time()))
    globals()[spec["variable"]] = value
    if route == "groq":
        global _groq_selected_model, _groq_models_checked_at
        _groq_selected_model = None
        _groq_models_checked_at = 0.0
    await creator_control_receipt("ai_model_update", "", "verified", "Creator changed a runtime model preference.", {"route": route, "model": value})
    return spec["label"], value


async def creator_control_model_status():
    rows = await db.all("SELECT setting_key,setting_value,updated_at FROM manifest_creator_runtime_settings")
    saved = {str(r["setting_key"]): (str(r["setting_value"]), float(r["updated_at"] or 0)) for r in rows}
    out = []
    for route, spec in CREATOR_MODEL_SETTINGS.items():
        model = str(globals().get(spec["variable"], ""))
        override = saved.get(spec["setting"])
        state = "Configured" if spec["configured"]() else "Not configured"
        detail = f"`{model[:120]}`" if state == "Configured" else "No protected API credential configured"
        if override and state == "Configured":
            detail += f" · Creator override saved {datetime.datetime.fromtimestamp(override[1], datetime.timezone.utc).strftime('%Y-%m-%d %H:%M UTC')}"
        out.append((route, spec["label"], state, detail))
    return out


async def creator_control_receipt(operation: str, server_id: str = "", status: str = "accepted", detail: str = "", metadata=None):
    request_id = new_trace_id()
    safe_meta = metadata if isinstance(metadata, dict) else {}
    # Keep receipts useful but deliberately exclude payload bodies and credential values.
    safe_meta = {str(k)[:60]: str(v)[:240] for k, v in list(safe_meta.items())[:20]
                 if not creator_control_masked_name(str(k)) and "token" not in str(k).lower() and "secret" not in str(k).lower()}
    now = time.time()
    await db.execute("INSERT INTO manifest_creator_control_receipts(request_id,actor_id,server_id,operation,status,detail,metadata_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)",
        (request_id, MAKER_USER_ID, str(server_id or "")[:80], str(operation)[:80], str(status)[:32], redact_sensitive_text(detail, limit=700), json.dumps(safe_meta, separators=(",", ":")), now, now))
    return request_id


def creator_control_bytes(value):
    try: n = max(0, int(value or 0))
    except Exception: n = 0
    units = ("B", "KB", "MB", "GB", "TB")
    size = float(n); idx = 0
    while size >= 1024 and idx < len(units) - 1:
        size /= 1024; idx += 1
    return f"{size:.1f} {units[idx]}" if idx else f"{int(size)} B"


def creator_control_duration(milliseconds):
    try:
        seconds = max(0, int(float(milliseconds or 0) / 1000))
    except Exception:
        return "unknown"
    days, seconds = divmod(seconds, 86400)
    hours, seconds = divmod(seconds, 3600)
    minutes, seconds = divmod(seconds, 60)
    parts = []
    if days: parts.append(f"{days}d")
    if hours or days: parts.append(f"{hours}h")
    if minutes or hours or days: parts.append(f"{minutes}m")
    parts.append(f"{seconds}s")
    return " ".join(parts)


async def silly_dev_request(method: str, path: str, *, params=None, payload=None, raw_body=None,
                            raw_response=False, content_type="application/json", timeout=25, max_bytes=None):
    """Narrow, redirect-proof SillyDev API client. Only relative paths are accepted."""
    if not silly_dev_configured():
        raise RuntimeError("The hosting control connection is not configured or its endpoint is not trusted.")
    method = str(method or "GET").upper()
    if method not in {"GET", "POST", "PUT", "DELETE"}:
        raise ValueError("Unsupported hosting API method.")
    if (not isinstance(path, str) or not path.startswith("/") or path.startswith("//") or
        ".." in path or "\\" in path or "?" in path or "#" in path):
        raise ValueError("Invalid hosting API path.")
    base = silly_dev_api_base()
    headers = {"Authorization": f"Bearer {SILLY_DEV_API_KEY}", "Accept": "text/plain" if raw_response else "application/json"}
    request_kwargs = {}
    if raw_body is not None:
        headers["Content-Type"] = content_type
        request_kwargs["data"] = raw_body
    elif payload is not None:
        headers["Content-Type"] = "application/json"
        request_kwargs["json"] = payload
    limit = int(max_bytes or (SILLY_DEV_MAX_SOURCE_BYTES if raw_response else SILLY_DEV_MAX_JSON_BYTES))
    session = await manifest_http_session()
    async with session.request(method, base + path, params=params, headers=headers,
                               allow_redirects=False, timeout=aiohttp.ClientTimeout(total=timeout, connect=8, sock_read=max(15, timeout-5)),
                               **request_kwargs) as response:
        if 300 <= response.status < 400:
            raise RuntimeError("The hosting API returned a redirect; it was refused to protect the authorization credential.")
        body = await response.content.read(limit + 1)
        if len(body) > limit:
            raise RuntimeError(f"The hosting API response exceeded the {limit} byte safety limit.")
        text = body.decode(response.charset or "utf-8", errors="replace")
        if response.status >= 400:
            detail = ""
            try:
                parsed = json.loads(text)
                errors = parsed.get("errors") or []
                detail = str((errors[0] or {}).get("detail") or (errors[0] or {}).get("code") or "") if errors else str(parsed.get("detail") or "")
            except Exception:
                detail = text
            detail = redact_sensitive_text(detail, limit=450)
            raise RuntimeError(f"Hosting API HTTP {response.status}" + (f": {detail}" if detail else ""))
        if response.status == 204 or not text.strip():
            return {"http_status": response.status, "accepted": response.status < 300}
        if raw_response:
            return text
        try:
            parsed = json.loads(text)
        except json.JSONDecodeError as exc:
            raise RuntimeError("The hosting API returned invalid JSON.") from exc
        if not isinstance(parsed, dict):
            raise RuntimeError("The hosting API returned an unexpected response shape.")
        parsed["_http_status"] = response.status
        return parsed


