async def silly_dev_create_backup(server_id, name=None):
    sid = silly_dev_validate_server_id(server_id)
    label = str(name or f"Manifest checkpoint {datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%d %H:%M UTC')}")[:100]
    data = await silly_dev_request("POST", f"/servers/{sid}/backups", payload={"name": label, "is_locked": True})
    attrs = data.get("attributes") or data
    backup_id = str(attrs.get("uuid") or "")
    if not backup_id:
        raise RuntimeError("The hosting panel accepted the backup request but returned no backup identifier.")
    return {"uuid": backup_id, **attrs}


async def silly_dev_wait_backup(server_id, backup_id, timeout=150):
    sid = silly_dev_validate_server_id(server_id)
    if not re.fullmatch(r"[A-Fa-f0-9-]{30,40}", str(backup_id or "")):
        raise ValueError("Invalid backup identifier.")
    deadline = time.time() + max(20, min(int(timeout), 240))
    last = {}
    while time.time() < deadline:
        data = await silly_dev_request("GET", f"/servers/{sid}/backups/{backup_id}")
        attrs = data.get("attributes") or data
        last = attrs
        if attrs.get("completed_at"):
            if attrs.get("is_successful"):
                return attrs
            raise RuntimeError("The hosting provider finished the backup but marked it unsuccessful.")
        await asyncio.sleep(3.0)
    raise TimeoutError("The backup is still running. No deployment or file update was started; inspect Backups in the Creator Console.")


async def silly_dev_power(server_id, signal):
    sid = silly_dev_validate_server_id(server_id)
    signal = str(signal or "").lower()
    if signal not in {"start", "stop", "restart"}:
        raise ValueError("Only start, graceful stop and restart are exposed in the Creator Console.")
    return await silly_dev_request("POST", f"/servers/{sid}/power", payload={"signal": signal})


async def silly_dev_deploy_git_with_checkpoint(server_id):
    sid = silly_dev_validate_server_id(server_id)
    git = await silly_dev_server_git(sid)
    attrs = git.get("attributes") or git
    meta = git.get("meta") or attrs.get("meta") or {}
    can_manage = attrs.get("can_manage") is True or meta.get("can_manage") is True
    if not attrs.get("repository") and not attrs.get("repo") and not attrs.get("branch"):
        raise RuntimeError("No Git repository appears to be linked to this server.")
    if not can_manage:
        raise PermissionError("The hosting API did not confirm Git deployment authority. Git deployment requires the server owner and an unrestricted API key.")
    backup = await silly_dev_create_backup(sid, "Manifest pre-Git-deploy checkpoint")
    await silly_dev_wait_backup(sid, backup["uuid"], timeout=180)
    result = await silly_dev_request("POST", f"/servers/{sid}/git/deploy", payload={})
    deploy_attrs = result.get("attributes") or result
    status = str(deploy_attrs.get("status") or "queued")
    deploy_id = str(deploy_attrs.get("uuid") or deploy_attrs.get("id") or "")
    normalized = {**deploy_attrs, "status": status, "uuid": deploy_id}
    receipt = await creator_control_receipt("git_deploy", sid, status, "Git deployment queued; completion must be checked separately.",
        {"deployment_id": deploy_id, "backup_id": backup["uuid"], "branch": deploy_attrs.get("branch", attrs.get("branch", ""))})
    return {"deployment": normalized, "backup": backup, "receipt": receipt}




