async def silly_dev_create_safe_schedule(server_id, *, name, kind, hour, minute):
    sid = silly_dev_validate_server_id(server_id)
    hour = int(hour); minute = int(minute)
    if not (0 <= hour <= 23 and 0 <= minute <= 59): raise ValueError("Use a valid 24-hour time.")
    templates = {
        "daily_backup": {"minute": str(minute), "hour": str(hour), "day_of_month": "*", "month": "*", "day_of_week": "*", "task": {"action": "backup", "time_offset": 0}},
        "weekly_backup": {"minute": str(minute), "hour": str(hour), "day_of_month": "*", "month": "*", "day_of_week": "1", "task": {"action": "backup", "time_offset": 0}},
        "weekly_restart": {"minute": str(minute), "hour": str(hour), "day_of_month": "*", "month": "*", "day_of_week": "1", "task": {"action": "power", "payload": "restart", "time_offset": 0}},
    }
    if kind not in templates: raise ValueError("Only backup and weekly graceful-restart templates are available.")
    template = templates[kind]
    body = {"name": str(name or "Manifest scheduled maintenance")[:100],
            "minute": template["minute"], "hour": template["hour"],
            "day_of_month": template["day_of_month"], "month": template["month"],
            "day_of_week": template["day_of_week"], "is_active": True, "only_when_online": True}
    created = await silly_dev_request("POST", f"/servers/{sid}/schedules", payload=body)
    attrs = created.get("attributes") or created
    schedule_id = int(attrs.get("id") or 0)
    if schedule_id <= 0: raise RuntimeError("Schedule creation returned no numeric schedule identifier.")
    task = dict(template["task"])
    task.setdefault("payload", None)
    task.setdefault("continue_on_failure", False)
    try:
        task_result = await silly_dev_request("POST", f"/servers/{sid}/schedules/{schedule_id}/tasks", payload=task)
    except Exception as exc:
        # Never leave an active empty schedule if adding its typed task failed.
        try: await silly_dev_set_schedule_active(sid, schedule_id, False)
        except Exception as disable_exc:
            raise RuntimeError(f"Schedule {schedule_id} was created but its task failed and the schedule could not be disabled. Disable it in the hosting panel immediately. Task error: {_safe_diag_text(exc,180)}; disable error: {_safe_diag_text(disable_exc,180)}")
        raise RuntimeError(f"Schedule {schedule_id} was created then disabled because its task could not be added: {_safe_diag_text(exc,250)}")
    result_attrs = task_result.get("attributes") or task_result
    return {"schedule": attrs, "task": result_attrs, "cron": f"{body['minute']} {body['hour']} {body['day_of_month']} {body['month']} {body['day_of_week']}"}


async def silly_dev_get_backup(server_id, backup_id):
    sid = silly_dev_validate_server_id(server_id)
