async def silly_dev_restore_backup_safely(server_id, backup_id):
    sid = silly_dev_validate_server_id(server_id)
    target = await silly_dev_get_backup(sid, backup_id)
    if not target.get("completed_at") or not target.get("is_successful"):
        raise RuntimeError("Only a completed successful backup can be restored.")
    checkpoint = await silly_dev_create_backup(sid, "Manifest pre-restore safety checkpoint")
    checkpoint_final = await silly_dev_wait_backup(sid, checkpoint["uuid"], timeout=210)
    result = await silly_dev_request("POST", f"/servers/{sid}/backups/{backup_id}/restore", payload={"truncate": False})
    receipt = await creator_control_receipt("backup_restore", sid, "accepted", "Restore accepted; restore completion is asynchronous and must be confirmed in the hosting panel.", {"target_backup": backup_id, "safety_checkpoint": checkpoint["uuid"]})
    return {"target": target, "checkpoint": checkpoint_final, "checkpoint_id": checkpoint["uuid"], "result": result, "receipt": receipt}


def creator_control_validate_python(raw: bytes):
    if not raw or len(raw) > CREATOR_CONTROL_MAX_SOURCE_BYTES:
        raise ValueError("Python source must be non-empty and no larger than 4 MiB.")
    try:
        source = raw.decode("utf-8-sig")
    except UnicodeDecodeError as exc:
        raise ValueError("Python source must be valid UTF-8.") from exc
    tree = ast.parse(source, filename="main.py")
    compile(tree, "main.py", "exec")
    names = [node.name for node in tree.body if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))]
    duplicates = sorted(name for name in set(names) if names.count(name) > 1)
    if duplicates:
        raise ValueError("Duplicate top-level definitions: " + ", ".join(duplicates[:15]))
    literal_secret = re.compile(r"(?im)^\s*(?:[A-Z0-9_]*(?:API_KEY|TOKEN|SECRET|PASSWORD|PRIVATE_KEY))\s*=\s*(['\"])(?!\s*(?:os\.getenv|os\.environ))[^'\"]{8,}\1")
    if literal_secret.search(source):
        raise ValueError("The candidate appears to contain a hard-coded credential. Keep secrets in environment variables.")
    normalized = source.encode("utf-8")
    return source, hashlib.sha256(normalized).hexdigest(), len(names)


def creator_control_validate_requirements(raw: bytes):
    if not raw or len(raw) > CREATOR_CONTROL_MAX_REQUIREMENTS_BYTES:
        raise ValueError("requirements.txt must be non-empty and no larger than 100 KB.")
    try: content = raw.decode("utf-8-sig")
    except UnicodeDecodeError as exc: raise ValueError("requirements.txt must be valid UTF-8.") from exc
    lines = []
    for number, line in enumerate(content.splitlines(), 1):
        clean = line.strip()
        if not clean or clean.startswith("#"): continue
        if clean.startswith(("-", "git+", "http://", "https://")) or " @ " in clean:
            raise ValueError(f"requirements.txt line {number} uses a remote source or pip directive; that is blocked in the Creator update path.")
        if not re.fullmatch(r"[A-Za-z0-9_.-]+(?:\[[A-Za-z0-9_,.-]+\])?(?:\s*(?:===|==|~=|!=|<=|>=|<|>)\s*[A-Za-z0-9.*+!_-]+(?:\s*,\s*(?:===|==|~=|!=|<=|>=|<|>)\s*[A-Za-z0-9.*+!_-]+)*)?", clean):
            raise ValueError(f"requirements.txt line {number} is not a standard package requirement.")
        lines.append(clean)
    if not lines: raise ValueError("requirements.txt contains no installable package entries.")
    normalized = content.encode("utf-8")
    return content, hashlib.sha256(normalized).hexdigest(), len(lines)


