async def silly_dev_set_safe_startup_variable(server_id, key, value):
    key = str(key or "").strip().upper()
    if not re.fullmatch(r"[A-Z][A-Z0-9_]{1,63}", key): raise ValueError("Invalid startup variable name.")
    if creator_control_masked_name(key): raise PermissionError("Secret, credential and authentication variables cannot be changed through Discord. Use the hosting panel's protected credential controls.")
    startup = await silly_dev_startup(server_id)
    row = next((x.get("attributes", x) for x in startup.get("data", []) if str(x.get("attributes", x).get("env_variable", "")).upper() == key), None)
    if not row: raise ValueError("That startup variable is not visible to this API key.")
    if not row.get("is_editable"): raise PermissionError("That startup variable is read-only.")
    safe_value = str(value or "")
    if len(safe_value) > 500 or any(ch in safe_value for ch in ("\x00", "\r", "\n")):
        raise ValueError("Startup values must be at most 500 characters and cannot contain newlines or null bytes.")
    result = await silly_dev_request("PUT", f"/servers/{silly_dev_validate_server_id(server_id)}/startup/variable", payload={"key": key, "value": safe_value})
    # Read back in memory only; never echo or log the setting value.
    try:
        refreshed = await silly_dev_startup(server_id)
        refreshed_row = next((x.get("attributes", x) for x in refreshed.get("data", []) if str(x.get("attributes", x).get("env_variable", "")).upper() == key), None)
        actual = refreshed_row.get("server_value") if refreshed_row else None
        verified = actual is not None and str(actual) == safe_value
    except Exception:
        verified = False
    return {"accepted": True, "verified": verified, "http_status": result.get("_http_status", result.get("http_status", 0))}


def manifest_creator_integration_inventory():
    """Truthful integration inventory: configured is not the same as tested/healthy."""
    rows = []
    def add(name, configured, wired, area, provider=None):
        state = "Not configured" if not configured else "Configured · not yet verified"
        health = (_external_health.get(provider, {}) if provider else {})
        if configured and health.get("ok", 0) and health.get("last_ok", 0) > time.time() - 3600:
            state = "Recently verified"
        if configured and health.get("fail", 0) > health.get("ok", 0) and health.get("last_error"):
            state = "Degraded · last operation failed"
        rows.append({"name": name, "state": state, "wired": bool(wired), "area": area})
    add("Primary chat intelligence", bool(GROQ_API_KEY), bool(ai), "chat")
    add("Fallback intelligence", bool(CLOUDFLARE_API_TOKEN and CLOUDFLARE_ACCOUNT_ID), True, "chat")
    add("Emergency intelligence reserve", bool(OPENROUTER_API_KEY), True, "chat")
    add("Specialist reasoning and image generation", bool(XAI_API_KEY), bool(xai), "chat/image")
    add("Exa live web research", bool(EXA_API_KEY), True, "research", "exa")
    add("Jina search and web reading", bool(JINA_API_KEY), True, "reader/search", "jina")
    add("Semantic embeddings and reranking", bool(VOYAGE_API_KEY), True, "retrieval", "voyage")
    add("Image/PDF text extraction", bool(OCR_SPACE_API_KEY), True, "ocr", "ocr")
    add("Audio transcription", bool(ASSEMBLYAI_API_KEY), True, "transcription", "assemblyai")
    audio_ready, audio_reason = music_ai_gate_status()
    add("Audio workflow discovery and jobs", audio_ready, True, "audio-workflows")
    if music_ai_key_configured() and not MUSIC_AI_GUARDIAN_CONSENT:
        rows[-1]["state"] = "Disabled · guardian consent required"
    add("Voice playback node", lavalink_configured(), bool(wavelink), "playback")
    add("Deployment and hosting control", silly_dev_configured(), True, "hosting")
    return rows




def creator_control_default_page(prefs):
    mode = str((prefs or {}).get("layout_mode") or "command")
    return {"operations": "hosting", "release": "releases", "compact": "overview", "command": "overview"}.get(mode, "overview")


async def creator_control_embed(page=None):
    prefs = await creator_control_preferences()
    page = page or creator_control_default_page(prefs)
    sid = prefs.get("selected_server_id") or ""
    layout = prefs.get("layout_mode", "command")
    compact = bool(prefs.get("compact", False)) or layout == "compact"
    e = discord.Embed(title="MANIFEST · CREATOR COMMAND CENTER", color=discord.Color.from_rgb(73, 104, 178))
    e.set_author(name="Creator & Owner · Private control surface")
    e.set_footer(text=f"Creator priority · Layout: {layout} · Private session")
    if not silly_dev_configured():
        e.description = "**Hosting connection:** Not configured. Add the SillyDev key as a protected environment variable on the deployment; never paste it into chat.\n\nLocal Manifest controls and integration inventory remain available."
    else:
        e.description = "**Hosting connection:** API credential configured. Live access is determined by SillyDev's server and permission scopes; no action is assumed successful until verified."
    e.add_field(name="Selected deployment", value=f"`{sid}`" if sid else "No deployment selected · open **Servers** to choose one", inline=True)
    e.add_field(name="Current build", value=f"`{VERSION}` · {BUILD_LABEL}", inline=True)
    e.add_field(name="Local source fingerprint", value=f"`{manifest_source_sha256()[:16] or 'unavailable'}`", inline=True)
    if page in {"overview", "hosting"} and sid and silly_dev_configured():
        try:
            payload = await silly_dev_request("GET", f"/servers/{silly_dev_validate_server_id(sid)}/resources")
            r = payload.get("attributes") or payload
            use = r.get("resources") or {}
            state = str(r.get("current_state") or "unknown").upper()
            e.add_field(name="Deployment state", value=f"**{state}**\nSuspended: {'yes' if r.get('is_suspended') else 'no'}", inline=True)
            e.add_field(name="Compute", value=f"CPU **{float(use.get('cpu_absolute') or 0):.1f}%**\nMemory **{creator_control_bytes(use.get('memory_bytes'))}**\nDisk **{creator_control_bytes(use.get('disk_bytes'))}**", inline=True)
            e.add_field(name="Uptime", value=creator_control_duration(use.get("uptime")) if use.get("uptime") else "Offline / starting", inline=True)
        except Exception as exc:
            e.add_field(name="Deployment telemetry", value=f"Unavailable: {_safe_diag_text(exc, 220)}", inline=False)
    if page == "releases" and sid and silly_dev_configured():
        try:
            payload = await silly_dev_server_git(sid)
            a = payload.get("attributes") or payload
            deps = a.get("deployments") or []
            lines = [f"Repository linked: **{'yes' if a.get('repository') or a.get('repo') else 'no'}**",
                     f"Branch: `{a.get('branch') or 'unknown'}`",
                     f"Can manage/deploy: **{'yes' if a.get('can_manage') else 'no'}**"]
            for d in deps[:5]: lines.append(f"• `{d.get('status','unknown')}` · {str(d.get('commit',{}).get('sha') or '')[:10]} · {d.get('created_at') or d.get('createdAt') or ''}")
            e.add_field(name="Git release status", value="\n".join(lines)[:1024], inline=False)
        except Exception as exc:
            e.add_field(name="Git release status", value=f"Unavailable / insufficient scope: {_safe_diag_text(exc, 250)}", inline=False)
    if page == "backups" and sid and silly_dev_configured():
        try:
            payload = await silly_dev_server_backups(sid)
            items = payload.get("data") or []
            lines=[]
            for row in items[:7]:
                a=row.get("attributes") or row
                lines.append(f"• **{str(a.get('name') or 'Backup')[:48]}** · {'complete' if a.get('completed_at') and a.get('is_successful') else 'running/failed'} · `{str(a.get('uuid') or '')[:8]}`")
            e.add_field(name="Recent backups", value="\n".join(lines)[:1024] or "No backups returned by this API scope.", inline=False)
        except Exception as exc:
            e.add_field(name="Recent backups", value=f"Unavailable: {_safe_diag_text(exc, 250)}", inline=False)
    if page == "integrations":
        items = manifest_creator_integration_inventory()
        lines = [f"{'🟢' if x['state']=='Recently verified' else '🟡' if x['state'].startswith('Configured') else '🔴' if x['state']=='Not configured' else '🟠'} **{x['name']}** · {x['state']}" for x in items]
        for idx in range(0, len(lines), 5):
            e.add_field(name=f"Integration inventory · {idx // 5 + 1}", value="\n".join(lines[idx:idx+5])[:1024], inline=False)
        e.add_field(name="Truth rule", value="Configured keys are not proof of a successful connection. A route becomes verified only after a real successful request. Secret values are never displayed.", inline=False)
    if page == "intelligence":
        model_rows = await creator_control_model_status()
        for route, label, state, detail in model_rows:
            e.add_field(name=f"{label} · {state}", value=detail, inline=False)
        e.add_field(name="Control", value="Use `/manifest control ai_model` to change a configured route. Changes are saved in the Manifest database and survive restart; API keys remain in protected environment variables.", inline=False)
        e.add_field(name="Routing safety", value="Model selection changes the route's model preference only. It does not alter API keys, provider order, quotas, or public disclosure policy.", inline=False)
    if page == "audio":
        ready, gate_reason = music_ai_gate_status()
        e.add_field(name="Creator Audio Studio", value=("Audio-processing workflows are enabled by protected deployment settings. Use the Audio Studio button for workflow discovery and recent job status." if ready else gate_reason), inline=False)
        e.add_field(name="Supported work", value="Existing-audio workflows may include stems/separation, lyrics and speech transcription, chords/beats, metadata, enhancement, mixing/mastering, and other account-enabled modules. Exact availability is read from the account's workflow list.", inline=False)
        e.add_field(name="Music generation boundary", value="The official API documentation describes processing jobs and generator modules such as metronome/text-to-speech; it does not document general prompt-to-full-song generation. Manifest will not label processing as original-song generation.", inline=False)
        e.add_field(name="Voice playback", value="Discord voice playback is a separate system. The Music Player panel controls queued listening; completed audio-processing jobs do not automatically play in a voice channel.", inline=False)
        e.add_field(name="Usage controls", value=f"Submission requires a fresh explicit confirmation. Limits: {MUSIC_AI_DAILY_JOB_LIMIT} submissions/rolling 24h · {MUSIC_AI_MAX_ACTIVE_JOBS} active/uncertain jobs. Review the provider's current pricing before confirming.", inline=False)
    if page == "schedules":
        if sid and silly_dev_configured():
            try:
                data = await silly_dev_server_schedules(sid)
                items = data.get("data") or []
                lines = []
                for row in items[:8]:
                    a = row.get("attributes") or row
                    cron = a.get("cron") or {}
                    expr = " ".join(str(cron.get(k, "*")) for k in ("minute", "hour", "day_of_month", "month", "day_of_week"))
                    lines.append(f"• **{str(a.get('name') or 'Schedule')[:48]}** · {'active' if a.get('is_active') else 'disabled'} · `{expr}`")
                e.add_field(name="Hosting schedules", value="\n".join(lines)[:1024] or "No schedules returned for this deployment.", inline=False)
                e.add_field(name="Timezone", value="Cron schedules use the timezone configured in the hosting panel. Verify that timezone before creating one.", inline=False)
            except Exception as exc:
                e.add_field(name="Hosting schedules", value=f"Unavailable / insufficient scope: {_safe_diag_text(exc, 400)}", inline=False)
        else:
            e.add_field(name="Hosting schedules", value="Select a deployment and configure the SillyDev API credential to inspect schedules.", inline=False)
    if page == "access":
        e.add_field(name="Manifest authority", value="**thunderxstorms5_.** · Creator & Owner · final authority\n**alemorci** · Co-Owner · bounded capabilities\n**v01d_demon** · Developer · explicit development capabilities", inline=False)
        e.add_field(name="Infrastructure boundary", value="SillyDev control, source deployment, restart/stop, startup settings, backups and final rollback are Creator-only. Server-level permissions remain separate.", inline=False)
    if page == "hosting":
        e.add_field(name="Control boundary", value="Typed power actions, backup, Git deployment, safe startup variables and verified source file updates. No raw console or shell command is exposed.", inline=False)
        if sid and silly_dev_configured():
            try:
                detail = await silly_dev_request("GET", f"/servers/{silly_dev_validate_server_id(sid)}")
                meta = detail.get("meta") or {}
                permissions = meta.get("permissions") or []
                owner = meta.get("is_owner", meta.get("owner", None))
                e.add_field(name="Hosting authority", value=f"Server owner identity: **{'yes' if owner is True else 'no' if owner is False else 'not reported'}**\nVisible scoped permissions: {', '.join(str(x)[:45] for x in permissions[:12]) or 'Not returned'}\nGit deployment is separately gated by the hosting API's `can_manage` result.", inline=False)
            except Exception as exc:
                e.add_field(name="Hosting authority", value=f"Scope details unavailable: {_safe_diag_text(exc, 250)}", inline=False)
    if page == "releases":
        e.add_field(name="Release discipline", value="Inspect → validate → backup → deploy → verify → promote or recover. A queued deployment is not reported as a completed release.", inline=False)
    if page == "overview":
        e.add_field(name="Quick operations", value="Server inventory · runtime health · backups · Git deployments · source update · integrations · personal layout", inline=False)
        e.add_field(name="Priority", value="Creator operations are private and receive their own interface. This panel does not inherit Co-Owner or Developer access.", inline=False)
    if compact:
        # Compact mode removes decorative nonessential whitespace, not information needed for safety.
        e.description = (e.description or "").replace("\n\n", "\n")
    return e


class CreatorControlPageSelect(discord.ui.Select):
    def __init__(self, view, page_order=None):
        self.parent_view = view
        all_pages = ["overview", "hosting", "releases", "backups", "schedules", "integrations", "intelligence", "audio", "access"]
        preferred = [x for x in (page_order or []) if x in all_pages]
        ordered = list(dict.fromkeys(preferred + all_pages))
        options = [discord.SelectOption(label=x.title(), value=x, default=(x == view.page)) for x in ordered[:25]]
        super().__init__(placeholder="Creator Console · choose a workspace", min_values=1, max_values=1, options=options, row=0)
    async def callback(self, interaction):
        self.parent_view.page = self.values[0]
        await interaction.response.defer()
        embed = await creator_control_embed(self.parent_view.page)
        await interaction.edit_original_response(embed=embed, view=self.parent_view)


