class CreatorControlServerSelect(discord.ui.Select):
    def __init__(self, owner_id, servers):
        self.owner_id = int(owner_id)
        opts=[]
        for row in servers[:25]:
            a=row.get("attributes") or row
            sid=str(a.get("identifier") or a.get("id") or "")
            name=str(a.get("name") or sid or "Unnamed server")[:100]
            if sid and re.fullmatch(r"[A-Fa-f0-9]{8}",sid): opts.append(discord.SelectOption(label=name, description=f"{sid} · {str(a.get('status') or 'available')[:50]}", value=sid))
        if not opts: opts=[discord.SelectOption(label="No selectable servers returned", value="none", default=True)]
        super().__init__(placeholder="Select your SillyDev deployment", min_values=1, max_values=1, options=opts, row=0, disabled=(len(opts)==1 and opts[0].value=="none"))
    async def callback(self, interaction):
        if interaction.user.id != self.owner_id or not creator_control_is_owner(interaction.user):
            return await interaction.response.send_message("This Creator control session is not yours.", ephemeral=True)
        if self.values[0] == "none": return await interaction.response.send_message("No accessible server was returned by the API key.", ephemeral=True)
        await interaction.response.defer()
        await creator_control_save_preferences(selected_server_id=self.values[0])
        new_view = await creator_control_new_view(self.owner_id)
        embed = await creator_control_embed(new_view.page)
        await interaction.edit_original_response(content="Deployment selected.", embed=embed, view=new_view)


class CreatorControlConfirmView(discord.ui.View):
    def __init__(self, owner_id, server_id, operation, *, backup_name=None):
        super().__init__(timeout=90)
        self.owner_id=int(owner_id); self.server_id=silly_dev_validate_server_id(server_id)
        self.operation=str(operation); self.backup_name=backup_name; self.used=False
    async def interaction_check(self, interaction):
        if interaction.user.id != self.owner_id or not creator_control_is_owner(interaction.user):
            await interaction.response.send_message("Creator-only confirmation. This action belongs to the Creator & Owner.", ephemeral=True); return False
        if self.used:
            await interaction.response.send_message("This confirmation has already been used.", ephemeral=True); return False
        return True
    @discord.ui.button(label="Confirm operation", style=discord.ButtonStyle.danger, row=0)
    async def confirm(self, interaction, button):
        self.used=True
        for item in self.children: item.disabled=True
        await interaction.response.defer(ephemeral=True, thinking=True)
        try:
            if self.operation == "backup":
                backup = await silly_dev_create_backup(self.server_id, self.backup_name)
                receipt = await creator_control_receipt("backup_create", self.server_id, "accepted", "Backup created; it may still be processing.", {"backup_id": backup["uuid"]})
                text=f"Backup request accepted.\nBackup: `{backup['uuid']}`\nLocked: **{'yes' if backup.get('is_locked') else 'no (key lacks backup.delete or lock was not confirmed)'}**\nReceipt: `{receipt}`\nLock state is reported only when the hosting API confirms it. The archive is not marked complete until the API confirms it."
            elif self.operation in {"start", "stop", "restart"}:
                result=await silly_dev_power(self.server_id,self.operation)
                receipt=await creator_control_receipt(f"power_{self.operation}",self.server_id,"accepted","Hosting API accepted the power action; state must be checked after it completes.",{"http_status":result.get("http_status","")})
                text=f"The hosting panel accepted **{self.operation}** for `{self.server_id}`. This confirms acceptance, not completion.\nReceipt: `{receipt}`"
            elif self.operation == "git_deploy":
                result=await silly_dev_deploy_git_with_checkpoint(self.server_id)
                dep=result["deployment"]
                text=f"Git deployment **{dep.get('status') or 'queued'}**.\nDeployment: `{dep.get('uuid') or 'unknown'}`\nPre-deploy backup: `{result['backup']['uuid']}`\nReceipt: `{result['receipt']}`\nUse the Deployments page to verify the final result."
            else:
                raise ValueError("Unknown Creator operation.")
            await interaction.followup.send(text,ephemeral=True)
        except Exception as exc:
            await creator_control_receipt(self.operation,self.server_id,"failed",_safe_diag_text(exc,500))
            await interaction.followup.send(f"Operation failed or was not accepted: {_safe_diag_text(exc,700)}",ephemeral=True)
        self.stop()
        try: await interaction.edit_original_response(view=self)
        except Exception: pass
    @discord.ui.button(label="Cancel", style=discord.ButtonStyle.secondary, row=0)
    async def cancel(self, interaction, button):
        self.used=True; self.stop()
        await interaction.response.edit_message(content="Operation cancelled. Nothing was sent to the hosting API.", embed=None, view=None)


class CreatorBackupSelect(discord.ui.Select):
    def __init__(self, owner_id, server_id, backups):
        self.owner_id=int(owner_id); self.server_id=silly_dev_validate_server_id(server_id)
        options=[]
