    @discord.ui.button(label="Recent Jobs",emoji="🕒",style=discord.ButtonStyle.secondary,row=0)
    async def recent_jobs(self,i,b):
        ready,_=music_ai_gate_status();await i.response.defer(ephemeral=True,thinking=True)
        rows=await db.all("SELECT job_id,workflow,filename,status,created_at,result_json FROM manifest_music_ai_jobs WHERE actor_id=? ORDER BY created_at DESC LIMIT 8",(MAKER_USER_ID,))
        lines=[];outputs=[]
        for row in rows:
            state=str(row["status"] or "unknown").upper();result={}
            try:result=json.loads(row["result_json"] or "{}")
            except Exception:result={}
            if ready and not str(row["job_id"]).startswith("pending-"):
                try:
                    live=await music_ai_get_job(str(row["job_id"]))
                    state=str(live.get("status") or state).upper()
                    if isinstance(live.get("result"),dict):result=live["result"]
                except Exception:state += " · refresh unavailable"
            age=f"<t:{int(row['created_at'])}:R>" if row["created_at"] else "time unknown"
            lines.append(f"• **{str(row['workflow'])[:60]}** · `{str(row['job_id'])[:12]}…` · {state} · {age}")
            if state.startswith("SUCCEEDED"):
                for label,url in music_ai_safe_result_outputs(result):
                    if len(outputs)>=15:break
                    outputs.append((f"{str(row['job_id'])[:6]} · {label}"[:80],url))
        view=None
        if outputs:
            view=discord.ui.View(timeout=300)
            for label,url in outputs:
                view.add_item(discord.ui.Button(label=label,style=discord.ButtonStyle.link,url=url))
        content="**Creator Audio Studio · Recent Jobs**\n"+("\n".join(lines) or "No audio jobs have been submitted from this console.")
        if outputs:content+="\n\n**Verified completed outputs** — private Creator links below."
        elif any("SUCCEEDED" in line for line in lines):content+="\n\nA job completed, but no output link on the approved Music.AI CDN host was returned."
        await i.followup.send(content,view=view,ephemeral=True)
