class CreatorSourceDeployConfirmView(discord.ui.View):
    def __init__(self, owner_id, server_id, main_source, main_hash, requirements_source=None, requirements_hash="", restart_after=False, old_main="", old_requirements=None):
        super().__init__(timeout=180)
        self.owner_id=int(owner_id); self.server_id=silly_dev_validate_server_id(server_id)
        self.main_source=main_source; self.main_hash=main_hash
        self.requirements_source=requirements_source; self.requirements_hash=requirements_hash
        self.restart_after=bool(restart_after); self.old_main=old_main; self.old_requirements=old_requirements
        self.used=False
    async def interaction_check(self, interaction):
        if interaction.user.id!=self.owner_id or not creator_control_is_owner(interaction.user):
            await interaction.response.send_message("Only the Creator & Owner can approve a source update.",ephemeral=True); return False
        if self.used:
            await interaction.response.send_message("This source update approval has already been used.",ephemeral=True); return False
        return True
    @discord.ui.button(label="Back up and apply files", style=discord.ButtonStyle.danger, row=0)
    async def apply(self, interaction, button):
        self.used=True
        for child in self.children: child.disabled=True
        await interaction.response.defer(ephemeral=True,thinking=True)
        backup_id=""
        attempted_main=False; attempted_req=False
        try:
            backup=await silly_dev_create_backup(self.server_id,"Manifest source update checkpoint")
            backup_id=backup["uuid"]
            await silly_dev_wait_backup(self.server_id,backup_id,timeout=180)
            if self.requirements_source is not None:
                attempted_req=True
                await silly_dev_write_file(self.server_id,"requirements.txt",self.requirements_source)
                got_req=await silly_dev_read_file(self.server_id,"requirements.txt")
                if hashlib.sha256(got_req.encode("utf-8")).hexdigest()!=self.requirements_hash:
                    raise RuntimeError("requirements.txt read-back did not match the staged checksum.")
            attempted_main=True
            await silly_dev_write_file(self.server_id,"main.py",self.main_source)
            got_main=await silly_dev_read_file(self.server_id,"main.py")
            if hashlib.sha256(got_main.encode("utf-8")).hexdigest()!=self.main_hash:
                raise RuntimeError("main.py read-back did not match the staged checksum.")
            receipt=await creator_control_receipt("source_files_updated",self.server_id,"verified","Source files were written and verified by read-back. Process restart is a separate operation.",{"backup_id":backup_id,"main_sha256":self.main_hash,"requirements_sha256":self.requirements_hash})
            text=f"**Source files updated and verified.**\n`main.py`: `{self.main_hash[:16]}`\n"+(f"`requirements.txt`: `{self.requirements_hash[:16]}`\n" if self.requirements_source is not None else "")+f"Backup checkpoint: `{backup_id}`\nReceipt: `{receipt}`\n"
            if self.requirements_source is not None:
                text+="Dependency installation is not assumed; confirm the host's configured install-on-start behavior before restarting.\n"
            if self.restart_after:
                result=await silly_dev_power(self.server_id,"restart")
                restart_receipt=await creator_control_receipt("source_update_restart",self.server_id,"accepted","Restart accepted after verified file write.",{"http_status":result.get("http_status","")})
                text+=f"Restart accepted (not yet confirmed complete). Receipt: `{restart_receipt}`"
            else:
                text+="The running process has not been restarted. Use the Restart control after reviewing the file update."
            await interaction.followup.send(text,ephemeral=True)
        except Exception as exc:
            recovery=[]
            # Compensate only the exact files this workflow may have touched. The verified backup remains the recovery point.
            if attempted_main:
                try:
                    await silly_dev_write_file(self.server_id,"main.py",self.old_main)
                    check_main=await silly_dev_read_file(self.server_id,"main.py")
                    if check_main != self.old_main: raise RuntimeError("read-back mismatch")
                    recovery.append("main.py previous content restored and verified")
                except Exception as restore_exc: recovery.append("main.py restore could not be verified: "+_safe_diag_text(restore_exc,160))
            if attempted_req and self.old_requirements is not None:
                try:
                    await silly_dev_write_file(self.server_id,"requirements.txt",self.old_requirements)
                    check_req=await silly_dev_read_file(self.server_id,"requirements.txt")
                    if check_req != self.old_requirements: raise RuntimeError("read-back mismatch")
                    recovery.append("requirements.txt previous content restored and verified")
                except Exception as restore_exc: recovery.append("requirements.txt restore could not be verified: "+_safe_diag_text(restore_exc,160))
            await creator_control_receipt("source_files_update",self.server_id,"failed",_safe_diag_text(exc,500),{"backup_id":backup_id,"recovery":"; ".join(recovery)})
            suffix=("\nRecovery: "+"; ".join(recovery) if recovery else "")
            if backup_id: suffix+=f"\nBackup recovery point: `{backup_id}`"
            await interaction.followup.send(f"Source update did not complete cleanly: {_safe_diag_text(exc,600)}{suffix}",ephemeral=True)
        self.stop()
        try: await interaction.edit_original_response(view=self)
        except Exception: pass
    @discord.ui.button(label="Cancel", style=discord.ButtonStyle.secondary, row=0)
    async def cancel(self, interaction, button):
        self.used=True; self.stop()
        await interaction.response.edit_message(content="Source update cancelled. No backup or file write was started.",embed=None,view=None)


