class CreatorStartupVariableConfirmView(discord.ui.View):
    def __init__(self, owner_id, server_id, key, value):
        super().__init__(timeout=120)
        self.owner_id=int(owner_id); self.server_id=silly_dev_validate_server_id(server_id)
        self.key=str(key).strip().upper(); self.value=str(value); self.used=False
    async def interaction_check(self, interaction):
        if interaction.user.id != self.owner_id or not creator_control_is_owner(interaction.user):
            await interaction.response.send_message("Only the Creator & Owner can approve this startup change.",ephemeral=True); return False
        if self.used:
            await interaction.response.send_message("This confirmation has already been used.",ephemeral=True); return False
        return True
    @discord.ui.button(label="Confirm startup change", style=discord.ButtonStyle.danger, row=0)
    async def confirm(self, interaction, button):
        self.used=True
        for item in self.children: item.disabled=True
        await interaction.response.defer(ephemeral=True,thinking=True)
        try:
            result=await silly_dev_set_safe_startup_variable(self.server_id,self.key,self.value)
            status="verified by panel read-back" if result.get("verified") else "accepted by panel; read-back is not yet confirmed"
            receipt=await creator_control_receipt("startup_variable_update",self.server_id,"verified" if result.get("verified") else "accepted","A non-secret startup variable change was submitted; the value is never stored in the receipt.",{"key":self.key})
            await interaction.followup.send(f"Startup variable `{self.key}` was **{status}**. It applies on the next start. Value was not echoed or stored in the audit receipt. Receipt: `{receipt}`",ephemeral=True)
        except Exception as exc:
            await creator_control_receipt("startup_variable_update",self.server_id,"failed",_safe_diag_text(exc,400),{"key":self.key})
            await interaction.followup.send(f"Startup variable was not changed: {_safe_diag_text(exc,650)}",ephemeral=True)
        self.stop()
        try: await interaction.edit_original_response(view=self)
        except Exception: pass
    @discord.ui.button(label="Cancel", style=discord.ButtonStyle.secondary, row=0)
    async def cancel(self, interaction, button):
        self.used=True; self.stop()
        await interaction.response.edit_message(content="Startup variable change cancelled. No hosting API write was sent.",embed=None,view=None)


@manifest_control_group.command(name="set_variable", description="Change a non-secret startup variable after Creator confirmation")
@app_commands.describe(key="Exact editable non-secret variable name", value="New value (applies on next start)")
async def creator_control_set_variable(interaction: discord.Interaction, key: str, value: str):
    if not creator_control_is_owner(interaction.user): return await interaction.response.send_message("Creator & Owner only.",ephemeral=True)
