    key=str(key or "").strip().upper(); value=str(value or "")
    if not re.fullmatch(r"[A-Z][A-Z0-9_]{1,63}",key) or creator_control_masked_name(key):
        return await interaction.response.send_message("That variable name is invalid or protected. Credential-like settings cannot be changed here.",ephemeral=True)
    if len(value)>500 or any(ch in value for ch in ("\x00","\r","\n")):
        return await interaction.response.send_message("Value must be at most 500 characters and cannot contain newlines or null bytes.",ephemeral=True)
    view=CreatorStartupVariableConfirmView(interaction.user.id,sid,key,value)
    await interaction.response.send_message(f"Confirm changing **{key}** on deployment `{sid}`. The value will not be echoed or written to Manifest logs/receipts, but it will be present in this private confirmation. The setting applies on the next start.",view=view,ephemeral=True)


