# Music.AI is an audio workflow engine, not the Lavalink playback provider.
# Creator-only upload/job submission validates the exact workflow slug and accepts
# bounded JSON parameters; Manifest never guesses a workflow-specific schema.
async def music_ai_list_workflows():
    if not music_ai_configured(): raise RuntimeError("Audio workflow integration is not configured.")
    data=await music_ai_request("GET","workflow",timeout=25)
    rows=data.get("workflows") or []
    return [x for x in rows if isinstance(x,dict)]


def music_ai_workflow_policy(workflow):
    """Block voice imitation/cloning workflows; consent cannot be inferred from an upload."""
    if not isinstance(workflow,dict):
        return False,"The selected workflow is not a valid account catalog entry."
    description=" ".join(str(workflow.get(k) or "") for k in ("name","slug","description","id"))
    normalized=re.sub(r"[_./-]+"," ",description.lower())
    restricted=(
        r"\bvoice\s*(?:transfer|clon(?:e|ing)|conversion|imitation|impersonation|model)\b",
        r"\b(?:clone|cloning|imitate|imitation|impersonate|impersonation)\s+(?:a\s+)?voice\b",
        r"\bcustom\s+voice\b",
        r"\bspeaker\s+(?:clone|cloning|imitation)\b",
    )
    if any(re.search(pattern,normalized) for pattern in restricted):
        return False,"Voice-cloning, voice-transfer and voice-imitation workflows are disabled in Manifest. Consent and identity rights cannot be verified from an uploaded file."
    return True,""

def music_ai_is_creation_workflow(workflow):
    if not isinstance(workflow,dict):return False
    text=" ".join(str(workflow.get(k) or "") for k in ("name","slug","description")).lower()
    markers=("generat","creat","compos","melody","accompan","arrang","song","music idea","music assist")
    return any(m in text for m in markers)

def music_ai_validate_json_params(params):
    params=params if isinstance(params,dict) else {}
    if len(params)>25:raise ValueError("Workflow parameter object may contain at most 25 top-level fields.")
    forbidden={"token","secret","password","api_key","authorization","credential"}
    def check_obj(obj,depth=0):
        if depth>5:raise ValueError("Workflow parameters are nested too deeply.")
        if isinstance(obj,dict):
            for key,value in obj.items():
                if any(term in str(key).lower() for term in forbidden):raise ValueError("Credential-like parameter names are not allowed.")
                check_obj(value,depth+1)
        elif isinstance(obj,list):
            if len(obj)>100:raise ValueError("Workflow parameter list is too large.")
            for value in obj:check_obj(value,depth+1)
        elif isinstance(obj,str):
            if len(obj)>4000:raise ValueError("A workflow text parameter is too long.")
        elif obj is not None and not isinstance(obj,(bool,int,float)):
            raise ValueError("Workflow parameters must contain only standard JSON values.")
    check_obj(params);return params


async def music_ai_upload_attachment(attachment: discord.Attachment):
    max_bytes = 15 * 1024 * 1024
    if int(getattr(attachment, "size", 0) or 0) > max_bytes:
        raise ValueError("Audio attachment exceeds the 15 MiB processing limit.")
    filename = str(getattr(attachment, "filename", "audio.bin"))[:120]
    suffix = Path(filename).suffix.lower()
    allowed = {".wav", ".mp3", ".m4a", ".mp4", ".flac", ".ogg", ".opus", ".aac", ".aiff", ".wma"}
    if suffix not in allowed:
        raise ValueError("Use a supported audio file extension: WAV, MP3, M4A, MP4, FLAC, OGG, OPUS, AAC, AIFF or WMA.")
    raw = await attachment.read(use_cached=True)
    if not raw or len(raw) > max_bytes:
        raise ValueError("Audio attachment is empty or exceeds the 15 MiB limit.")
    upload = await music_ai_request("GET", "upload", timeout=25)
    upload_url = str(upload.get("uploadUrl") or "")
    download_url = str(upload.get("downloadUrl") or "")
    parsed_upload = urlsplit(upload_url); parsed_download = urlsplit(download_url)
    for parsed in (parsed_upload, parsed_download):
        if parsed.scheme != "https" or parsed.hostname != "storage.googleapis.com" or parsed.username or parsed.password or parsed.port or parsed.fragment:
            raise RuntimeError("The audio workflow service returned an upload URL outside the approved storage host.")
    session = await manifest_http_session()
    content_type = getattr(attachment, "content_type", None) or "application/octet-stream"
    async with session.put(upload_url, data=raw, headers={"Content-Type": content_type}, allow_redirects=False, timeout=aiohttp.ClientTimeout(total=90)) as resp:
        if 300 <= resp.status < 400:
            raise RuntimeError("Audio storage redirected the signed upload request; redirect refused.")
        if resp.status < 200 or resp.status >= 300:
            raise RuntimeError(f"Audio upload failed with storage HTTP {resp.status}.")
    return {"download_url": download_url, "filename": filename, "bytes": len(raw)}


async def music_ai_submit_attachment_job(*, workflow_slug, attachment, name, extra_params=None, actor_id=None, guild_id=0, channel_id=0, payload_fingerprint=None, rights_attested=False):
    if int(actor_id or 0) != MAKER_USER_ID:
        raise PermissionError("Only the Creator & Owner can submit private audio-processing jobs.")
    if rights_attested is not True:
        raise PermissionError("Explicit confirmation of media rights and required consents is required before upload.")
    if not music_ai_configured():
        _, reason = music_ai_gate_status()
        raise RuntimeError(reason)
    slug = str(workflow_slug or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._/-]{0,159}", slug):
        raise ValueError("Invalid workflow slug.")
    params=music_ai_validate_json_params(extra_params if isinstance(extra_params,dict) else {})
    async with MUSIC_AI_JOB_LOCK:
        now=time.time(); cutoff=now-86400
        daily=await db.one("SELECT COUNT(*) n FROM manifest_music_ai_jobs WHERE actor_id=? AND created_at>=? AND status NOT IN ('FAILED','CANCELLED','CANCELED')",(MAKER_USER_ID,cutoff))
        active=await db.one("SELECT COUNT(*) n FROM manifest_music_ai_jobs WHERE actor_id=? AND status IN ('SUBMITTING','SUBMISSION_UNKNOWN','QUEUED','STARTED','RUNNING')",(MAKER_USER_ID,))
        if int(daily['n'] or 0) >= MUSIC_AI_DAILY_JOB_LIMIT:
            raise RuntimeError(f"Creator audio limit reached: {MUSIC_AI_DAILY_JOB_LIMIT} accepted or uncertain submissions per rolling 24 hours.")
        if int(active['n'] or 0) >= MUSIC_AI_MAX_ACTIVE_JOBS:
            raise RuntimeError(f"Creator audio concurrency limit reached: {MUSIC_AI_MAX_ACTIVE_JOBS} active or uncertain job(s). Refresh recent jobs before trying again.")
        workflows=await music_ai_list_workflows()
        workflow=next((row for row in workflows if str(row.get("slug") or "")==slug),None)
        if not workflow:
            raise ValueError("That workflow slug was not returned by the configured account. Refresh Workflows and use an exact slug.")
        workflow_allowed,workflow_reason=music_ai_workflow_policy(workflow)
        if not workflow_allowed:
            raise PermissionError(workflow_reason)
        filename=str(getattr(attachment,"filename","audio.bin"))[:120]
        reservation=f"pending-{uuid.uuid4().hex}"
        await db.execute("INSERT INTO manifest_music_ai_jobs(job_id,actor_id,guild_id,channel_id,workflow,filename,status,result_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)",
            (reservation,MAKER_USER_ID,int(guild_id or 0),int(channel_id or 0),slug,filename,"SUBMITTING","{}",now,now))
        post_attempted=False
        try:
            uploaded=await music_ai_upload_attachment(attachment)
            job_params=dict(params)
            job_params["inputUrl"]=uploaded["download_url"]
            job_name=str(name or f"Manifest · {slug}")[:100]
            post_attempted=True
            created=await music_ai_request("POST","job",payload={"name":job_name,"workflow":slug,"params":job_params,"metadata":{"source":"Manifest Creator Audio Studio"}},timeout=35)
            job_id=str(created.get("id") or "")
            if not re.fullmatch(r"[A-Fa-f0-9-]{30,40}",job_id):
                raise RuntimeError("Audio workflow API did not return a valid job identifier.")
            persisted=await db.execute("UPDATE manifest_music_ai_jobs SET job_id=?,filename=?,status='QUEUED',updated_at=? WHERE job_id=? AND actor_id=?",
                (job_id,uploaded["filename"],time.time(),reservation,MAKER_USER_ID))
            if int(getattr(persisted,"rowcount",0) or 0)!=1:
                raise RuntimeError("The provider accepted a job, but Manifest could not verify its durable reservation. The submission is retained as uncertain to prevent an accidental duplicate charge.")
            try:
                await creator_control_receipt("audio_job_submit","","accepted","Audio workflow job queued; provider completion is pending.",{"job_id":job_id,"workflow":slug,"filename":uploaded["filename"],"bytes":uploaded["bytes"],"payload_fingerprint":str(payload_fingerprint or "unavailable"),"media_rights_and_required_consents_attested":True})
            except Exception:
                # The job row is already committed. Receipt failure must not turn a
                # real provider acceptance into a false "not submitted" message.
                log.exception("Music.AI job accepted and persisted, but its Creator receipt could not be written")
            return {"id":job_id,"workflow":slug,"filename":uploaded["filename"],"bytes":uploaded["bytes"]}
        except Exception:
            state="SUBMISSION_UNKNOWN" if post_attempted else "FAILED"
            try:await db.execute("UPDATE manifest_music_ai_jobs SET status=?,updated_at=? WHERE job_id=?",(state,time.time(),reservation))
            except Exception:log.exception("Could not finalize audio job reservation")
            if post_attempted:
                log.error("Music.AI submission outcome is uncertain; reservation retained to prevent accidental duplicate billing.")
            raise


async def music_ai_submit_creation_job(*,workflow_slug,name,params,actor_id=None,guild_id=0,channel_id=0,payload_fingerprint=None):
    """Submit a creation-oriented account workflow without pretending its schema.

    This route is only eligible when the authenticated workflow catalog itself marks
    the workflow as creation/generation oriented. The Creator supplies the exact JSON
    parameters defined by that private workflow; Manifest does not guess parameter keys.
    """
    if int(actor_id or 0)!=MAKER_USER_ID:raise PermissionError("Only the Creator & Owner can submit private creation workflows.")
    if not music_ai_configured():
        _,reason=music_ai_gate_status();raise RuntimeError(reason)
    slug=str(workflow_slug or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._/-]{0,159}",slug):raise ValueError("Invalid workflow slug.")
    params=music_ai_validate_json_params(params if isinstance(params,dict) else {})
    if not params:raise ValueError("Creation workflows require the exact workflow parameters; Manifest will not guess an empty schema.")
    async with MUSIC_AI_JOB_LOCK:
        now=time.time();cutoff=now-86400
        daily=await db.one("SELECT COUNT(*) n FROM manifest_music_ai_jobs WHERE actor_id=? AND created_at>=? AND status NOT IN ('FAILED','CANCELLED','CANCELED')",(MAKER_USER_ID,cutoff))
        active=await db.one("SELECT COUNT(*) n FROM manifest_music_ai_jobs WHERE actor_id=? AND status IN ('SUBMITTING','SUBMISSION_UNKNOWN','QUEUED','STARTED','RUNNING')",(MAKER_USER_ID,))
        if int(daily['n'] or 0)>=MUSIC_AI_DAILY_JOB_LIMIT:raise RuntimeError(f"Creator audio limit reached: {MUSIC_AI_DAILY_JOB_LIMIT} accepted or uncertain submissions per rolling 24 hours.")
        if int(active['n'] or 0)>=MUSIC_AI_MAX_ACTIVE_JOBS:raise RuntimeError(f"Creator audio concurrency limit reached: {MUSIC_AI_MAX_ACTIVE_JOBS} active or uncertain job(s). Refresh recent jobs before trying again.")
        workflows=await music_ai_list_workflows();workflow=next((row for row in workflows if str(row.get("slug") or "")==slug),None)
        if not workflow:raise ValueError("That workflow slug was not returned by the configured account. Refresh Creation Map and use an exact slug.")
        allowed,reason=music_ai_workflow_policy(workflow)
        if not allowed:raise PermissionError(reason)
        if not music_ai_is_creation_workflow(workflow):raise ValueError("That catalog entry is not clearly marked as a creation/generation workflow. Use the normal audio-processing route instead.")
        reservation=f"pending-{uuid.uuid4().hex}";job_name=str(name or f"Manifest Create · {slug}")[:100]
        await db.execute("INSERT INTO manifest_music_ai_jobs(job_id,actor_id,guild_id,channel_id,workflow,filename,status,result_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)",(reservation,MAKER_USER_ID,int(guild_id or 0),int(channel_id or 0),slug,"[creation workflow]","SUBMITTING","{}",now,now))
        post_attempted=False
        try:
            post_attempted=True
            created=await music_ai_request("POST","job",payload={"name":job_name,"workflow":slug,"params":params,"metadata":{"source":"Manifest Creator Audio Studio","mode":"creation"}},timeout=35)
            job_id=str(created.get("id") or "")
            if not re.fullmatch(r"[A-Fa-f0-9-]{30,40}",job_id):raise RuntimeError("Audio workflow API did not return a valid job identifier.")
            persisted=await db.execute("UPDATE manifest_music_ai_jobs SET job_id=?,status='QUEUED',updated_at=? WHERE job_id=? AND actor_id=?",(job_id,time.time(),reservation,MAKER_USER_ID))
            if int(getattr(persisted,"rowcount",0) or 0)!=1:raise RuntimeError("The provider accepted a creation job, but Manifest could not verify its durable reservation. It remains uncertain to prevent accidental duplicate billing.")
            try:await creator_control_receipt("audio_creation_submit","","accepted","Creation workflow queued; provider completion is pending.",{"job_id":job_id,"workflow":slug,"payload_fingerprint":str(payload_fingerprint or "unavailable")})
            except Exception:log.exception("Music.AI creation job accepted and persisted, but its Creator receipt could not be written")
            return {"id":job_id,"workflow":slug}
        except Exception:
            state="SUBMISSION_UNKNOWN" if post_attempted else "FAILED"
            try:await db.execute("UPDATE manifest_music_ai_jobs SET status=?,updated_at=? WHERE job_id=?",(state,time.time(),reservation))
            except Exception:log.exception("Could not finalize creation job reservation")
            if post_attempted:log.error("Music.AI creation submission outcome is uncertain; reservation retained to prevent accidental duplicate billing.")
            raise

async def music_ai_get_job(job_id):
    if not re.fullmatch(r"[A-Fa-f0-9-]{30,40}",str(job_id or "")): raise ValueError("Invalid audio job identifier.")
    data = await music_ai_request("GET",f"job/{job_id}",timeout=25)
    status = str(data.get("status") or "unknown").upper()[:40]
    result = data.get("result") if isinstance(data.get("result"), dict) else {}
    await db.execute("UPDATE manifest_music_ai_jobs SET status=?,result_json=?,updated_at=? WHERE job_id=?",
        (status, json.dumps(result, ensure_ascii=False, separators=(",", ":"))[:12000], time.time(), str(job_id)))
    return data


@manifest_control_group.command(name="audio_workflows", description="List workflows available to the configured audio-processing account")
async def creator_control_audio_workflows(interaction: discord.Interaction):
    if not creator_control_is_owner(interaction.user): return await interaction.response.send_message("Creator & Owner only.",ephemeral=True)
