        e=discord.Embed(title="Audio Workflow Job",description=f"Job `{data.get('id') or job_id}` · **{status}**",color=discord.Color.green() if status=="SUCCEEDED" else discord.Color.orange())
        e.add_field(name="Workflow",value=str(data.get("workflow") or "unknown")[:200],inline=True)
        e.add_field(name="Created",value=str(data.get("createdAt") or "unknown")[:100],inline=True)
        result=data.get("result") if isinstance(data.get("result"),dict) else {}
