# ========================= MANIFEST OPERATIONS =========================
def _is_silly_dev_authorized(user_id:int)->bool:
    """Private workspace identity is explicit and separate from Discord bot ownership."""
    try:return int(user_id) in SILLY_DEV_AUTHORIZED_IDS
    except Exception:return False

def _is_verified_dev(user_id:int)->bool:
    return int(user_id) in OWNER_IDS or int(user_id) in DEV_USER_IDS

async def _has_manifest_dev_role(member:discord.Member)->bool:
    if not member or not member.guild: return False
    try: rid=int(await db.setting(member.guild.id,"developer_role_id",0) or 0)
    except Exception: rid=0
    return bool(rid and any(r.id==rid for r in getattr(member,"roles",())))

async def manifest_dev(member:discord.Member)->bool:
    # Global Manifest diagnostics are identity-bound. Capability checks decide which global surfaces each team role may use.
    # A server-local role must never manufacture global bot-operations authority.
    return bool(member and _is_verified_dev(member.id))

async def manifest_server_operator(member:discord.Member)->bool:
    # Final authority audit: Manifest-team identity and cosmetic/local developer roles
    # NEVER manufacture guild authority. Server-changing/configuration operations
    # require live Discord owner/Admin/Manage Server authority.
    if not member or not member.guild: return False
    p=member.guild_permissions
    return bool(member.id==member.guild.owner_id or p.administrator or p.manage_guild)

def loop_state(loop):
    try:
        if loop is None: return "missing"
        if loop.is_being_cancelled(): return "cancelled"
        if loop.is_running(): return "running"
        return "stopped"
    except Exception: return "unknown"

def op_task_rows():
    return [(n,loop_state(globals().get(n))) for n in (
        "autopilot_loop", "giveaway_loop", "reminder_loop",
        "quarantine_reconciliation_loop", "diagnostics_loop", "silly_dev_scout_loop"
    )]

def _safe_diag_text(value,limit=700):
    return redact_sensitive_text(value,limit=limit)

def new_trace_id(): return "M-"+uuid.uuid4().hex[:8].upper()

async def diag_trace_start(subsystem,operation,guild_id=0,user_id=0):
    tid=new_trace_id(); now=time.time()
    await db.execute("INSERT INTO diagnostic_traces(trace_id,guild_id,user_id,subsystem,operation,status,stages_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)",(tid,guild_id or 0,user_id or 0,subsystem,operation,'started','[]',now,now))
    return tid

async def diag_trace_stage(trace_id,stage,ok=True,detail=""):
    row=await db.one("SELECT stages_json FROM diagnostic_traces WHERE trace_id=?",(trace_id,))
    try: stages=json.loads(row['stages_json'] or '[]') if row else []
    except Exception: stages=[]
    stages.append({'stage':str(stage)[:80],'ok':bool(ok),'detail':_safe_diag_text(detail,250),'at':time.time()})
    await db.execute("UPDATE diagnostic_traces SET stages_json=?,updated_at=? WHERE trace_id=?",(json.dumps(stages,separators=(',',':')),time.time(),trace_id))

async def diag_issue(subsystem,error,severity='error',guild_id=0,trace_id=''):
    et=type(error).__name__ if isinstance(error,BaseException) else 'OperationalError'
    summary=_safe_diag_text(error,700)
    normalized=re.sub(r"^\d{4}-\d{2}-\d{2}[^|]*\|\s*", "", summary)
    fp=hashlib.sha256(f"{subsystem}|{et}|{normalized[:240]}".encode()).hexdigest()[:24]
    now=time.time()
    await db.execute("""INSERT INTO diagnostic_issues(fingerprint,subsystem,severity,error_type,summary,first_seen,last_seen,occurrences,last_guild_id,last_trace_id,status)
      VALUES(?,?,?,?,?,?,?,?,?,?, 'open') ON CONFLICT(fingerprint) DO UPDATE SET last_seen=excluded.last_seen,occurrences=diagnostic_issues.occurrences+1,last_guild_id=excluded.last_guild_id,last_trace_id=excluded.last_trace_id,summary=excluded.summary,status='open'""",
      (fp,subsystem,severity,et,summary,now,now,1,guild_id or 0,trace_id or ''))
    if trace_id:
        await db.execute("UPDATE diagnostic_traces SET status='failed',error_type=?,error_summary=?,updated_at=? WHERE trace_id=?",(et,summary,now,trace_id))
    # Critical diagnostics are owner-notified through the centralized DM engine.
    # The dedupe key prevents a repeating watchdog failure from spamming owners.
    if str(severity).lower() == 'critical':
        try:
            await manifest_notify_owners('critical',f"Subsystem: **{subsystem}**\nError: **{et}**\n{summary[:1200]}",subject='🚨 Manifest Critical Diagnostic',guild_id=guild_id,dedupe_key=fp,cooldown=900)
        except Exception:
            log.exception('Critical owner notification failed')
    return fp

async def diag_trace_finish(trace_id,status='success'):
    await db.execute("UPDATE diagnostic_traces SET status=?,updated_at=? WHERE trace_id=?",(status,time.time(),trace_id))

async def deep_health_snapshot():
    checks=[]
    checks.append(('gateway','operational' if bot.is_ready() and not bot.is_closed() else 'unavailable',f'{round(bot.latency*1000)}ms'))
    try:
        await db.one('SELECT 1'); checks.append(('database','operational','read ok'))
        row=await db.one('PRAGMA integrity_check'); val=(list(row)[0] if row else 'unknown'); checks.append(('db_integrity','operational' if str(val).lower()=='ok' else 'degraded',str(val)))
    except Exception as ex: checks.append(('database','unavailable',type(ex).__name__))
    for name,state in op_task_rows(): checks.append((name,'operational' if state=='running' else 'degraded',state))
    primary_ready=bool(ai)
    secondary_ready=bool(CLOUDFLARE_API_TOKEN and CLOUDFLARE_ACCOUNT_ID)
    specialist_ready=bool(xai)
    configured_routes=sum((primary_ready,secondary_ready,specialist_ready,bool(OPENROUTER_API_KEY)))
    checks.append(('manifest_intelligence','configured' if configured_routes else 'not_configured',f'{configured_routes} private route(s) configured'))
    open_errors=await db.one("SELECT COUNT(*) c FROM diagnostic_issues WHERE status='open'")
    checks.append(('error_inbox','operational' if not open_errors or open_errors['c']==0 else 'degraded',f"{open_errors['c'] if open_errors else 0} open"))
    return checks

@manifest_diag_group.command(name="health",description="Show Manifest health and background task status")
async def manifest_health(i:discord.Interaction):
    if not await manifest_dev(i.user): return await i.response.send_message("⚠️ Manifest health diagnostics are restricted to the verified Manifest team.",ephemeral=True)
    await i.response.defer(ephemeral=True)
    checks=[]
    checks.append(("Discord Gateway", "🟢 Connected" if bot.is_ready() and not bot.is_closed() else "🔴 Offline"))
    try:
        await db.one("SELECT 1")
        checks.append(("Database", "🟢 Healthy"))
        checks.append(("Schema", "🟢 Self-healed / verified" if db.schema_ready else "🟠 Not verified"))
    except Exception as e:
        checks.append(("Database", f"🔴 Failed: {type(e).__name__}"))
        checks.append(("Schema", "🔴 Unavailable"))
    for name,state in op_task_rows(): checks.append((name.replace("_"," ").title(), "🟢 "+state if state=="running" else "🔴 "+state))
    e=discord.Embed(title=f"🩺 Manifest Health • V{VERSION}",description="\n".join(f"**{a}:** {b}" for a,b in checks),color=discord.Color.green() if all("🟢" in x[1] for x in checks) else discord.Color.orange())
    e.add_field(name="Connected Guilds",value=str(len(bot.guilds))); e.add_field(name="Latency",value=f"{round(bot.latency*1000)} ms")
    e.set_footer(text="Operational details are restricted to authorized operators.")
    await i.followup.send(embed=e,ephemeral=True)

