@manifest_diag_group.command(name="errors",description="Show grouped Manifest diagnostic issues")
async def manifest_errors(i:discord.Interaction,limit:int=15):
    if not await manifest_dev(i.user): return await i.response.send_message("⚠️ Verified Manifest team access required.",ephemeral=True)
    limit=max(1,min(limit,25)); rows=await db.all("SELECT * FROM diagnostic_issues WHERE status='open' ORDER BY last_seen DESC LIMIT ?",(limit,))
    if not rows: return await i.response.send_message("✅ **Error Inbox** — no open persisted diagnostic issues.",ephemeral=True)
    lines=[]
    for r in rows:
        trace=f" • `{r['last_trace_id']}`" if r['last_trace_id'] else ''
        lines.append(f"• **{r['subsystem']}** · {r['error_type']} · ×{r['occurrences']}{trace}\n  {_safe_diag_text(r['summary'],180)}")
    await i.response.send_message(("🚨 **Manifest Error Inbox**\n"+"\n".join(lines))[:4000],ephemeral=True)

@manifest_diag_group.command(name="trace",description="Inspect one Manifest diagnostic trace")
async def manifest_trace(i:discord.Interaction,trace_id:str):
    if not await manifest_dev(i.user): return await i.response.send_message("⚠️ Verified Manifest team access required.",ephemeral=True)
    tid=trace_id.strip().upper(); row=await db.one("SELECT * FROM diagnostic_traces WHERE trace_id=?",(tid,))
    if not row:return await i.response.send_message("Trace not found or already expired.",ephemeral=True)
    try: stages=json.loads(row['stages_json'] or '[]')
    except Exception: stages=[]
    lines=[f"{'✓' if x.get('ok') else '✗'} {x.get('stage')}"+(f" — {x.get('detail')}" if x.get('detail') else '') for x in stages]
    txt=f"🔎 **{tid}** · {row['subsystem']} / {row['operation']}\nStatus: **{row['status']}**\n"+"\n".join(lines)
    if row['error_summary']: txt+=f"\n\n**Error:** {_safe_diag_text(row['error_summary'],600)}"
    await i.response.send_message(txt[:4000],ephemeral=True)

