        check("conversation recent-window", getattr(probe,'maxlen',0)==50, f"maxlen={getattr(probe,'maxlen',None)}")
        history.pop(probe_key,None)
        check("runtime resilience engine", callable(supervise_task) and callable(manifest_http_session) and callable(_ai_provider_allowed), "task supervision, pooled HTTP, provider circuits wired")
        creator_rows=await db.all("SELECT name FROM sqlite_master WHERE type='table' AND name IN ('creator_policies','creator_projects','creator_versions','creator_audit','creator_invocations','creator_game_scores','creator_form_submissions','manifest_log_routes')")
