        check("External provider endpoint safety",callable(_trusted_external_endpoint) and "_trusted_external_endpoint" in ocr_space_image.__code__.co_names and "apikey" in ocr_space_image.__code__.co_consts and "_trusted_external_endpoint" in assemblyai_transcribe.__code__.co_names,"Protected API credentials use the approved HTTPS endpoints and OCR.space's documented API-key header")
        check("Feature integrity audit",callable(manifest_feature_audit) and callable(manifest_feature_audit_embed),"Runtime command tree and optional integration inventory are inspectable")
        check("Command discovery privacy",manifest_command_is_creator_only("manifest control audio_run") and manifest_command_is_creator_only("manifest diagnostics regression") and not manifest_command_is_creator_only("music play"),"Creator hosting/diagnostics routes are hidden from non-Creator command discovery")
