@manifest_diag_group.command(name="doctor",description="Diagnose Manifest configuration and background systems")
async def manifest_doctor(i:discord.Interaction):
    if not await manifest_dev(i.user): return await i.response.send_message("⚠️ Verified Manifest team access required.",ephemeral=True)
    await i.response.defer(ephemeral=True)
    issues=[]; ok=[]
    try:
        await db.one("SELECT 1")
        ok.append("Database reachable")
        required={"tickets","action_receipts","diagnostic_issues","diagnostic_traces","automation_rules"}
        rows=await db.all("SELECT name FROM sqlite_master WHERE type='table'")
        present={str(r['name']) for r in rows}
        missing=sorted(required-present)
        if missing: issues.append("Missing core tables: "+", ".join(missing))
        else: ok.append("Core diagnostic/action tables present")
    except Exception as e:
        issues.append(f"Database/schema check failed: {type(e).__name__}: {e}")
    if not bot.is_ready(): issues.append("Discord gateway is not ready")
    else: ok.append("Discord gateway ready")
    for n,state in op_task_rows(): (ok if state=="running" else issues).append(f"{n}: {state}")
    active_bg=sum(1 for t in _manifest_background_tasks if not t.done())
    ok.append(f"Supervised one-shot background tasks: {active_bg}")
    now=time.time()
    open_circuits=[state for state in _ai_provider_state.values() if float(state.get('opened_until',0) or 0)>now]
    if open_circuits: issues.append(f"Manifest Intelligence has {len(open_circuits)} temporarily isolated route(s)")
    else: ok.append("Manifest Intelligence routing healthy")
    me=i.guild.me
    needed=("view_channel","send_messages","read_message_history")
    missing=[x.replace("_"," ") for x in needed if not getattr(me.guild_permissions,x,False)] if me else list(needed)
    if missing: issues.append("Missing core permissions: "+", ".join(missing))
    else: ok.append("Core channel permissions available")
    text="🩺 **Manifest Doctor**\n\n"+"\n".join("🟢 "+x for x in ok)
    if issues: text+="\n\n⚠️ **Issues**\n"+"\n".join("• "+x for x in issues)
    else: text+="\n\n✅ No immediate operational issues detected."
    await i.followup.send(text[:4000],ephemeral=True)

async def _channel_reference_exists(guild_id:int, channel_id:int):
    """Return True/False for a live guild channel reference, None if unverifiable."""
    guild=bot.get_guild(int(guild_id))
    if not guild:return None
    channel=guild.get_channel(int(channel_id))
    if channel is not None:return True
    try:
        channel=await guild.fetch_channel(int(channel_id))
        return bool(channel and getattr(getattr(channel,'guild',None),'id',None)==int(guild_id))
    except discord.NotFound:
        return False
    except (discord.Forbidden,discord.HTTPException):
        return None
    except Exception:
        return None

async def cross_system_integrity_snapshot():
    """Read-only lifecycle/integrity audit across Manifest. Never repairs Discord state by itself."""
    findings=[]; ok=[]
    try:
        row=await db.one("PRAGMA quick_check")
        value=(list(row)[0] if row else "unknown")
        (ok if str(value).lower()=="ok" else findings).append(("database", "SQLite quick_check: "+str(value)))
    except Exception as ex: findings.append(("database", f"Integrity check failed: {type(ex).__name__}"))
    for name,state in op_task_rows():
        if state=="running": ok.append(("worker",f"{name} running"))
        else: findings.append(("worker",f"{name} is {state}"))
    try:
        rows=await db.all("SELECT channel_id,guild_id,id FROM tickets WHERE status='open' ORDER BY created_at DESC LIMIT 30")
        missing=0;unknown=0
        for r in rows:
            if not r['channel_id']:missing+=1;continue
            state=await _channel_reference_exists(int(r['guild_id'] or 0),int(r['channel_id']))
            if state is False:missing+=1
            elif state is None:unknown+=1
        if missing:findings.append(("tickets",f"{missing} open ticket record(s) point to channels that could not be found in live Discord state"))
        if unknown:findings.append(("tickets",f"{unknown} open ticket channel reference(s) could not be verified because Discord access was unavailable"))
        if not missing and not unknown:ok.append(("tickets","Open ticket channel references were verified against live Discord state"))
    except Exception as ex:findings.append(("tickets",f"Lifecycle audit failed: {type(ex).__name__}"))
    try:
        rows=await db.all("SELECT id,channel_id,message_id,guild_id FROM giveaways WHERE status='active' ORDER BY id DESC LIMIT 30")
        missing=0;unknown=0
        for r in rows:
            if not r['channel_id']:missing+=1;continue
            state=await _channel_reference_exists(int(r['guild_id'] or 0),int(r['channel_id']))
            if state is False:missing+=1
            elif state is None:unknown+=1
        if missing:findings.append(("giveaways",f"{missing} active giveaway(s) point to channels that could not be found in live Discord state"))
        if unknown:findings.append(("giveaways",f"{unknown} active giveaway channel reference(s) could not be verified because Discord access was unavailable"))
        if not missing and not unknown:ok.append(("giveaways","Active giveaway channel references were verified against live Discord state"))
    except Exception as ex:findings.append(("giveaways",f"Lifecycle audit failed: {type(ex).__name__}"))
    try:
        r=await db.one("SELECT COUNT(*) c FROM runtime_failures WHERE created_at>=?",(time.time()-86400,))
        n=int(r['c'] if r else 0)
        if n: findings.append(('runtime',f"{n} unhandled Discord event failure(s) recorded in the last 24h"))
        else: ok.append(('runtime','No unhandled Discord event failures recorded in the last 24h'))
    except Exception as ex: findings.append(('runtime',f"Runtime failure audit failed: {type(ex).__name__}"))
    try:
        r=await db.one("SELECT COUNT(*) c FROM diagnostic_issues WHERE status='open'")
        n=int(r['c'] if r else 0)
        if n: findings.append(("diagnostics",f"{n} grouped diagnostic issue(s) remain open"))
        else: ok.append(("diagnostics","No open grouped diagnostic issues"))
    except Exception as ex: findings.append(("diagnostics",f"Inbox audit failed: {type(ex).__name__}"))
    # Final reconstruction audit: inspect persisted lifecycles without mutating them.
    lifecycle_checks=(
        ("reminders", "SELECT COUNT(*) c FROM reminders WHERE status IN ('pending','retry') AND due_at<?", (time.time()-300,), "overdue reminder(s) are still pending"),
        ("announcements", "SELECT COUNT(*) c FROM scheduled_announcements WHERE status IN ('scheduled','retry') AND due_at<?", (time.time()-300,), "overdue scheduled announcement(s) are still pending"),
        ("staff", "SELECT COUNT(*) c FROM staff_absences WHERE status='active' AND ends_at>0 AND ends_at<?", (time.time()-3600,), "staff absence(s) passed their end time but remain active"),
        ("security", "SELECT COUNT(*) c FROM security_incidents WHERE lower(state) NOT IN ('resolved','closed') AND updated_at<?", (time.time()-7*86400,), "security incident(s) have been unresolved for more than 7 days"),
        ("games", "SELECT COUNT(*) c FROM game_sessions WHERE status IN ('lobby','active') AND updated_at<?", (time.time()-6*3600,), "game session(s) appear stale"),
    )
    for area,query,args,label in lifecycle_checks:
        try:
            r=await db.one(query,args); n=int(r['c'] if r else 0)
            if n: findings.append((area,f"{n} {label}"))
            else: ok.append((area,f"No {label}"))
        except Exception as ex:
            # A schema mismatch here is itself a reconstruction blocker, not something to hide.
            findings.append((area,f"Lifecycle audit unavailable: {type(ex).__name__}: {_safe_diag_text(ex,120)}"))
    try:
        bad=0
        rows=await db.all("SELECT guild_id,conditions_json,payload_json FROM automation_rules WHERE enabled=1")
        for r in rows:
            try:
                cond=json.loads(r['conditions_json'] or '{}'); payload=json.loads(r['payload_json'] or '{}')
                cid=int(payload.get('channel_id') or cond.get('channel_id') or 0)
                if cid and bot.get_channel(cid) is None: bad+=1
            except Exception: bad+=1
        if bad: findings.append(("automations",f"{bad} enabled automation reference/configuration problem(s) detected"))
        else: ok.append(("automations","Enabled automation references/configuration look valid"))
    except Exception as ex: findings.append(("automations",f"Lifecycle audit unavailable: {type(ex).__name__}: {_safe_diag_text(ex,120)}"))
    return ok,findings

@manifest_diag_group.command(name="integrity",description="Audit Manifest lifecycle consistency without changing server state")
async def manifest_integrity(i:discord.Interaction):
    if not await manifest_dev(i.user): return await i.response.send_message("⚠️ Manifest integrity diagnostics are restricted to the verified Manifest team.",ephemeral=True)
    await i.response.defer(ephemeral=True)
    ok,findings=await cross_system_integrity_snapshot()
    lines=["🧩 **Manifest Cross-System Integrity**",f"Checks passed: **{len(ok)}** · Findings: **{len(findings)}**"]
    if findings:
        lines += ["","**Needs attention**"]+[f"⚠️ **{area.title()}** — {detail}" for area,detail in findings[:20]]
    else: lines += ["","✅ No cross-system lifecycle inconsistencies detected by this read-only audit."]
    lines += ["","This check is read-only; it does not alter Discord roles, permissions, channels, or member state."]
    await i.followup.send("\n".join(lines)[:4000],ephemeral=True)


@manifest_ops_group.command(name="legacy_usage",description="Show which requests still depend on Manifest compatibility routing")
async def manifest_legacy_usage(i:discord.Interaction, hours:int=168):
    if not await manifest_dev(i.user): return await i.response.send_message("⚠️ Verified Manifest team access required.",ephemeral=True)
    hours=max(1,min(hours,24*30)); since=time.time()-hours*3600
    rows=await db.all("SELECT route,COUNT(*) c,MAX(created_at) last_seen FROM legacy_route_usage WHERE created_at>=? GROUP BY route ORDER BY c DESC",(since,))
    total=sum(int(r['c']) for r in rows)
    if not rows: return await i.response.send_message(f"✅ No compatibility-router hits recorded in the last **{hours}h**.",ephemeral=True)
    lines=[f"🧭 **Legacy Compatibility Usage · {hours}h**",f"Total fallback hits: **{total}**",""]
    lines += [f"• **{r['route']}** — {r['c']} hit(s)" for r in rows]
    lines += ["","This is migration telemetry only. It helps us remove old routing after runtime testing instead of deleting dependencies blindly."]
    await i.response.send_message("\n".join(lines)[:4000],ephemeral=True)

@manifest_diag_group.command(name="readiness",description="Check whether this build is ready for Discord runtime testing")
async def manifest_readiness(i:discord.Interaction):
    if not await manifest_dev(i.user): return await i.response.send_message("⚠️ Manifest readiness diagnostics are restricted to the verified Manifest team.",ephemeral=True)
    await i.response.defer(ephemeral=True)
    ok,findings=await cross_system_integrity_snapshot()
    health=await deep_health_snapshot()
    blockers=[]; warnings=[]
    for area,detail in findings:
        low=detail.lower()
        if area in {'database','worker'} or 'unavailable' in low or 'failed' in low:
            blockers.append((area,detail))
        else: warnings.append((area,detail))
    for name,state,detail in health:
        if state not in {'operational','ok','running'}:
            (blockers if name in {'database','gateway'} else warnings).append((name,detail or state))
    state='BLOCKED' if blockers else ('READY WITH WARNINGS' if warnings else 'READY FOR RUNTIME TESTING')
    lines=[f"🚦 **Manifest Runtime Readiness — {state}**",f"Passed checks: **{len(ok)}** · Blockers: **{len(blockers)}** · Warnings: **{len(warnings)}**"]
    if blockers:
        lines += ['', '**Blockers**']+[f"🔴 **{a.title()}** — {d}" for a,d in blockers[:10]]
    if warnings:
        lines += ['', '**Warnings**']+[f"🟠 **{a.title()}** — {d}" for a,d in warnings[:10]]
    if not blockers:
        lines += ['', 'This means the static/persisted checks found no deployment blocker. It does **not** claim Discord runtime testing has passed.']
    lines += ['', 'Read-only check: no roles, channels, permissions, members, or server settings were changed.']
    await i.followup.send("\n".join(lines)[:4000],ephemeral=True)

async def manifest_preflight_self_test():
    """Read-only reconstruction preflight. It validates wiring, not live Discord mutations."""
    checks=[]
    def add(name,ok,detail=""):
        checks.append((str(name),bool(ok),_safe_diag_text(detail,220)))

    # Identity invariants: global team identity must never silently drift into guild authority.
    add("owner identity", set(OWNER_IDS)=={1386055253581103164,1299310732390961173} and manifest_authority_rank(MAKER_USER_ID)>manifest_authority_rank(CO_OWNER_ID), "Creator/Owner outranks Co-Owner; authority is capability-based")
    add("developer identity", bool(DEV_USER_IDS) or not DEV_USER_IDS, "developer access is explicitly configured (or intentionally owner-only)")

    # Core persistence required by the reconstructed lifecycle systems.
    required_tables={
        'tickets','ticket_events','giveaways','giveaway_events','reminders','scheduled_announcements',
        'security_incidents','quarantine_snapshots','staff_absences','staff_tasks','automation_rules',
        'automation_runs','diagnostic_issues','diagnostic_traces','system_health','server_snapshots',
        'game_sessions','game_players','game_config','game_daily_progress','event_rsvps','role_panels','role_panel_options','xp_events','invite_events','startup_reconciliation','integration_registry'
    }
    try:
        rows=await db.all("SELECT name FROM sqlite_master WHERE type='table'")
        present={str(r['name']) for r in rows}
        missing=sorted(required_tables-present)
        add("reconstruction schema",not missing,"missing: "+", ".join(missing) if missing else f"{len(required_tables)} critical tables present")
    except Exception as ex:
        add("reconstruction schema",False,f"{type(ex).__name__}: {ex}")

    # Command-tree wiring. This catches a surprisingly easy failure mode in one-file builds:
    # a feature exists in Python but its group was never attached to the tree.
    try:
        names={getattr(c,'name','') for c in bot.tree.get_commands()}
        required_groups={'manifest','server','security','staff','community','games','automation'}
        missing=sorted(required_groups-names)
        add("command tree",not missing,"missing groups: "+", ".join(missing) if missing else "core groups attached")
    except Exception as ex:
        add("command tree",False,f"{type(ex).__name__}: {ex}")

    # Capability coverage: a registry entry is not proof that the feature is wired.
    # Each deterministic family must have at least one concrete implementation anchor
    # (function, command-group symbol, or persistence table). This is deliberately
    # read-only and flags gaps instead of deleting/quarantining anything.
    capability_anchors={
        "reminders": ("reminder_group", "reminder_loop", "reminders"),
        "afk": ("set_afk", "afk_status"),
        "birthdays": ("birthdays", "birthday_loop"),
        "moderation": ("moderation_group", "permission_plan"),
        "roles": ("role_group", "custom_role_group", "custom_roles"),
        "channels": ("server_group", "channel_group", "permission_plan"),
        "tickets": ("open_ticket_capability", "close_ticket_capability", "tickets"),
        "security": ("security_status", "security_event", "security_incidents"),
        "server_insights": ("server_pulse_report", "server_pulse_command"),
        "server_memory": ("_memory_upsert", "memory_items", "memories"),
        "play": ("game_play", "game_guess", "game_daily_progress", "game_sessions"),
        "giveaways": ("create_giveaway", "community_giveaway", "giveaways"),
        "staff_intelligence": ("staff_review", "staff_policy", "staff_tasks"),
        "notifications": ("manifest_notify_user", "manifest_notify_owners", "manifest_notifications"),
        "autoresponders": ("autoresponder_group", "autoresponders"),
        "guardian": ("security_event", "open_security_incident", "security_incidents"),
        "emoji_management": ("emoji_group", "emoji"),
        "music_playback_gui": ("MusicPlayerView", "MusicPlayModal", "music_panel_embed"),
        "music_session_governance": ("manifest_music_settings", "music_control_allowed", "MusicSettingsView", "music_settings_command"),
        "music_history": ("manifest_music_history", "manifest_music_track_start", "music_history_command"),
        "music_search_picker": ("MusicSearchResultView", "resolve_music_candidates", "music_play"),
        "logging_command_center": ("ManifestLogsPanelView", "manifest_logs_panel_embed", "logs_panel"),
        "creator_audio_processing": ("CreatorAudioStudioView", "music_ai_submit_attachment_job", "music_ai_submit_creation_job", "manifest_music_ai_jobs"),
        "analytics": ("manifest_analytics_snapshot", "guild_daily_metrics", "daily_active_users"),
        "support_intelligence": ("manifest_support_intelligence_snapshot", "tickets"),
        "play_seasons": ("game_season_scores", "game_season_key", "send_game_season_leaderboard"),
        "play_tournaments": ("game_tournaments", "GameTournamentView", "send_active_game_tournament"),
        "server_snapshots": ("live_server_snapshot", "capture_server_snapshot", "server_snapshots"),
        "setup_intelligence": ("manifest_setup_center_embed", "server_doctor_report", "health_score"),
        "feature_integrity": ("manifest_feature_audit", "manifest_command_integrity_report"),
        "creator_control": ("CreatorControlCenterView", "silly_dev_request", "creator_control_is_owner"),
    }
    try:
        source_text=Path(__file__).read_text(encoding="utf-8")
        coverage=[]
        for capability,anchors in capability_anchors.items():
            found=[a for a in anchors if a in source_text]
            if capability not in MANIFEST_CAPABILITIES:
                coverage.append(f"{capability}=unregistered")
            elif found:
                coverage.append(f"{capability}=wired")
            else:
                coverage.append(f"{capability}=missing-anchor")
        gaps=[x for x in coverage if not x.endswith("=wired")]
        add("capability coverage",not gaps,"; ".join(coverage) if not gaps else "Gaps: "+", ".join(gaps))
    except Exception as ex:
        add("capability coverage",False,f"{type(ex).__name__}: {ex}")

    # Deterministic workers must be alive for reminders/giveaways/health even when AI is unavailable.
    workers=op_task_rows()
    stopped=[f"{n}={state}" for n,state in workers if state!='running']
    add("background workers",not stopped,", ".join(stopped) if stopped else f"{len(workers)} workers running")

    # Capability registry should retain the deterministic action layer; AI is not allowed to be the executor.
    try:
        deterministic=[k for k,v in MANIFEST_CAPABILITIES.items() if v.get('deterministic')]
        add("capability registry",bool(deterministic),f"{len(deterministic)} deterministic capability families")
    except Exception as ex:
        add("capability registry",False,f"{type(ex).__name__}: {ex}")

    # AI/image providers are optional for core safety systems, so absence is informational rather than failure.
    add("AI independence",True,"core preflight does not require an AI provider")
    return checks

async def manifest_command_integrity_report():
    """Audit the live command/UI surface so existence is never confused with runtime proof."""
    report={"slash":[],"prefix":[],"groups":[],"issues":[],"ui":{},"workers":op_task_rows()}
    try:
        walked=list(bot.tree.walk_commands())
        for c in walked:
            q=getattr(c,"qualified_name",getattr(c,"name","?"))
            desc=(getattr(c,"description","") or "").strip()
            report["slash"].append(q)
            children=list(getattr(c,"commands",[]) or [])
            if children:
                report["groups"].append((q,len(children)))
                if len(children)>25: report["issues"].append(f"/{q} has {len(children)} immediate children (Discord limit 25)")
            if not children and (not desc or desc.lower() in {"…","...","no description"}):
                report["issues"].append(f"/{q} has no useful description")
        seen=set()
        for q in report["slash"]:
            if q in seen: report["issues"].append(f"duplicate slash command: /{q}")
            seen.add(q)
    except Exception as ex: report["issues"].append(f"slash tree inspection failed: {type(ex).__name__}: {ex}")
    try:
        report["prefix"]=[c.qualified_name for c in bot.walk_commands() if c.name!='help']
    except Exception as ex: report["issues"].append(f"prefix command inspection failed: {type(ex).__name__}: {ex}")
    # Persistent interactive surfaces that must survive restart where appropriate.
    # UI availability is derived from the live command tree/configuration rather
    # than hard-coded True values. A feature being implemented in Python does not
    # mean its interactive surface is actually registered or configured.
    names=set(report["slash"])
    report["ui"]={
        "ticket": any(x.startswith("ticket") for x in names),
        "verification": any(x.startswith("security") and "verify" in x for x in names),
        "giveaway": any("giveaway" in x for x in names),
        "games": any(x.startswith("games") for x in names),
    }
    stopped=[n for n,state in report["workers"] if state!='running']
    if stopped: report["issues"].append("stopped workers: "+", ".join(stopped))
    return report

@manifest_diag_group.command(name="audit",description="Audit every registered command group, worker and major interactive surface")
async def manifest_command_audit(i:discord.Interaction):
    if not await manifest_dev(i.user):return await i.response.send_message("⚠️ Manifest Developer access required.",ephemeral=True)
    await i.response.defer(ephemeral=True)
    r=await manifest_command_integrity_report()
    state="ISSUES FOUND" if r["issues"] else "STRUCTURALLY HEALTHY"
    groups=", ".join(f"/{n} ({c})" for n,c in sorted(r["groups"],key=lambda x:x[0]))
    workers=", ".join(f"{n}={st}" for n,st in r["workers"]) or "none"
    issues="\n".join("• "+x for x in r["issues"][:20]) or "• No structural command/UI/worker issue detected."
    msg=(f"🧪 **Manifest Full Surface Audit — {state}**\n"
         f"Slash/application entries: **{len(r['slash'])}** · Prefix entries: **{len(r['prefix'])}**\n"
         f"Major UI surfaces tracked: **{sum(bool(v) for v in r['ui'].values())}/{len(r['ui'])}**\n\n"
         f"**Group child counts**\n{groups[:1500]}\n\n**Workers**\n{workers}\n\n**Findings**\n{issues}\n\n"
         "This proves registration/wiring checks only. A command is not labelled runtime-tested merely because it appears here.")
    await i.followup.send(msg[:4000],ephemeral=True)

