@manifest_ops_group.command(name="restart",description="Gracefully request a Manifest process restart")
async def manifest_restart(i:discord.Interaction):
    if not manifest_has_global_capability(i.user,"production.shutdown"): return await i.response.send_message("⚠️ Creator & Owner production authority required.",ephemeral=True)
    rid=new_trace_id(); payload=json.dumps({'receipt':rid,'requested_by':i.user.id,'requested_at':time.time(),'completed':False})
    await db.execute("INSERT INTO manifest_runtime_state(key,value,updated_at) VALUES('pending_restart',?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at",(payload,time.time()))
    await i.response.send_message(f"♻️ **Restart requested** · `{rid}`\nI saved the restart receipt and am shutting down cleanly. Completion is only confirmed after a new process reaches ready state; the host must be configured to relaunch Manifest.",ephemeral=True)
    log.warning("Operational restart %s requested by %s (%s)",rid,i.user,i.user.id)
    try: await db.conn.commit()
    except Exception: pass
    await asyncio.sleep(1); await bot.close(); os._exit(0)

