@manifest_dev_group.command(name="approve",description="Approve and apply one low-risk development proposal")
async def manifest_dev_approve_cmd(i:discord.Interaction,job_id:int):
    if i.user.id not in OWNER_IDS or not _is_silly_dev_authorized(i.user.id):
        return await i.response.send_message("⚠️ Global Manifest owner access required.",ephemeral=True)
    await i.response.defer(ephemeral=True)
    row=await db.one("SELECT * FROM manifest_dev_jobs WHERE id=?",(int(job_id),))
    if not row: return await i.followup.send("❌ Development job not found.",ephemeral=True)
    cur=await db.execute("UPDATE manifest_dev_jobs SET status='approved',approved_by=?,updated_at=? WHERE id=? AND status='proposed'",
                         (i.user.id,time.time(),int(job_id)))
    claimed=int(getattr(cur,"rowcount",0) or 0)==1
    try: await cur.close()
    except Exception: pass
    if not claimed:
        fresh=await db.one("SELECT status FROM manifest_dev_jobs WHERE id=?",(int(job_id),))
        return await i.followup.send(f"⚠️ This job is no longer awaiting approval. Current status: **{fresh['status'] if fresh else 'missing'}**. No second apply was started.",ephemeral=True)
    try:
        new_hash=await manifest_dev_apply(job_id,i.user.id)
        await i.followup.send(f"✅ **Local source patch applied and compiled**\nJob `{job_id}` · SHA `{new_hash[:16]}`\nA `.devbak` checkpoint was created. **The SillyDev remote deployment was not changed.**",ephemeral=True)
    except Exception as ex:
        await db.execute("UPDATE manifest_dev_jobs SET status='failed',error=?,updated_at=? WHERE id=? AND status='approved'",
                         (f"{type(ex).__name__}: {ex}"[:700],time.time(),int(job_id))); await db.conn.commit()
        await i.followup.send(f"❌ **Patch refused**\n`{type(ex).__name__}: {_safe_diag_text(ex,600)}`",ephemeral=True)

