MANIFEST_SYSTEM_CATALOG={
    "moderation": {"label":"Moderation","roots":{"mod"},"description":"Warnings, timeouts, kicks, bans, message cleanup and moderation cases."},
    "security": {"label":"Security","roots":{"security"},"description":"Sentinel, Guardian, verification, anti-raid, anti-nuke and recovery."},
    "tickets": {"label":"Support","roots":{"ticket"},"description":"Tickets, claims, support lifecycle and service operations."},
    "community": {"label":"Community","roots":{"community","report","suggestion","waitlist","boost","rules"},"description":"Events, polls, roles, reports, suggestions and community workflows."},
    "play": {"label":"Play","roots":{"games"},"description":"Manifest Play, server games, daily challenges and leaderboards."},
    "creator": {"label":"Creator","roots":{"creator"},"description":"Safe server-built commands, games, forms and Creator Studio."},
    "automation": {"label":"Automation","roots":{"automation","autoresponder","reminder","autopilot"},"description":"Typed automations, responders, reminders and server assistance."},
    "staff": {"label":"Staff","roots":{"staff"},"description":"Staff workload, reviews, leave, tasks and contribution evidence."},
    "brain": {"label":"Server Brain","roots":{"brain"},"description":"Durable server context, FAQ, preferences and server intelligence."},
    "activity": {"label":"Activity","roots":{"activity","level","economy"},"description":"Activity analytics, XP, levels and server engagement."},
    "music": {"label":"Music","roots":{"music"},"description":"Voice playback and queue controls."},
    "utility": {"label":"Utility","roots":{"utility","info","profile","custom_role"},"description":"Information, member tools, utilities and privacy controls."},
    "logs": {"label":"Audit & Logs","roots":{"logs"},"description":"Log routing, audit evidence and operational records."},
    "intelligence": {"label":"Manifest Intelligence","roots":set(),"description":"Current-information and intelligence tools without provider exposure."},
}
MANIFEST_ROOT_TO_SYSTEM={root:key for key,meta in MANIFEST_SYSTEM_CATALOG.items() for root in meta["roots"]}
MANIFEST_ACCESS_MODES={"everyone","roles","selected","staff","managers","disabled"}

class ManifestSystemAccessDenied(app_commands.CheckFailure):
    def __init__(self,message="This Manifest system is not available to your current server role."):
        super().__init__(message); self.public_message=message

async def manifest_system_policy(guild_id:int,system_key:str):
    key=str(system_key or "").strip().lower()
    if key not in MANIFEST_SYSTEM_CATALOG:return {"system_key":key,"enabled":1,"access_mode":"everyone","role_ids":[],"user_ids":[]}
    row=await db.one("SELECT enabled,access_mode,allowed_role_ids_json,allowed_user_ids_json FROM manifest_system_policies WHERE guild_id=? AND system_key=?",(int(guild_id),key))
    if not row:return {"system_key":key,"enabled":1,"access_mode":"everyone","role_ids":[],"user_ids":[]}
    try: roles=[int(x) for x in json.loads(row['allowed_role_ids_json'] or '[]') if str(x).isdigit()]
    except Exception: roles=[]
    try: users=[int(x) for x in json.loads(row['allowed_user_ids_json'] or '[]') if str(x).isdigit()]
    except Exception: users=[]
    mode=str(row['access_mode'] or 'everyone').lower()
    if mode not in MANIFEST_ACCESS_MODES:mode='everyone'
    return {"system_key":key,"enabled":int(row['enabled'] or 0),"access_mode":mode,"role_ids":roles,"user_ids":users}

async def manifest_system_access_allowed(member,system_key:str):
    if not member or not getattr(member,'guild',None):return True,"DM scope"
    # Server management authority always retains access to inspect/reconfigure Manifest.
    if server_manager(member):return True,"Server manager"
    policy=await manifest_system_policy(member.guild.id,system_key)
    if not policy['enabled'] or policy['access_mode']=='disabled':return False,"This Manifest system is disabled for non-managers in this server."
    mode=policy['access_mode']
    if mode=='everyone':return True,"Everyone"
    if mode=='managers':return False,"This Manifest system is restricted to server managers."
    if mode=='staff':
        return (moderator(member),"Staff policy" if moderator(member) else "This Manifest system is restricted to server staff.")
    if mode in {'roles','selected'}:
        member_roles={r.id for r in getattr(member,'roles',[]) or []}
        if member.id in set(policy.get('user_ids') or []):return True,"Selected member"
        if member_roles.intersection(set(policy['role_ids'])):return True,"Allowed role"
        return False,"You are not included in this Manifest system's selected access policy."
    return True,"Default"

def manifest_system_key_for_interaction(interaction):
    qn=str(getattr(getattr(interaction,'command',None),'qualified_name','') or '').strip().lower()
    if not qn:return None
    parts=qn.split()
    # Manifest's own control plane is intentionally not generally gateable. Intelligence is.
    if parts[0]=='manifest':
        if len(parts)>1 and parts[1]=='intelligence':return 'intelligence'
        return None
    return MANIFEST_ROOT_TO_SYSTEM.get(parts[0])

async def manifest_tree_interaction_check(interaction):
    if not interaction.guild:return True
    key=manifest_system_key_for_interaction(interaction)
    if not key:return True
    ok,why=await manifest_system_access_allowed(interaction.user,key)
    if ok:return True
    raise ManifestSystemAccessDenied(why)

async def record_quality_event(guild_id:int,area:str,event_type:str,success:bool=True,latency_ms:float=0,details:str=""):
    try:
        await db.execute("INSERT INTO manifest_quality_events(guild_id,area,event_type,success,latency_ms,details,created_at) VALUES(?,?,?,?,?,?,?)",(int(guild_id or 0),str(area)[:50],str(event_type)[:80],int(bool(success)),max(0,float(latency_ms or 0)),str(details)[:500],time.time()))
    except Exception:
        log.debug("Quality telemetry write failed",exc_info=True)

async def manifest_quality_snapshot(guild_id:int):
    since=time.time()-86400
    row=await db.one("SELECT COUNT(*) total,COALESCE(SUM(CASE WHEN success=1 THEN 1 ELSE 0 END),0) ok,COALESCE(AVG(CASE WHEN latency_ms>0 THEN latency_ms END),0) avg_ms FROM manifest_quality_events WHERE guild_id IN (?,0) AND created_at>?",(int(guild_id or 0),since))
    commands=await db.one("SELECT COUNT(*) total,COALESCE(SUM(CASE WHEN success=1 THEN 1 ELSE 0 END),0) ok FROM manifest_command_events WHERE guild_id=? AND created_at>?",(int(guild_id or 0),since))
    incidents=await db.one("SELECT COUNT(*) c FROM runtime_incidents WHERE guild_id=? AND status='open'",(int(guild_id or 0),))
    ctot=int(commands['total'] or 0) if commands else 0; cok=int(commands['ok'] or 0) if commands else 0
    return {"events":int(row['total'] or 0) if row else 0,"quality_ok":int(row['ok'] or 0) if row else 0,"avg_ms":round(float(row['avg_ms'] or 0),1) if row else 0,"commands":ctot,"command_success":cok,"command_rate":round(cok/ctot*100,1) if ctot else 100.0,"incidents":int(incidents['c'] or 0) if incidents else 0}

async def manifest_access_summary(guild):
    rows=[]
    for key,meta in MANIFEST_SYSTEM_CATALOG.items():
        p=await manifest_system_policy(guild.id,key)
        role_names=[]
        for rid in p['role_ids'][:6]:
            r=guild.get_role(rid); role_names.append(r.name if r else f"missing:{rid}")
        user_names=[]
        for uid in p.get('user_ids',[])[:4]:
            m=guild.get_member(uid); user_names.append(m.display_name if m else f"user:{uid}")
        access=p['access_mode'].replace('_',' ').title()
        selected=role_names+user_names
        if selected:access += " · " + ", ".join(selected)
        rows.append((key,meta['label'],bool(p['enabled']),access))
    return rows

@manifest_access_group.command(name="list",description="Show who can use each major Manifest system")
async def manifest_access_list(i:discord.Interaction):
    if not i.guild or not server_manager(i.user):return await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True)
    rows=await manifest_access_summary(i.guild)
    lines=[f"{'✅' if enabled else '⛔'} **{label}** — {access}" for _,label,enabled,access in rows]
    e=manifest_ui_embed("Manifest · System Access","Policies only narrow access; they never grant Discord permissions or bypass a system's own authority checks.")
    e.add_field(name="Current policies",value="\n".join(lines)[:3900],inline=False)
    await i.response.send_message(embed=e,ephemeral=True)

@manifest_access_group.command(name="set",description="Restrict a major Manifest system to everyone, roles, staff or managers")
@app_commands.choices(system=[app_commands.Choice(name=v['label'],value=k) for k,v in MANIFEST_SYSTEM_CATALOG.items()],mode=[app_commands.Choice(name=x.title(),value=x) for x in ("everyone","selected","staff","managers","disabled")])
async def manifest_access_set(i:discord.Interaction,system:app_commands.Choice[str],mode:app_commands.Choice[str],role:discord.Role|None=None,member:discord.Member|None=None):
    if not i.guild or not server_manager(i.user):return await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True)
    role_ids=[];user_ids=[]
    if mode.value=='selected':
        if role is None and member is None:return await i.response.send_message("Choose at least one role or member when using Selected mode.",ephemeral=True)
        if role is not None:
            if role.is_default() or role.managed:return await i.response.send_message("That role cannot be used as a Manifest access role.",ephemeral=True)
            role_ids=[role.id]
        if member is not None:user_ids=[member.id]
    await db.execute("INSERT INTO manifest_system_policies(guild_id,system_key,enabled,access_mode,allowed_role_ids_json,allowed_user_ids_json,updated_by,updated_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(guild_id,system_key) DO UPDATE SET enabled=excluded.enabled,access_mode=excluded.access_mode,allowed_role_ids_json=excluded.allowed_role_ids_json,allowed_user_ids_json=excluded.allowed_user_ids_json,updated_by=excluded.updated_by,updated_at=excluded.updated_at",(i.guild_id,system.value,0 if mode.value=='disabled' else 1,mode.value,json.dumps(role_ids),json.dumps(user_ids),i.user.id,time.time()))
    await record_quality_event(i.guild_id,'access','policy_update',True,details=f"{system.value}:{mode.value}")
    chosen=[]
    if role:chosen.append(role.mention)
    if member:chosen.append(member.mention)
    await i.response.send_message(f"✅ **{MANIFEST_SYSTEM_CATALOG[system.value]['label']}** access is now **{mode.name}**"+(f" for {', '.join(chosen)}." if chosen else ".")+"\nThis does not grant any Discord permission or bypass the system's own checks.",ephemeral=True)

@manifest_access_group.command(name="grant",description="Add a role or member to a Manifest system's selected-access list")
@app_commands.choices(system=[app_commands.Choice(name=v['label'],value=k) for k,v in MANIFEST_SYSTEM_CATALOG.items()])
async def manifest_access_grant(i:discord.Interaction,system:app_commands.Choice[str],role:discord.Role|None=None,member:discord.Member|None=None):
    if not i.guild or not server_manager(i.user):return await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True)
    if role is None and member is None:return await i.response.send_message("Choose a role or member to grant.",ephemeral=True)
    if role is not None and (role.is_default() or role.managed):return await i.response.send_message("That role cannot be used as a Manifest access role.",ephemeral=True)
    p=await manifest_system_policy(i.guild_id,system.value);roles=set(p['role_ids']);users=set(p.get('user_ids') or [])
    if role:roles.add(role.id)
    if member:users.add(member.id)
    await db.execute("INSERT INTO manifest_system_policies(guild_id,system_key,enabled,access_mode,allowed_role_ids_json,allowed_user_ids_json,updated_by,updated_at) VALUES(?,?,1,'selected',?,?,?,?) ON CONFLICT(guild_id,system_key) DO UPDATE SET enabled=1,access_mode='selected',allowed_role_ids_json=excluded.allowed_role_ids_json,allowed_user_ids_json=excluded.allowed_user_ids_json,updated_by=excluded.updated_by,updated_at=excluded.updated_at",(i.guild_id,system.value,json.dumps(sorted(roles)),json.dumps(sorted(users)),i.user.id,time.time()))
    await i.response.send_message(f"✅ Added the selected {'role' if role else 'member'} to **{MANIFEST_SYSTEM_CATALOG[system.value]['label']}** access.",ephemeral=True)

@manifest_access_group.command(name="revoke",description="Remove a role or member from a Manifest system's selected-access list")
@app_commands.choices(system=[app_commands.Choice(name=v['label'],value=k) for k,v in MANIFEST_SYSTEM_CATALOG.items()])
async def manifest_access_revoke(i:discord.Interaction,system:app_commands.Choice[str],role:discord.Role|None=None,member:discord.Member|None=None):
    if not i.guild or not server_manager(i.user):return await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True)
    if role is None and member is None:return await i.response.send_message("Choose a role or member to revoke.",ephemeral=True)
    p=await manifest_system_policy(i.guild_id,system.value);roles=set(p['role_ids']);users=set(p.get('user_ids') or [])
    if role:roles.discard(role.id)
    if member:users.discard(member.id)
    await db.execute("INSERT INTO manifest_system_policies(guild_id,system_key,enabled,access_mode,allowed_role_ids_json,allowed_user_ids_json,updated_by,updated_at) VALUES(?,?,1,'selected',?,?,?,?) ON CONFLICT(guild_id,system_key) DO UPDATE SET access_mode='selected',allowed_role_ids_json=excluded.allowed_role_ids_json,allowed_user_ids_json=excluded.allowed_user_ids_json,updated_by=excluded.updated_by,updated_at=excluded.updated_at",(i.guild_id,system.value,json.dumps(sorted(roles)),json.dumps(sorted(users)),i.user.id,time.time()))
    await i.response.send_message(f"🧹 Removed the selected {'role' if role else 'member'} from **{MANIFEST_SYSTEM_CATALOG[system.value]['label']}** access.",ephemeral=True)

@manifest_access_group.command(name="clear",description="Return a Manifest system to its default access policy")
@app_commands.choices(system=[app_commands.Choice(name=v['label'],value=k) for k,v in MANIFEST_SYSTEM_CATALOG.items()])
async def manifest_access_clear(i:discord.Interaction,system:app_commands.Choice[str]):
    if not i.guild or not server_manager(i.user):return await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True)
    await db.execute("DELETE FROM manifest_system_policies WHERE guild_id=? AND system_key=?",(i.guild_id,system.value))
    await i.response.send_message(f"↩️ **{MANIFEST_SYSTEM_CATALOG[system.value]['label']}** returned to Manifest's default access policy.",ephemeral=True)

@manifest_access_group.command(name="explain",description="Explain Manifest access versus Discord permissions")
async def manifest_access_explain(i:discord.Interaction):
    e=manifest_ui_embed("Manifest · Access Model","Manifest access policies and Discord permissions solve different problems.")
    e.add_field(name="Manifest policy",value="Controls which members may enter a Manifest system. It can narrow access only.",inline=False)
    e.add_field(name="Discord authority",value="Moderation/server-changing actions still require their real Discord permissions, role hierarchy and Manifest verification path at execution time.",inline=False)
    e.add_field(name="Native Discord controls",value="Server Settings → Integrations can also restrict individual app commands by role/member/channel. Manifest policies coexist with those controls.",inline=False)
    await i.response.send_message(embed=e,ephemeral=True)

# The tree-level gate makes system policies universal for slash-command families.
# It is assigned on the instance so setup/sync remain unchanged.
bot.tree.interaction_check=manifest_tree_interaction_check

async def manifest_prefix_policy_check(ctx):
    if not getattr(ctx,'guild',None):return True
    if server_manager(ctx.author):return True
    qn=str(getattr(getattr(ctx,'command',None),'qualified_name','') or '').strip().lower()
    if not qn:return True
    key=MANIFEST_ROOT_TO_SYSTEM.get(qn.split()[0])
    if not key:return True
    ok,why=await manifest_system_access_allowed(ctx.author,key)
    if ok:return True
    raise commands.CheckFailure(why)
bot.add_check(manifest_prefix_policy_check)

