# ========================= MUSIC COMMANDS =========================
def _music_player_for(i):
    if not getattr(i, "guild", None) or not wavelink:
        return None
    player = getattr(i.guild, "voice_client", None)
    return player if isinstance(player, wavelink.Player) else None

def _music_duration(ms):
    try:
        seconds=max(0,int(ms or 0)//1000)
        return f"{seconds//3600:02d}:{(seconds%3600)//60:02d}:{seconds%60:02d}" if seconds>=3600 else f"{seconds//60:02d}:{seconds%60:02d}"
    except Exception:
        return "--:--"

def music_panel_embed(guild):
    e=discord.Embed(title="MANIFEST · MUSIC", color=discord.Color.from_rgb(82, 112, 177))
    p=getattr(guild,"voice_client",None) if guild else None
    if not wavelink or not isinstance(p,wavelink.Player):
        e.description="**Ready when you are.**\nJoin a voice channel and press **Play** to start a shared music session."
        e.add_field(name="Playback",value="No active session",inline=True)
        e.add_field(name="Controls",value="Play · Queue · Volume · Shuffle",inline=True)
        e.set_footer(text="Every listener must follow the server's voice and content rules.")
        return e
    current=getattr(p,"current",None)
    if current:
        title=str(getattr(current,"title","Unknown track"))[:240]
        author=str(getattr(current,"author","Unknown artist"))[:160]
        uri=str(getattr(current,"uri","") or "")
        e.description=f"**{title}**\n{author}" + (f"\n[Open track]({uri})" if uri.startswith("https://") else "")
        length=int(getattr(current,"length",0) or 0)
        position=int(getattr(p,"position",0) or 0)
        duration=f"{_music_duration(position)} / {_music_duration(length)}" if length>0 else _music_duration(position)
        e.add_field(name="Progress",value=duration,inline=True)
    else:
        e.description="No track is playing. Press **Play** to add one."
    qcount=int(getattr(getattr(p,"queue",None),"count",0) or 0)
    e.add_field(name="Playback",value="Paused" if getattr(p,"paused",False) else ("Playing" if current else "Idle"),inline=True)
    e.add_field(name="Queue",value=f"{qcount} queued",inline=True)
    e.add_field(name="Volume",value=f"{int(getattr(p,'volume',50) or 0)}%",inline=True)
    e.add_field(name="Repeat",value=_music_repeat_state(p),inline=True)
    e.add_field(name="Autoplay",value=_music_autoplay_state(p),inline=True)
    channel=getattr(p,"channel",None)
    listeners=max(0,len([m for m in getattr(channel,"members",[]) if not getattr(m,"bot",False)])) if channel else 0
    e.add_field(name="Voice channel",value=f"{getattr(channel,'mention','Connected')} · {listeners} listener{'s' if listeners!=1 else ''}",inline=True)
    if current:
        art=str(getattr(current,"artwork",None) or getattr(current,"artwork_url",None) or "")
        if art.startswith("https://"):e.set_thumbnail(url=art)
    upcoming=list(getattr(p,"queue",[]) or [])[:4]
    if upcoming:
        e.add_field(name="Up next",value="\n".join(f"**{n}.** {str(getattr(t,'title','Unknown track'))[:110]}" for n,t in enumerate(upcoming,1))[:950],inline=False)
    e.set_footer(text="Use the buttons below · voice/DJ policy is rechecked on every control")
    return e

def music_queue_embed(guild):
    e=discord.Embed(title="MANIFEST · QUEUE",color=discord.Color.from_rgb(82,112,177))
    p=getattr(guild,"voice_client",None) if guild else None
    if not wavelink or not isinstance(p,wavelink.Player):
        e.description="No active music session."
        return e
    current=getattr(p,"current",None)
    lines=[f"**Now playing:** {str(getattr(current,'title','Unknown track'))[:170]}" if current else "**Now playing:** Nothing"]
    queued=list(getattr(p,"queue",[]) or [])
    lines.extend(f"`{n}.` {str(getattr(track,'title','Unknown track'))[:150]}" for n,track in enumerate(queued[:20],1))
    if len(queued)>20:lines.append(f"…and {len(queued)-20} more")
    e.description="\n".join(lines)[:3900]
    e.set_footer(text=f"{len(queued)} queued track(s)")
    return e

async def _music_voice_member(interaction, *, require_player=True):
    if not interaction.guild or not isinstance(interaction.user,discord.Member):
        raise RuntimeError("This control is available inside a server.")
    member=interaction.user
    if not member.voice or not member.voice.channel:
        raise RuntimeError("Join Manifest's active voice channel to use playback controls.")
    p=_music_player_for(interaction)
    if require_player and not p:
        raise RuntimeError("No music session is active. Press Play to start one.")
    if p and getattr(p,"channel",None)!=member.voice.channel:
        raise RuntimeError("Join the same voice channel as Manifest before using these controls.")
    return p

class MusicSearchResultSelect(discord.ui.Select):
    def __init__(self,parent_view,tracks):
        self.parent_view=parent_view;self.tracks=list(tracks or [])[:10]
        options=[]
        for idx,track in enumerate(self.tracks):
            title=str(getattr(track,"title","Unknown track"))[:100]
            author=str(getattr(track,"author","") or "Unknown artist")[:80]
            length=_music_duration(int(getattr(track,"length",0) or 0))
            options.append(discord.SelectOption(label=title,value=str(idx),description=f"{author} · {length}"[:100]))
        super().__init__(placeholder="Choose the exact track to queue…",min_values=1,max_values=1,options=options,row=0)
    async def callback(self,i):
        ok,why=await music_control_allowed(i)
        if not ok:return await i.response.send_message(why,ephemeral=True)
        try:
            await _music_voice_member(i,require_player=False)
            idx=int(self.values[0]);track=self.tracks[idx]
            player=await music_player(i.guild,i.user,i.channel)
            was_playing=bool(getattr(player,"current",None) or getattr(player,"playing",False))
            await player.queue.put_wait(track);await start_music_if_needed(player)
            self.parent_view.stop()
            detail=f"{'Queued' if was_playing else 'Now playing'} **{str(getattr(track,'title','Unknown track'))[:190]}**."
            await i.response.edit_message(content="🎵 "+detail,embed=None,view=None)
            panel=self.parent_view.panel_view
            if panel and getattr(panel,"message",None):
                try:await panel.message.edit(embed=music_panel_embed(i.guild),view=panel)
                except Exception:pass
        except Exception as ex:
            await i.response.send_message(f"Manifest Music could not queue that result: {_safe_diag_text(ex,420)}",ephemeral=True)

class MusicSearchResultView(discord.ui.View):
    def __init__(self,guild_id,user_id,tracks,panel_view=None):
        super().__init__(timeout=120);self.guild_id=int(guild_id);self.user_id=int(user_id);self.panel_view=panel_view
        self.add_item(MusicSearchResultSelect(self,tracks))
    async def interaction_check(self,i):
        if not i.guild or i.guild.id!=self.guild_id or i.user.id!=self.user_id:
            await i.response.send_message("These search results belong to the member who searched for them.",ephemeral=True);return False
        return True
    @discord.ui.button(label="Cancel",emoji="✕",style=discord.ButtonStyle.secondary,row=1)
    async def cancel(self,i,b):
        self.stop();await i.response.edit_message(content="Music search cancelled.",embed=None,view=None)

class MusicPlayModal(discord.ui.Modal,title="Add music to the queue"):
    query=discord.ui.TextInput(label="Song, artist, playlist, or supported URL",placeholder="Search for a track…",max_length=300)
    def __init__(self,parent_view):
        super().__init__();self.parent_view=parent_view
    async def on_submit(self,i):
        if not i.guild or not isinstance(i.user,discord.Member):
            return await i.response.send_message("Server only.",ephemeral=True)
        ok,why=await music_control_allowed(i)
        if not ok:return await i.response.send_message(why,ephemeral=True)
        await i.response.defer(ephemeral=True,thinking=True)
        try:
            query=str(self.query.value).strip()
            # Direct URLs are deterministic and may resolve to a playlist. Text searches
            # intentionally show a picker so Manifest never guesses which song was meant.
            results=await resolve_music_candidates(query,8)
            if isinstance(results,wavelink.Playlist):
                player=await music_player(i.guild,i.user,i.channel)
                added=await player.queue.put_wait(results);await start_music_if_needed(player)
                await i.followup.send(f"🎵 Added playlist **{str(results.name)[:180]}** · {added} track(s).",ephemeral=True)
            elif re.match(r"^https?://",query,re.I) or len(results)==1:
                player=await music_player(i.guild,i.user,i.channel);track=results[0]
                was_playing=bool(getattr(player,"current",None) or getattr(player,"playing",False))
                await player.queue.put_wait(track);await start_music_if_needed(player)
                await i.followup.send(f"🎵 {'Queued' if was_playing else 'Now playing'} **{str(track.title)[:220]}**.",ephemeral=True)
            else:
                e=discord.Embed(title="MANIFEST · MUSIC SEARCH",description="Pick the exact result you want. Manifest will recheck the current voice/DJ policy when you choose it.",color=discord.Color.from_rgb(82,112,177))
                e.add_field(name="Search",value=query[:500],inline=False)
                await i.followup.send(embed=e,view=MusicSearchResultView(i.guild.id,i.user.id,results,self.parent_view),ephemeral=True)
            if self.parent_view.message:
                try:await self.parent_view.message.edit(embed=music_panel_embed(i.guild),view=self.parent_view)
                except Exception:pass
        except Exception as ex:
            log.warning("Music search/play request failed: %s",type(ex).__name__)
            await i.followup.send(f"Manifest Music could not search that request: {_safe_diag_text(ex,450)}",ephemeral=True)

class MusicVolumeModal(discord.ui.Modal,title="Set music volume"):
    volume=discord.ui.TextInput(label="Volume percentage (0–100)",placeholder="50",min_length=1,max_length=3,default="50")
    def __init__(self,parent_view):
        super().__init__();self.parent_view=parent_view
    async def on_submit(self,i):
        ok,why=await music_control_allowed(i)
        if not ok:return await i.response.send_message(why,ephemeral=True)
        try:value=int(str(self.volume.value).strip())
        except Exception:return await i.response.send_message("Enter a whole number from 0 to 100.",ephemeral=True)
        if not 0<=value<=100:return await i.response.send_message("Volume must be between 0 and 100.",ephemeral=True)
        try:
            p=await _music_voice_member(i)
            await p.set_volume(value)
            await i.response.send_message(f"Volume set to **{value}%**.",ephemeral=True)
            if self.parent_view.message:
                try:await self.parent_view.message.edit(embed=music_panel_embed(i.guild),view=self.parent_view)
                except Exception:pass
        except Exception as ex:
            await i.response.send_message(_safe_diag_text(ex,350),ephemeral=True)

class MusicSeekModal(discord.ui.Modal,title="Seek in current track"):
    position=discord.ui.TextInput(label="Position",placeholder="1:30 or 90",max_length=12)
    def __init__(self,parent_view):super().__init__();self.parent_view=parent_view
    async def on_submit(self,i):
        ok,why=await music_control_allowed(i)
        if not ok:return await i.response.send_message(why,ephemeral=True)
        try:
            p=await _music_voice_member(i)
            current=getattr(p,"current",None)
            if not current:return await i.response.send_message("Nothing is playing.",ephemeral=True)
            target=_music_parse_seek(self.position.value)
            if target is None:return await i.response.send_message("Use seconds (`90`) or a timestamp such as `1:30` or `1:02:10`.",ephemeral=True)
            length=int(getattr(current,"length",0) or 0)
            if length<=0:return await i.response.send_message("This track does not expose a seekable duration.",ephemeral=True)
            if target<0 or target>=length:return await i.response.send_message(f"Choose a position before {_music_duration(length)}.",ephemeral=True)
            await p.seek(target)
            await i.response.send_message(f"Seeked to **{_music_duration(target)}**.",ephemeral=True)
            if self.parent_view.message:
                try:await self.parent_view.message.edit(embed=music_panel_embed(i.guild),view=self.parent_view)
                except Exception:pass
        except Exception as ex:await i.response.send_message(_safe_diag_text(ex,350),ephemeral=True)

async def music_history_embed(guild):
    rows=await music_history_rows(guild.id,12)
    e=discord.Embed(title="MANIFEST · RECENTLY PLAYED",color=discord.Color.from_rgb(82,112,177))
    if not rows:
        e.description="No completed playback history has been recorded yet."
        return e
    lines=[]
    for n,row in enumerate(rows,1):
        title=str(row["title"] or "Unknown track")[:120];author=str(row["author"] or "Unknown artist")[:70]
        when=f"<t:{int(row['played_at'])}:R>" if row["played_at"] else "time unknown"
        lines.append(f"`{n}.` **{title}** · {author} · {when}")
    e.description="\n".join(lines)[:3900]
    e.set_footer(text="Server-local playback history · newest first")
    return e

class MusicDefaultVolumeModal(discord.ui.Modal,title="Default music volume"):
    volume=discord.ui.TextInput(label="Default volume (0–100)",placeholder="50",min_length=1,max_length=3,default="50")
    def __init__(self,parent_view):super().__init__();self.parent_view=parent_view
    async def on_submit(self,i):
        if i.user.id!=self.parent_view.owner_id or not server_manager(i.user):return await i.response.send_message("This settings panel belongs to the server manager who opened it.",ephemeral=True)
        try:value=int(str(self.volume.value).strip())
        except Exception:return await i.response.send_message("Enter a whole number from 0 to 100.",ephemeral=True)
        if not 0<=value<=100:return await i.response.send_message("Volume must be from 0 to 100.",ephemeral=True)
        await save_music_settings(i.guild.id,actor_id=i.user.id,default_volume=value)
        p=_music_player_for(i)
        if p and getattr(p,"current",None) is None:
            try:await p.set_volume(value)
            except Exception:pass
        await i.response.edit_message(embed=await music_settings_embed(i.guild),view=self.parent_view)

class MusicDJRoleSelect(discord.ui.RoleSelect):
    def __init__(self,parent_view):
        super().__init__(placeholder="Choose the DJ role",min_values=1,max_values=1,row=0)
        self.parent_view=parent_view
    async def callback(self,i):
        if i.user.id!=self.parent_view.owner_id or not server_manager(i.user):return await i.response.send_message("This settings panel belongs to the server manager who opened it.",ephemeral=True)
        role=self.values[0]
        if role.is_default() or role.managed:return await i.response.send_message("Choose a normal server role, not @everyone or a managed integration role.",ephemeral=True)
        await save_music_settings(i.guild.id,actor_id=i.user.id,dj_role_id=role.id)
        await i.response.edit_message(embed=await music_settings_embed(i.guild),view=self.parent_view)

async def music_settings_embed(guild):
    st=await music_settings(guild.id);role=guild.get_role(st["dj_role_id"]) if st["dj_role_id"] else None
    e=discord.Embed(title="MANIFEST · MUSIC CONTROL ROOM",description="Configure who can control the player and how new sessions start. These settings never grant Discord moderation authority.",color=discord.Color.from_rgb(82,112,177))
    e.add_field(name="Control policy",value="**DJ-only** · configured DJ role + server managers" if st["control_mode"]=="dj" else "**Voice listeners** · members in Manifest's active voice channel",inline=False)
    e.add_field(name="DJ role",value=role.mention if role else "Not configured",inline=True)
    e.add_field(name="Default volume",value=f"{st['default_volume']}%",inline=True)
    e.add_field(name="Autoplay default",value="On" if st["autoplay"] else "Off",inline=True)
    if st["control_mode"]=="dj" and not role:e.add_field(name="Attention",value="DJ-only mode is enabled without a DJ role. Only server managers can mutate playback until a role is selected.",inline=False)
    e.set_footer(text="Changes apply immediately to authorization; defaults apply when a music session starts")
    return e

class MusicSettingsView(discord.ui.View):
    def __init__(self,owner_id,guild_id):
        super().__init__(timeout=600);self.owner_id=int(owner_id);self.guild_id=int(guild_id);self.add_item(MusicDJRoleSelect(self))
    async def interaction_check(self,i):
        if not i.guild or i.guild.id!=self.guild_id or i.user.id!=self.owner_id or not server_manager(i.user):
            await i.response.send_message("This private music settings panel belongs to the server manager who opened it.",ephemeral=True);return False
        return True
    @discord.ui.button(label="Toggle DJ Mode",emoji="🎛️",style=discord.ButtonStyle.primary,row=1)
    async def mode(self,i,b):
        st=await music_settings(i.guild.id);target="voice" if st["control_mode"]=="dj" else "dj"
        await save_music_settings(i.guild.id,actor_id=i.user.id,control_mode=target)
        await i.response.edit_message(embed=await music_settings_embed(i.guild),view=self)
    @discord.ui.button(label="Toggle Autoplay",emoji="♾️",style=discord.ButtonStyle.secondary,row=1)
    async def autoplay(self,i,b):
        st=await music_settings(i.guild.id);target=not bool(st["autoplay"])
        await save_music_settings(i.guild.id,actor_id=i.user.id,autoplay=target)
        p=_music_player_for(i)
        if p:
            try:p.autoplay=wavelink.AutoPlayMode.partial if target else wavelink.AutoPlayMode.disabled
            except Exception:pass
        await i.response.edit_message(embed=await music_settings_embed(i.guild),view=self)
    @discord.ui.button(label="Default Volume",emoji="🔊",style=discord.ButtonStyle.secondary,row=1)
    async def default_volume(self,i,b):await i.response.send_modal(MusicDefaultVolumeModal(self))
    @discord.ui.button(label="Clear DJ Role",emoji="🧹",style=discord.ButtonStyle.secondary,row=1)
    async def clear_dj(self,i,b):
        await save_music_settings(i.guild.id,actor_id=i.user.id,dj_role_id=0)
        await i.response.edit_message(embed=await music_settings_embed(i.guild),view=self)
    @discord.ui.button(label="Close",emoji="✕",style=discord.ButtonStyle.danger,row=1)
    async def close(self,i,b):self.stop();await i.response.edit_message(content="Music settings closed.",embed=None,view=None)

async def music_library_embed(guild,user):
    favorites=await music_favorites_rows(guild.id,user.id,8)
    sets=await music_saved_sets_rows(guild.id,8)
    e=discord.Embed(title="MANIFEST · MUSIC LIBRARY",description="Personal favorites plus reusable server sets. Saved sets store track references, not audio files.",color=discord.Color.from_rgb(82,112,177))
    if favorites:
        e.add_field(name="Your favorites",value="\n".join(f"**{n}.** {str(r['title'])[:95]}" for n,r in enumerate(favorites,1))[:1000],inline=False)
    else:e.add_field(name="Your favorites",value="No favorites yet. Use **Favorite Current** while a track is playing.",inline=False)
    if sets:
        lines=[]
        for n,r in enumerate(sets,1):
            try:count=len(json.loads(r["tracks_json"] or "[]"))
            except Exception:count=0
            lines.append(f"**{n}.** {str(r['name'])[:70]} · {count} track{'s' if count!=1 else ''}")
        e.add_field(name="Server saved sets",value="\n".join(lines)[:1000],inline=False)
    else:e.add_field(name="Server saved sets",value="No server sets saved yet.",inline=False)
    e.set_footer(text="Loading a set rechecks current voice/DJ policy · maximum 50 tracks per saved set")
    return e

class MusicSaveSetModal(discord.ui.Modal,title="Save current music set"):
    name=discord.ui.TextInput(label="Set name",placeholder="Late Night Mix",min_length=2,max_length=60)
    def __init__(self,parent_view):super().__init__();self.parent_view=parent_view
    async def on_submit(self,i):
        if not await music_library_curator_allowed(i):return await i.response.send_message("Only a server manager or the configured DJ role can save/overwrite server music sets.",ephemeral=True)
        try:
            name,count=await music_save_current_set(i.guild,i.user.id,self.name.value)
            self.parent_view.rows=await music_saved_sets_rows(i.guild.id,25)
            await i.response.send_message(f"Saved **{name}** with **{count}** track{'s' if count!=1 else ''}.",ephemeral=True)
        except Exception as ex:await i.response.send_message(_safe_diag_text(ex,400),ephemeral=True)

class MusicSavedSetSelect(discord.ui.Select):
    def __init__(self,parent_view,rows):
        options=[]
        for r in rows[:25]:
            try:count=len(json.loads(r["tracks_json"] or "[]"))
            except Exception:count=0
            options.append(discord.SelectOption(label=str(r["name"] or "Saved set")[:100],value=str(r["id"]),description=f"{count} track{'s' if count!=1 else ''}"[:100]))
        super().__init__(placeholder="Load a saved server set…",min_values=1,max_values=1,options=options,row=0)
        self.parent_view=parent_view
    async def callback(self,i):
        ok,why=await music_control_allowed(i)
        if not ok:return await i.response.send_message(why,ephemeral=True)
        await i.response.defer(ephemeral=True,thinking=True)
        try:
            name,added,failed=await music_load_saved_set(i.guild,i.user,i.channel,int(self.values[0]))
            msg=f"Loaded **{name}** · **{added}** track{'s' if added!=1 else ''} queued."
            if failed:msg+=f" **{failed}** saved reference{'s' if failed!=1 else ''} could not be resolved."
            await i.followup.send(msg,ephemeral=True)
        except Exception as ex:await i.followup.send(_safe_diag_text(ex,450),ephemeral=True)

class MusicFavoriteSelect(discord.ui.Select):
    def __init__(self,parent_view,favorites):
        options=[]
        for idx,r in enumerate(favorites[:25]):
            desc=(str(r["author"] or "") or "Saved favorite")[:100]
            options.append(discord.SelectOption(label=str(r["title"] or "Favorite")[:100],value=str(idx),description=desc))
        super().__init__(placeholder="Queue one of your favorites…",min_values=1,max_values=1,options=options,row=1)
        self.parent_view=parent_view
    async def callback(self,i):
        ok,why=await music_control_allowed(i)
        if not ok:return await i.response.send_message(why,ephemeral=True)
        try:
            row=self.parent_view.favorites[int(self.values[0])]
            results=await resolve_music(str(row["uri"]))
            p=await music_player(i.guild,i.user,i.channel)
            track=results.tracks[0] if isinstance(results,wavelink.Playlist) and getattr(results,"tracks",None) else results[0]
            await p.queue.put_wait(track);await start_music_if_needed(p)
            await i.response.send_message(f"Queued favorite **{str(getattr(track,'title',row['title']))[:180]}**.",ephemeral=True)
        except Exception as ex:await i.response.send_message(_safe_diag_text(ex,400),ephemeral=True)

class MusicLibraryView(discord.ui.View):
    def __init__(self,guild_id,user_id,rows,favorites=None):
        super().__init__(timeout=600);self.guild_id=int(guild_id);self.user_id=int(user_id);self.rows=list(rows or []);self.favorites=list(favorites or [])
        if self.rows:self.add_item(MusicSavedSetSelect(self,self.rows))
        if self.favorites:self.add_item(MusicFavoriteSelect(self,self.favorites))
    async def interaction_check(self,i):
        if not i.guild or i.guild.id!=self.guild_id or i.user.id!=self.user_id:
            await i.response.send_message("This private music library belongs to the member who opened it.",ephemeral=True);return False
        return True
    @discord.ui.button(label="Favorite Current",emoji="⭐",style=discord.ButtonStyle.primary,row=2)
    async def favorite(self,i,b):
        p=_music_player_for(i);track=getattr(p,"current",None) if p else None
        if not track:return await i.response.send_message("Nothing is playing right now.",ephemeral=True)
        try:
            snap=await music_favorite_current(i.guild.id,i.user.id,track)
            await i.response.edit_message(embed=await music_library_embed(i.guild,i.user),view=self)
        except Exception as ex:await i.response.send_message(_safe_diag_text(ex,350),ephemeral=True)
    @discord.ui.button(label="Save Current Set",emoji="💾",style=discord.ButtonStyle.secondary,row=2)
    async def save_set(self,i,b):
        if not await music_library_curator_allowed(i):return await i.response.send_message("Only a server manager or the configured DJ role can save/overwrite server music sets.",ephemeral=True)
        await i.response.send_modal(MusicSaveSetModal(self))
    @discord.ui.button(label="Refresh",emoji="🔄",style=discord.ButtonStyle.secondary,row=2)
    async def refresh(self,i,b):
        rows=await music_saved_sets_rows(i.guild.id,25);favorites=await music_favorites_rows(i.guild.id,i.user.id,25)
        new=MusicLibraryView(i.guild.id,i.user.id,rows,favorites)
        await i.response.edit_message(embed=await music_library_embed(i.guild,i.user),view=new)
    @discord.ui.button(label="Close",emoji="✕",style=discord.ButtonStyle.danger,row=2)
    async def close(self,i,b):self.stop();await i.response.edit_message(content="Music library closed.",embed=None,view=None)

class MusicPlayerView(discord.ui.View):
    """Shared guild player panel; each action rechecks current voice membership."""
    def __init__(self,guild_id:int,host_id:int):
        super().__init__(timeout=900)
        self.guild_id=int(guild_id);self.host_id=int(host_id);self.message=None
    async def interaction_check(self,i):
        if not i.guild or i.guild.id!=self.guild_id:
            await i.response.send_message("This music panel belongs to another server.",ephemeral=True);return False
        self.message=i.message
        return True
    async def _panel_update(self,i):
        await i.response.edit_message(embed=music_panel_embed(i.guild),view=self)
    async def _destructive_allowed(self,i):
        if server_manager(i.user):return True
        ok,_=await music_control_allowed(i,destructive=True)
        return bool(ok and i.user.id==self.host_id)
    @discord.ui.button(label="Play",emoji="▶️",style=discord.ButtonStyle.success,row=0)
    async def play(self,i,b):
        ok,why=await music_control_allowed(i)
        if not ok:return await i.response.send_message(why,ephemeral=True)
        await i.response.send_modal(MusicPlayModal(self))
    @discord.ui.button(label="Pause / Resume",emoji="⏯️",style=discord.ButtonStyle.primary,row=0)
    async def pause_resume(self,i,b):
        ok,why=await music_control_allowed(i)
        if not ok:return await i.response.send_message(why,ephemeral=True)
        try:
            p=await _music_voice_member(i)
            if getattr(p,"paused",False):await p.pause(False)
            elif getattr(p,"playing",False):await p.pause(True)
            else:return await i.response.send_message("There is no playing track to pause or resume.",ephemeral=True)
            await self._panel_update(i)
        except Exception as ex:await i.response.send_message(_safe_diag_text(ex,350),ephemeral=True)
    @discord.ui.button(label="Skip",emoji="⏭️",style=discord.ButtonStyle.secondary,row=0)
    async def skip(self,i,b):
        ok,why=await music_control_allowed(i)
        if not ok:return await i.response.send_message(why,ephemeral=True)
        try:
            p=await _music_voice_member(i)
            if not getattr(p,"current",None):return await i.response.send_message("Nothing is playing.",ephemeral=True)
            await p.skip(force=True);await self._panel_update(i)
        except Exception as ex:await i.response.send_message(_safe_diag_text(ex,350),ephemeral=True)
    @discord.ui.button(label="Queue",emoji="📜",style=discord.ButtonStyle.secondary,row=0)
    async def queue(self,i,b):
        await i.response.send_message(embed=music_queue_embed(i.guild),ephemeral=True)
    @discord.ui.button(label="Volume",emoji="🔊",style=discord.ButtonStyle.secondary,row=0)
    async def volume(self,i,b):
        ok,why=await music_control_allowed(i)
        if not ok:return await i.response.send_message(why,ephemeral=True)
        try:await _music_voice_member(i)
        except Exception as ex:return await i.response.send_message(_safe_diag_text(ex,350),ephemeral=True)
        await i.response.send_modal(MusicVolumeModal(self))
    @discord.ui.button(label="Shuffle",emoji="🔀",style=discord.ButtonStyle.secondary,row=1)
    async def shuffle(self,i,b):
        ok,why=await music_control_allowed(i)
        if not ok:return await i.response.send_message(why,ephemeral=True)
        try:
            p=await _music_voice_member(i)
            if int(getattr(p.queue,"count",0) or 0)<2:return await i.response.send_message("Add at least two queued tracks before shuffling.",ephemeral=True)
            p.queue.shuffle();await self._panel_update(i)
        except Exception as ex:await i.response.send_message(_safe_diag_text(ex,350),ephemeral=True)
    @discord.ui.button(label="Clear Queue",emoji="🧹",style=discord.ButtonStyle.secondary,row=1)
    async def clear_queue(self,i,b):
        if not await self._destructive_allowed(i):return await i.response.send_message("Only the panel host or a server manager can clear the shared queue.",ephemeral=True)
        try:
            p=await _music_voice_member(i);p.queue.clear();await self._panel_update(i)
        except Exception as ex:await i.response.send_message(_safe_diag_text(ex,350),ephemeral=True)
    @discord.ui.button(label="Stop",emoji="⏹️",style=discord.ButtonStyle.danger,row=1)
    async def stop_playback(self,i,b):
        if not await self._destructive_allowed(i):return await i.response.send_message("Only the panel host or a server manager can stop the shared session.",ephemeral=True)
        try:
            p=await _music_voice_member(i);p.queue.clear();await p.stop();await self._panel_update(i)
        except Exception as ex:await i.response.send_message(_safe_diag_text(ex,350),ephemeral=True)
    @discord.ui.button(label="Leave",emoji="🚪",style=discord.ButtonStyle.danger,row=1)
    async def leave(self,i,b):
        if not await self._destructive_allowed(i):return await i.response.send_message("Only the panel host or a server manager can disconnect Manifest.",ephemeral=True)
        try:
            p=await _music_voice_member(i);p.queue.clear();await p.disconnect();await self._panel_update(i)
        except Exception as ex:await i.response.send_message(_safe_diag_text(ex,350),ephemeral=True)
    @discord.ui.button(label="Seek",emoji="⏩",style=discord.ButtonStyle.secondary,row=2)
    async def seek(self,i,b):
        ok,why=await music_control_allowed(i)
        if not ok:return await i.response.send_message(why,ephemeral=True)
        try:await _music_voice_member(i)
        except Exception as ex:return await i.response.send_message(_safe_diag_text(ex,350),ephemeral=True)
        await i.response.send_modal(MusicSeekModal(self))
    @discord.ui.button(label="Repeat",emoji="🔁",style=discord.ButtonStyle.secondary,row=2)
    async def repeat(self,i,b):
        ok,why=await music_control_allowed(i)
        if not ok:return await i.response.send_message(why,ephemeral=True)
        try:
            p=await _music_voice_member(i);state=await _music_cycle_repeat(p);await self._panel_update(i)
        except Exception as ex:await i.response.send_message(_safe_diag_text(ex,350),ephemeral=True)
    @discord.ui.button(label="Autoplay",emoji="♾️",style=discord.ButtonStyle.secondary,row=2)
    async def autoplay(self,i,b):
        ok,why=await music_control_allowed(i)
        if not ok:return await i.response.send_message(why,ephemeral=True)
        try:
            p=await _music_voice_member(i);state=await _music_toggle_autoplay(p)
            if server_manager(i.user):await save_music_settings(i.guild.id,actor_id=i.user.id,autoplay=(state=="On"))
            await self._panel_update(i)
        except Exception as ex:await i.response.send_message(_safe_diag_text(ex,350),ephemeral=True)
    @discord.ui.button(label="History",emoji="🕘",style=discord.ButtonStyle.secondary,row=2)
    async def history(self,i,b):
        await i.response.defer(ephemeral=True)
        await i.followup.send(embed=await music_history_embed(i.guild),ephemeral=True)
    @discord.ui.button(label="Settings",emoji="⚙️",style=discord.ButtonStyle.secondary,row=2)
    async def settings(self,i,b):
        if not server_manager(i.user):return await i.response.send_message("Manage Server is required to open music settings.",ephemeral=True)
        view=MusicSettingsView(i.user.id,i.guild.id)
