@music_group.command(name="play",description="Search, choose and queue music through Manifest Music")
async def music_play(i:discord.Interaction,query:str):
    if not i.guild or not isinstance(i.user,discord.Member):return await i.response.send_message("Server only.",ephemeral=True)
    ok,why=await music_control_allowed(i)
    if not ok:return await i.response.send_message(why,ephemeral=True)
    await i.response.defer(ephemeral=True,thinking=True)
    try:
        results=await resolve_music_candidates(query,8)
        if isinstance(results,wavelink.Playlist):
            player=await music_player(i.guild,i.user,i.channel);added=await player.queue.put_wait(results);await start_music_if_needed(player)
            return await i.followup.send(f"🎵 Added playlist **{str(results.name)[:180]}** · {added} track(s).",ephemeral=True)
        if re.match(r"^https?://",str(query or "").strip(),re.I) or len(results)==1:
            player=await music_player(i.guild,i.user,i.channel);track=results[0];was_playing=bool(getattr(player,"current",None) or getattr(player,"playing",False));await player.queue.put_wait(track);await start_music_if_needed(player)
            return await i.followup.send(f"🎵 {'Queued' if was_playing else 'Now playing'} **{str(track.title)[:220]}**.",ephemeral=True)
        e=discord.Embed(title="MANIFEST · MUSIC SEARCH",description="Choose the exact track instead of letting Manifest guess from the first result.",color=discord.Color.from_rgb(82,112,177))
        e.add_field(name="Search",value=str(query)[:500],inline=False)
        await i.followup.send(embed=e,view=MusicSearchResultView(i.guild.id,i.user.id,results,None),ephemeral=True)
    except Exception as ex:
        log.warning("Music play command failed: %s",type(ex).__name__)
        await i.followup.send(f"Manifest Music could not search that request: {_safe_diag_text(ex,450)}",ephemeral=True)

