@music_group.command(name="remove",description="Remove a queued track")
async def music_remove(i:discord.Interaction,position:app_commands.Range[int,1,100]):
    ok,why=await music_control_allowed(i)
    if not ok:return await i.response.send_message(why,ephemeral=True)
    try:
        p=await _music_voice_member(i);idx=position-1
        if idx>=p.queue.count:return await i.response.send_message("That queue position does not exist.",ephemeral=True)
        track=p.queue.get_at(idx);p.queue.delete(idx);await i.response.send_message(f"Removed **{str(track.title)[:180]}**.",ephemeral=True)
    except Exception as ex:await i.response.send_message(_safe_diag_text(ex,350),ephemeral=True)

