@music_group.command(name="settings",description="View or change Manifest Music server controls")
async def music_settings_command(i:discord.Interaction,mode:str|None=None,dj_role:discord.Role|None=None,clear_dj_role:bool=False,default_volume:app_commands.Range[int,0,100]|None=None,autoplay:bool|None=None):
    if not i.guild or not isinstance(i.user,discord.Member):return await i.response.send_message("Server only.",ephemeral=True)
    changing=any(x is not None for x in (mode,dj_role,default_volume,autoplay)) or clear_dj_role
    if changing and not server_manager(i.user):return await i.response.send_message("Manage Server is required to change music settings.",ephemeral=True)
    if mode is not None and str(mode).lower() not in {"voice","dj"}:return await i.response.send_message("Mode must be `voice` or `dj`.",ephemeral=True)
    if dj_role and (dj_role.is_default() or dj_role.managed):return await i.response.send_message("Choose a normal server role for DJ access.",ephemeral=True)
    if changing:
        await save_music_settings(i.guild.id,actor_id=i.user.id,dj_role_id=(0 if clear_dj_role else dj_role.id if dj_role else None),control_mode=mode,default_volume=default_volume,autoplay=autoplay)
    e=await music_settings_embed(i.guild)
    view=MusicSettingsView(i.user.id,i.guild.id) if server_manager(i.user) else None
    await i.response.send_message(embed=e,view=view,ephemeral=True)

