@mod_group.command(name="unban",description="Unban by user ID")
async def sunban(i:discord.Interaction,user_id:str,reason:str="No reason provided"):
    try:uid=int(user_id)
    except ValueError:return await i.response.send_message("Invalid Discord ID.",ephemeral=True)
    ok,x=await action_unban(i.guild,i.user,uid,reason);await i.response.send_message(("✅ " if ok else "⚠️ ")+x,ephemeral=True)
@mod_group.command(name="purge",description="Delete recent messages")
async def spurge(i:discord.Interaction,amount:app_commands.Range[int,1,100]):
    if not (i.user.id==i.guild.owner_id or i.user.guild_permissions.administrator or i.user.guild_permissions.manage_messages):return await i.response.send_message("You need Manage Messages.",ephemeral=True)
    if not i.guild.me.guild_permissions.manage_messages:return await i.response.send_message("Manifest needs Manage Messages.",ephemeral=True)
    await i.response.defer(ephemeral=True)
    try:d=await i.channel.purge(limit=amount,reason=f"Manifest purge by {i.user} ({i.user.id})")
    except discord.Forbidden:return await i.followup.send("⚠️ Discord denied the purge in this channel.",ephemeral=True)
    except discord.HTTPException as ex:return await i.followup.send(f"⚠️ Discord could not complete the purge (`{getattr(ex,'status','error')}`).",ephemeral=True)
    count=len(d)
    try:await action_receipt(i.guild,i.user,"moderation.purge","medium",f"#{i.channel.name}",True,f"Discord confirmed {count} deleted message(s)",verification_state="Discord-returned",evidence_ref=f"purge:{i.channel.id}:{i.id}",reason="Explicit purge command",source="slash_command",request_id=f"interaction:{i.id}")
    except Exception:log.exception("Slash purge succeeded but action journal failed")
    try:await elog(i.guild,"mod","🧹 Purge",f"{count} messages confirmed deleted",i.user)
    except Exception:log.exception("Slash purge succeeded but moderation log failed")
    await i.followup.send(f"✅ Discord confirmed **{count}** deleted message{'s' if count!=1 else ''}.",ephemeral=True)

@mod_group.command(name="warn",description="Warn a member")
async def swarn(i:discord.Interaction,member:discord.Member,reason:str):
    if not moderator(i.user):return await i.response.send_message("You need moderation permission.",ephemeral=True)
    ok,why=hierarchy(i.user,member)
    if not ok:return await i.response.send_message(f"⚠️ {why}",ephemeral=True)
    await db.execute("INSERT INTO warnings(guild_id,user_id,moderator_id,reason,created_at) VALUES(?,?,?,?,?)",(i.guild_id,member.id,i.user.id,reason,time.time()))
    case_id=await create_case(i.guild,member,i.user,"warn",reason)
    row=await db.one("SELECT id FROM warnings WHERE guild_id=? AND user_id=? AND moderator_id=? ORDER BY id DESC LIMIT 1",(i.guild_id,member.id,i.user.id))
    if row:
        await action_receipt(i.guild,i.user,"moderation.warn","high",member,True,f"Warning recorded • warning #{row['id']} • case #{case_id}",verification_state="Manifest-verified",evidence_ref=f"warning:{row['id']}",reason=reason,source="slash_command",request_id=f"interaction:{i.id}")
    await elog(i.guild,"mod","⚠️ Member Warned",reason,i.user,member);await i.response.send_message(f"✅ Warned {member.mention}.",ephemeral=True)

@mod_group.command(name="cases",description="View recent moderation cases for a member")
async def mod_cases(i:discord.Interaction,member:discord.Member):
    if not moderator(i.user):return await i.response.send_message("You need Moderate Members or Administrator.",ephemeral=True)
    await i.response.send_message(f"📋 **Moderation cases for {member}**\n{await case_text(i.guild,member)}",ephemeral=True)

@server_group.command(name="create_channel",description="Create a text channel")
async def create_channel(i:discord.Interaction,name:str,category:discord.CategoryChannel|None=None):
    if not manager(i.user):return await i.response.send_message("You need Manage Server.",ephemeral=True)
    if not i.guild.me.guild_permissions.manage_channels:return await i.response.send_message("Manifest needs Manage Channels.",ephemeral=True)
    c=await i.guild.create_text_channel(name[:100],category=category,reason=f"Manifest: {i.user}")
    try:fresh=await i.guild.fetch_channel(c.id)
    except discord.HTTPException:fresh=i.guild.get_channel(c.id)
    verified=bool(fresh and isinstance(fresh,discord.TextChannel) and getattr(fresh,"name","")==c.name)
    try:await action_receipt(i.guild,i.user,"channel.create","medium",str(c.id),verified,f"Created #{c.name}; live verification {'passed' if verified else 'failed'}",verification_state="Manifest-verified" if verified else "Unverified",evidence_ref=f"channel-create:{c.id}",reason="Explicit create_channel command",source="slash_command",request_id=f"interaction:{i.id}")
    except Exception:log.exception("Channel create finished but action journal failed")
    await i.response.send_message(f"✅ Created {c.mention} and verified it." if verified else "⚠️ Discord returned a created channel, but Manifest could not independently verify it.",ephemeral=True)

