@server_group.command(name="role_add",description="Add a role to a member")
async def role_add(i:discord.Interaction,member:discord.Member,role:discord.Role):
    if not (manager(i.user) or i.user.guild_permissions.manage_roles):return await i.response.send_message("You need Manage Roles.",ephemeral=True)
    if not i.guild.me.guild_permissions.manage_roles:return await i.response.send_message("Manifest needs Manage Roles.",ephemeral=True)
    if role>=i.guild.me.top_role:return await i.response.send_message("That role is above Manifest.",ephemeral=True)
    if i.user.id!=i.guild.owner_id and role>=i.user.top_role:return await i.response.send_message("That role is not below your highest role.",ephemeral=True)
    ok,why=hierarchy(i.user,member)
    if not ok and member.id!=i.user.id:return await i.response.send_message(f"⚠️ {why}",ephemeral=True)
    await member.add_roles(role,reason=f"Manifest: {i.user}")
    try:fresh=await i.guild.fetch_member(member.id)
    except discord.HTTPException:fresh=i.guild.get_member(member.id)
    verified=bool(fresh and role in fresh.roles)
    try:await action_receipt(i.guild,i.user,"role.assign","medium",f"{member.id}:{role.id}",verified,f"Assigned {role.name} to {member}; verification {'passed' if verified else 'failed'}",verification_state="Manifest-verified" if verified else "Unverified",evidence_ref=f"role-assign:{member.id}:{role.id}",reason="Explicit role_add command",source="slash_command",request_id=f"interaction:{i.id}")
    except Exception:log.exception("Role add finished but action journal failed")
    await i.response.send_message(f"✅ Added {role.mention} to {member.mention} and verified it." if verified else "⚠️ Discord accepted the role change, but Manifest could not independently verify it.",ephemeral=True)

@server_group.command(name="role_remove",description="Remove a role from a member")
async def role_remove(i:discord.Interaction,member:discord.Member,role:discord.Role):
    if not (manager(i.user) or i.user.guild_permissions.manage_roles):return await i.response.send_message("You need Manage Roles.",ephemeral=True)
    if not i.guild.me.guild_permissions.manage_roles:return await i.response.send_message("Manifest needs Manage Roles.",ephemeral=True)
    if role>=i.guild.me.top_role:return await i.response.send_message("That role is above Manifest.",ephemeral=True)
    if i.user.id!=i.guild.owner_id and role>=i.user.top_role:return await i.response.send_message("That role is not below your highest role.",ephemeral=True)
    ok,why=hierarchy(i.user,member)
    if not ok and member.id!=i.user.id:return await i.response.send_message(f"⚠️ {why}",ephemeral=True)
    await member.remove_roles(role,reason=f"Manifest: {i.user}")
    try:fresh=await i.guild.fetch_member(member.id)
    except discord.HTTPException:fresh=i.guild.get_member(member.id)
    verified=bool(fresh and role not in fresh.roles)
    try:await action_receipt(i.guild,i.user,"role.remove","medium",f"{member.id}:{role.id}",verified,f"Removed {role.name} from {member}; verification {'passed' if verified else 'failed'}",verification_state="Manifest-verified" if verified else "Unverified",evidence_ref=f"role-remove:{member.id}:{role.id}",reason="Explicit role_remove command",source="slash_command",request_id=f"interaction:{i.id}")
    except Exception:log.exception("Role remove finished but action journal failed")
    await i.response.send_message(f"✅ Removed {role.mention} from {member.mention} and verified it." if verified else "⚠️ Discord accepted the role change, but Manifest could not independently verify it.",ephemeral=True)

@server_group.command(name="nickname",description="Change a member nickname")
async def nickname(i:discord.Interaction,member:discord.Member,nickname:str):
    if not (manager(i.user) or i.user.guild_permissions.manage_nicknames):return await i.response.send_message("You need Manage Nicknames.",ephemeral=True)
    if not i.guild.me.guild_permissions.manage_nicknames:return await i.response.send_message("Manifest needs Manage Nicknames.",ephemeral=True)
    ok,why=hierarchy(i.user,member)
    if not ok:return await i.response.send_message(f"⚠️ {why}",ephemeral=True)
    if member.id==i.guild.owner_id:return await i.response.send_message("Discord does not allow changing the server owner's nickname this way.",ephemeral=True)
    if member.top_role>=i.guild.me.top_role:return await i.response.send_message("That member is not below Manifest's highest role.",ephemeral=True)
    new_nick=nickname[:32]
    try:await member.edit(nick=new_nick,reason=f"Manifest nickname change by {i.user} ({i.user.id})")
    except discord.Forbidden:return await i.response.send_message("Discord denied the nickname change because of permissions or role hierarchy.",ephemeral=True)
    except discord.HTTPException as ex:return await i.response.send_message(f"Discord could not change the nickname (`{getattr(ex,'status','error')}`).",ephemeral=True)
    try:fresh=await i.guild.fetch_member(member.id)
    except discord.HTTPException:fresh=i.guild.get_member(member.id)
    verified=bool(fresh and fresh.nick==new_nick)
    try:await action_receipt(i.guild,i.user,"member.nickname","medium",member,verified,f"Nickname verified as {new_nick}" if verified else "Nickname could not be independently verified",verification_state="Manifest-verified" if verified else "Unverified",evidence_ref=f"nickname:{member.id}",reason="Explicit nickname command",source="slash_command",request_id=f"interaction:{i.id}")
    except Exception:log.exception("Slash nickname action finished but its journal write failed")
    await i.response.send_message("✅ Nickname updated and verified." if verified else "⚠️ Discord accepted the nickname change, but I couldn't independently verify it.",ephemeral=True)

