class ManifestLogsPanelView(discord.ui.View):
    def __init__(self,owner_id,guild_id,kind="mod"):
        super().__init__(timeout=600);self.owner_id=int(owner_id);self.guild_id=int(guild_id);self.kind=str(kind or "mod");self.channel_id=0;self.severity="info"
        self.add_item(ManifestLogKindSelect(self));self.add_item(ManifestLogChannelSelect(self));self.add_item(ManifestLogSeveritySelect(self))
    async def interaction_check(self,i):
        if i.user.id!=self.owner_id or not i.guild or i.guild.id!=self.guild_id:
            await i.response.send_message("This Logging Command Center belongs to the manager who opened it.",ephemeral=True);return False
        if not server_manager(i.user):
            await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True);return False
        return True
    @discord.ui.button(label="Save route",emoji="💾",style=discord.ButtonStyle.success,row=3)
    async def save(self,i,b):
        cid=int(self.channel_id or 0)
        if not cid:
            current=await manifest_log_route(i.guild.id,self.kind);cid=int(current.get("channel_id") or 0)
        ch=i.guild.get_channel(cid) if cid else None
        if not isinstance(ch,discord.TextChannel):return await i.response.send_message("Choose a destination text channel first.",ephemeral=True)
        perms=ch.permissions_for(i.guild.me)
        if not (perms.view_channel and perms.send_messages and perms.embed_links):return await i.response.send_message("Manifest needs View Channel, Send Messages and Embed Links in that destination.",ephemeral=True)
        await db.execute("INSERT INTO manifest_log_routes(guild_id,kind,channel_id,enabled,min_severity,updated_by,updated_at) VALUES(?,?,?,1,?,?,?) ON CONFLICT(guild_id,kind) DO UPDATE SET channel_id=excluded.channel_id,enabled=1,min_severity=excluded.min_severity,updated_by=excluded.updated_by,updated_at=excluded.updated_at",(i.guild.id,self.kind,ch.id,self.severity,i.user.id,time.time()))
        new=ManifestLogsPanelView(i.user.id,i.guild.id,self.kind);new.severity=self.severity
        await i.response.edit_message(embed=await manifest_logs_panel_embed(i.guild,self.kind),view=new)
    @discord.ui.button(label="Test delivery",emoji="🧪",style=discord.ButtonStyle.primary,row=3)
    async def test(self,i,b):
        route=await manifest_log_route(i.guild.id,self.kind);cid=int(route.get("channel_id") or 0);ch=i.guild.get_channel(cid) if cid else None
        if not route.get("enabled",True):return await i.response.send_message("This stream is disabled. Enable it before testing delivery.",ephemeral=True)
        if not isinstance(ch,discord.TextChannel):return await i.response.send_message("This stream has no valid destination yet.",ephemeral=True)
        perms=ch.permissions_for(i.guild.me)
        if not (perms.view_channel and perms.send_messages and perms.embed_links):return await i.response.send_message("The configured destination is missing View Channel, Send Messages or Embed Links.",ephemeral=True)
        e=discord.Embed(title="Manifest logging test",description=f"Test event for **{self.kind.title()}** logging. This confirms Discord delivery only; no moderation/security action occurred.",color=discord.Color.blurple(),timestamp=discord.utils.utcnow())
        e.set_footer(text=f"Requested by {i.user} · Manifest V{VERSION}")
        try:await ch.send(embed=e,allowed_mentions=discord.AllowedMentions.none());await i.response.send_message(f"Test delivered to {ch.mention}.",ephemeral=True)
        except discord.HTTPException as ex:await i.response.send_message(f"Discord rejected the test delivery: {_safe_diag_text(ex,350)}",ephemeral=True)
    @discord.ui.button(label="Enable / Disable",emoji="⏻",style=discord.ButtonStyle.secondary,row=3)
    async def toggle(self,i,b):
        route=await manifest_log_route(i.guild.id,self.kind);enabled=not bool(route.get("enabled",True));cid=int(route.get("channel_id") or 0)
        await db.execute("INSERT INTO manifest_log_routes(guild_id,kind,channel_id,enabled,min_severity,updated_by,updated_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(guild_id,kind) DO UPDATE SET enabled=excluded.enabled,updated_by=excluded.updated_by,updated_at=excluded.updated_at",(i.guild.id,self.kind,cid,int(enabled),str(route.get("min_severity") or "info"),i.user.id,time.time()))
        await i.response.edit_message(embed=await manifest_logs_panel_embed(i.guild,self.kind),view=ManifestLogsPanelView(i.user.id,i.guild.id,self.kind))
    @discord.ui.button(label="Remove route",emoji="🧹",style=discord.ButtonStyle.danger,row=4)
    async def remove(self,i,b):
        await db.execute("DELETE FROM manifest_log_routes WHERE guild_id=? AND kind=?",(i.guild.id,self.kind))
        if self.kind in LOGS:await db.execute(f"UPDATE guild_settings SET {LOGS[self.kind]}=0 WHERE guild_id=?",(i.guild.id,))
        await i.response.edit_message(embed=await manifest_logs_panel_embed(i.guild,self.kind),view=ManifestLogsPanelView(i.user.id,i.guild.id,self.kind))
    @discord.ui.button(label="Refresh",emoji="🔄",style=discord.ButtonStyle.secondary,row=4)
    async def refresh(self,i,b):await i.response.edit_message(embed=await manifest_logs_panel_embed(i.guild,self.kind),view=ManifestLogsPanelView(i.user.id,i.guild.id,self.kind))
    @discord.ui.button(label="Close",emoji="✕",style=discord.ButtonStyle.secondary,row=4)
    async def close(self,i,b):self.stop();await i.response.edit_message(content="Logging Command Center closed.",embed=None,view=None)

