@manifest_config_group.command(name="control_center",description="Open Manifest's adaptive server control center")
async def manifest_control_center(i:discord.Interaction):
    if not i.guild:return await i.response.send_message("Use this inside a server.",ephemeral=True)
    if not server_manager(i.user):return await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True)
    await i.response.defer(ephemeral=True)
    await i.followup.send(embed=await manifest_control_center_embed(i.guild),view=ManifestControlCenterView(i.user.id),ephemeral=True)

@manifest_config_group.command(name="integrations",description="Scan this server for existing bot systems Manifest should coexist with")
async def manifest_integrations(i:discord.Interaction):
    if not i.guild:return await i.response.send_message("Use this inside a server.",ephemeral=True)
    if not server_manager(i.user):return await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True)
    await i.response.defer(ephemeral=True)
    found=await discover_server_integrations(i.guild,persist=True)
    if not found:return await i.followup.send("🔎 I didn't find strong evidence of an existing ticket, verification, giveaway, logging, or welcome system. That does **not** prove none exists; Manifest will keep discovery conservative.",ephemeral=True)
    lines=[]
    for x in sorted(found,key=lambda z:z['system_key']):
        provider=x['provider_type'].replace('_',' ').title(); mode=x['mode'].title(); confidence=int(float(x['confidence'])*100)
        lines.append(f"• **{x['system_key'].title()}** — {provider} · {mode} · {confidence}% confidence")
    await i.followup.send("🧩 **Integration Discovery**\n"+"\n".join(lines)+"\n\nExternal systems stay **Observe** by default. Detection does not give Manifest control over another bot.",ephemeral=True)

# ========================= TICKETS =========================
async def ticket_control_snapshot(guild):
    """Read-only ticket control snapshot for the polished management UI."""
    cat_id=int(await db.setting(guild.id,'ticket_category_id',0) or 0)
    role_id=int(await db.setting(guild.id,'support_role_id',0) or 0)
    cat=guild.get_channel(cat_id) if cat_id else None
    role=guild.get_role(role_id) if role_id else None
    detected=await detect_existing_ticket_system(guild,persist=True)
    open_row=await db.one("SELECT COUNT(*) c FROM tickets WHERE guild_id=? AND status='open'",(guild.id,))
    return {
        'category':cat if isinstance(cat,discord.CategoryChannel) else None,
        'role':role,
        'detected':detected,
        'open_tickets':int(open_row['c'] or 0),
    }

def ticket_control_embed(guild,snapshot):
    cat=snapshot['category']; role=snapshot['role']; detected=snapshot['detected']
    if cat and role:
        state='READY'
        state_note='Manifest has a valid configured category and support role.'
    elif detected and detected.get('provider_type')=='external_bot':
        state='EXTERNAL SYSTEM DETECTED'
        state_note='Manifest is observing another ticket system and will not duplicate it.'
    elif cat or role:
        state='DEGRADED'
        state_note='Part of the Manifest configuration exists, but a dependency needs review.'
    else:
        state='NOT CONFIGURED'
        state_note='No Manifest ticket infrastructure is currently configured.'
    e=discord.Embed(
        title='Manifest · Ticket Control',
        description=f"**{state}**\n{state_note}\n\nA review-first control surface for support infrastructure. This panel is private and **read-only until you explicitly confirm a change**.",
        color=discord.Color.blurple()
    )
    e.add_field(name='Infrastructure',value=f"Category: {cat.mention if cat else '—'}\nSupport role: {role.mention if role else '—'}\nOpen tickets: **{snapshot['open_tickets']}**",inline=True)
    if detected:
        provider=detected.get('provider_type','unknown').replace('_',' ').title()
        mode=str(detected.get('mode','observe')).title()
        confidence=int(float(detected.get('confidence',0))*100)
        e.add_field(name='Detection',value=f"Provider: **{provider}**\nMode: **{mode}**\nConfidence: **{confidence}%**",inline=True)
    else:
        e.add_field(name='Detection',value='No strong ticket-system evidence detected.',inline=True)
    e.add_field(name='Safety model',value='Review → explicit approval → preflight → execute → verify. Existing channels and roles are never deleted just because they have familiar names.',inline=False)
    e.set_footer(text='Manifest Ticket Control · private management interface')
    return e

async def ticket_control_audit(guild):
    snap=await ticket_control_snapshot(guild)
    me=guild.me
    checks=[]
    cat=snap['category']; role=snap['role']
    checks.append(('Configuration','ready' if cat and role else 'attention',
                   'Configured category and support role are present.' if cat and role else 'Manifest ticket infrastructure is not fully configured.'))
    if me:
        perms=me.guild_permissions
        required=[('Manage Channels',perms.manage_channels),('Manage Roles',perms.manage_roles),('View Channel',perms.view_channel),('Send Messages',perms.send_messages)]
        missing=[name for name,ok in required if not ok]
        checks.append(('Manifest permissions','ready' if not missing else 'attention',
                       'All baseline ticket permissions are available.' if not missing else 'Missing: '+', '.join(missing)))
    else:
        checks.append(('Manifest permissions','attention','Manifest member state is unavailable; permission verification could not complete.'))
    if cat:
        checks.append(('Category access','ready' if cat.guild.id==guild.id else 'attention', 'Configured category belongs to this server.'))
    if role:
        checks.append(('Support role','ready' if role.guild.id==guild.id else 'attention', 'Configured support role belongs to this server.'))
    d=snap['detected']
    if d and d.get('provider_type')=='external_bot' and d.get('confidence',0)>=0.75:
        checks.append(('External integration','attention',f"Another ticket system was detected with {int(float(d.get('confidence',0))*100)}% confidence. Manifest will not duplicate it."))
    else:
        checks.append(('External integration','ready','No high-confidence conflicting ticket system was detected.'))
    return snap,checks

def ticket_audit_embed(guild,snap,checks):
    e=discord.Embed(title='Manifest · Ticket Audit',description='Read-only verification of the current ticket configuration. **No Discord changes are performed by this audit.**',color=discord.Color.blurple())
    lines=[]
    for name,state,note in checks:
        mark='OK' if state=='ready' else 'REVIEW'
        lines.append(f'**{mark} · {name}**\n{note}')
    e.add_field(name='Verification',value='\n\n'.join(lines),inline=False)
    e.add_field(name='Live state',value=f"Open tickets: **{snap['open_tickets']}**\nCategory: {snap['category'].mention if snap['category'] else 'Not configured'}\nSupport role: {snap['role'].mention if snap['role'] else 'Not configured'}",inline=False)
    e.set_footer(text='Manifest Ticket Control · audit is read-only')
    return e

class TicketSetupConfirmView(discord.ui.View):
    def __init__(self,owner_id):
        super().__init__(timeout=120); self.owner_id=int(owner_id); self.done=False
    async def interaction_check(self,i):
        if i.user.id!=self.owner_id:
            await i.response.send_message('This setup review belongs to the manager who requested it.',ephemeral=True); return False
        if not i.guild or not server_manager(i.user):
            await i.response.send_message('Manage Server or Administrator is required.',ephemeral=True); return False
        return True
    @discord.ui.button(label='Review',style=discord.ButtonStyle.secondary)
    async def review(self,i,button):
        snap=await ticket_control_snapshot(i.guild)
        await i.response.send_message(embed=ticket_control_embed(i.guild,snap),ephemeral=True)
    @discord.ui.button(label='Confirm setup',style=discord.ButtonStyle.success)
    async def confirm(self,i,button):
        if self.done:return await i.response.send_message('This setup review has already been completed.',ephemeral=True)
        self.done=True
        await i.response.defer(ephemeral=True)
        ok,msg,_=await setup_ticket_system(i.guild,i.user)
        await i.followup.send(('✓ ' if ok else '⚠ ')+msg,ephemeral=True)
        for child in self.children: child.disabled=True
        try: await i.message.edit(view=self)
        except Exception: pass
    @discord.ui.button(label='Cancel',style=discord.ButtonStyle.danger)
    async def cancel(self,i,button):
        self.done=True
        for child in self.children: child.disabled=True
        await i.response.edit_message(content='Ticket setup cancelled. **Nothing was changed.**',embed=None,view=self)

class TicketDisableConfirmView(discord.ui.View):
    """Explicit confirmation for disabling Manifest ticket ownership.

    Disabling is deliberately separate from destructive cleanup: this only removes
    Manifest's stored ownership/configuration references. Discord objects remain.
    """
    def __init__(self,owner_id):
        super().__init__(timeout=90); self.owner_id=int(owner_id); self.done=False
    async def interaction_check(self,i):
        if i.user.id!=self.owner_id:
            await i.response.send_message('This confirmation belongs to the manager who opened it.',ephemeral=True); return False
        if not i.guild or not server_manager(i.user):
            await i.response.send_message('Manage Server or Administrator is required.',ephemeral=True); return False
        return True
    @discord.ui.button(label='Disable Manifest tickets',style=discord.ButtonStyle.danger)
    async def confirm(self,i,button):
        if self.done:return await i.response.send_message('This confirmation has already been completed.',ephemeral=True)
        self.done=True
        await db.execute("UPDATE guild_settings SET ticket_category_id=0,support_role_id=0 WHERE guild_id=?",(i.guild.id,))
        for child in self.children: child.disabled=True
        await i.response.edit_message(content='**Manifest ticket ownership disabled.** No Discord category, role, channel, or member data was deleted.',embed=None,view=self)
    @discord.ui.button(label='Keep enabled',style=discord.ButtonStyle.secondary)
    async def cancel(self,i,button):
        self.done=True
        for child in self.children: child.disabled=True
        await i.response.edit_message(content='No changes were made. **Manifest tickets remain enabled.**',view=self)

