async def setup_ticket_system(guild, actor, *, panel_channel=None):
    """Idempotent default ticket setup used by chat and future UI surfaces.
    Creates/reuses the system, persists configuration, posts a working panel, and verifies it.
    """
    if not guild or not actor:
        return False, "Ticket setup needs a server context.", None
    p=actor.guild_permissions
    if actor.id!=guild.owner_id and not (p.administrator or p.manage_guild):
        return False, "You need **Manage Server** to set up tickets.", None
    me=guild.me
    if not me or not me.guild_permissions.manage_channels:
        return False, "Manifest needs **Manage Channels** to set up tickets.", None
    detected=await detect_existing_ticket_system(guild)
    if detected and detected['provider_type']=='external_bot' and detected['confidence']>=0.75 and detected.get('mode')!='disabled':
        return False, f"I detected an existing ticket system operated by another bot in **{detected.get('mode','observe').title()}** mode, so I won't create a duplicate. Disable that integration first if you intentionally want Manifest to build a separate native ticket system.", None
    # Reuse configured objects when valid; otherwise create safe defaults.
    cat=guild.get_channel(await db.setting(guild.id,"ticket_category_id",0))
    if not isinstance(cat,discord.CategoryChannel):
        cat=discord.utils.find(lambda c:c.name.lower()=="tickets",guild.categories)
    if not isinstance(cat,discord.CategoryChannel):
        cat=await guild.create_category("Tickets",reason=f"Manifest ticket setup by {actor}")
    support=guild.get_role(await db.setting(guild.id,"support_role_id",0))
    if support is None:
        # Prefer an existing obvious staff role instead of creating duplicate staff structures.
        for name in ("ticket staff","support team","support","staff","moderator","mod"):
            support=discord.utils.find(lambda r:r.name.lower()==name,guild.roles)
            if support: break
    if support is None:
        if not me.guild_permissions.manage_roles:
            return False, "Manifest needs **Manage Roles** to create the default Ticket Staff role.", None
        support=await guild.create_role(name="Ticket Staff",reason=f"Manifest ticket setup by {actor}")
    # A dedicated panel channel avoids dumping setup UI into whichever chat invoked it.
    panel=None
    if isinstance(panel_channel,discord.TextChannel): panel=panel_channel
    if panel is None:
        panel=discord.utils.find(lambda c:c.name.lower() in {"open-a-ticket","tickets","support"} and c.category_id==cat.id,guild.text_channels)
    if panel is None:
        overwrites={guild.default_role:discord.PermissionOverwrite(view_channel=True,send_messages=False),me:discord.PermissionOverwrite(view_channel=True,send_messages=True,manage_channels=True)}
        panel=await guild.create_text_channel("open-a-ticket",category=cat,overwrites=overwrites,reason=f"Manifest ticket setup by {actor}")
    await db.execute("UPDATE guild_settings SET ticket_category_id=?, support_role_id=? WHERE guild_id=?",(cat.id,support.id,guild.id))
    await panel.send(embed=discord.Embed(title="🎫 Support Center",description="Choose a ticket type below. Manifest will open a private workspace for you.",color=discord.Color.blurple()),view=TicketView())
    # Verify persisted IDs and live objects before reporting success.
    saved_cat=await db.setting(guild.id,"ticket_category_id",0); saved_role=await db.setting(guild.id,"support_role_id",0)
    if saved_cat!=cat.id or saved_role!=support.id or guild.get_channel(cat.id) is None or guild.get_channel(panel.id) is None or guild.get_role(support.id) is None:
        return False, "Ticket setup changed Discord, but verification failed, so I won't call it complete.", None
    return True,f"Tickets are set up. Panel: {panel.mention} • Staff: {support.mention}",panel

_ticket_open_lock=asyncio.Lock()

async def open_ticket_capability(guild,user,*,reason="",ticket_type="support",subject="",source="ticket_capability",request_id=""):
    """Serialize ticket creation so rapid repeated requests reuse one open ticket."""
    async with _ticket_open_lock:
        return await _open_ticket_capability_unlocked(
            guild,user,reason=reason,ticket_type=ticket_type,subject=subject,source=source,request_id=request_id
        )

async def _open_ticket_capability_unlocked(guild,user,*,reason="",ticket_type="support",subject="",source="ticket_capability",request_id=""):
    """Open a ticket under a crash-recoverable cross-process SQLite lease."""
    token=uuid.uuid4().hex
    now=time.time()
    try:
        claim=await db.execute(
            "INSERT INTO ticket_open_claims(guild_id,user_id,token,lease_until,created_at) VALUES(?,?,?,?,?) "
            "ON CONFLICT(guild_id,user_id) DO UPDATE SET token=excluded.token,lease_until=excluded.lease_until,created_at=excluded.created_at "
            "WHERE ticket_open_claims.lease_until<=?",
            (int(guild.id),int(user.id),token,now+600,now,now)
        )
        acquired=int(getattr(claim,"rowcount",0) or 0)==1
        try: await claim.close()
        except Exception: pass
    except Exception:
        log.exception("Could not acquire persistent ticket-opening claim")
        return False,"Manifest couldn't establish a safe ticket-opening lock. No ticket channel was created.",None
    if not acquired:
        return False,"A ticket-opening request for you is already running in another Manifest worker. Check your existing tickets before retrying.",None

    ch=None
    db_row_created=False
    try:
        old=await db.one(
            "SELECT channel_id FROM tickets WHERE guild_id=? AND user_id=? AND status IN ('open','resolved') ORDER BY created_at DESC LIMIT 1",
            (guild.id,user.id)
        )
        if old:
            existing=guild.get_channel(old["channel_id"])
            if existing:
                return True,f"You already have an open ticket: {existing.mention}",existing
            await db.execute(
                "UPDATE tickets SET status='closed',closed_at=?,close_reason='Ticket channel no longer exists' WHERE guild_id=? AND user_id=? AND status IN ('open','resolved')",
                (time.time(),guild.id,user.id)
            )

        me=guild.me
        if not me or not me.guild_permissions.manage_channels:
            return False,"Manifest needs **Manage Channels** to open tickets.",None
        cat=guild.get_channel(await db.setting(guild.id,"ticket_category_id",0))
        support=guild.get_role(await db.setting(guild.id,"support_role_id",0))
        # A configured ticket system has at least a category or support role. Do not silently invent one.
        if not isinstance(cat,discord.CategoryChannel) and not support:
            detected=await detect_existing_ticket_system(guild)
            if detected and detected['provider_type']=='external_bot' and detected['confidence']>=0.75:
                return False,"This server already appears to use another bot's ticket system. Manifest is observing it rather than creating a competing ticket. Use that system's panel, or have an owner explicitly switch ticket ownership to Manifest.",None
            return False,"No usable ticket system is currently configured for Manifest.",None

        ow={guild.default_role:discord.PermissionOverwrite(view_channel=False),
            user:discord.PermissionOverwrite(view_channel=True,send_messages=True),
            me:discord.PermissionOverwrite(view_channel=True,send_messages=True,manage_channels=True)}
        if support:
            ow[support]=discord.PermissionOverwrite(view_channel=True,send_messages=True)
        ch=await guild.create_text_channel(
            f"ticket-{user.name}"[:100],
            category=cat if isinstance(cat,discord.CategoryChannel) else None,
            overwrites=ow,reason=f"Manifest ticket opened by {user}"
        )
        # Fetch the created object from Discord rather than trusting only the local cache.
        fresh_channel=await guild.fetch_channel(ch.id)
        if not isinstance(fresh_channel,discord.TextChannel):
            raise RuntimeError("Discord did not return the new ticket as a text channel")
        ch=fresh_channel

        await db.execute(
            "INSERT INTO tickets(channel_id,guild_id,user_id,status,ticket_type,subject,created_at) VALUES(?,?,?,'open',?,?,?)",
            (ch.id,guild.id,user.id,str(ticket_type)[:32],str(subject)[:200],time.time())
        )
        db_row_created=True
        await ch.send(
            user.mention,
            embed=discord.Embed(
                title="🎫 Manifest Support",
                description=((f"**Type:** {str(ticket_type).title()}\n" +
                              (f"**Subject:** {str(subject)[:200]}\n" if subject else "") +
                              "\n" + (str(reason)[:800] if reason else "Describe what you need help with."))),
                color=discord.Color.blurple()
            ),
            view=TicketControlView(),
            allowed_mentions=discord.AllowedMentions(users=True)
        )

        # Auxiliary metrics/audit are best-effort after the ticket itself is usable.
        aux_errors=[]
        try:
            await db.execute("INSERT INTO ticket_events(channel_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",
                             (ch.id,guild.id,user.id,'opened',str(reason)[:500],time.time()))
        except Exception:
            aux_errors.append("ticket event journal")
            log.exception("Ticket %s opened but event journal failed",ch.id)
        try:
            day=datetime.datetime.now(datetime.timezone.utc).date().isoformat()
            await db.execute("INSERT INTO guild_daily_metrics(guild_id,day,tickets_opened) VALUES(?,?,1) ON CONFLICT(guild_id,day) DO UPDATE SET tickets_opened=tickets_opened+1",(guild.id,day))
        except Exception:
            aux_errors.append("daily metric")
            log.exception("Ticket %s opened but daily metric update failed",ch.id)
        try:
            await elog(guild,"ticket","🎫 Ticket Opened",ch.mention,user)
        except Exception:
            aux_errors.append("ticket log")
            log.exception("Ticket %s opened but ticket log delivery failed",ch.id)
        try:
            await action_receipt(guild,user,"ticket.open","medium",str(ch.id),True,
                                 "Ticket channel, database record and support panel creation verified",
                                 verification_state="Manifest-verified",evidence_ref=f"ticket-open:{ch.id}",
                                 reason=reason or "Ticket opened",source=source,request_id=request_id)
        except Exception:
            aux_errors.append("action receipt")
            log.exception("Ticket %s opened but action receipt failed",ch.id)
        suffix=(" Auxiliary records needing repair: "+", ".join(aux_errors)+".") if aux_errors else ""
        return True,f"Opened your ticket: {ch.mention}"+suffix,ch

    except Exception as ex:
        # A channel without a working panel/record is not a successful ticket.
        try:
            if db_row_created:
                await db.execute(
                    "UPDATE tickets SET status='closed',closed_at=?,close_reason=? WHERE channel_id=? AND status IN ('open','resolved')",
                    (time.time(),f"Ticket setup failed: {type(ex).__name__}"[:500],int(ch.id))
                )
        except Exception:
            log.exception("Could not mark partially created ticket as closed")
        cleanup_ok=False
        if ch is not None:
            try:
                await ch.delete(reason="Manifest ticket setup failed; cleaning up incomplete ticket")
                cleanup_ok=(guild.get_channel(ch.id) is None)
            except Exception:
                log.exception("Could not clean up incomplete ticket channel %s",getattr(ch,"id",0))
                cleanup_ok=False
        if cleanup_ok:
            return False,f"Ticket setup failed ({type(ex).__name__}); the incomplete channel was removed. No active ticket remains.",None
        if ch is not None:
            return False,f"Ticket setup failed ({type(ex).__name__}) after Discord created {ch.mention}. Cleanup could not be verified; staff should inspect this channel before retrying.",ch
        log.exception("Ticket creation failed before a channel was confirmed")
        return False,f"Ticket creation failed ({type(ex).__name__}). No successful ticket was recorded.",None
    finally:
        try:
            await db.execute("DELETE FROM ticket_open_claims WHERE guild_id=? AND user_id=? AND token=?",
                             (int(guild.id),int(user.id),token))
        except Exception:
            log.exception("Could not release ticket-opening claim for guild %s user %s",guild.id,user.id)

async def close_ticket_capability(guild,channel,actor,*,reason="Closed",delete_channel=True,source="ticket_capability",request_id=""):
    """One verified close path for buttons, slash commands and chat actions."""
    row=await db.one("SELECT * FROM tickets WHERE guild_id=? AND channel_id=?",(guild.id,channel.id))
    if not row or row["status"] not in {"open","resolved"}: return False,"This isn't an active Manifest ticket."
    if actor.id!=row["user_id"] and not manager(actor): return False,"You can't close this ticket."
    now=time.time()
    cur=await db.execute("UPDATE tickets SET status='closed',closed_by=?,closed_at=?,close_reason=? WHERE guild_id=? AND channel_id=? AND status IN ('open','resolved')",(actor.id,now,reason[:500],guild.id,channel.id))
    changed=int(getattr(cur,"rowcount",0) or 0)==1
    try: await cur.close()
    except Exception: pass
    if not changed:
        fresh=await db.one("SELECT status FROM tickets WHERE guild_id=? AND channel_id=?",(guild.id,channel.id))
        return False,("This ticket was already closed by another action." if fresh and fresh["status"]=="closed" else "The ticket state changed before closure; refresh and try again.")
    audit_warnings=[]
    try:
        await db.execute("INSERT INTO ticket_events(channel_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(channel.id,guild.id,actor.id,"closed",reason[:500],now))
    except Exception:
        audit_warnings.append("ticket event journal unavailable")
        log.exception("Ticket %s was closed but event journaling failed",channel.id)
    try:
        day=datetime.datetime.now(datetime.timezone.utc).date().isoformat()
        await db.execute("INSERT INTO guild_daily_metrics(guild_id,day,tickets_closed) VALUES(?,?,1) ON CONFLICT(guild_id,day) DO UPDATE SET tickets_closed=tickets_closed+1",(guild.id,day))
    except Exception:
        audit_warnings.append("daily metric unavailable")
        log.exception("Ticket %s was closed but daily metrics failed",channel.id)
    try:
        await elog(guild,"ticket","🔒 Ticket Closed",f"{channel.mention} • {reason[:300]}",actor)
    except Exception:
        audit_warnings.append("ticket log unavailable")
        log.exception("Ticket %s was closed but ticket log delivery failed",channel.id)
    # Verify persistence before deleting the workspace.
    check=await db.one("SELECT status,closed_at FROM tickets WHERE channel_id=?",(channel.id,))
    if not check or check["status"]!="closed" or not check["closed_at"]: return False,"I couldn't verify the ticket closure, so I left the channel intact."
    if delete_channel:
        try:
            await channel.delete(reason=f"Manifest ticket closed by {actor}: {reason[:300]}")
        except discord.HTTPException as ex:
            # Discord may have deleted the channel even if the response was lost.
            try:
                await guild.fetch_channel(channel.id)
                return False,"The ticket was recorded as closed, but Discord confirmed the channel still exists."
            except discord.NotFound:
                pass
            except Exception:
                return False,"The ticket database is closed, but I couldn't independently verify whether Discord deleted the channel. Staff should inspect it before retrying."
        try:
            await guild.fetch_channel(channel.id)
            return False,"The ticket was recorded as closed, but Discord still returns the channel."
        except discord.NotFound:
            pass
        except Exception:
            return False,"The ticket database is closed, but channel deletion could not be independently verified."
    try:
        detail="Ticket database closure and Discord channel deletion verified" if delete_channel else "Ticket database closure verified; channel intentionally retained"
        await action_receipt(guild,actor,"ticket.close","medium",str(channel.id),1,detail,verification_state="Manifest-verified",evidence_ref=f"ticket-close:{channel.id}",reason=reason,source=source,request_id=request_id)
    except Exception:
        audit_warnings.append("action receipt unavailable")
        log.exception("Ticket %s was closed but action receipt could not be saved",channel.id)
    suffix=(" Audit warning: "+", ".join(audit_warnings)+".") if audit_warnings else ""
    return True,"Ticket closed and verified."+suffix

class TicketMemberModal(discord.ui.Modal, title="Ticket member access"):
    member=discord.ui.TextInput(label="Member ID or @mention",placeholder="Paste a Discord user ID or mention")
    def __init__(self, *, remove=False):
        super().__init__(); self.remove=remove
    async def on_submit(self,i:discord.Interaction):
        row=await db.one("SELECT * FROM tickets WHERE channel_id=? AND status='open'",(i.channel_id,))
        if not row or not manager(i.user): return await i.response.send_message("Staff permission required in an open ticket.",ephemeral=True)
        raw=str(self.member.value); m=re.search(r"(\d{15,22})",raw)
        if not m: return await i.response.send_message("Enter a valid member ID or mention.",ephemeral=True)
        try:
            target=await i.guild.fetch_member(int(m.group(1)))
        except (discord.NotFound,discord.HTTPException):
            return await i.response.send_message("I couldn't verify that member in this server.",ephemeral=True)
        permission_applied=False
        try:
            if self.remove:
                await i.channel.set_permissions(target,overwrite=None,reason=f"Manifest ticket access removed by {i.user}")
                permission_applied=True
                # Re-evaluate effective permissions after Discord accepted the
                # overwrite change; removing a personal overwrite is not enough
                # if another role still grants the member channel visibility.
                live_channel=await i.guild.fetch_channel(i.channel_id)
                perms=live_channel.permissions_for(target)
                verified=not perms.view_channel
                if not verified:
                    return await i.response.send_message("I removed the member-specific overwrite, but they may still have access through another role. I can't truthfully confirm removal from this ticket.",ephemeral=True)
                try:
                    await db.execute("DELETE FROM ticket_members WHERE channel_id=? AND user_id=?",(i.channel_id,target.id))
                    await db.execute("INSERT INTO ticket_events(channel_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(i.channel_id,i.guild_id,i.user.id,"member_removed",str(target.id),time.time()))
                except Exception:
                    log.exception("Ticket member access was removed but its event record failed channel=%s member=%s",i.channel_id,target.id)
                try:
                    await action_receipt(i.guild,i.user,"ticket.member_remove","medium",f"{i.channel_id}:{target.id}",True,"Ticket member access removal verified",verification_state="Manifest-verified",evidence_ref=f"ticket-member-remove:{i.channel_id}:{target.id}",reason="Staff removed ticket member access",source="ticket_button",request_id=f"interaction:{i.id}")
                except Exception: log.exception("Verified ticket member removal receipt failed channel=%s member=%s",i.channel_id,target.id)
                await i.response.send_message(f"Removed {target.mention} from this ticket.",allowed_mentions=discord.AllowedMentions.none())
            else:
                await i.channel.set_permissions(target,view_channel=True,send_messages=True,read_message_history=True,reason=f"Manifest ticket access added by {i.user}")
                permission_applied=True
                live_channel=await i.guild.fetch_channel(i.channel_id)
                perms=live_channel.permissions_for(target)
                if not (perms.view_channel and perms.send_messages and perms.read_message_history):
                    return await i.response.send_message("Discord accepted the ticket permission change, but Manifest couldn't verify all required access. Check the channel before retrying.",ephemeral=True)
                audit_warnings=[]
                try:
                    await db.execute("INSERT OR REPLACE INTO ticket_members(channel_id,user_id,added_by,created_at) VALUES(?,?,?,?)",(i.channel_id,target.id,i.user.id,time.time()))
                    await db.execute("INSERT INTO ticket_events(channel_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(i.channel_id,i.guild_id,i.user.id,"member_added",str(target.id),time.time()))
                except Exception:
                    audit_warnings.append("ticket event journal unavailable")
                    log.exception("Ticket member access was added but its event record failed channel=%s member=%s",i.channel_id,target.id)
                try:
                    await action_receipt(i.guild,i.user,"ticket.member_add","medium",f"{i.channel_id}:{target.id}",True,"Ticket member access addition verified",verification_state="Manifest-verified",evidence_ref=f"ticket-member-add:{i.channel_id}:{target.id}",reason="Staff added ticket member access",source="ticket_button",request_id=f"interaction:{i.id}")
                except Exception:
                    audit_warnings.append("action receipt unavailable")
                    log.exception("Verified ticket member addition receipt failed channel=%s member=%s",i.channel_id,target.id)
                suffix=(" Audit warning: "+", ".join(audit_warnings)+".") if audit_warnings else ""
                await i.response.send_message(f"Added {target.mention} to this ticket."+suffix,allowed_mentions=discord.AllowedMentions.none())
        except discord.HTTPException:
            message=("Discord accepted the permission change, but live verification failed. Inspect this ticket before retrying." if permission_applied else "Discord rejected that permission change. Check Manifest's role/permissions.")
            await i.response.send_message(message,ephemeral=True)



async def claim_ticket_atomic(guild_id:int,channel_id:int,actor,*,allow_resolved=False):
    """Claim one Manifest ticket without overwriting another staff member.

    Returns (success, state, claimed_by). A repeated click by the current claimant
    is idempotent and does not create another event or receipt.
    """
    statuses=("open","resolved") if allow_resolved else ("open",)
    placeholders=",".join("?" for _ in statuses)
    params=(int(guild_id),int(channel_id))
    row=await db.one(
        f"SELECT claimed_by,status FROM tickets WHERE guild_id=? AND channel_id=? AND status IN ({placeholders})",
        (*params,*statuses)
    )
    if not row:
        return False,"not_open",0
    current=int(row["claimed_by"] or 0)
    if current==int(actor.id):
        if allow_resolved and row["status"]=="resolved":
            cur=await db.execute(
                "UPDATE tickets SET status='open',reopened_at=? WHERE guild_id=? AND channel_id=? AND status='resolved' AND claimed_by=?",
                (time.time(),int(guild_id),int(channel_id),int(actor.id))
            )
            changed=int(getattr(cur,"rowcount",0) or 0)
            try: await cur.close()
            except Exception: pass
            if changed:
                try:
                    await db.execute("INSERT INTO ticket_events(channel_id,guild_id,actor_id,event_type,created_at) VALUES(?,?,?,?,?)",(int(channel_id),int(guild_id),int(actor.id),"reopened",time.time()))
                except Exception: log.exception("Ticket %s reopened but event journaling failed",channel_id)
                return True,"reopened",int(actor.id)
        return True,"already",int(actor.id)
    if current:
        return False,"claimed",current
    cur=await db.execute(
        f"UPDATE tickets SET claimed_by=?,status='open' WHERE guild_id=? AND channel_id=? AND status IN ({placeholders}) AND COALESCE(claimed_by,0)=0",
        (int(actor.id),int(guild_id),int(channel_id),*statuses)
    )
    changed=int(getattr(cur,"rowcount",0) or 0)
    try: await cur.close()
    except Exception: pass
    fresh=await db.one("SELECT claimed_by,status FROM tickets WHERE guild_id=? AND channel_id=?",(int(guild_id),int(channel_id)))
    if changed==1 and fresh and int(fresh["claimed_by"] or 0)==int(actor.id) and fresh["status"]=="open":
        try:
            await db.execute("INSERT INTO ticket_events(channel_id,guild_id,actor_id,event_type,created_at) VALUES(?,?,?,?,?)",(int(channel_id),int(guild_id),int(actor.id),"claimed",time.time()))
        except Exception: log.exception("Ticket %s claimed by %s but event journaling failed",channel_id,actor.id)
        return True,"claimed",int(actor.id)
    if fresh and int(fresh["claimed_by"] or 0)==int(actor.id):
        return True,"already",int(actor.id)
    if fresh and int(fresh["claimed_by"] or 0):
        return False,"claimed",int(fresh["claimed_by"])
    return False,"not_open",0

class TicketActions(discord.ui.Select):
    def __init__(self):
        super().__init__(placeholder="More ticket actions…",custom_id="manifest:v4:ticket:actions",min_values=1,max_values=1,options=[
            discord.SelectOption(label="Add member",value="add",emoji="➕"),
            discord.SelectOption(label="Remove member",value="remove",emoji="➖"),
            discord.SelectOption(label="Unclaim",value="unclaim",emoji="↩️"),
            discord.SelectOption(label="Mark resolved",value="resolve",emoji="✅"),
            discord.SelectOption(label="Set priority",value="priority",emoji="⚡"),
            discord.SelectOption(label="Reopen",value="reopen",emoji="🔓"),
            discord.SelectOption(label="Private transcript",value="transcript",emoji="📄"),
            discord.SelectOption(label="Ticket info",value="info",emoji="ℹ️"),
        ])
    async def callback(self,i:discord.Interaction):
        row=await db.one("SELECT * FROM tickets WHERE channel_id=?",(i.channel_id,))
        if not row: return await i.response.send_message("This isn't a Manifest ticket.",ephemeral=True)
        v=self.values[0]
        if v in {"add","remove","unclaim","resolve","priority","reopen"} and not manager(i.user): return await i.response.send_message("Staff permission required.",ephemeral=True)
        if v=="add": return await i.response.send_modal(TicketMemberModal(remove=False))
        if v=="remove": return await i.response.send_modal(TicketMemberModal(remove=True))
        if v=="unclaim":
            await db.execute("UPDATE tickets SET claimed_by=0 WHERE channel_id=?",(i.channel_id,)); await db.execute("INSERT INTO ticket_events(channel_id,guild_id,actor_id,event_type,created_at) VALUES(?,?,?,?,?)",(i.channel_id,i.guild_id,i.user.id,"unclaimed",time.time()))
            check=await db.one("SELECT claimed_by FROM tickets WHERE channel_id=?",(i.channel_id,))
            if check and int(check['claimed_by'] or 0)==0: await action_receipt(i.guild,i.user,"ticket.unclaim","medium",str(i.channel_id),True,"Ticket unclaim verified",verification_state="Manifest-verified",evidence_ref=f"ticket-unclaim:{i.channel_id}",reason="Staff ticket unclaim",source="ticket_button",request_id=f"interaction:{i.id}")
            return await i.response.send_message("Ticket is unclaimed.")
        if v=="resolve":
            await db.execute("UPDATE tickets SET status='resolved',resolved_at=? WHERE channel_id=?",(time.time(),i.channel_id)); await db.execute("INSERT INTO ticket_events(channel_id,guild_id,actor_id,event_type,created_at) VALUES(?,?,?,?,?)",(i.channel_id,i.guild_id,i.user.id,"resolved",time.time()))
            check=await db.one("SELECT status FROM tickets WHERE channel_id=?",(i.channel_id,))
            if check and check['status']=="resolved": await action_receipt(i.guild,i.user,"ticket.resolve","medium",str(i.channel_id),True,"Ticket resolution verified",verification_state="Manifest-verified",evidence_ref=f"ticket-resolve:{i.channel_id}",reason="Staff marked ticket resolved",source="ticket_button",request_id=f"interaction:{i.id}")
            return await i.response.send_message("✅ Marked resolved. Staff can still close it when ready.")
        if v=="priority":
            levels=["low","normal","high","urgent"]; current=(row["priority"] or "normal") if "priority" in row.keys() else "normal"; new=levels[(levels.index(current)+1)%len(levels)] if current in levels else "normal"
            await db.execute("UPDATE tickets SET priority=? WHERE channel_id=?",(new,i.channel_id)); await db.execute("INSERT INTO ticket_events(channel_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(i.channel_id,i.guild_id,i.user.id,"priority",new,time.time()))
            check=await db.one("SELECT priority FROM tickets WHERE channel_id=?",(i.channel_id,))
            if check and check['priority']==new: await action_receipt(i.guild,i.user,"ticket.priority","low",str(i.channel_id),True,f"Ticket priority changed to {new} and verified",verification_state="Manifest-verified",evidence_ref=f"ticket-priority:{i.channel_id}:{new}",reason="Staff changed ticket priority",source="ticket_button",request_id=f"interaction:{i.id}")
            return await i.response.send_message(f"⚡ Priority → **{new}**.")
        if v=="reopen":
            await db.execute("UPDATE tickets SET status='open',reopened_at=? WHERE channel_id=?",(time.time(),i.channel_id)); await db.execute("INSERT INTO ticket_events(channel_id,guild_id,actor_id,event_type,created_at) VALUES(?,?,?,?,?)",(i.channel_id,i.guild_id,i.user.id,"reopened",time.time()))
            check=await db.one("SELECT status FROM tickets WHERE channel_id=?",(i.channel_id,))
            if check and check['status']=="open": await action_receipt(i.guild,i.user,"ticket.reopen","medium",str(i.channel_id),True,"Ticket reopen verified",verification_state="Manifest-verified",evidence_ref=f"ticket-reopen:{i.channel_id}",reason="Staff reopened ticket",source="ticket_button",request_id=f"interaction:{i.id}")
            return await i.response.send_message("🔓 Ticket reopened.")
        if v=="transcript":
            perms=i.channel.permissions_for(i.user)
            if not (perms.view_channel and perms.read_message_history):return await i.response.send_message("You need live View Channel and Read Message History access to export this ticket.",ephemeral=True)
            if i.user.id!=int(row['user_id']) and not manager(i.user):return await i.response.send_message("Only the ticket opener or authorized staff can export this transcript.",ephemeral=True)
            await i.response.defer(ephemeral=True)
            try:
                data,count=await build_ticket_transcript(i.channel,500)
                await db.execute("INSERT INTO ticket_events(channel_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(i.channel_id,i.guild_id,i.user.id,'transcript_exported',f'messages={count}',time.time()))
                return await i.followup.send(f"📄 Private transcript generated from **{count}** visible message(s).",file=discord.File(io.BytesIO(data),filename=f"manifest-ticket-{i.channel_id}.txt"),ephemeral=True)
            except discord.Forbidden:return await i.followup.send("Manifest cannot read this ticket's message history with its current Discord permissions.",ephemeral=True)
            except discord.HTTPException:return await i.followup.send("Manifest couldn't complete the transcript export. Nothing in the ticket was changed.",ephemeral=True)
        claimer=i.guild.get_member(int(row['claimed_by'] or 0))
        return await i.response.send_message(f"Status: **{row['status']}** • Type: **{row['ticket_type'] if 'ticket_type' in row.keys() else 'support'}** • Priority: **{row['priority'] if 'priority' in row.keys() else 'normal'}** • Opened by <@{row['user_id']}> • Claimed by {claimer.mention if claimer else '**nobody**'}",ephemeral=True,allowed_mentions=discord.AllowedMentions.none())

class TicketControlView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None); self.add_item(TicketActions())
    @discord.ui.button(label="Claim",emoji="🙋",style=discord.ButtonStyle.secondary,custom_id="manifest:v4:ticket:claim")
    async def claim(self,i:discord.Interaction,b:discord.ui.Button):
        row=await db.one("SELECT * FROM tickets WHERE channel_id=? AND status IN ('open','resolved')",(i.channel_id,))
        if not row:return await i.response.send_message("This isn't an active Manifest ticket.",ephemeral=True)
        if not manager(i.user):return await i.response.send_message("Staff permission required.",ephemeral=True)
        claimed,state,claimer_id=await claim_ticket_atomic(i.guild_id,i.channel_id,i.user,allow_resolved=True)
        if not claimed:
            if state=="claimed":
                claimer=i.guild.get_member(claimer_id)
                who=claimer.mention if claimer else f"<@{claimer_id}>"
                return await i.response.send_message(f"This ticket is already claimed by {who}.",ephemeral=True)
            return await i.response.send_message("This ticket is no longer open or available to claim.",ephemeral=True)
        if state=="already":
            return await i.response.send_message("🙋 This ticket is already assigned to you.",ephemeral=True)
        await action_receipt(i.guild,i.user,"ticket.claim","medium",str(i.channel_id),True,"Ticket claim atomically applied and verified",verification_state="Manifest-verified",evidence_ref=f"ticket-claim:{i.channel_id}",reason="Staff ticket claim",source="ticket_button",request_id=f"interaction:{i.id}")
        await i.response.send_message(f"🙋 Claimed by {i.user.mention}.")
    @discord.ui.button(label="Close",emoji="🔒",style=discord.ButtonStyle.danger,custom_id="manifest:v4:ticket:close")
    async def close(self,i:discord.Interaction,b:discord.ui.Button):
        row=await db.one("SELECT * FROM tickets WHERE channel_id=? AND status IN ('open','resolved')",(i.channel_id,))
        if not row:return await i.response.send_message("This isn't an active Manifest ticket.",ephemeral=True)
        if i.user.id!=row['user_id'] and not manager(i.user):return await i.response.send_message("You can't close this ticket.",ephemeral=True)
        await i.response.send_message("🔒 Closing this ticket…")
        await asyncio.sleep(1)
        ok,msg=await close_ticket_capability(i.guild,i.channel,i.user,reason="Closed from ticket controls",source="ticket_button",request_id=f"interaction:{i.id}")
        if not ok:
            try: await i.followup.send(f"⚠️ {msg}",ephemeral=True)
            except discord.HTTPException: pass

