async def build_ticket_transcript(channel:discord.TextChannel,limit:int=1000):
    """Create a bounded plain-text transcript only from messages the requester can already read."""
    lines=[];count=0
    async for m in channel.history(limit=max(1,min(int(limit),1000)),oldest_first=True):
        stamp=m.created_at.astimezone(datetime.timezone.utc).strftime('%Y-%m-%d %H:%M:%S UTC')
        content=(m.clean_content or '').replace('\x00','')[:3500]
        attach=' '.join(a.url for a in m.attachments[:5])
        body=content+((' [attachments: '+attach+']') if attach else '')
        lines.append(f"[{stamp}] {m.author} ({m.author.id}): {body}")
        count+=1
    header=f"Manifest ticket transcript\nServer: {channel.guild.name} ({channel.guild.id})\nChannel: #{channel.name} ({channel.id})\nMessages: {count}\nGenerated: {datetime.datetime.now(datetime.timezone.utc).isoformat()}\n\n"
    data=(header+'\n'.join(lines)).encode('utf-8','replace')
    # Keep comfortably below common Discord upload limits; truncate oldest content only if needed.
    if len(data)>7_500_000:data=data[-7_500_000:]
    return data,count

@ticket_group.command(name="transcript",description="Export a private transcript of the current Manifest ticket")
async def ticket_transcript(i:discord.Interaction,limit:app_commands.Range[int,50,1000]=500):
    if not i.guild or not isinstance(i.channel,discord.TextChannel):return await i.response.send_message("Open this inside a Manifest ticket channel.",ephemeral=True)
    row=await db.one("SELECT * FROM tickets WHERE guild_id=? AND channel_id=?",(i.guild_id,i.channel_id))
    if not row:return await i.response.send_message("This isn't a Manifest ticket.",ephemeral=True)
    perms=i.channel.permissions_for(i.user)
    if not (perms.view_channel and perms.read_message_history):return await i.response.send_message("You need live View Channel and Read Message History access to export this ticket.",ephemeral=True)
    if i.user.id!=int(row['user_id']) and not manager(i.user):return await i.response.send_message("Only the ticket opener or authorized staff can export this transcript.",ephemeral=True)
    await i.response.defer(ephemeral=True)
    try:
        data,count=await build_ticket_transcript(i.channel,int(limit))
        filename=f"manifest-ticket-{i.channel_id}.txt"
        await db.execute("INSERT INTO ticket_events(channel_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(i.channel_id,i.guild_id,i.user.id,'transcript_exported',f'messages={count}',time.time()))
        await i.followup.send(f"📄 Private transcript generated from **{count}** visible message(s).",file=discord.File(io.BytesIO(data),filename=filename),ephemeral=True)
    except discord.Forbidden:
        await i.followup.send("Manifest cannot read this ticket's message history with its current Discord permissions.",ephemeral=True)
    except discord.HTTPException:
        await i.followup.send("Manifest couldn't complete the transcript export. Nothing in the ticket was changed.",ephemeral=True)

