@autopilot_group.command(name="setup",description="Apply a safe starter setup from Manifest's server scan")
async def autopilot_setup(i:discord.Interaction,apply:bool=False):
    if not manager(i.user):return await i.response.send_message("You need Manage Server.",ephemeral=True)
    await update_server_needs(i.guild)
    if not apply:
        await i.response.send_message("🧠 I can safely create missing onboarding channels, but I will not change or delete existing channels. Run `/autopilot setup apply:true` to apply the starter setup.",ephemeral=True);return
    if not i.guild.me.guild_permissions.manage_channels:
        return await i.response.send_message("Manifest needs **Manage Channels** to apply the starter setup.",ephemeral=True)
    names={c.name.lower() for c in i.guild.text_channels}
    created=[]
    for name in ("welcome","rules","support"):
        if name in names:continue
        try:
            c=await i.guild.create_text_channel(name,reason=f"Manifest Autopilot starter setup by {i.user}")
            created.append(c.mention)
        except discord.HTTPException:continue
    await db.execute("UPDATE autopilot_config SET auto_setup_enabled=1,last_setup_at=? WHERE guild_id=?",(time.time(),i.guild_id))
    await i.response.send_message("🤖 Starter setup complete: "+(", ".join(created) if created else "nothing was missing"),ephemeral=True)


# ========================= V17 COMMUNITY / MANAGEMENT =========================
def can_manage(i):
    return bool(i.guild and (i.user.id==i.guild.owner_id or i.user.guild_permissions.administrator or i.user.guild_permissions.manage_guild))

def parse_duration(raw:str):
    m=re.fullmatch(r"\s*(\d+)\s*([smhdw]?)\s*",raw.lower())
    if not m:return None
    n=int(m.group(1)); unit=m.group(2) or "m"; mult={"s":1,"m":60,"h":3600,"d":86400,"w":604800}[unit]
    return min(n*mult,60*60*24*365)

