@level_group.command(name="config",description="Configure XP anti-farm and booster behavior")
async def level_config(i:discord.Interaction,enabled:bool|None=None,cooldown_seconds:int|None=None,booster_multiplier:float|None=None):
    if not can_manage(i):return await i.response.send_message("Manage Server required.",ephemeral=True)
    cfg=await _xp_config(i.guild_id)
    enabled=int(cfg['enabled']) if enabled is None else int(enabled)
    cooldown=max(15,min(600,cooldown_seconds if cooldown_seconds is not None else int(cfg['cooldown_seconds'])))
    boost=max(1.0,min(3.0,booster_multiplier if booster_multiplier is not None else float(cfg['booster_multiplier'])))
    await db.execute("UPDATE xp_config SET enabled=?,cooldown_seconds=?,booster_multiplier=?,updated_at=? WHERE guild_id=?",(enabled,cooldown,boost,time.time(),i.guild_id))
    await i.response.send_message(f"✅ XP {'enabled' if enabled else 'disabled'} • cooldown **{cooldown}s** • booster ×**{boost:g}**",ephemeral=True)

