@level_group.command(name="reward",description="Configure a level/XP reward role")
async def level_reward(i:discord.Interaction,role:discord.Role,level_required:int=0,xp_required:int=0,remove_previous:bool=False):
    if not can_manage(i):return await i.response.send_message("Manage Server required.",ephemeral=True)
    me=i.guild.me
    if role.is_default() or role.managed or not me or me.top_role<=role:return await i.response.send_message("I can only manage ordinary roles below Manifest's highest role.",ephemeral=True)
    await db.execute("INSERT INTO xp_reward_roles(guild_id,role_id,level_required,xp_required,remove_previous,enabled) VALUES(?,?,?,?,?,1) ON CONFLICT(guild_id,role_id) DO UPDATE SET level_required=excluded.level_required,xp_required=excluded.xp_required,remove_previous=excluded.remove_previous,enabled=1",(i.guild_id,role.id,max(0,level_required),max(0,xp_required),int(remove_previous)))
    await i.response.send_message(f"✅ {role.mention} unlocks at level **{max(0,level_required)}** / **{max(0,xp_required):,} XP**. Existing Discord roles are otherwise untouched.",ephemeral=True)

