@level_group.command(name="boost",description="Create a temporary XP event multiplier")
async def level_boost(i:discord.Interaction,multiplier:float,hours:int,label:str="XP event",role:discord.Role|None=None,member:discord.Member|None=None):
    if not can_manage(i):return await i.response.send_message("Manage Server required.",ephemeral=True)
    if bool(role) and bool(member):return await i.response.send_message("Choose either a role or a member, not both.",ephemeral=True)
    multiplier=max(1.0,min(3.0,multiplier));hours=max(1,min(168,hours));now=time.time()
    await db.execute("INSERT INTO xp_temporary_modifiers(guild_id,user_id,role_id,multiplier,label,starts_at,ends_at,created_by,enabled) VALUES(?,?,?,?,?,?,?,?,1)",(i.guild_id,member.id if member else 0,role.id if role else 0,multiplier,label[:80],now,now+hours*3600,i.user.id))
    target=member.mention if member else role.mention if role else "everyone"
    await i.response.send_message(f"✅ **{label[:80]}**: ×{multiplier:g} XP for {target} for **{hours}h**. Total XP stacking remains safety-capped.",ephemeral=True)

