@info_group.command(name="invite_reward",description="Configure a safe invite milestone reward role")
async def invite_reward(i:discord.Interaction,role:discord.Role,invites_required:int):
    if not can_manage(i):return await i.response.send_message("Manage Server required.",ephemeral=True)
    me=i.guild.me
    if role.is_default() or role.managed or not me or me.top_role<=role:return await i.response.send_message("I can only grant ordinary roles below Manifest's highest role.",ephemeral=True)
    n=max(1,min(10000,invites_required))
    await db.execute("INSERT INTO invite_config(guild_id,enabled,track_leaves,reward_role_id,reward_at,updated_at) VALUES(?,1,1,?,?,?) ON CONFLICT(guild_id) DO UPDATE SET enabled=1,reward_role_id=excluded.reward_role_id,reward_at=excluded.reward_at,updated_at=excluded.updated_at",(i.guild_id,role.id,n,time.time()))
    await i.response.send_message(f"✅ {role.mention} is the invite milestone reward at **{n}** tracked joins. Manifest will never edit unrelated roles.",ephemeral=True)

def _period_days(period:str):
    return {'24h':1,'7d':7,'30d':30,'3m':90,'1y':365,'all':36500}.get(period.lower(),30)

@activity_group.command(name="overview",description="Historical server activity overview")
@app_commands.choices(period=[app_commands.Choice(name=x.upper(),value=x) for x in ('24h','7d','30d','3m','1y','all')])
async def activity_overview(i:discord.Interaction,period:app_commands.Choice[str]|None=None):
    p=(period.value if period else '30d');days=_period_days(p);start=(datetime.datetime.now(datetime.timezone.utc)-datetime.timedelta(days=days-1)).date().isoformat()
    rows=await db.all("SELECT * FROM guild_daily_metrics WHERE guild_id=? AND day>=? ORDER BY day",(i.guild_id,start))
    messages=sum(int(r['messages']) for r in rows);joins=sum(int(r['joins']) for r in rows);leaves=sum(int(r['leaves']) for r in rows)
    active=await db.one("SELECT COUNT(DISTINCT user_id) n FROM daily_active_users WHERE guild_id=? AND day>=?",(i.guild_id,start))
    xp=await db.one("SELECT COALESCE(SUM(amount),0) n FROM xp_events WHERE guild_id=? AND created_at>=?",(i.guild_id,time.time()-days*86400))
    inv=await db.one("SELECT COUNT(*) n FROM invite_events WHERE guild_id=? AND event_type='join' AND created_at>=?",(i.guild_id,time.time()-days*86400))
    e=discord.Embed(title=f"📊 Server Activity • {p.upper()}",color=discord.Color.blurple())
    e.add_field(name="Messages",value=f"{messages:,}");e.add_field(name="Unique active",value=f"{int(active['n'] or 0):,}");e.add_field(name="Net growth",value=f"{joins-leaves:+,}")
    e.add_field(name="Joins / Leaves",value=f"{joins:,} / {leaves:,}");e.add_field(name="Tracked invites",value=f"{int(inv['n'] or 0):,}");e.add_field(name="XP earned",value=f"{int(xp['n'] or 0):,}")
    e.set_footer(text="Historical metrics are recorded by Manifest; unavailable periods are not estimated.")
    await i.response.send_message(embed=e)

@activity_group.command(name="trend",description="Daily message and growth trend")
async def activity_trend(i:discord.Interaction,days:int=30):
    days=max(2,min(90,days));start=(datetime.datetime.now(datetime.timezone.utc)-datetime.timedelta(days=days-1)).date().isoformat()
    rows=await db.all("SELECT day,messages,joins,leaves,unique_users FROM guild_daily_metrics WHERE guild_id=? AND day>=? ORDER BY day",(i.guild_id,start))
    if not rows:return await i.response.send_message("No historical activity has been recorded for that period yet.",ephemeral=True)
    # Discord embeds cannot render native charts without an image dependency; provide an honest compact trend and keep raw history for future chart rendering.
    peak=max(rows,key=lambda r:int(r['messages']));total=sum(int(r['messages']) for r in rows);net=sum(int(r['joins'])-int(r['leaves']) for r in rows)
    recent=rows[-7:];lines=[f"`{r['day'][5:]}` {int(r['messages']):>5} msgs • {int(r['unique_users']):>3} active • {int(r['joins'])-int(r['leaves']):+} net" for r in recent]
    e=discord.Embed(title=f"📈 Activity Trend • {days}D",description="\n".join(lines),color=discord.Color.blurple())
    e.add_field(name="Messages",value=f"{total:,}");e.add_field(name="Net growth",value=f"{net:+,}");e.add_field(name="Peak day",value=f"{peak['day']} • {int(peak['messages']):,} messages")
    e.set_footer(text="Showing the latest 7 daily rows; totals cover the requested period.")
    await i.response.send_message(embed=e)

@activity_group.command(name="channels",description="Most active channels in a historical period")
@app_commands.choices(period=[app_commands.Choice(name=x.upper(),value=x) for x in ('24h','7d','30d','3m','1y','all')])
async def activity_channels(i:discord.Interaction,period:app_commands.Choice[str]|None=None):
    p=period.value if period else '30d';days=_period_days(p);start=(datetime.datetime.now(datetime.timezone.utc)-datetime.timedelta(days=days-1)).date().isoformat()
    rows=await db.all("SELECT channel_id,SUM(messages) messages,MAX(unique_users) active FROM channel_daily_metrics WHERE guild_id=? AND day>=? GROUP BY channel_id ORDER BY messages DESC LIMIT 10",(i.guild_id,start))
    if not rows:return await i.response.send_message("No channel history has been recorded for that period yet.",ephemeral=True)
    lines=[]
    for r in rows:
        ch=i.guild.get_channel(int(r['channel_id']));name=ch.mention if ch else f"Deleted channel `{r['channel_id']}`"
        lines.append(f"{name} — **{int(r['messages']):,}** messages")
    await i.response.send_message(embed=discord.Embed(title=f"💬 Channel Activity • {p.upper()}",description="\n".join(lines),color=discord.Color.blurple()))

@activity_group.command(name="busy_times",description="Show the server's busiest UTC hours")
@app_commands.choices(period=[app_commands.Choice(name=x.upper(),value=x) for x in ('7d','30d','3m','1y','all')])
async def activity_busy_times(i:discord.Interaction,period:app_commands.Choice[str]|None=None):
    p=period.value if period else '30d';days=_period_days(p);start=(datetime.datetime.now(datetime.timezone.utc)-datetime.timedelta(days=days-1)).date().isoformat()
    rows=await db.all("SELECT hour,SUM(messages) messages FROM hourly_activity WHERE guild_id=? AND day>=? GROUP BY hour ORDER BY messages DESC",(i.guild_id,start))
    if not rows:return await i.response.send_message("No hourly history has been recorded for that period yet.",ephemeral=True)
    top=rows[:6];total=sum(int(r['messages']) for r in rows) or 1
    text="\n".join(f"`{int(r['hour']):02d}:00–{(int(r['hour'])+1)%24:02d}:00 UTC` — **{int(r['messages']):,}** ({int(r['messages'])/total:.0%})" for r in top)
    await i.response.send_message(embed=discord.Embed(title=f"🕒 Busy Times • {p.upper()}",description=text,color=discord.Color.blurple()))

@activity_group.command(name="workload",description="Ticket, moderation, security and staff workload")
@app_commands.choices(period=[app_commands.Choice(name=x.upper(),value=x) for x in ('24h','7d','30d','3m','1y','all')])
async def activity_workload(i:discord.Interaction,period:app_commands.Choice[str]|None=None):
    if not can_manage(i):return await i.response.send_message("Manage Server required.",ephemeral=True)
    p=period.value if period else '30d';days=_period_days(p);cut=time.time()-days*86400
    tickets=await db.one("SELECT COUNT(*) opened,SUM(CASE WHEN event_type='closed' THEN 1 ELSE 0 END) closed FROM ticket_events WHERE guild_id=? AND created_at>=?",(i.guild_id,cut))
    cases=await db.one("SELECT COUNT(*) n FROM mod_cases WHERE guild_id=? AND created_at>=?",(i.guild_id,cut))
    security=await db.one("SELECT COUNT(*) n FROM security_events WHERE guild_id=? AND created_at>=?",(i.guild_id,cut))
    staff=await db.one("SELECT COUNT(*) n FROM staff_events WHERE guild_id=? AND created_at>=?",(i.guild_id,cut))
    opened=await db.one("SELECT COUNT(*) n FROM ticket_events WHERE guild_id=? AND event_type='opened' AND created_at>=?",(i.guild_id,cut))
    closed=await db.one("SELECT COUNT(*) n FROM ticket_events WHERE guild_id=? AND event_type='closed' AND created_at>=?",(i.guild_id,cut))
    e=discord.Embed(title=f"🧭 Operational Workload • {p.upper()}",color=discord.Color.blurple())
    e.add_field(name="Tickets",value=f"{int(opened['n'] or 0):,} opened • {int(closed['n'] or 0):,} closed")
    e.add_field(name="Moderation cases",value=f"{int(cases['n'] or 0):,}");e.add_field(name="Security events",value=f"{int(security['n'] or 0):,}");e.add_field(name="Staff workflow events",value=f"{int(staff['n'] or 0):,}")
    e.set_footer(text="Counts are operational events, not judgments about staff performance.")
    await i.response.send_message(embed=e,ephemeral=True)

@activity_group.command(name="retention",description="Show measured join retention cohorts")
async def activity_retention(i:discord.Interaction,cohort_days:int=30):
    cohort_days=max(7,min(180,cohort_days));now=time.time();start=now-cohort_days*86400;eligible_end=now-7*86400
    rows=await db.all("SELECT user_id,MIN(created_at) joined FROM member_presence_events WHERE guild_id=? AND event_type='join' AND created_at BETWEEN ? AND ? GROUP BY user_id",(i.guild_id,start,eligible_end))
    if not rows:return await i.response.send_message("Not enough recorded join history for a 7-day retention cohort yet.",ephemeral=True)
    retained=0;left=0
    for r in rows:
        leave=await db.one("SELECT created_at FROM member_presence_events WHERE guild_id=? AND user_id=? AND event_type='leave' AND created_at>? AND created_at<=? ORDER BY created_at LIMIT 1",(i.guild_id,r['user_id'],r['joined'],float(r['joined'])+7*86400))
        if leave:left+=1
        else:retained+=1
    total=len(rows);rate=retained/total if total else 0
    e=discord.Embed(title="📌 7-Day Join Retention",description=f"Measured from **{total:,}** joins with at least seven days of observation.",color=discord.Color.blurple())
    e.add_field(name="Retained through day 7",value=f"{retained:,} ({rate:.1%})");e.add_field(name="Left within 7 days",value=f"{left:,}")
    e.set_footer(text="Manifest only uses events recorded since this analytics system began; it does not invent older cohorts.")
    await i.response.send_message(embed=e)

@activity_group.command(name="voice",description="Measured voice activity for a historical period")
@app_commands.choices(period=[app_commands.Choice(name=x.upper(),value=x) for x in ('24h','7d','30d','3m','1y','all')])
async def activity_voice(i:discord.Interaction,period:app_commands.Choice[str]|None=None):
    p=period.value if period else '30d';days=_period_days(p);cut=time.time()-days*86400
    row=await db.one("SELECT COALESCE(SUM(duration_seconds),0) seconds,COUNT(DISTINCT user_id) users,COUNT(*) sessions FROM voice_sessions WHERE guild_id=? AND joined_at>=? AND left_at>0",(i.guild_id,cut))
    sec=int(row['seconds'] or 0);hours=sec/3600
    e=discord.Embed(title=f"🎙️ Voice Activity • {p.upper()}",color=discord.Color.blurple())
    e.add_field(name="Measured voice time",value=f"{hours:,.1f} hours");e.add_field(name="Participants",value=f"{int(row['users'] or 0):,}");e.add_field(name="Completed sessions",value=f"{int(row['sessions'] or 0):,}")
    e.set_footer(text="Only completed voice sessions recorded by Manifest are included.")
    await i.response.send_message(embed=e)

