async def send_submission(i,kind,name,description,file):
    now=time.time();cur=await db.execute("INSERT INTO submissions(kind,guild_id,user_id,name,description,created_at,updated_at) VALUES(?,?,?,?,?,?,?)",(kind,i.guild_id or 0,i.user.id,name[:120],description[:1800],now,now))
    rid=cur.lastrowid
    await db.execute("INSERT INTO submission_events(submission_id,kind,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(rid,kind,i.user.id,'created','',now))
    e=discord.Embed(title=f"{kind.title()} #{rid}: {name[:120]}",description=description[:4000],color=discord.Color.blurple());e.add_field(name="From",value=f"{i.user} (`{i.user.id}`)");e.add_field(name="Server",value=f"{i.guild.name if i.guild else 'DM'} (`{i.guild_id or 0}`)")
    if file:e.add_field(name="Attachment",value=file.url[:1024],inline=False)
    delivered=0
    for oid in {MAKER_USER_ID,CO_OWNER_ID}-{0}:
        try:u=bot.get_user(oid) or await bot.fetch_user(oid);await u.send(embed=e);delivered+=1
        except discord.HTTPException:pass
    await db.execute("INSERT INTO submission_events(submission_id,kind,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(rid,kind,0,'owner_notification',f'delivered={delivered}',time.time()))
    await i.response.send_message(f"✅ {kind.title()} submitted as `#{rid}`.",ephemeral=True)
