@owner_group.command(name="submission_update",description="Update a bug/suggestion lifecycle state")
@app_commands.choices(status=[app_commands.Choice(name=x.title(),value=x) for x in ('pending','reviewing','planned','resolved','declined')])
async def owner_submission_update(i:discord.Interaction,submission_id:int,status:app_commands.Choice[str],resolution:str=""):
    if not manifest_has_global_capability(i.user,"feedback.manage"):return await i.response.send_message("Manifest feedback-management access required.",ephemeral=True)
    r=await db.one("SELECT * FROM submissions WHERE id=?",(submission_id,))
    if not r:return await i.response.send_message("Submission not found.",ephemeral=True)
    await db.execute("UPDATE submissions SET status=?,resolution=?,handled_by=?,updated_at=? WHERE id=?",(status.value,resolution[:1800],i.user.id,time.time(),submission_id))
    await db.execute("INSERT INTO submission_events(submission_id,kind,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(submission_id,r['kind'],i.user.id,'status_changed',f"{r['status']}->{status.value}; {resolution[:500]}",time.time()))
    try:
        u=bot.get_user(r['user_id']) or await bot.fetch_user(r['user_id']);await u.send(f"📬 Your Manifest {r['kind']} `#{submission_id}` is now **{status.value}**."+(f"\n{resolution[:1500]}" if resolution else ''))
    except discord.HTTPException:pass
    await i.response.send_message(f"✅ Submission `#{submission_id}` → **{status.value}**.",ephemeral=True)

@waitlist_group.command(name="setup",description="Create/update a waitlist")
async def wait_setup(i:discord.Interaction,name:str,pattern:str,channel:discord.TextChannel):
    if not can_manage(i):return await i.response.send_message("Manage Server required.",ephemeral=True)
    await db.execute("INSERT INTO waitlists(guild_id,name,pattern,channel_id) VALUES(?,?,?,?) ON CONFLICT(guild_id,name) DO UPDATE SET pattern=excluded.pattern,channel_id=excluded.channel_id",(i.guild_id,name[:80],pattern[:120],channel.id));await i.response.send_message("✅ Waitlist configured.",ephemeral=True)
@waitlist_group.command(name="add",description="Add a member to a waitlist")
async def wait_add(i:discord.Interaction,user:discord.Member,name:str):
    if not can_manage(i):return await i.response.send_message("Manage Server required.",ephemeral=True)
    w=await db.one("SELECT id FROM waitlists WHERE guild_id=? AND name=?",(i.guild_id,name));
    if not w:return await i.response.send_message("Waitlist not found.",ephemeral=True)
    r=await db.one("SELECT COALESCE(MAX(position),0)+1 n FROM waitlist_members WHERE waitlist_id=?",(w['id'],));await db.execute("INSERT OR IGNORE INTO waitlist_members(waitlist_id,user_id,position) VALUES(?,?,?)",(w['id'],user.id,r['n']));await i.response.send_message(f"✅ Added {user.mention}.",ephemeral=True)
@waitlist_group.command(name="view",description="View a waitlist")
async def wait_view(i:discord.Interaction,name:str):
    w=await db.one("SELECT id FROM waitlists WHERE guild_id=? AND name=?",(i.guild_id,name));
    if not w:return await i.response.send_message("Waitlist not found.",ephemeral=True)
    rows=await db.all("SELECT user_id,position FROM waitlist_members WHERE waitlist_id=? ORDER BY position LIMIT 50",(w['id'],));await i.response.send_message(embed=discord.Embed(title=f"⏳ {name}",description="\n".join(f"**{r['position']}.** <@{r['user_id']}>" for r in rows) or "Empty.",color=discord.Color.blurple()))
@waitlist_group.command(name="refresh",description="Renumber a waitlist")
async def wait_refresh(i:discord.Interaction,name:str):
    if not can_manage(i):return await i.response.send_message("Manage Server required.",ephemeral=True)
    w=await db.one("SELECT id FROM waitlists WHERE guild_id=? AND name=?",(i.guild_id,name));rows=await db.all("SELECT id FROM waitlist_members WHERE waitlist_id=? ORDER BY position,id",(w['id'],)) if w else []
    for n,r in enumerate(rows,1):await db.execute("UPDATE waitlist_members SET position=? WHERE id=?",(n,r['id']))
    await i.response.send_message("✅ Refreshed.",ephemeral=True)
@waitlist_group.command(name="edit",description="Edit waitlist pattern/channel")
async def wait_edit(i:discord.Interaction,name:str,pattern:str,channel:discord.TextChannel):
    if not can_manage(i):return await i.response.send_message("Manage Server required.",ephemeral=True)
    await db.execute("UPDATE waitlists SET pattern=?,channel_id=? WHERE guild_id=? AND name=?",(pattern[:120],channel.id,i.guild_id,name));await i.response.send_message("✅ Updated.",ephemeral=True)

