# ========================= MANIFEST CREATOR PLATFORM =========================
# Server-authored content is data, never executable code. Creator projects cannot
# call Discord mutation APIs, raw SQL, the filesystem, the network, environment
# variables, or Manifest's private intelligence/developer internals.
CREATOR_CAPABILITIES = (
    "creator.view", "creator.command.create", "creator.command.edit", "creator.command.publish",
    "creator.game.create", "creator.game.edit", "creator.game.publish",
    "creator.form.create", "creator.form.edit", "creator.form.publish", "creator.form.responses",
    "creator.audit.view",
)
CREATOR_COMMAND_TYPES = {"text", "embed", "random", "dice"}
CREATOR_RESERVED_SLUGS = {
    "help","manifest","mod","server","logs","ticket","economy","level","brain","utility","music","autopilot",
    "activity","reminder","autoresponder","report","bug","submit","suggestion","waitlist","boost","custom_role",
    "games","personality","owner","rules","community","creator","security","profile","automation","staff","privacy"
}
CREATOR_SAFE_TEMPLATE_KEYS = {"user","server","channel","member_count"}
_creator_cooldowns = {}


def _creator_slug(raw:str)->str:
    slug=re.sub(r"[^a-z0-9_-]+","-",str(raw or "").strip().lower()).strip("-_")
    return slug[:32]


def _creator_member_is_manager(member)->bool:
    return bool(member and getattr(member,"guild",None) and (
        member.id==member.guild.owner_id or member.guild_permissions.administrator or member.guild_permissions.manage_guild
    ))


async def creator_has_capability(guild, member, capability:str)->bool:
    """Server-local Creator authorization. Discord server managers always retain control.
    Delegation is explicit per capability and never grants Discord permissions.
    """
    if not guild or not member or capability not in CREATOR_CAPABILITIES:return False
    if _creator_member_is_manager(member):return True
    row=await db.one("SELECT allowed_role_ids_json,allowed_user_ids_json FROM creator_policies WHERE guild_id=? AND capability=?",(guild.id,capability))
    if not row:return False
    try: users={int(x) for x in json.loads(row['allowed_user_ids_json'] or '[]')}
    except Exception: users=set()
    if member.id in users:return True
    try: roles={int(x) for x in json.loads(row['allowed_role_ids_json'] or '[]')}
    except Exception: roles=set()
    return bool(roles.intersection({int(r.id) for r in getattr(member,'roles',())}))



def creator_project_user_allowed(project, member)->bool:
    if not member or not getattr(member,'guild',None):return False
    if _creator_member_is_manager(member):return True
    mode=str(project['audience_mode'] or 'everyone') if 'audience_mode' in project.keys() else 'everyone'
    if mode=='everyone':return True
    if mode=='managers':return False
    if mode=='roles':
        try:allowed={int(x) for x in json.loads(project['allowed_role_ids_json'] or '[]')}
        except Exception:allowed=set()
        return bool(allowed.intersection({int(r.id) for r in getattr(member,'roles',())}))
    return False


async def creator_audit(guild_id:int,actor_id:int,event_type:str,summary:str,project_id:int=0,metadata=None):
    await db.execute("INSERT INTO creator_audit(guild_id,actor_id,project_id,event_type,summary,metadata_json,created_at) VALUES(?,?,?,?,?,?,?)",
                     (guild_id,actor_id,int(project_id or 0),event_type[:80],str(summary or '')[:1000],json.dumps(metadata or {},separators=(',',':'),default=str)[:3000],time.time()))
    if event_type not in {"command.invoke","command.error","game.answer","form.submit"}:
        try:
            guild=bot.get_guild(int(guild_id));actor=guild.get_member(int(actor_id)) if guild else None
            if guild:await elog(guild,"creator","🛠️ Creator Studio",f"**{event_type}**\n{str(summary or '')[:1500]}",actor=actor)
        except Exception:log.exception("Creator log routing failed")


async def creator_current_spec(project_id:int):
    row=await db.one("SELECT p.*,v.spec_json FROM creator_projects p LEFT JOIN creator_versions v ON v.project_id=p.id AND v.version=p.current_version WHERE p.id=?",(project_id,))
    if not row:return None,None
    try: spec=json.loads(row['spec_json'] or '{}')
    except Exception: spec={}
    return row,spec


async def creator_save_version(project_id:int,actor_id:int,spec:dict,summary:str):
    async with db.conn.execute("SELECT current_version FROM creator_projects WHERE id=?",(project_id,)) as cur:
        row=await cur.fetchone()
    if not row:raise ValueError("Creator project not found")
    version=int(row[0] or 0)+1
    payload=json.dumps(spec,separators=(',',':'),ensure_ascii=False)
    if len(payload)>30000:raise ValueError("Creator project is too large. Keep the configuration under 30 KB.")
    await db.conn.execute("BEGIN IMMEDIATE")
    try:
        await db.conn.execute("INSERT INTO creator_versions(project_id,version,spec_json,change_summary,created_by,created_at) VALUES(?,?,?,?,?,?)",
                              (project_id,version,payload,str(summary or '')[:500],actor_id,time.time()))
        await db.conn.execute("UPDATE creator_projects SET current_version=?,updated_at=? WHERE id=?",(version,time.time(),project_id))
        await db.conn.commit()
    except Exception:
        await db.conn.rollback();raise
    return version


def _creator_render_template(text:str,message)->str:
    values={
        "user":getattr(message.author,'mention',getattr(message.author,'display_name','member')),
        "server":getattr(message.guild,'name','server'),
        "channel":getattr(message.channel,'mention','#channel'),
        "member_count":str(getattr(message.guild,'member_count',0) or 0),
    }
    out=str(text or '')
    for key,val in values.items():out=out.replace("{"+key+"}",str(val))
    # Unknown brace tokens remain literal; no expression evaluation exists.
    return out[:1900]


async def creator_invoke_project(message,project,spec):
    cooldown=max(0,min(int(project['cooldown_seconds'] or 0),86400)); key=(int(project['id']),int(message.author.id)); now=time.time()
    if cooldown and now-_creator_cooldowns.get(key,0)<cooldown:return True
    _creator_cooldowns[key]=now
    typ=str(spec.get('type','text'))
    if typ=='text':
        await message.channel.send(_creator_render_template(spec.get('text',''),message),allowed_mentions=discord.AllowedMentions(users=[message.author],roles=False,everyone=False,replied_user=False))
    elif typ=='embed':
        e=discord.Embed(title=_creator_render_template(spec.get('title',''),message)[:256],description=_creator_render_template(spec.get('text',''),message)[:4000],color=discord.Color.blurple())
        await message.channel.send(embed=e,allowed_mentions=discord.AllowedMentions.none())
    elif typ=='random':
        choices=[str(x)[:500] for x in spec.get('choices',[]) if str(x).strip()][:50]
        if not choices:return False
        await message.channel.send(_creator_render_template(random.choice(choices),message),allowed_mentions=discord.AllowedMentions(users=[message.author],roles=False,everyone=False,replied_user=False))
    elif typ=='dice':
        sides=max(2,min(int(spec.get('sides',6) or 6),1000)); count=max(1,min(int(spec.get('count',1) or 1),20))
        rolls=[random.randint(1,sides) for _ in range(count)]
        await message.channel.send(f"🎲 {message.author.mention} rolled **{', '.join(map(str,rolls))}**"+(f" · total **{sum(rolls)}**" if count>1 else ""),allowed_mentions=discord.AllowedMentions(users=True,roles=False,everyone=False))
    else:return False
    await db.execute("INSERT INTO creator_invocations(project_id,user_id,last_at,uses) VALUES(?,?,?,1) ON CONFLICT(project_id,user_id) DO UPDATE SET last_at=excluded.last_at,uses=uses+1",(project['id'],message.author.id,now))
    await creator_audit(message.guild.id,message.author.id,"command.invoke",f"Invoked !{project['slug']}",project['id'],{"version":project['current_version']})
    return True


async def try_creator_custom_command(message)->bool:
    if not message.guild or not message.content.startswith(PREFIXES):return False
    prefix=message.content[0]; token=message.content[1:].split(None,1)[0].lower() if len(message.content)>1 else ''
    if not token:return False
    # Built-in Manifest commands always win and cannot be shadowed by server content.
    if bot.get_command(token):return False
    row=await db.one("SELECT * FROM creator_projects WHERE guild_id=? AND kind='command' AND slug=? AND status='published'",(message.guild.id,token))
    if not row:return False
    if not creator_project_user_allowed(row,message.author):
        await message.channel.send("You don't have access to that server-created command.",allowed_mentions=discord.AllowedMentions.none())
        return True
    _,spec=await creator_current_spec(int(row['id']))
    try:return await creator_invoke_project(message,row,spec)
    except Exception as ex:
        log.exception("Creator command invocation failed")
        await creator_audit(message.guild.id,message.author.id,"command.error",type(ex).__name__,row['id'])
        return True


async def _creator_require(i,capability):
    if not i.guild or not isinstance(i.user,discord.Member):
        await i.response.send_message("Creator Studio is server-only.",ephemeral=True);return False
    if not await creator_has_capability(i.guild,i.user,capability):
        await i.response.send_message("You don't have this Manifest Creator capability. A server owner/manager can delegate it in Creator Access.",ephemeral=True);return False
    return True


class CreatorStudioView(discord.ui.View):
    def __init__(self,owner_id:int):super().__init__(timeout=180);self.owner_id=owner_id
    async def interaction_check(self,i):
        if i.user.id!=self.owner_id:
            await i.response.send_message("Open your own Creator Studio with `/creator studio`.",ephemeral=True);return False
        return True
    @discord.ui.button(label="Commands",style=discord.ButtonStyle.primary,emoji="🧩",row=0)
    async def commands_btn(self,i,b):
        rows=await db.all("SELECT id,name,slug,status,current_version FROM creator_projects WHERE guild_id=? AND kind='command' ORDER BY updated_at DESC LIMIT 15",(i.guild_id,))
        txt="\n".join(f"`#{r['id']}` **{r['name']}** · `!{r['slug']}` · {r['status']} · v{r['current_version']}" for r in rows) or "No server-built commands yet."
        await i.response.edit_message(embed=discord.Embed(title="🧩 Creator · Commands",description=txt[:3900],color=discord.Color.blurple()),view=self)
    @discord.ui.button(label="Games",style=discord.ButtonStyle.primary,emoji="🎮",row=0)
    async def games_btn(self,i,b):
        rows=await db.all("SELECT id,name,status,current_version FROM creator_projects WHERE guild_id=? AND kind='game' ORDER BY updated_at DESC LIMIT 15",(i.guild_id,))
        txt="\n".join(f"`#{r['id']}` **{r['name']}** · {r['status']} · v{r['current_version']}" for r in rows) or "No server-built games yet."
        await i.response.edit_message(embed=discord.Embed(title="🎮 Creator · Games",description=txt[:3900],color=discord.Color.blurple()),view=self)
    @discord.ui.button(label="Access",style=discord.ButtonStyle.secondary,emoji="🔐",row=0)
    async def access_btn(self,i,b):
        rows=await db.all("SELECT capability,allowed_role_ids_json,allowed_user_ids_json FROM creator_policies WHERE guild_id=? ORDER BY capability",(i.guild_id,))
        txt="\n".join(f"**{r['capability']}** · roles {len(json.loads(r['allowed_role_ids_json'] or '[]'))} · users {len(json.loads(r['allowed_user_ids_json'] or '[]'))}" for r in rows) or "No delegated Creator capabilities. Server managers retain control by default."
        await i.response.edit_message(embed=discord.Embed(title="🔐 Creator · Access",description=txt[:3900],color=discord.Color.blurple()),view=self)
    @discord.ui.button(label="Forms",style=discord.ButtonStyle.secondary,emoji="📝",row=0)
    async def forms_btn(self,i,b):
        rows=await db.all("SELECT id,name,status,current_version FROM creator_projects WHERE guild_id=? AND kind='form' ORDER BY updated_at DESC LIMIT 15",(i.guild_id,))
        txt="\n".join(f"`#{r['id']}` **{r['name']}** · {r['status']} · v{r['current_version']}" for r in rows) or "No server-built forms yet."
        await i.response.edit_message(embed=discord.Embed(title="📝 Creator · Forms",description=txt[:3900],color=discord.Color.blurple()),view=self)
    @discord.ui.button(label="Audit",style=discord.ButtonStyle.secondary,emoji="📜",row=0)
    async def audit_btn(self,i,b):
        if not await creator_has_capability(i.guild,i.user,"creator.audit.view"):
            return await i.response.send_message("Creator Audit access required.",ephemeral=True)
        rows=await db.all("SELECT actor_id,event_type,summary,created_at FROM creator_audit WHERE guild_id=? ORDER BY created_at DESC LIMIT 15",(i.guild_id,))
        txt="\n".join(f"<@{r['actor_id']}> · **{r['event_type']}** · {str(r['summary'])[:120]} · <t:{int(r['created_at'])}:R>" for r in rows) or "No Creator activity yet."
        await i.response.edit_message(embed=discord.Embed(title="📜 Creator · Audit",description=txt[:3900],color=discord.Color.blurple()),view=self)
    @discord.ui.button(label="Close",style=discord.ButtonStyle.danger,row=1)
    async def close_btn(self,i,b):
        for item in self.children:item.disabled=True
        await i.response.edit_message(view=self)


@creator_group.command(name="studio",description="Open the Manifest Creator Studio")
async def creator_studio(i:discord.Interaction):
    if not await _creator_require(i,"creator.view"):return
    commands_n=await db.one("SELECT COUNT(*) n FROM creator_projects WHERE guild_id=? AND kind='command'",(i.guild_id,))
    games_n=await db.one("SELECT COUNT(*) n FROM creator_projects WHERE guild_id=? AND kind='game'",(i.guild_id,))
    forms_n=await db.one("SELECT COUNT(*) n FROM creator_projects WHERE guild_id=? AND kind='form'",(i.guild_id,))
    e=discord.Embed(title="🛠️ Manifest Creator Studio",description="Build safe server experiences without code execution or hidden authority. Built-in Manifest commands always win; server-changing actions remain behind Manifest's verified authority engine. Existing `/automation studio` remains the verified automation builder instead of being duplicated here.",color=discord.Color.blurple())
    e.add_field(name="Commands",value=str(int(commands_n['n'] or 0)))
    e.add_field(name="Games",value=str(int(games_n['n'] or 0)))
    e.add_field(name="Forms",value=str(int(forms_n['n'] or 0)))
    e.add_field(name="Safety",value="Sandboxed · versioned · audited",inline=False)
    await i.response.send_message(embed=e,view=CreatorStudioView(i.user.id),ephemeral=True)


@creator_group.command(name="command_create",description="Create a safe server command draft")
@app_commands.choices(command_type=[app_commands.Choice(name=x.title(),value=x) for x in ("text","embed","random","dice")])
async def creator_command_create(i:discord.Interaction,name:str,command_type:app_commands.Choice[str],content:str,cooldown_seconds:int=5):
    if not await _creator_require(i,"creator.command.create"):return
    slug=_creator_slug(name)
    if not slug or slug in CREATOR_RESERVED_SLUGS or bot.get_command(slug):return await i.response.send_message("Choose a different command name; that trigger is reserved by Manifest.",ephemeral=True)
    typ=command_type.value
    if typ=='random':
        choices=[x.strip() for x in content.split('|') if x.strip()][:50]
        if len(choices)<2:return await i.response.send_message("Random commands need at least two choices separated with `|`.",ephemeral=True)
        spec={"type":"random","choices":choices}
    elif typ=='dice':
        m=re.fullmatch(r"\s*(\d{1,2})d(\d{1,4})\s*",content.lower())
        if not m:return await i.response.send_message("For Dice, use notation like `2d6` or `1d20`.",ephemeral=True)
        spec={"type":"dice","count":max(1,min(int(m.group(1)),20)),"sides":max(2,min(int(m.group(2)),1000))}
    elif typ=='embed':spec={"type":"embed","title":name[:256],"text":content[:4000]}
    else:spec={"type":"text","text":content[:1900]}
    now=time.time()
    try:
        cur=await db.execute("INSERT INTO creator_projects(guild_id,kind,name,slug,description,status,owner_id,current_version,cooldown_seconds,created_at,updated_at) VALUES(?,?,?,?,?,'draft',?,0,?,?,?)",
                             (i.guild_id,'command',name[:80],slug,'Safe server command',i.user.id,max(0,min(cooldown_seconds,86400)),now,now))
    except Exception:return await i.response.send_message("A Creator command with that name already exists in this server.",ephemeral=True)
    ver=await creator_save_version(cur.lastrowid,i.user.id,spec,"Initial command draft")
    await creator_audit(i.guild_id,i.user.id,"command.create",f"Created !{slug} draft v{ver}",cur.lastrowid)
    await i.response.send_message(f"🧩 Created **!{slug}** as draft `#{cur.lastrowid}` · v{ver}. Test it with `/creator command_test`, then publish when ready.",ephemeral=True)


@creator_group.command(name="command_edit",description="Create a new version of a server command")
async def creator_command_edit(i:discord.Interaction,project_id:int,content:str,change_summary:str="Updated content"):
    if not await _creator_require(i,"creator.command.edit"):return
    row,spec=await creator_current_spec(project_id)
    if not row or row['guild_id']!=i.guild_id or row['kind']!='command':return await i.response.send_message("Command project not found.",ephemeral=True)
    typ=spec.get('type','text')
    if typ=='random':spec['choices']=[x.strip() for x in content.split('|') if x.strip()][:50]
    elif typ=='dice':
        m=re.fullmatch(r"\s*(\d{1,2})d(\d{1,4})\s*",content.lower())
        if not m:return await i.response.send_message("Dice content must look like `2d6`.",ephemeral=True)
        spec.update(count=max(1,min(int(m.group(1)),20)),sides=max(2,min(int(m.group(2)),1000)))
    else:spec['text']=content[:4000 if typ=='embed' else 1900]
    ver=await creator_save_version(project_id,i.user.id,spec,change_summary)
    await creator_audit(i.guild_id,i.user.id,"command.edit",f"Updated !{row['slug']} to v{ver}",project_id,{"summary":change_summary[:300]})
    await i.response.send_message(f"✅ **!{row['slug']}** saved as v{ver}. Existing published status is preserved.",ephemeral=True)


@creator_group.command(name="command_test",description="Preview a Creator command without publishing it")
async def creator_command_test(i:discord.Interaction,project_id:int):
    if not await _creator_require(i,"creator.view"):return
    row,spec=await creator_current_spec(project_id)
    if not row or row['guild_id']!=i.guild_id or row['kind']!='command':return await i.response.send_message("Command project not found.",ephemeral=True)
    typ=spec.get('type')
    if typ=='random':preview=random.choice(spec.get('choices') or ['(empty)'])
    elif typ=='dice':
        rolls=[random.randint(1,int(spec.get('sides',6))) for _ in range(int(spec.get('count',1)))];preview=f"🎲 {rolls} · total {sum(rolls)}"
    else:
        class _Preview:pass
        pm=_Preview();pm.author=i.user;pm.guild=i.guild;pm.channel=i.channel
        preview=_creator_render_template(spec.get('text',''),pm)
    await i.response.send_message(f"🧪 **Draft preview · !{row['slug']} · v{row['current_version']}**\n{preview[:1800]}",ephemeral=True)


