@creator_group.command(name="rollback",description="Roll a Creator project back by creating a new version from an older one")
async def creator_rollback(i:discord.Interaction,project_id:int,version:int):
    row=await db.one("SELECT * FROM creator_projects WHERE id=? AND guild_id=?",(project_id,i.guild_id))
    if not row:return await i.response.send_message("Creator project not found.",ephemeral=True)
    cap="creator.command.edit" if row['kind']=='command' else "creator.game.edit"
    if not await _creator_require(i,cap):return
    old=await db.one("SELECT spec_json FROM creator_versions WHERE project_id=? AND version=?",(project_id,version))
    if not old:return await i.response.send_message("That version was not found.",ephemeral=True)
    try:spec=json.loads(old['spec_json'])
    except Exception:return await i.response.send_message("That saved version is damaged; rollback refused.",ephemeral=True)
    newver=await creator_save_version(project_id,i.user.id,spec,f"Rollback from v{version}")
    await creator_audit(i.guild_id,i.user.id,"project.rollback",f"{row['name']} rolled back from v{version} as v{newver}",project_id)
    await i.response.send_message(f"↩️ Restored v{version} as new version **v{newver}**. Status was not changed.",ephemeral=True)



@creator_group.command(name="project_info",description="Inspect a Creator project and its safety/status metadata")
async def creator_project_info(i:discord.Interaction,project_id:int):
    if not await _creator_require(i,"creator.view"):return
    row,spec=await creator_current_spec(project_id)
    if not row or row['guild_id']!=i.guild_id:return await i.response.send_message("Creator project not found.",ephemeral=True)
    inv=await db.one("SELECT COALESCE(SUM(uses),0) n FROM creator_invocations WHERE project_id=?",(project_id,))
    audience=str(row['audience_mode'] or 'everyone') if 'audience_mode' in row.keys() else 'everyone'
    details=[f"**Kind:** {row['kind']}",f"**Status:** {row['status']}",f"**Version:** v{row['current_version']}",f"**Audience:** {audience}",f"**Owner:** <@{row['owner_id']}>",f"**Updated:** <t:{int(row['updated_at'])}:R>"]
    if row['kind']=='command':details += [f"**Trigger:** `!{row['slug']}`",f"**Invocations:** {int(inv['n'] or 0)}",f"**Cooldown:** {int(row['cooldown_seconds'] or 0)}s"]
    elif row['kind']=='game':details.append(f"**Questions:** {len(spec.get('questions') or [])}")
    elif row['kind']=='form':details.append(f"**Fields:** {len(spec.get('questions') or [])}")
    details.append("**Sandbox:** no arbitrary code, filesystem, raw SQL, network calls, environment access, or Discord server mutation")
    await i.response.send_message(embed=discord.Embed(title=f"🛠️ Creator · {row['name']}",description="\n".join(details),color=discord.Color.blurple()),ephemeral=True)


