@creator_group.command(name="project_audience",description="Choose who can use a published Creator project")
@app_commands.choices(mode=[app_commands.Choice(name="Everyone",value="everyone"),app_commands.Choice(name="Selected role",value="roles"),app_commands.Choice(name="Server managers",value="managers")])
async def creator_project_audience(i:discord.Interaction,project_id:int,mode:app_commands.Choice[str],role:discord.Role|None=None):
    row=await db.one("SELECT * FROM creator_projects WHERE id=? AND guild_id=?",(project_id,i.guild_id))
    if not row:return await i.response.send_message("Creator project not found.",ephemeral=True)
    cap={"command":"creator.command.edit","game":"creator.game.edit","form":"creator.form.edit"}.get(row['kind'])
    if not cap or not await _creator_require(i,cap):return
    roles=[]
    if mode.value=='roles':
        if not role:return await i.response.send_message("Choose the role that should have access.",ephemeral=True)
        if role.is_default() or role.managed:return await i.response.send_message("Choose a normal server role.",ephemeral=True)
        roles=[role.id]
    await db.execute("UPDATE creator_projects SET audience_mode=?,allowed_role_ids_json=?,updated_at=? WHERE id=?",(mode.value,json.dumps(roles),time.time(),project_id))
    await creator_audit(i.guild_id,i.user.id,"project.audience",f"{row['name']} audience → {mode.value}",project_id,{"role_ids":roles})
    target=role.mention if mode.value=='roles' and role else mode.value
    await i.response.send_message(f"👥 **{row['name']}** audience → {target}.",ephemeral=True)


