@creator_group.command(name="access_grant",description="Delegate a Creator capability to a role or member")
@app_commands.choices(capability=[app_commands.Choice(name=x,value=x) for x in CREATOR_CAPABILITIES])
async def creator_access_grant(i:discord.Interaction,capability:app_commands.Choice[str],role:discord.Role|None=None,member:discord.Member|None=None):
    if not i.guild or not _creator_member_is_manager(i.user):return await i.response.send_message("Manage Server required to delegate Creator capabilities.",ephemeral=True)
    if not role and not member:return await i.response.send_message("Choose a role or member to grant.",ephemeral=True)
    cap=capability.value;row=await db.one("SELECT * FROM creator_policies WHERE guild_id=? AND capability=?",(i.guild_id,cap))
    try:roles=set(json.loads(row['allowed_role_ids_json'] or '[]')) if row else set()
    except Exception:roles=set()
    try:users=set(json.loads(row['allowed_user_ids_json'] or '[]')) if row else set()
    except Exception:users=set()
    if role:
        if role.is_default() or role.managed:return await i.response.send_message("That role cannot be used for Creator delegation.",ephemeral=True)
        roles.add(role.id)
    if member:users.add(member.id)
    await db.execute("INSERT INTO creator_policies(guild_id,capability,allowed_role_ids_json,allowed_user_ids_json,updated_by,updated_at) VALUES(?,?,?,?,?,?) ON CONFLICT(guild_id,capability) DO UPDATE SET allowed_role_ids_json=excluded.allowed_role_ids_json,allowed_user_ids_json=excluded.allowed_user_ids_json,updated_by=excluded.updated_by,updated_at=excluded.updated_at",
                     (i.guild_id,cap,json.dumps(sorted(roles)),json.dumps(sorted(users)),i.user.id,time.time()))
    await creator_audit(i.guild_id,i.user.id,"access.grant",f"Granted {cap}",0,{"role_id":getattr(role,'id',0),"user_id":getattr(member,'id',0)})
    await i.response.send_message(f"🔐 Updated **{cap}** access.",ephemeral=True)


@creator_group.command(name="access_revoke",description="Revoke a delegated Creator capability from a role or member")
@app_commands.choices(capability=[app_commands.Choice(name=x,value=x) for x in CREATOR_CAPABILITIES])
async def creator_access_revoke(i:discord.Interaction,capability:app_commands.Choice[str],role:discord.Role|None=None,member:discord.Member|None=None):
    if not i.guild or not _creator_member_is_manager(i.user):return await i.response.send_message("Manage Server required to change Creator access.",ephemeral=True)
    row=await db.one("SELECT * FROM creator_policies WHERE guild_id=? AND capability=?",(i.guild_id,capability.value))
    if not row:return await i.response.send_message("No delegated access exists for that capability.",ephemeral=True)
    try:roles=set(json.loads(row['allowed_role_ids_json'] or '[]'));users=set(json.loads(row['allowed_user_ids_json'] or '[]'))
    except Exception:roles=set();users=set()
    if role:roles.discard(role.id)
    if member:users.discard(member.id)
    await db.execute("UPDATE creator_policies SET allowed_role_ids_json=?,allowed_user_ids_json=?,updated_by=?,updated_at=? WHERE guild_id=? AND capability=?",
                     (json.dumps(sorted(roles)),json.dumps(sorted(users)),i.user.id,time.time(),i.guild_id,capability.value))
    await creator_audit(i.guild_id,i.user.id,"access.revoke",f"Revoked {capability.value}",0,{"role_id":getattr(role,'id',0),"user_id":getattr(member,'id',0)})
    await i.response.send_message(f"🔐 Updated **{capability.value}** access.",ephemeral=True)


@creator_group.command(name="access_show",description="Show Creator capability delegation")
async def creator_access_show(i:discord.Interaction):
    if not await _creator_require(i,"creator.view"):return
    rows=await db.all("SELECT * FROM creator_policies WHERE guild_id=? ORDER BY capability",(i.guild_id,))
    lines=[]
    for r in rows:
        try:roles=[f"<@&{x}>" for x in json.loads(r['allowed_role_ids_json'] or '[]')];users=[f"<@{x}>" for x in json.loads(r['allowed_user_ids_json'] or '[]')]
        except Exception:roles=[];users=[]
        lines.append(f"**{r['capability']}** — "+(", ".join(roles+users) if roles or users else "managers only"))
    await i.response.send_message("🔐 **Creator Access**\n"+("\n".join(lines) if lines else "No delegated capabilities. Server managers retain full Creator control."),ephemeral=True)


