@creator_group.command(name="game_question_add",description="Add a multiple-choice question to a Creator game")
async def creator_game_question_add(i:discord.Interaction,project_id:int,question:str,correct_answer:str,wrong_answers:str):
    if not await _creator_require(i,"creator.game.edit"):return
    row,spec=await creator_current_spec(project_id)
    if not row or row['guild_id']!=i.guild_id or row['kind']!='game':return await i.response.send_message("Game project not found.",ephemeral=True)
    wrong=[x.strip() for x in wrong_answers.split('|') if x.strip()][:3]
    if not 1<=len(wrong)<=3:return await i.response.send_message("Give 1–3 wrong answers separated with `|`.",ephemeral=True)
    qs=list(spec.get('questions') or [])
    if len(qs)>=50:return await i.response.send_message("A Creator game can currently contain up to 50 questions.",ephemeral=True)
    qs.append({"question":question[:500],"correct":correct_answer[:120],"wrong":[x[:120] for x in wrong]});spec['questions']=qs
    ver=await creator_save_version(project_id,i.user.id,spec,f"Added question {len(qs)}")
    await creator_audit(i.guild_id,i.user.id,"game.edit",f"Added question {len(qs)} to {row['name']} v{ver}",project_id)
    await i.response.send_message(f"✅ Added question **{len(qs)}** · game now v{ver}.",ephemeral=True)


