# ========================= MANIFEST PLAY =========================
def game_scope_id(interaction):
    return int(interaction.guild_id or 0)

def game_channel_id(interaction):
    return int(interaction.channel_id or 0)

async def game_config_for(guild_id:int):
    row=await db.one("SELECT * FROM game_config WHERE guild_id=?",(int(guild_id or 0),))
    return dict(row) if row else {"guild_id":int(guild_id or 0),"enabled":1,"channel_id":0,"daily_challenges":1,"updated_at":0}

async def game_gate(i:discord.Interaction):
    gid=game_scope_id(i)
    cfg=await game_config_for(gid)
    if not int(cfg.get("enabled",1)):
        await i.response.send_message("🎮 Manifest Play is disabled in this server.",ephemeral=True);return False
    channel_id=int(cfg.get("channel_id",0) or 0)
    if channel_id and i.guild and i.channel_id!=channel_id:
        ch=i.guild.get_channel(channel_id)
        await i.response.send_message(f"🎮 Manifest Play is configured for {ch.mention if ch else 'another channel'}.",ephemeral=True);return False
    return True

async def create_game_session(guild_id:int,channel_id:int,host_id:int,game_type:str,state:dict|None=None,status:str="active"):
    now=time.time();cur=await db.execute("INSERT INTO game_sessions(guild_id,channel_id,game_type,host_id,status,state_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)",(int(guild_id or 0),int(channel_id or 0),game_type,host_id,status,json.dumps(state or {}),now,now))
    sid=cur.lastrowid;await db.execute("INSERT OR IGNORE INTO game_players(session_id,user_id,joined_at) VALUES(?,?,?)",(sid,host_id,now));return sid

async def game_add_player(sid:int,user_id:int):
    await db.execute("INSERT OR IGNORE INTO game_players(session_id,user_id,joined_at) VALUES(?,?,?)",(sid,user_id,time.time()))

async def game_event(sid:int,gid:int,uid:int,event_type:str,points:int=0,details:str=""):
    await db.execute("INSERT INTO game_events(session_id,guild_id,user_id,event_type,points,details,created_at) VALUES(?,?,?,?,?,?,?)",(sid,int(gid or 0),uid,event_type,points,details[:1000],time.time()))
    if uid and points:await db.execute("UPDATE game_players SET score=score+? WHERE session_id=? AND user_id=?",(points,sid,uid))

GAME_DAILY_TYPES=("trivia","hangman","rps","tic_tac_toe","connect4","manifest_guess","emoji_decode","word_scramble","number_hunt")
def game_day_key(now=None):
    return datetime.datetime.fromtimestamp(now or time.time(),datetime.timezone.utc).date().isoformat()
def game_season_key(now=None):
    return datetime.datetime.fromtimestamp(now or time.time(),datetime.timezone.utc).strftime("%Y-%m")
def game_daily_type(guild_id:int,day:str|None=None):
    day=day or game_day_key();raw=hashlib.sha256(f"{int(guild_id or 0)}:{day}:manifest-play".encode()).digest()
    return GAME_DAILY_TYPES[int.from_bytes(raw[:2],'big')%len(GAME_DAILY_TYPES)]

def game_label(key):
    return {"rps":"Rock Paper Scissors","tic_tac_toe":"Tic-Tac-Toe","connect4":"Connect Four","trivia":"Trivia","hangman":"Hangman","manifest_guess":"Manifest Guess","emoji_decode":"Emoji Decode","word_scramble":"Word Scramble","number_hunt":"Number Hunt","party":"Manifest Party"}.get(key,key.replace('_',' ').title())

async def _game_daily_credit(gid:int,uid:int,game_type:str):
    cfg=await game_config_for(gid)
    if not int(cfg.get("daily_challenges",1)):return False,0
    day=game_day_key();challenge=game_daily_type(gid,day);now=time.time()
    await db.execute("INSERT OR IGNORE INTO game_daily_progress(guild_id,user_id,day,challenge_key,updated_at) VALUES(?,?,?,?,?)",(gid,uid,day,challenge,now))
    await db.execute("UPDATE game_daily_progress SET completed_games=completed_games+1,updated_at=? WHERE guild_id=? AND user_id=? AND day=?",(now,gid,uid,day))
    if game_type!=challenge:return False,0
    cur=await db.execute("UPDATE game_daily_progress SET challenge_done=1,bonus_points=bonus_points+25,updated_at=? WHERE guild_id=? AND user_id=? AND day=? AND challenge_done=0",(now,gid,uid,day))
    if getattr(cur,'rowcount',0)==1:
        await db.execute("UPDATE game_stats SET points=points+25 WHERE guild_id=? AND user_id=?",(gid,uid));return True,25
    return False,0

async def finish_game_session(sid:int,gid:int,winner_ids:list[int]|None=None,draw:bool=False):
    winner_ids=set(winner_ids or []);now=time.time();gid=int(gid or 0)
    cur=await db.execute("UPDATE game_sessions SET status='finished',ended_at=?,updated_at=? WHERE id=? AND status IN ('lobby','active')",(now,now,sid))
    if getattr(cur,'rowcount',0)==0:return False
    session=await db.one("SELECT game_type FROM game_sessions WHERE id=?",(sid,));game_type=str(session['game_type']) if session else 'game'
    players=await db.all("SELECT user_id,score,streak FROM game_players WHERE session_id=?",(sid,))
    for r in players:
        uid=int(r['user_id']);win=uid in winner_ids
        await db.execute("INSERT INTO game_stats(guild_id,user_id,games_played,wins,losses,draws,points,best_streak) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(guild_id,user_id) DO UPDATE SET games_played=games_played+1,wins=wins+excluded.wins,losses=losses+excluded.losses,draws=draws+excluded.draws,points=points+excluded.points,best_streak=MAX(best_streak,excluded.best_streak)",(gid,uid,1,int(win),int(not win and not draw),int(draw),int(r['score']),int(r['streak'])))
        daily,bonus=await _game_daily_credit(gid,uid,game_type)
        earned=max(0,int(r['score'] or 0))+int(bonus or 0)
        season=game_season_key(now)
        await db.execute("INSERT INTO game_season_scores(guild_id,season_key,user_id,points,games_played,wins,last_played_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(guild_id,season_key,user_id) DO UPDATE SET points=points+excluded.points,games_played=games_played+1,wins=wins+excluded.wins,last_played_at=excluded.last_played_at",(gid,season,uid,earned,1,int(win),now))
        await db.execute("UPDATE game_tournament_players SET points=points+?,games_played=games_played+1,wins=wins+? WHERE user_id=? AND tournament_id IN (SELECT id FROM game_tournaments WHERE guild_id=? AND status='active' AND starts_at<=? AND ends_at>?)",(earned,int(win),uid,gid,now,now))
        stats=await db.one("SELECT games_played,wins,points FROM game_stats WHERE guild_id=? AND user_id=?",(gid,uid))
        achievements=(("first_game",stats and stats['games_played']>=1),("first_win",stats and stats['wins']>=1),("ten_games",stats and stats['games_played']>=10),("fifty_games",stats and stats['games_played']>=50),("hundred_points",stats and stats['points']>=100),("daily_challenger",daily))
        for key,ok in achievements:
            if ok:await db.execute("INSERT OR IGNORE INTO game_achievements(guild_id,user_id,achievement,earned_at) VALUES(?,?,?,?)",(gid,uid,key,now))
        if daily:await game_event(sid,gid,uid,"daily_challenge",bonus,game_type)
    return True

async def game_hub_embed(i:discord.Interaction):
    gid=game_scope_id(i);cfg=await game_config_for(gid);day=game_day_key();challenge=game_daily_type(gid,day)
    e=manifest_ui_embed("Manifest · Play","Interactive games built into Manifest. Pick from the menu—no command memorization required.")
    e.add_field(name="Featured",value="🧠 **Manifest Guess** — think of a character and Manifest narrows it down with adaptive questions.\n🎉 **Party** — a shared lobby for quick community rounds.",inline=False)
    e.add_field(name="Today's challenge",value=(f"Finish **{game_label(challenge)}** today for **+25 Play points**." if int(cfg.get('daily_challenges',1)) else "Daily challenges are disabled here."),inline=False)
    e.add_field(name="Also included",value="Trivia · Hangman · Emoji Decode · Word Scramble · Number Hunt · RPS · Tic-Tac-Toe · Connect Four",inline=False)
    e.add_field(name="Season & community events",value=f"**{game_season_key()} season** · monthly leaderboard · optional no-entry-fee tournaments scored from completed games.\nCreate an event with `/games tournament`; open the current season from this Play panel.",inline=False)
    e.set_footer(text="Play points are server entertainment stats only; no wagers or purchases, and points have no real-world value.")
    return e

class RPSView(discord.ui.View):
    def __init__(self,player_id,sid=0,gid=0): super().__init__(timeout=120); self.player_id=player_id;self.sid=sid;self.gid=gid;self.finished=False
    async def play(self,i,choice):
        if i.user.id!=self.player_id:return await i.response.send_message("This round belongs to someone else. Start your own game.",ephemeral=True)
        if self.finished:return await i.response.send_message("This round is already finished.",ephemeral=True)
        botc=random.choice(["rock","paper","scissors"]);win=(choice,botc) in {("rock","scissors"),("paper","rock"),("scissors","paper")};tie=choice==botc; result="Tie" if tie else ("You win" if win else "Manifest wins")
        self.finished=True;pts=12 if win else 5 if tie else 2
        if self.sid:
            await game_event(self.sid,self.gid,i.user.id,"finish",pts,"win" if win else "draw" if tie else "loss");await finish_game_session(self.sid,self.gid,[i.user.id] if win else [],draw=tie)
        for x in self.children:x.disabled=True
        await i.response.edit_message(content=f"✂️ **Rock Paper Scissors**\nYou: **{choice}** • Manifest: **{botc}** → **{result}**\n+{pts} Play points",view=self)
    @discord.ui.button(label="Rock",emoji="🪨")
    async def rock(self,i,b):await self.play(i,"rock")
    @discord.ui.button(label="Paper",emoji="📄")
    async def paper(self,i,b):await self.play(i,"paper")
    @discord.ui.button(label="Scissors",emoji="✂️")
    async def scissors(self,i,b):await self.play(i,"scissors")

class TTTButton(discord.ui.Button):
    def __init__(self,pos):super().__init__(label="·",style=discord.ButtonStyle.secondary,row=pos//3);self.pos=pos
    async def callback(self,i):await self.view.move(i,self.pos)
class TTTView(discord.ui.View):
    def __init__(self,p1,p2=None,sid=0,gid=0):
        super().__init__(timeout=300);self.players=[p1,p2];self.turn=0;self.board=[None]*9;self.sid=sid;self.gid=gid;self.finished=False
        for x in range(9):self.add_item(TTTButton(x))
    def winner(self):
        for a,b,c in ((0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)):
            if self.board[a] and self.board[a]==self.board[b]==self.board[c]:return self.board[a]
    async def finish(self,i,winner_mark=None):
        if self.finished:return
        self.finished=True;draw=winner_mark is None
        winner_idx=0 if winner_mark=="X" else 1 if winner_mark=="O" else -1
        winner=self.players[winner_idx] if winner_idx>=0 else None
        for idx,p in enumerate(self.players):
            if not p:continue
            pts=20 if winner and p.id==winner.id else 8 if draw else 4
            await game_event(self.sid,self.gid,p.id,"finish",pts,"win" if winner and p.id==winner.id else "draw" if draw else "loss")
        await finish_game_session(self.sid,self.gid,[winner.id] if winner else [],draw=draw)
    async def move(self,i,pos):
        if self.finished:return await i.response.send_message("This game is already finished.",ephemeral=True)
        expected=self.players[self.turn]
        if expected and i.user.id!=expected.id:return await i.response.send_message("Not your turn.",ephemeral=True)
        if self.board[pos]:return await i.response.send_message("That square is taken.",ephemeral=True)
        mark="X" if self.turn==0 else "O";self.board[pos]=mark;btn=self.children[pos];btn.label=mark;btn.style=discord.ButtonStyle.primary if mark=="X" else discord.ButtonStyle.success;btn.disabled=True
        win=self.winner()
        if win or all(self.board):
            await self.finish(i,win)
            for b in self.children:b.disabled=True
            text=f"❎⭕ **{win} wins!**" if win else "❎⭕ **Draw.**"
            return await i.response.edit_message(content=text,view=self)
        self.turn=1-self.turn
        if self.players[1] is None and self.turn==1:
            empty=[n for n,v in enumerate(self.board) if not v];pick=random.choice(empty);self.board[pick]="O";b=self.children[pick];b.label="O";b.style=discord.ButtonStyle.success;b.disabled=True
            win=self.winner()
            if win or all(self.board):
                # Only the human is persisted as a player in solo mode.
                await game_event(self.sid,self.gid,self.players[0].id,"finish",8 if not win else 4,"draw" if not win else "loss");await finish_game_session(self.sid,self.gid,[],draw=not bool(win));self.finished=True
                for z in self.children:z.disabled=True
                return await i.response.edit_message(content=("⭕ **Manifest wins!**" if win else "❎⭕ **Draw.**"),view=self)
            self.turn=0
        await i.response.edit_message(content=f"❎⭕ Turn: {(self.players[self.turn].mention if self.players[self.turn] else 'Manifest')}",view=self,allowed_mentions=discord.AllowedMentions.none())

class C4Button(discord.ui.Button):
    def __init__(self,col):super().__init__(label=str(col+1),style=discord.ButtonStyle.secondary,row=0);self.col=col
    async def callback(self,i):await self.view.drop(i,self.col)
class C4View(discord.ui.View):
    def __init__(self,p1,p2=None,sid=0,gid=0):
        super().__init__(timeout=420);self.players=[p1,p2];self.turn=0;self.board=[[0]*7 for _ in range(6)];self.sid=sid;self.gid=gid;self.finished=False
        for c in range(7):self.add_item(C4Button(c))
    def render(self):return "\n".join("".join("⚫" if x==0 else ("🔴" if x==1 else "🟡") for x in r) for r in self.board)+"\n1️⃣2️⃣3️⃣4️⃣5️⃣6️⃣7️⃣"
    def won(self,n):
        for r in range(6):
            for c in range(7):
                if self.board[r][c]!=n:continue
                for dr,dc in ((0,1),(1,0),(1,1),(1,-1)):
                    if all(0<=r+dr*k<6 and 0<=c+dc*k<7 and self.board[r+dr*k][c+dc*k]==n for k in range(4)):return True
        return False
    async def put(self,col,n):
        for r in range(5,-1,-1):
            if self.board[r][col]==0:self.board[r][col]=n;return True
        return False
    async def drop(self,i,col):
        if self.finished:return await i.response.send_message("This game is already finished.",ephemeral=True)
        expected=self.players[self.turn]
        if expected and i.user.id!=expected.id:return await i.response.send_message("Not your turn.",ephemeral=True)
        n=self.turn+1
        if not await self.put(col,n):return await i.response.send_message("That column is full.",ephemeral=True)
        won=self.won(n);draw=not won and all(all(x for x in r) for r in self.board)
        if won or draw:
            winner=expected if won else None
            if self.players[1] is None:
                pts=20 if winner else 8;await game_event(self.sid,self.gid,self.players[0].id,"finish",pts,"win" if winner else "draw")
            else:
                for p in self.players:
                    if p:await game_event(self.sid,self.gid,p.id,"finish",20 if winner and p.id==winner.id else 8 if draw else 4,"win" if winner and p.id==winner.id else "draw" if draw else "loss")
            await finish_game_session(self.sid,self.gid,[winner.id] if winner else [],draw=draw);self.finished=True
            for b in self.children:b.disabled=True
            result=(f"{winner.mention} wins!" if winner else "Draw.")
            return await i.response.edit_message(content=self.render()+"\n**"+result+"**",view=self,allowed_mentions=discord.AllowedMentions.none())
        self.turn=1-self.turn
        if self.players[1] is None and self.turn==1:
            choices=[c for c in range(7) if self.board[0][c]==0];c=random.choice(choices);await self.put(c,2)
            if self.won(2):
                await game_event(self.sid,self.gid,self.players[0].id,"finish",4,"loss");await finish_game_session(self.sid,self.gid,[],False);self.finished=True
                for b in self.children:b.disabled=True
                return await i.response.edit_message(content=self.render()+"\n**Manifest wins!**",view=self)
            self.turn=0
        await i.response.edit_message(content=self.render()+f"\nTurn: {(self.players[self.turn].mention if self.players[self.turn] else 'Manifest')}",view=self,allowed_mentions=discord.AllowedMentions.none())

class PartySessionView(discord.ui.View):
    def __init__(self,host,sid:int):super().__init__(timeout=900);self.host_id=host.id;self.sid=sid;self.players={host.id:host};self.round=0
    def names(self):return ", ".join(x.display_name for x in self.players.values()) or "Nobody"
    @discord.ui.button(label="Join",emoji="➕",style=discord.ButtonStyle.success)
    async def join(self,i,b):
        if i.user.id in self.players:return await i.response.send_message("You're already in this party.",ephemeral=True)
        self.players[i.user.id]=i.user;await game_add_player(self.sid,i.user.id);await game_event(self.sid,i.guild_id or 0,i.user.id,"join")
        await i.response.edit_message(content=f"🎉 **Manifest Party** · {len(self.players)} players\n{self.names()}",view=self)
    @discord.ui.button(label="Next round",emoji="🎲",style=discord.ButtonStyle.primary)
    async def next(self,i,b):
        if i.user.id!=self.host_id:return await i.response.send_message("Only the party host can start the next round.",ephemeral=True)
        if len(self.players)<2:return await i.response.send_message("At least two players are needed for Party Mode.",ephemeral=True)
        self.round+=1
        decks=[("Would You Rather","Explore space 🚀 or the deep ocean 🌊?"),("Most Likely To","Who is most likely to accidentally become famous?"),("Categories","Name something found in a school. No repeats."),("Caption Battle","Write the funniest clean caption for an imaginary cat wearing sunglasses."),("Quick Trivia","Which planet is known as the Red Planet?"),("Two Truths & a Lie","One player posts three short statements; everyone guesses the lie.")]
        kind,prompt=random.choice(decks);await db.execute("UPDATE game_sessions SET round_no=?,state_json=?,updated_at=? WHERE id=?",(self.round,json.dumps({'round':self.round,'kind':kind,'prompt':prompt}),time.time(),self.sid));await game_event(self.sid,i.guild_id or 0,i.user.id,"round",details=kind)
        await i.response.edit_message(content=f"🎉 **Manifest Party · Round {self.round}**\n**{kind}** — {prompt}\n\nPlayers: {self.names()}",view=self)
    @discord.ui.button(label="Leave",style=discord.ButtonStyle.secondary)
    async def leave(self,i,b):
        if i.user.id not in self.players:return await i.response.send_message("You're not in this party.",ephemeral=True)
        if i.user.id==self.host_id:return await i.response.send_message("The host can use End instead.",ephemeral=True)
        self.players.pop(i.user.id,None);await db.execute("UPDATE game_players SET status='left' WHERE session_id=? AND user_id=?",(self.sid,i.user.id));await i.response.edit_message(content=f"🎉 **Manifest Party** · {len(self.players)} players\n{self.names()}",view=self)
    @discord.ui.button(label="End",style=discord.ButtonStyle.danger)
    async def end(self,i,b):
        if i.user.id!=self.host_id:return await i.response.send_message("Only the host can end this party.",ephemeral=True)
        await finish_game_session(self.sid,i.guild_id or 0,draw=True)
        for x in self.children:x.disabled=True
        await i.response.edit_message(content=f"🎉 **Party ended** after {self.round} round(s).\nPlayers: {self.names()}",view=self)

