        await game_event(self.sid,self.gid,i.user.id,"finish",pts,"correct" if correct else "wrong");await finish_game_session(self.sid,self.gid,[i.user.id] if correct else [],False)
        for b in self.children:b.disabled=True
        await i.response.edit_message(content=f"{self.title}\n{self.prompt}\n\n{'✅ Correct!' if correct else f'❌ Answer: **{answer}**'} · +{pts} Play points",view=self)
