WORD_SCRAMBLE=["manifest","galaxy","rocket","castle","python","discord","planet","forest","puzzle","thunder","diamond","library"]
class WordScrambleModal(discord.ui.Modal,title="Word Scramble"):
    answer=discord.ui.TextInput(label="Unscrambled word",max_length=40)
    def __init__(self,game):super().__init__();self.game=game
    async def on_submit(self,i):await self.game.submit(i,str(self.answer.value))
class WordScrambleView(discord.ui.View):
    def __init__(self,user,sid,gid,word):super().__init__(timeout=180);self.uid=user.id;self.sid=sid;self.gid=gid;self.word=word;self.attempts=0;self.finished=False
    @discord.ui.button(label="Answer",emoji="✍️",style=discord.ButtonStyle.primary)
    async def answer_button(self,i,b):
        if i.user.id!=self.uid:return await i.response.send_message("This round belongs to someone else.",ephemeral=True)
        await i.response.send_modal(WordScrambleModal(self))
    async def submit(self,i,value):
        if self.finished:return await i.response.send_message("This round is already finished.",ephemeral=True)
        self.attempts+=1
        if value.strip().casefold()==self.word.casefold():
            self.finished=True;pts=max(8,18-(self.attempts-1)*4);await game_event(self.sid,self.gid,i.user.id,"finish",pts,"correct");await finish_game_session(self.sid,self.gid,[i.user.id],False)
            for x in self.children:x.disabled=True
            return await i.response.edit_message(content=f"🔤 **Word Scramble**\n✅ **{self.word.upper()}** · +{pts} Play points",view=self)
        if self.attempts>=3:
            self.finished=True;await game_event(self.sid,self.gid,i.user.id,"finish",2,"loss");await finish_game_session(self.sid,self.gid,[],False)
            for x in self.children:x.disabled=True
            return await i.response.edit_message(content=f"🔤 **Word Scramble**\n❌ The word was **{self.word.upper()}** · +2 Play points",view=self)
        await i.response.send_message(f"Not quite — **{3-self.attempts}** attempt(s) left.",ephemeral=True)

class NumberHuntModal(discord.ui.Modal,title="Number Hunt"):
    guess=discord.ui.TextInput(label="Your guess (1-100)",max_length=3)
    def __init__(self,game):super().__init__();self.game=game
    async def on_submit(self,i):await self.game.submit(i,str(self.guess.value))
class NumberHuntView(discord.ui.View):
    def __init__(self,user,sid,gid,target):super().__init__(timeout=180);self.uid=user.id;self.sid=sid;self.gid=gid;self.target=target;self.attempts=0;self.finished=False
    @discord.ui.button(label="Make a guess",emoji="🎯",style=discord.ButtonStyle.primary)
    async def guess_button(self,i,b):
        if i.user.id!=self.uid:return await i.response.send_message("This round belongs to someone else.",ephemeral=True)
        await i.response.send_modal(NumberHuntModal(self))
    async def submit(self,i,value):
        if self.finished:return await i.response.send_message("This round is already finished.",ephemeral=True)
        try:n=int(value)
        except ValueError:return await i.response.send_message("Enter a whole number from 1 to 100.",ephemeral=True)
        if not 1<=n<=100:return await i.response.send_message("Enter a number from 1 to 100.",ephemeral=True)
        self.attempts+=1
        if n==self.target:
            self.finished=True;pts=max(8,24-(self.attempts-1)*3);await game_event(self.sid,self.gid,i.user.id,"finish",pts,"correct");await finish_game_session(self.sid,self.gid,[i.user.id],False)
            for x in self.children:x.disabled=True
            return await i.response.edit_message(content=f"🎯 **Number Hunt**\n✅ **{self.target}** in {self.attempts} guess(es) · +{pts} Play points",view=self)
        if self.attempts>=7:
            self.finished=True;await game_event(self.sid,self.gid,i.user.id,"finish",2,"loss");await finish_game_session(self.sid,self.gid,[],False)
            for x in self.children:x.disabled=True
            return await i.response.edit_message(content=f"🎯 **Number Hunt**\n❌ Out of guesses. It was **{self.target}** · +2 Play points",view=self)
        await i.response.send_message(("⬆️ Higher." if n<self.target else "⬇️ Lower.")+f" **{7-self.attempts}** guess(es) left.",ephemeral=True)

