async def send_game_stats(i,member,ephemeral=False):
    gid=game_scope_id(i);r=await db.one("SELECT * FROM game_stats WHERE guild_id=? AND user_id=?",(gid,member.id));achs=await db.all("SELECT achievement FROM game_achievements WHERE guild_id=? AND user_id=? ORDER BY earned_at",(gid,member.id))
    if not r:return await i.response.send_message(f"🎮 **{member.display_name}** hasn't finished a tracked game yet.",ephemeral=ephemeral)
    labels={'first_game':'First Game','first_win':'First Win','ten_games':'10 Games','fifty_games':'50 Games','hundred_points':'100 Points','daily_challenger':'Daily Challenger'}
    games=int(r['games_played'] or 0);wins=int(r['wins'] or 0);rate=round(wins*100/games) if games else 0
    e=manifest_ui_embed(f"Manifest Play · {member.display_name}",f"A consistent profile across Manifest's tracked games.")
    e.add_field(name="Games",value=f"**{games}**");e.add_field(name="Wins",value=f"**{wins}**");e.add_field(name="Win rate",value=f"**{rate}%**")
    e.add_field(name="Play points",value=f"**{int(r['points'] or 0):,}**");e.add_field(name="Draws",value=f"**{int(r['draws'] or 0)}**");e.add_field(name="Losses",value=f"**{int(r['losses'] or 0)}**")
    e.add_field(name="Achievements",value=", ".join(labels.get(x['achievement'],x['achievement']) for x in achs) or "None yet",inline=False)
    await i.response.send_message(embed=e,ephemeral=ephemeral)

async def send_game_leaderboard(i,ephemeral=False):
    gid=game_scope_id(i);rows=await db.all("SELECT user_id,games_played,wins,points FROM game_stats WHERE guild_id=? ORDER BY points DESC,wins DESC LIMIT 10",(gid,));lines=[]
    for n,r in enumerate(rows,1):
        m=i.guild.get_member(r['user_id']) if i.guild else None;lines.append(f"**{n}.** {(m.display_name if m else 'User '+str(r['user_id']))} — **{r['points']} pts** · {r['wins']} wins · {r['games_played']} games")
    await i.response.send_message(embed=discord.Embed(title="🏆 Manifest Play Leaderboard",description="\n".join(lines) or "No tracked games yet.",color=discord.Color.gold()),ephemeral=ephemeral)

async def send_game_season_leaderboard(i,ephemeral=False):
    gid=game_scope_id(i);season=game_season_key();rows=await db.all("SELECT user_id,points,wins,games_played FROM game_season_scores WHERE guild_id=? AND season_key=? ORDER BY points DESC,wins DESC,games_played DESC LIMIT 10",(gid,season));lines=[]
    for n,r in enumerate(rows,1):
        member=i.guild.get_member(int(r['user_id'])) if i.guild else None
        label=member.display_name if member else f"User {r['user_id']}"
        lines.append(f"**{n}.** {label} — **{int(r['points']):,} pts** · {int(r['wins'])} wins · {int(r['games_played'])} games")
    text="\n".join(lines) or "No season scores yet. Finish any tracked Play game to appear here."
    embed=discord.Embed(title=f"📅 Manifest Play · {season} Season",description=text,color=discord.Color.blurple())
    embed.set_footer(text="Scores reset each UTC calendar month. Lifetime stats and achievements are unchanged; Play points have no real-world value.")
    await i.response.send_message(embed=embed,ephemeral=ephemeral,allowed_mentions=discord.AllowedMentions.none())

async def game_tournament_board(tournament_id:int,guild_id:int):
    event=await db.one("SELECT * FROM game_tournaments WHERE id=? AND guild_id=?",(int(tournament_id),int(guild_id)))
    if not event:raise ValueError("That tournament no longer exists in this server.")
    now=time.time();status=str(event['status'] or 'active')
    if status=='active' and now>=float(event['ends_at'] or 0):
        await db.execute("UPDATE game_tournaments SET status='completed',completed_at=? WHERE id=? AND status='active'",(now,int(tournament_id)));status='completed'
    rows=await db.all("SELECT user_id,points,games_played,wins FROM game_tournament_players WHERE tournament_id=? ORDER BY points DESC,wins DESC,games_played DESC LIMIT 10",(int(tournament_id),))
    total=await db.one("SELECT COUNT(*) n FROM game_tournament_players WHERE tournament_id=?",(int(tournament_id),))
    lines=[]
    for rank,row in enumerate(rows,1):
        lines.append(f"**{rank}.** <@{int(row['user_id'])}> — **{int(row['points']):,} pts** · {int(row['wins'])} wins · {int(row['games_played'])} games")
    desc=("\n".join(lines) or "No participants yet. Join the event, then play any tracked Manifest Play game.")
    embed=discord.Embed(title=f"🏆 {str(event['name'])[:180]}",description=desc,color=discord.Color.gold())
    embed.add_field(name="Event status",value=f"**{status.title()}** · {int(total['n'] or 0) if total else 0}/200 participants",inline=True)
    embed.add_field(name="Event window",value=f"<t:{int(event['starts_at'])}:f> to <t:{int(event['ends_at'])}:f>",inline=True)
    embed.set_footer(text="No entry fee, wagers, purchases or real-world prizes. Scores are server entertainment points only.")
    return embed,status

async def send_active_game_tournament(i,ephemeral=True):
    if not i.guild:return await i.response.send_message("Tournaments are available inside a server.",ephemeral=True)
    now=time.time()
    await db.execute("UPDATE game_tournaments SET status='completed',completed_at=? WHERE guild_id=? AND status='active' AND ends_at<=?",(now,i.guild.id,now))
    event=await db.one("SELECT id FROM game_tournaments WHERE guild_id=? AND status='active' AND starts_at<=? AND ends_at>? ORDER BY created_at DESC LIMIT 1",(i.guild.id,now,now))
    if not event:
        return await i.response.send_message("There is no active Play tournament right now. A server manager can create one with `/games tournament name:<event name>`. The monthly season leaderboard is available from the Play panel.",ephemeral=ephemeral)
    embed,_=await game_tournament_board(int(event['id']),i.guild.id)
    await i.response.send_message(embed=embed,view=GameTournamentView(int(event['id']),i.guild.id),ephemeral=ephemeral,allowed_mentions=discord.AllowedMentions.none())

class GameTournamentView(discord.ui.View):
    def __init__(self,tournament_id:int,guild_id:int):
        super().__init__(timeout=86400);self.tournament_id=int(tournament_id);self.guild_id=int(guild_id)
    async def interaction_check(self,i):
        if not i.guild or i.guild.id!=self.guild_id:
            await i.response.send_message("This tournament belongs to another server.",ephemeral=True);return False
        return True
    @discord.ui.button(label="Join tournament",emoji="✅",style=discord.ButtonStyle.success,row=0)
    async def join(self,i,b):
        event=await db.one("SELECT status,starts_at,ends_at FROM game_tournaments WHERE id=? AND guild_id=?",(self.tournament_id,self.guild_id))
        now=time.time()
        if not event:return await i.response.send_message("This tournament is no longer available.",ephemeral=True)
        if str(event['status'])!='active' or now<float(event['starts_at'] or 0) or now>=float(event['ends_at'] or 0):
            return await i.response.send_message("Registration is closed for this event.",ephemeral=True)
        existing=await db.one("SELECT 1 ok FROM game_tournament_players WHERE tournament_id=? AND user_id=?",(self.tournament_id,i.user.id))
        if not existing:
            count=await db.one("SELECT COUNT(*) n FROM game_tournament_players WHERE tournament_id=?",(self.tournament_id,))
            if int(count['n'] or 0)>=200:return await i.response.send_message("This event has reached its 200-player capacity.",ephemeral=True)
            await db.execute("INSERT OR IGNORE INTO game_tournament_players(tournament_id,user_id,joined_at) VALUES(?,?,?)",(self.tournament_id,i.user.id,now))
        await i.response.send_message("You are registered. Complete any tracked Manifest Play games during the event to earn tournament points.",ephemeral=True)
    @discord.ui.button(label="Leaderboard",emoji="🏆",style=discord.ButtonStyle.primary,row=0)
    async def leaderboard(self,i,b):
        try:
            embed,_=await game_tournament_board(self.tournament_id,self.guild_id)
            await i.response.send_message(embed=embed,ephemeral=True,allowed_mentions=discord.AllowedMentions.none())
        except Exception as exc:await i.response.send_message(_safe_diag_text(exc,350),ephemeral=True)

