@games_group.command(name="tournament",description="Open or create a no-entry-fee community Play tournament")
@app_commands.describe(name="Leave blank to open the active event; enter a name to create one",duration_hours="Event duration from 1 to 168 hours")
async def game_tournament_create(i:discord.Interaction,name:str="",duration_hours:int=72):
    if not i.guild:return await i.response.send_message("Tournaments are server-only.",ephemeral=True)
    if not await game_gate(i):return
    clean=re.sub(r"\s+"," ",str(name or "")).strip()
    if not clean:return await send_active_game_tournament(i,ephemeral=False)
    if not can_manage(i):return await i.response.send_message("Manage Server is required to create a Play tournament.",ephemeral=True)
    if len(clean)>60:return await i.response.send_message("Choose an event name from 1 to 60 characters.",ephemeral=True)
    if not 1<=int(duration_hours)<=168:return await i.response.send_message("Event duration must be from 1 to 168 hours.",ephemeral=True)
    now=time.time()
    await db.execute("UPDATE game_tournaments SET status='completed',completed_at=? WHERE guild_id=? AND status='active' AND ends_at<=?",(now,i.guild.id,now))
    current=await db.one("SELECT id,name,ends_at FROM game_tournaments WHERE guild_id=? AND status='active' AND ends_at>? LIMIT 1",(i.guild.id,now))
    if current:return await i.response.send_message(f"There is already an active Play tournament: **{str(current['name'])[:60]}** · ends <t:{int(current['ends_at'])}:R>. Open it with `/games tournament`.",ephemeral=True)
    end=now+int(duration_hours)*3600
    cur=await db.execute("INSERT INTO game_tournaments(guild_id,name,status,starts_at,ends_at,created_by,created_at) VALUES(?,?,'active',?,?,?,?)",(i.guild.id,clean,now,end,i.user.id,now))
    tournament_id=int(cur.lastrowid)
    e=discord.Embed(title=f"🏆 Manifest Play Tournament · {clean}",description="Join below, then play any tracked Manifest Play game during the event. Your completed-game points count toward this event automatically.",color=discord.Color.gold())
    e.add_field(name="Event window",value=f"Starts <t:{int(now)}:R>\nEnds <t:{int(end)}:f>",inline=True)
    e.add_field(name="Registration",value="Up to 200 participants · one registration per member",inline=True)
    e.set_footer(text="No entry fee, wagers, purchases or real-world prizes. Points are server entertainment stats only.")
    await i.response.send_message(embed=e,view=GameTournamentView(tournament_id,i.guild.id),allowed_mentions=discord.AllowedMentions.none())
