# ========================= SENTINEL VERIFICATION GATE =========================
async def get_verification(gid):
    row=await db.one("SELECT * FROM verification_config WHERE guild_id=?",(gid,))
    if row:return row
    await db.execute("INSERT OR IGNORE INTO verification_config(guild_id) VALUES(?)",(gid,))
    return await db.one("SELECT * FROM verification_config WHERE guild_id=?",(gid,))

async def restore_verification_channels(guild):
    rows=await db.all("SELECT channel_id,view_channel,send_messages FROM verification_backups WHERE guild_id=?",(guild.id,))
    restored=0
    for r in rows:
        ch=guild.get_channel(r['channel_id'])
        if not isinstance(ch,discord.TextChannel):continue
        try:
            ow=ch.overwrites_for(guild.default_role)
            ow.view_channel=None if r['view_channel'] < 0 else bool(r['view_channel'])
            ow.send_messages=None if r['send_messages'] < 0 else bool(r['send_messages'])
            await ch.set_permissions(guild.default_role,overwrite=ow,reason="Manifest verification gate disabled")
            restored+=1
        except (discord.Forbidden,discord.HTTPException):
            continue
    await db.execute("DELETE FROM verification_backups WHERE guild_id=?",(guild.id,))
    return restored

class VerificationView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None)

    @discord.ui.button(label="Verify",emoji="✅",style=discord.ButtonStyle.success,custom_id="manifest:v24:verify")
    async def verify(self,i:discord.Interaction,b:discord.ui.Button):
        if not i.guild:
            return await i.response.send_message("Verification is only available inside a server.",ephemeral=True)
        cfg=await get_verification(i.guild.id)
        if not cfg['enabled']:
            return await i.response.send_message("The verification gate is currently disabled.",ephemeral=True)
        role=i.guild.get_role(cfg['role_id'])
        if not role:
            return await i.response.send_message("The verification role is missing. A server manager needs to repair the verification setup.",ephemeral=True)
        if role >= i.guild.me.top_role:
            return await i.response.send_message("Manifest's role must be above the verification role.",ephemeral=True)
        age_hours=(discord.utils.utcnow()-i.user.created_at).total_seconds()/3600
        minimum=max(0,int(cfg['min_account_age_hours']))
        if minimum and age_hours < minimum:
            remaining=max(1,math.ceil(minimum-age_hours))
            return await i.response.send_message(f"⏳ Your Discord account must be at least **{minimum} hours old** to verify here. Try again in about **{remaining} hour(s)**.",ephemeral=True)
        try:
            if isinstance(i.user,discord.Member):
                await i.user.add_roles(role,reason="Manifest Sentinel verification")
            else:
                return await i.response.send_message("I couldn't verify that member.",ephemeral=True)
        except discord.Forbidden:
            return await i.response.send_message("Manifest cannot assign the verification role. Check my Manage Roles permission and role position.",ephemeral=True)
        await db.execute("INSERT INTO verification_events(guild_id,user_id,event_type,created_at,details) VALUES(?,?,?,?,?)",(i.guild.id,i.user.id,'verified',time.time(),f'account_age_hours={age_hours:.1f}'))
        await security_event(i.guild,'member_verified',i.user.id,role.id,f'Account age {age_hours:.1f}h')
        await i.response.send_message(f"✅ You're verified in **{i.guild.name}**. Welcome in.",ephemeral=True)


