# ========================= STAFF OPERATIONS / LOA =========================
async def staff_policy(gid:int):
    row=await db.one("SELECT * FROM staff_policy WHERE guild_id=?",(gid,))
    if not row:
        await db.execute("INSERT OR IGNORE INTO staff_policy(guild_id,updated_at) VALUES(?,?)",(gid,time.time()))
        row=await db.one("SELECT * FROM staff_policy WHERE guild_id=?",(gid,))
    return row

async def active_absence(gid:int,uid:int):
    now=time.time()
    row=await db.one("SELECT * FROM staff_absences WHERE guild_id=? AND user_id=? AND status='active' AND starts_at<=? AND ends_at>? ORDER BY id DESC LIMIT 1",(gid,uid,now,now))
    return row

async def staff_messages_in_days(gid:int,uid:int,days:int=30):
    start=(datetime.datetime.now(datetime.timezone.utc)-datetime.timedelta(days=max(1,days)-1)).strftime("%Y-%m-%d")
    row=await db.one("SELECT COALESCE(SUM(total),0) n FROM activity_buckets WHERE guild_id=? AND user_id=? AND day>=?",(gid,uid,start))
    return int(row['n'] or 0) if row else 0

async def loa_days_used(gid:int,uid:int,window_days:int=90):
    cutoff=time.time()-window_days*86400
    rows=await db.all("SELECT starts_at,ends_at FROM staff_absences WHERE guild_id=? AND user_id=? AND kind='loa' AND status IN ('active','completed') AND ends_at>?",(gid,uid,cutoff))
    total=0.0
    for r in rows:
        total += max(0.0,min(float(r['ends_at']),time.time())-max(float(r['starts_at']),cutoff))/86400
    return total

async def staff_event(gid,uid,actor,event_type,details=''):
    await db.execute("INSERT INTO staff_events(guild_id,user_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(gid,uid,actor,event_type,details[:1500],time.time()))

async def staff_is_eligible_member(member:discord.Member):
    # Staff identity never grants authority. This is only workflow eligibility.
    p=member.guild_permissions
    if member.guild.owner_id==member.id or p.administrator or p.manage_guild or p.moderate_members or p.manage_messages or p.kick_members or p.ban_members:
        return True
    cfg=await db.one("SELECT support_role_id FROM guild_settings WHERE guild_id=?",(member.guild.id,))
    return bool(cfg and cfg['support_role_id'] and any(r.id==int(cfg['support_role_id']) for r in member.roles))

async def evaluate_loa_request(member:discord.Member,days:int):
    policy=await staff_policy(member.guild.id)
    msgs=await staff_messages_in_days(member.guild.id,member.id,30)
    used=await loa_days_used(member.guild.id,member.id,90)
    reasons=[]
    if not int(policy['auto_loa']): reasons.append('automatic LOA approval is disabled')
    if days>int(policy['auto_loa_max_days']): reasons.append(f"request exceeds the {policy['auto_loa_max_days']}-day automatic limit")
    if msgs<int(policy['min_messages_30d']): reasons.append(f"activity is {msgs}/{policy['min_messages_30d']} eligible messages in the last 30 days")
    if used+days>int(policy['max_loa_days_90d']): reasons.append(f"90-day LOA allowance would be exceeded ({used:.1f}+{days}/{policy['max_loa_days_90d']} days)")
    return (not reasons),msgs,used,reasons,policy

async def post_staff_review(guild,embed):
    policy=await staff_policy(guild.id); cid=int(policy['review_channel_id'] or 0)
    ch=guild.get_channel(cid) if cid else None
    if isinstance(ch,discord.TextChannel):
        try: await ch.send(embed=embed,allowed_mentions=discord.AllowedMentions.none())
        except discord.HTTPException: pass

@staff_group.command(name="loa",description="Request leave of absence without unnecessary waiting")
@app_commands.describe(days="Number of days away",reason="Optional private staff reason",handover="Optional work/tickets/tasks to hand over")
async def staff_loa(i:discord.Interaction,days:app_commands.Range[int,1,90],reason:str="",handover:str=""):
    if not isinstance(i.user,discord.Member) or not await staff_is_eligible_member(i.user):
        return await i.response.send_message("This workflow is for configured staff. It does not grant staff permissions.",ephemeral=True)
    if await active_absence(i.guild_id,i.user.id):
        return await i.response.send_message("You already have an active LOA/reduced-activity period.",ephemeral=True)
    approved,msgs,used,reasons,policy=await evaluate_loa_request(i.user,int(days))
    now=time.time(); end=now+int(days)*86400; status='active' if approved else 'requested'
    cur=await db.execute("INSERT INTO staff_absences(guild_id,user_id,kind,reason,starts_at,ends_at,status,requested_at,decided_at,decided_by,auto_decision,handover) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",(i.guild_id,i.user.id,'loa',reason[:1000],now,end,status,now,now if approved else 0,0,1 if approved else 0,handover[:1500]))
    rid=cur.lastrowid
    await staff_event(i.guild_id,i.user.id,i.user.id,'loa_auto_approved' if approved else 'loa_requested',f'id={rid} days={days} messages30={msgs} used90={used:.1f}')
    if approved:
        return await i.response.send_message(f"✅ **LOA approved automatically** through <t:{int(end)}:D>. Your staff activity requirements are paused during the approved period."+("\nYour handover was saved." if handover else ""),ephemeral=True)
    e=discord.Embed(title=f"Staff LOA review • #{rid}",description=f"{i.user.mention} requested **{days} day(s)** of LOA.",color=discord.Color.orange())
    e.add_field(name="Objective check",value="\n".join(f"• {x}" for x in reasons)[:1000],inline=False)
    e.add_field(name="Activity",value=f"{msgs} eligible messages / 30d • {used:.1f} LOA days used / 90d",inline=False)
    if handover:e.add_field(name="Handover",value=handover[:1000],inline=False)
    await post_staff_review(i.guild,e)
    await i.response.send_message(f"🕒 LOA request **#{rid}** needs staff-management review because " + "; ".join(reasons) + ".",ephemeral=True)

@staff_group.command(name="reduced",description="Request a reduced-activity period")
async def staff_reduced(i:discord.Interaction,days:app_commands.Range[int,1,60],reason:str=""):
    if not isinstance(i.user,discord.Member) or not await staff_is_eligible_member(i.user):
        return await i.response.send_message("This workflow is for configured staff.",ephemeral=True)
    if await active_absence(i.guild_id,i.user.id):return await i.response.send_message("You already have an active LOA/reduced-activity period.",ephemeral=True)
    policy=await staff_policy(i.guild_id);now=time.time();end=now+int(days)*86400
    # Reduced activity is lower risk than full LOA: within the auto-LOA duration it can start automatically.
    approved=int(days)<=int(policy['auto_loa_max_days'])
    cur=await db.execute("INSERT INTO staff_absences(guild_id,user_id,kind,reason,starts_at,ends_at,status,requested_at,decided_at,auto_decision) VALUES(?,?,?,?,?,?,?,?,?,?)",(i.guild_id,i.user.id,'reduced',reason[:1000],now,end,'active' if approved else 'requested',now,now if approved else 0,1 if approved else 0))
    await staff_event(i.guild_id,i.user.id,i.user.id,'reduced_auto_approved' if approved else 'reduced_requested',f'id={cur.lastrowid} days={days}')
    await i.response.send_message((f"✅ Reduced activity is active through <t:{int(end)}:D>. Requirement calculations will use the server's reduced-activity percentage." if approved else f"🕒 Reduced-activity request **#{cur.lastrowid}** was sent for review."),ephemeral=True)

@staff_group.command(name="decide",description="Approve or decline a pending LOA/reduced-activity request")
async def staff_decide(i:discord.Interaction,request_id:int,approve:bool):
    if not server_manager(i.user):return await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True)
    row=await db.one("SELECT * FROM staff_absences WHERE id=? AND guild_id=?",(request_id,i.guild_id))
    if not row or row['status']!='requested':return await i.response.send_message("That pending staff request was not found.",ephemeral=True)
    status='active' if approve else 'declined';now=time.time()
    await db.execute("UPDATE staff_absences SET status=?,decided_at=?,decided_by=? WHERE id=?",(status,now,i.user.id,request_id))
    await staff_event(i.guild_id,row['user_id'],i.user.id,'absence_approved' if approve else 'absence_declined',f'id={request_id} kind={row["kind"]}')
    await i.response.send_message(f"{'✅ Approved' if approve else '❌ Declined'} staff request **#{request_id}**.",ephemeral=True)

@staff_group.command(name="return",description="End your active LOA/reduced-activity period early")
async def staff_return(i:discord.Interaction):
    row=await active_absence(i.guild_id,i.user.id)
    if not row:return await i.response.send_message("You don't have an active LOA/reduced-activity period.",ephemeral=True)
    now=time.time();await db.execute("UPDATE staff_absences SET status='completed',ended_at=? WHERE id=?",(now,row['id']))
    await staff_event(i.guild_id,i.user.id,i.user.id,'staff_returned',f'id={row["id"]} kind={row["kind"]}')
    await i.response.send_message("👋 Welcome back. Your normal staff requirements resume from now; approved time away is not counted as missed activity.",ephemeral=True)

@staff_group.command(name="who_is_away",description="Show current LOA and reduced-activity staff")
async def staff_who_is_away(i:discord.Interaction):
    if not server_manager(i.user):return await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True)
    now=time.time();rows=await db.all("SELECT * FROM staff_absences WHERE guild_id=? AND status='active' AND ends_at>? ORDER BY ends_at",(i.guild_id,now))
    lines=[]
    for r in rows[:30]:
        m=i.guild.get_member(r['user_id']); who=m.mention if m else f"`{r['user_id']}`"; lines.append(f"• {who} — **{r['kind'].replace('_',' ').title()}** until <t:{int(r['ends_at'])}:R>")
    await i.response.send_message("\n".join(lines) or "No staff are currently on LOA/reduced activity.",ephemeral=True)

@staff_group.command(name="policy",description="Configure automatic staff leave decisions")
async def staff_policy_cmd(i:discord.Interaction,auto_loa:bool,auto_max_days:app_commands.Range[int,1,60],min_messages_30d:app_commands.Range[int,0,10000],max_loa_days_90d:app_commands.Range[int,1,90],review_channel:discord.TextChannel|None=None):
    if not server_manager(i.user):return await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True)
    await db.execute("INSERT INTO staff_policy(guild_id,auto_loa,auto_loa_max_days,min_messages_30d,max_loa_days_90d,review_channel_id,updated_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(guild_id) DO UPDATE SET auto_loa=excluded.auto_loa,auto_loa_max_days=excluded.auto_loa_max_days,min_messages_30d=excluded.min_messages_30d,max_loa_days_90d=excluded.max_loa_days_90d,review_channel_id=excluded.review_channel_id,updated_at=excluded.updated_at",(i.guild_id,int(auto_loa),int(auto_max_days),int(min_messages_30d),int(max_loa_days_90d),review_channel.id if review_channel else 0,time.time()))
    await i.response.send_message(f"✅ Staff leave policy updated. Auto LOA: **{'ON' if auto_loa else 'OFF'}** • max auto **{auto_max_days}d** • activity floor **{min_messages_30d}/30d** • 90d allowance **{max_loa_days_90d}d**.",ephemeral=True)

@staff_group.command(name="requirement",description="Set objective requirements for a staff role")
async def staff_requirement(i:discord.Interaction,role:discord.Role,period_days:app_commands.Range[int,7,90]=30,min_messages:app_commands.Range[int,0,10000]=0,min_tickets:app_commands.Range[int,0,1000]=0,min_cases:app_commands.Range[int,0,1000]=0):
    if not server_manager(i.user):return await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True)
    await db.execute("INSERT INTO staff_requirements(guild_id,role_id,period_days,min_messages,min_tickets,min_cases,enabled,updated_at) VALUES(?,?,?,?,?,?,1,?) ON CONFLICT(guild_id,role_id) DO UPDATE SET period_days=excluded.period_days,min_messages=excluded.min_messages,min_tickets=excluded.min_tickets,min_cases=excluded.min_cases,enabled=1,updated_at=excluded.updated_at",(i.guild_id,role.id,int(period_days),int(min_messages),int(min_tickets),int(min_cases),time.time()))
    await i.response.send_message(f"✅ Requirements saved for {role.mention}. LOA/reduced-activity periods are accounted for instead of being treated as inactivity.",ephemeral=True)

async def staff_requirement_progress(guild:discord.Guild,member:discord.Member,req):
    days=int(req['period_days']);start=time.time()-days*86400
    messages=await staff_messages_in_days(guild.id,member.id,days)
    t=await db.one("SELECT COUNT(*) n FROM tickets WHERE guild_id=? AND claimed_by=? AND closed_at>=?",(guild.id,member.id,start));tickets=int(t['n'] or 0) if t else 0
    c=await db.one("SELECT COUNT(*) n FROM mod_cases WHERE guild_id=? AND moderator_id=? AND created_at>=?",(guild.id,member.id,start));cases=int(c['n'] or 0) if c else 0
    absence=await active_absence(guild.id,member.id)
    factor=1.0
    if absence and absence['kind']=='loa':factor=0.0
    elif absence and absence['kind']=='reduced':
        policy=await staff_policy(guild.id);factor=max(0.0,min(1.0,int(policy['reduced_activity_percent'])/100))
    targets={'messages':round(int(req['min_messages'])*factor),'tickets':round(int(req['min_tickets'])*factor),'cases':round(int(req['min_cases'])*factor)}
    met=messages>=targets['messages'] and tickets>=targets['tickets'] and cases>=targets['cases']
    return messages,tickets,cases,targets,met,absence

@staff_group.command(name="review",description="Review objective staff progress without automatic punishment")
async def staff_review(i:discord.Interaction,member:discord.Member):
    if not server_manager(i.user):return await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True)
    reqs=await db.all("SELECT * FROM staff_requirements WHERE guild_id=? AND enabled=1",(i.guild_id,))
    req=next((r for r in reqs if any(role.id==r['role_id'] for role in member.roles)),None)
    if not req:return await i.response.send_message("No objective requirement policy is configured for that member's staff roles.",ephemeral=True)
    messages,tickets,cases,targets,met,absence=await staff_requirement_progress(i.guild,member,req)
    e=discord.Embed(title=f"Staff review • {member.display_name}",description="Objective evidence only — Manifest does not automatically decide a person's quality or punish them.",color=discord.Color.green() if met else discord.Color.orange())
    e.add_field(name="Messages",value=f"{messages} / {targets['messages']}");e.add_field(name="Tickets",value=f"{tickets} / {targets['tickets']}");e.add_field(name="Cases",value=f"{cases} / {targets['cases']}")
    e.add_field(name="Status",value=("Requirements paused — approved LOA" if absence and absence['kind']=='loa' else "Reduced-activity targets applied" if absence else "Eligible for review" if met else "Needs attention"),inline=False)
    await i.response.send_message(embed=e,ephemeral=True)

