@staff_group.command(name="leaderboard",description="Compare staff operational contribution using measured evidence")
async def staff_leaderboard(i:discord.Interaction,days:app_commands.Range[int,7,90]=30):
    if not server_manager(i.user):return await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True)
    ids=set()
    for r in await db.all("SELECT DISTINCT user_id FROM staff_events WHERE guild_id=? AND created_at>=?",(i.guild_id,time.time()-int(days)*86400)):ids.add(int(r['user_id']))
    for r in await db.all("SELECT DISTINCT moderator_id user_id FROM mod_cases WHERE guild_id=? AND created_at>=?",(i.guild_id,time.time()-int(days)*86400)):ids.add(int(r['user_id']))
    scored=[]
    for uid in list(ids)[:60]:
        m=i.guild.get_member(uid)
        if not m or m.bot:continue
        d=await manifest_staff_contribution(i.guild,m,days);scored.append((d['index'],m,d))
    scored.sort(key=lambda x:(x[0],x[2]['tickets'],x[2]['tasks']),reverse=True)
    lines=[f"`{n}.` **{m.display_name}** — {score}/100 • {d['tickets']} tickets • {d['tasks']} tasks • {d['cases']} cases"+(f" • {d['absence'].replace('_',' ')}" if d['absence'] else "") for n,(score,m,d) in enumerate(scored[:15],1)]
    await i.response.send_message(("📊 **Staff Contribution Evidence**\n"+("\n".join(lines) if lines else "No measured staff activity for this period.")+"\n\n*Operational evidence only — never an automatic promotion/demotion or trust ranking.*")[:1900],ephemeral=True)

@automation_group.command(name="create",description="Create a simple server automation")
async def automation_create(i:discord.Interaction,name:str,trigger:str,action:str,payload:str):
    if not server_manager(i.user):return await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True)
    action=action.strip().lower();trigger=trigger.strip()
    if action not in {'join_message','keyword_reply'}:return await i.response.send_message("Legacy `join_ping` is no longer created because automated pings are unsafe. Use a typed automation instead.",ephemeral=True)
    if action=='join_message':
        trigger_type='member_join';action_type='send_message';channel_id=i.channel_id;conditions={}
    else:
        trigger_type='keyword';action_type='send_message';channel_id=i.channel_id;conditions={'contains_content':trigger}
    typed_payload={'channel_id':channel_id,'text':payload[:1900]}
    ok,why=await validate_automation_rule(i.guild,i.user,trigger_type,action_type,typed_payload,conditions)
    if not ok:return await i.response.send_message(f"⚠️ Automation rejected: {why}",ephemeral=True)
    cur=await db.execute("INSERT INTO automation_rules(guild_id,creator_id,name,trigger_type,conditions_json,action_type,payload_json,enabled,cooldown_seconds,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)",(i.guild_id,i.user.id,name[:80],trigger_type,json.dumps(conditions),action_type,json.dumps(typed_payload),1,30,time.time()))
    await i.response.send_message(f"⚙️ Automation **#{cur.lastrowid}** created on the typed engine. Legacy automations are no longer created.",ephemeral=True)

