    legacy_count=await db.one("SELECT COUNT(*) n FROM custom_automations WHERE guild_id=? AND enabled=1",(i.guild_id,))
    if legacy_count and int(legacy_count['n'] or 0):
        lines.append(f"\n⚠️ {int(legacy_count['n'])} legacy automation(s) remain stored; they are not created by the current engine.")
    await i.response.send_message("\n".join(lines)[:1900] or "No typed automations.",ephemeral=True)

