async def get_server_policy(guild_id):
    r=await db.one("SELECT * FROM server_policies WHERE guild_id=?",(guild_id,))
    if not r:
        await db.execute("INSERT OR IGNORE INTO server_policies(guild_id) VALUES(?)",(guild_id,))
        r=await db.one("SELECT * FROM server_policies WHERE guild_id=?",(guild_id,))
    return r

async def persist_manifest_memory(guild_id:int, key:str, value:str, source:str="owner"):
    """Persist small, non-secret server preferences/decisions in SQLite."""
    await db.execute(
        "INSERT INTO manifest_server_memory(guild_id,memory_key,value,source,updated_at) VALUES(?,?,?,?,?) "
        "ON CONFLICT(guild_id,memory_key) DO UPDATE SET value=excluded.value,source=excluded.source,updated_at=excluded.updated_at",
        (int(guild_id),str(key)[:120],str(value)[:4000],str(source)[:40],time.time())
    )

async def read_manifest_memory(guild_id:int, key:str, default=""):
    row=await db.one("SELECT value FROM manifest_server_memory WHERE guild_id=? AND memory_key=?",(int(guild_id),str(key)[:120]))
    return row["value"] if row else default

async def save_setup_history(guild, actor_id:int, blueprint:dict, status:str, snapshot_id:int=0, error:str=""):
    cur=await db.execute(
        "INSERT INTO manifest_setup_history(guild_id,actor_id,template,complexity,readiness,plan_json,snapshot_id,status,created_at,applied_at,error) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
        (guild.id,int(actor_id or 0),blueprint.get("template","community"),blueprint.get("complexity","balanced"),int(blueprint.get("readiness",0)),
         json.dumps(blueprint.get("actions",[]),separators=(",",":")),int(snapshot_id or 0),status,time.time(),time.time() if status in {"applied","partial"} else 0,str(error)[:1000])
    )
    return int(cur.lastrowid)

async def build_server_setup_plan(guild, request=""):
    """Deterministic, read-only setup planner. Never mutates Discord."""
    h=await server_health_report(guild)
    policy=await get_server_policy(guild.id)
    text=(request or "").strip().lower()
    names={c.name.casefold() for c in guild.channels}
    categories={c.name.casefold() for c in guild.categories}
    roles={r.name.casefold() for r in guild.roles}
    plan=[]; warnings=[]

    def has_any(values):
        return any(v in names or v in categories for v in values)
    def add(kind,name,reason,risk="low"):
        plan.append({"kind":kind,"name":name,"reason":reason,"risk":risk})

    # Infer a conservative template from the request; no AI or fuzzy mutation is involved.
    if any(x in text for x in ("gaming","game","roblox","minecraft")):
        if not has_any(("general","chat","lobby")): add("channel","general","primary community chat")
        if not has_any(("media","clips","screenshots")): add("channel","media","share clips, screenshots and creations")
    elif any(x in text for x in ("study","school","education")):
        if not has_any(("general","chat")): add("channel","general","general discussion")
        if not has_any(("study","homework","help")): add("channel","study-help","focused study/help discussion")
    elif any(x in text for x in ("support","ticket","help")):
        if not has_any(("support","help","tickets")): add("category","Support","organize member support")
    elif any(x in text for x in ("creator","community","social")):
        if not has_any(("general","chat")): add("channel","general","primary community chat")
        if not has_any(("announcements","news")): add("channel","announcements","important server updates")
    else:
        if not has_any(("general","chat","lobby")): add("channel","general","primary community chat")
        if not has_any(("announcements","news")): add("channel","announcements","important server updates")

    if not any(("mod" in r or "staff" in r) for r in roles):
        warnings.append("No obvious staff/moderation role was detected; review roles manually before creating one.")
    if not h['security']['anti_raid']:
        warnings.append("Anti-raid protection is not enabled.")
    if not h['security']['anti_nuke']:
        warnings.append("Anti-nuke protection is not enabled.")
    if h['members'] >= 50 and not h['verification']['enabled']:
        warnings.append("Verification is not configured for a larger community.")
    if h['missing_bot_permissions']:
        warnings.append("Manifest is missing required Discord permissions: " + ", ".join(h['missing_bot_permissions']))

    return {"health":h,"policy":policy,"plan":plan[:12],"warnings":warnings[:8]}

async def manifest_server_constitution(guild_id):
    """Return the durable owner-defined setup constitution for a guild."""
    policy=await get_server_policy(guild_id)
    template=await read_manifest_memory(guild_id,"constitution_template","")
    complexity=await read_manifest_memory(guild_id,"constitution_complexity","")
    return {
        "template": template or "auto",
        "complexity": complexity or "balanced",
        "autonomy": str(policy["autonomy"] if policy else "assisted"),
        "risk_policy": str(policy["risk_policy"] if policy else "safe"),
    }

async def save_manifest_constitution(guild_id:int, actor_id:int, template:str, complexity:str, autonomy:str, risk_policy:str):
    """Persist owner setup preferences without storing secrets."""
    allowed_templates={"auto","community","gaming","study","creator","support","marketplace"}
    allowed_complexity={"simple","balanced","advanced","maximum"}
    allowed_autonomy={"assisted","community","full"}
    allowed_risk={"safe","managed"}
    template=template if template in allowed_templates else "auto"
    complexity=complexity if complexity in allowed_complexity else "balanced"
    autonomy=autonomy if autonomy in allowed_autonomy else "assisted"
    risk_policy=risk_policy if risk_policy in allowed_risk else "safe"
    await db.execute(
        "INSERT INTO server_policies(guild_id,autonomy,risk_policy,updated_at) VALUES(?,?,?,?) "
        "ON CONFLICT(guild_id) DO UPDATE SET autonomy=excluded.autonomy,risk_policy=excluded.risk_policy,updated_at=excluded.updated_at",
        (int(guild_id),autonomy,risk_policy,time.time())
    )
    await persist_manifest_memory(guild_id,"constitution_template",template,"owner")
    await persist_manifest_memory(guild_id,"constitution_complexity",complexity,"owner")
    await persist_manifest_memory(guild_id,"constitution_autonomy",autonomy,"owner")
    await persist_manifest_memory(guild_id,"constitution_risk_policy",risk_policy,"owner")
    await persist_manifest_memory(guild_id,"constitution_last_actor",str(int(actor_id)),"owner")
    await persist_manifest_memory(guild_id,"constitution_updated_at",str(int(time.time())),"owner")
    return await manifest_server_constitution(guild_id)

async def build_manifest_setup_blueprint(guild, template="auto", complexity="balanced"):
    """Build a deterministic, idempotent starter architecture for new/existing servers.
    Planning is read-only. The result separates safe structure actions from owner review items.
    """
    constitution=await manifest_server_constitution(guild.id)
    template=(template or constitution["template"] or "auto").lower().strip()
    complexity=(complexity or constitution["complexity"] or "balanced").lower().strip()
    if template=="auto":
        profile=await db.one("SELECT server_type FROM server_profiles WHERE guild_id=?",(guild.id,))
        detected=(profile["server_type"] if profile else "mixed") or "mixed"
        template={"gaming":"gaming","education":"study","creator":"creator","business/community":"community","social/hangout":"community"}.get(detected,"community")
    aliases={"roblox":"gaming","minecraft":"gaming","support":"support","friends":"community"}
    template=aliases.get(template,template)
    base={
        "community": [("Start Here","rules"),("Start Here","welcome"),("Community","general"),("Community","media"),("Support","support")],
        "gaming": [("Start Here","rules"),("Start Here","welcome"),("Community","general"),("Gaming","game-chat"),("Gaming","media"),("Support","support")],
        "study": [("Start Here","rules"),("Start Here","welcome"),("Study","study-help"),("Study","resources"),("Community","general"),("Support","support")],
        "creator": [("Start Here","rules"),("Start Here","welcome"),("Community","general"),("Creator","content"),("Creator","media"),("Support","support")],
        "support": [("Start Here","rules"),("Start Here","welcome"),("Support","support"),("Support","faq"),("Support","announcements")],
        "marketplace": [("Start Here","rules"),("Start Here","welcome"),("Marketplace","listings"),("Marketplace","showcase"),("Support","support")],
    }.get(template, [("Start Here","rules"),("Start Here","welcome"),("Community","general"),("Support","support")])
    if complexity in {"advanced","maximum"}:
        base += [("Community","suggestions"),("Community","events")]
    if complexity=="maximum":
        base += [("Information","faq")]

    existing_categories={c.name.casefold():c for c in guild.categories}
    existing_channels={c.name.casefold():c for c in guild.text_channels}
    existing_roles={r.name.casefold():r for r in guild.roles}
    # Detect external/Manifest ticket surfaces before proposing a new support
    # channel. A setup blueprint must coexist with existing systems by default.
    integrations=await discover_server_integrations(guild,persist=True)
    ticket_integration=next((x for x in integrations if x.get('system_key')=='tickets'),None)
    preserved_integrations=[]
    if ticket_integration:
        preserved_integrations.append({k:ticket_integration.get(k) for k in ('system_key','provider_type','provider_id','mode','confidence')})
    actions=[]; review=[]; done=0
    seen_categories=set(existing_categories)
    planned_categories=set()
    for category,name in base:
        if name.casefold() in existing_channels:
            done+=1
            continue
        if name.casefold()=='support' and ticket_integration:
            # Existing system evidence satisfies the support-system review gate;
            # do not create an unrelated duplicate channel automatically.
            done+=1
            continue
        if category.casefold() not in existing_categories and category.casefold() not in planned_categories:
            actions.append({"kind":"category","name":category,"reason":"recommended server section"})
            planned_categories.add(category.casefold())
        actions.append({"kind":"channel","name":name,"category":category,"reason":"missing recommended channel"})

    staff_detected=any(("mod" in r or "staff" in r or "admin" in r) and r not in {"administrator"} for r in existing_roles)
    if not staff_detected:
        review.append("No obvious staff/moderation role was detected. Review your staff structure before adding permissions.")
    if "rules" not in existing_channels:
        review.append("Add clear server rules before opening the community to new members.")
    if "welcome" not in existing_channels:
        review.append("Consider using Discord Onboarding/Server Guide alongside the welcome channel.")

    h=await server_health_report(guild)
    security_gaps=[]
    if not h['security']['anti_raid']:
        security_gaps.append("Anti-raid protection is not enabled.")
    if not h['security']['anti_nuke']:
        security_gaps.append("Anti-nuke protection is not enabled.")
    if h['members'] >= 50 and not h['verification']['enabled']:
        security_gaps.append("Verification is not configured for a larger community.")
    if h['missing_bot_permissions']:
        security_gaps.append("Manifest is missing required Discord permissions: " + ", ".join(h['missing_bot_permissions']))
    review.extend(security_gaps)
    if ticket_integration:
        review.append(f"An existing ticket/support system was detected ({ticket_integration.get('provider_type','unknown')} · {int(float(ticket_integration.get('confidence',0))*100)}% confidence); the blueprint will preserve it instead of creating a duplicate support channel.")

    total=len(base)
    readiness=round(done*100/max(1,total))
    if security_gaps:
        readiness=max(0,readiness-10)
    return {
        "template":template,"complexity":complexity,"actions":actions,
        "preserved_integrations":preserved_integrations,
        "completed":done,"total":total,"readiness":readiness,
        "health_score":h.get("health_score",0),"security_gaps":security_gaps,
        "review":review[:10],"requires_review":bool(review),
        "summary":f"{done}/{total} recommended channels already exist; {len(actions)} safe structure action(s) remain."
    }

async def apply_manifest_setup_blueprint(guild, actor, blueprint):
    """Apply only generated non-destructive structure; verify every Discord mutation."""
    if not guild or not actor:return False,"Missing server context.",[],None
    if not (actor.id==guild.owner_id or actor.id in OWNER_IDS or actor.guild_permissions.administrator or actor.guild_permissions.manage_guild):
        return False,"Server-owner/authorized Manifest access is required.",[],None
    me=guild.me
    if not me or not me.guild_permissions.manage_channels:
        return False,"Manifest needs Manage Channels to apply the setup.",[],None
    snapshot=await capture_server_snapshot(guild,actor.id,f"before Manifest {blueprint.get('template','community')} setup")
    created=[]; errors=[]
    categories={c.name.casefold():c for c in guild.categories}
    channels={c.name.casefold():c for c in guild.text_channels}
    for action in blueprint.get("actions",[]):
        try:
            if action["kind"]=="category":
                key=action["name"].casefold()
                if key not in categories:
                    c=await guild.create_category(action["name"],reason=f"Manifest setup by {actor}")
                    fresh=await guild.fetch_channel(c.id)
                    if not isinstance(fresh,discord.CategoryChannel) or fresh.name.casefold()!=key or getattr(getattr(fresh,'guild',None),'id',None)!=guild.id:
                        raise RuntimeError("category creation could not be verified")
                    categories[key]=fresh; created.append(f"category **{fresh.name}**")
            elif action["kind"]=="channel":
                key=action["name"].casefold()
                if key in channels:continue
                cat=categories.get(str(action.get("category","")).casefold())
                c=await guild.create_text_channel(action["name"],category=cat,reason=f"Manifest setup by {actor}")
                fresh=await guild.fetch_channel(c.id)
                if not isinstance(fresh,discord.TextChannel) or fresh.name.casefold()!=key or getattr(getattr(fresh,'guild',None),'id',None)!=guild.id:
                    raise RuntimeError("channel creation could not be verified")
                if cat and fresh.category_id != cat.id:
                    raise RuntimeError("channel category placement could not be verified")
                channels[key]=fresh; created.append(fresh.mention)
        except (discord.Forbidden,discord.HTTPException,RuntimeError) as ex:
            errors.append(f"{action.get('kind')} {action.get('name')}: {type(ex).__name__}")
    await update_server_needs(guild)
    if errors:
        return False,f"Created/verified {len(created)} item(s); {len(errors)} action(s) failed verification.",created,snapshot
    return True,f"Created and verified {len(created)} item(s).",created,snapshot

async def server_doctor_report(guild):
    """Read-only server diagnosis combining permissions, configuration and live queues."""
    h=await server_health_report(guild)
    issues=[]; fixes=[]; seen=set()
    def add(issue,fix):
        key=str(issue).casefold()
        if key in seen:return
        seen.add(key);issues.append(str(issue));fixes.append(str(fix))

    if h['missing_bot_permissions']:
        add("Manifest is missing: " + ", ".join(h['missing_bot_permissions']),
            "Restore only the Discord permissions required by the features you intend to use.")
    for gap in h['configuration_gaps']:
        add(f"Missing {gap}.",f"Review whether a {gap} is needed, then configure it without replacing an existing system.")
    if not h['security']['anti_raid'] or not h['security']['anti_nuke']:
        add("Core security protection is not fully enabled.","Review /security setup and choose thresholds appropriate for this server before enabling automatic responses.")
    if not h['verification']['enabled'] and h['members'] >= 50:
        add("Verification is not configured for a larger community.","Consider /security verify_setup if this community needs a verification gate.")

    # Validate references saved by managers. A saved ID is not proof that its
    # channel/role still exists, and a missing destination should be actionable.
    try:
        settings=await db.one("SELECT * FROM guild_settings WHERE guild_id=?",(guild.id,))
        channel_fields=(
            ("ai_channel_id","AI response channel"),("log_mod_id","moderation log channel"),
            ("log_arrival_id","arrival log channel"),("log_security_id","security log channel"),
            ("log_message_id","message log channel"),("log_ticket_id","ticket log channel"),
            ("welcome_channel_id","welcome channel"),("autopilot_channel_id","Autopilot channel"),
        )
        for field,label in channel_fields:
            if not settings or field not in settings.keys():continue
            cid=int(settings[field] or 0)
            if not cid:continue
            channel=guild.get_channel(cid)
            if channel is None:
                try:
                    channel=await guild.fetch_channel(cid)
                    if getattr(getattr(channel,'guild',None),'id',None)!=guild.id:channel=None
                except discord.NotFound:
                    channel=None
                except (discord.Forbidden,discord.HTTPException):
                    # A permission/network failure is not proof of deletion.
                    continue
            if channel is None:
                add(f"The configured {label} reference no longer resolves.",f"Choose a replacement {label} or clear the stale setting.")
            elif guild.me:
                perms=channel.permissions_for(guild.me)
                if not perms.view_channel or not perms.send_messages:
                    add(f"Manifest cannot both view and send in the configured {label}.",f"Adjust that channel's overwrites so Manifest has View Channel and Send Messages, if this feature should operate there.")

        if settings:
            support_role_id=int(settings['support_role_id'] or 0)
            if support_role_id and guild.get_role(support_role_id) is None:
                add("The configured support role no longer exists.","Select a replacement support role in ticket settings.")
    except Exception as ex:
        log.warning("Server Doctor configuration-reference check failed for guild %s: %s",guild.id,type(ex).__name__)

    try:
        verification=await db.one("SELECT role_id,channel_id,enabled FROM verification_config WHERE guild_id=?",(guild.id,))
        if verification and int(verification['enabled'] or 0):
            rid=int(verification['role_id'] or 0);cid=int(verification['channel_id'] or 0)
            if rid and guild.get_role(rid) is None:
                add("Verification is enabled but its verified-member role reference is missing.","Select an existing verified-member role and recheck its hierarchy/permissions.")
            if cid and guild.get_channel(cid) is None:
                try: fetched=await guild.fetch_channel(cid)
                except discord.NotFound:fetched=None
                except (discord.Forbidden,discord.HTTPException):fetched=True  # unknown, not confirmed broken
                if fetched is None:
                    add("Verification is enabled but its panel channel reference is missing.","Select a replacement verification channel and republish the panel.")
    except Exception as ex:
        log.warning("Server Doctor verification check failed for guild %s: %s",guild.id,type(ex).__name__)

    # Durable queue state matters as much as configuration: surface work that
    # needs an operator rather than silently treating a stale queue as healthy.
    checks=(
        ("stale_tickets", "SELECT COUNT(*) c FROM tickets WHERE guild_id=? AND status='open' AND created_at>0 AND created_at<?", (guild.id,time.time()-72*3600), "open ticket(s) are older than 72 hours", "Review ownership and either respond, resolve, or escalate each stale ticket."),
        ("uncertain_announcements", "SELECT COUNT(*) c FROM scheduled_announcements WHERE guild_id=? AND delivered=0 AND status='uncertain'", (guild.id,), "scheduled announcement(s) have uncertain delivery", "Check the destination channel before retrying; acknowledge possible duplicates only after inspection."),
        ("failed_announcements", "SELECT COUNT(*) c FROM scheduled_announcements WHERE guild_id=? AND delivered=0 AND status='failed'", (guild.id,), "scheduled announcement(s) failed", "Inspect the stored error and destination permissions before retrying."),
        ("failed_automations", "SELECT COUNT(*) c FROM automation_runs WHERE guild_id=? AND status IN ('failed','uncertain') AND created_at>=?", (guild.id,time.time()-7*86400), "automation run(s) failed or became uncertain in the last 7 days", "Open Automation Runs/Doctor, inspect each failed rule and avoid blindly replaying uncertain actions."),
        ("open_incidents", "SELECT COUNT(*) c FROM security_incidents WHERE guild_id=? AND state NOT IN ('resolved','closed')", (guild.id,), "unresolved security incident(s) remain open", "Review the incident evidence and recovery state before resolving or restoring quarantined members."),
        ("uncertain_reminders", "SELECT COUNT(*) c FROM reminders WHERE guild_id=? AND delivered=0 AND status='uncertain'", (guild.id,), "reminder(s) have uncertain delivery", "Check whether the reminder already reached its destination before using the explicit duplicate-risk retry path."),
    )
    for key,query,args,label,fix in checks:
        try:
            row=await db.one(query,args);count=int(row['c'] or 0) if row else 0
            if count:add(f"{count} {label}.",fix)
        except Exception as ex:
            log.debug("Server Doctor optional queue check %s unavailable for guild %s: %s",key,guild.id,type(ex).__name__)

    try:
        diag=await db.one("SELECT COUNT(*) c FROM diagnostic_issues WHERE status='open' AND last_guild_id=?",(guild.id,))
        count=int(diag['c'] or 0) if diag else 0
        if count:add(f"{count} grouped Manifest diagnostic issue(s) are open for this server.","Have a Manifest operator inspect the related diagnostic traces before changing configuration.")
    except Exception:
        pass

    return h, issues[:12], fixes[:12]


# ========================= WHOLE-SERVER INTELLIGENCE =========================
MANIFEST_SERVER_MODES={"normal","event","raid_alert","maintenance","lockdown","recovery"}

def _manifest_fp(*parts):
    return hashlib.sha256("|".join(str(x) for x in parts).encode("utf-8","ignore")).hexdigest()[:32]

async def manifest_current_mode(guild_id:int):
    row=await db.one("SELECT * FROM manifest_server_modes WHERE guild_id=?",(guild_id,))
    if not row:return {"mode":"normal","reason":"","expires_at":0,"set_by":0}
    if float(row["expires_at"] or 0)>0 and float(row["expires_at"])<=time.time():
        previous=(row["previous_mode"] or "normal").lower()
        if previous not in MANIFEST_SERVER_MODES:previous="normal"
        await db.execute("UPDATE manifest_server_modes SET mode=?,reason='Temporary mode expired',set_at=?,expires_at=0 WHERE guild_id=?",(previous,time.time(),guild_id))
        return {"mode":previous,"reason":"Temporary mode expired","expires_at":0,"set_by":int(row["set_by"] or 0)}
    return {"mode":row["mode"] or "normal","reason":row["reason"] or "","expires_at":float(row["expires_at"] or 0),"set_by":int(row["set_by"] or 0)}

async def manifest_set_mode(guild_id:int,mode:str,actor_id:int,reason:str="",minutes:int=0):
    mode=(mode or "normal").strip().lower().replace(" ","_")
    if mode not in MANIFEST_SERVER_MODES:return False,"Unknown mode."
    old=await manifest_current_mode(guild_id); expires=time.time()+max(1,min(int(minutes),10080))*60 if minutes else 0
    await db.execute("INSERT INTO manifest_server_modes(guild_id,mode,reason,set_by,set_at,expires_at,previous_mode) VALUES(?,?,?,?,?,?,?) ON CONFLICT(guild_id) DO UPDATE SET previous_mode=manifest_server_modes.mode,mode=excluded.mode,reason=excluded.reason,set_by=excluded.set_by,set_at=excluded.set_at,expires_at=excluded.expires_at",(guild_id,mode,reason[:500],actor_id,time.time(),expires,old['mode']))
    await persist_manifest_memory(guild_id,"server_mode",mode,"owner")
    return True,f"Mode set to {mode.replace('_',' ').upper()}"+(f" until <t:{int(expires)}:R>" if expires else "")

async def manifest_permission_intelligence(guild):
    risky=[]; admins=[]; role_managers=[]
    for r in sorted(guild.roles,key=lambda x:x.position,reverse=True):
        if r.is_default() or r.managed:continue
        p=r.permissions; flags=[]
        for name,val in (("Administrator",p.administrator),("Manage Server",p.manage_guild),("Manage Roles",p.manage_roles),("Manage Channels",p.manage_channels),("Ban Members",p.ban_members),("Mention Everyone",p.mention_everyone)):
            if val:flags.append(name)
        if p.administrator:admins.append(r.name)
        if p.manage_roles:role_managers.append(r.name)
        if flags:risky.append((r.name,flags))
    me=guild.me; bot_top=getattr(getattr(me,'top_role',None),'position',0)
    blocked=[r.name for r in guild.roles if not r.is_default() and not r.managed and r.position>=bot_top] if me else []
    return {"administrator_roles":admins,"manage_roles_roles":role_managers,"risky":risky[:15],"above_manifest":blocked[:15]}

async def manifest_member_journey(guild):
    names={c.name.lower():c for c in guild.text_channels}; signals=[]
    def has(words):return any(any(w in n for w in words) for n in names)
    checks=[("arrival",has(("welcome","start-here","introduc"))), ("rules",has(("rules","guideline"))), ("roles",has(("role","choose"))), ("community",has(("general","chat","lounge"))), ("support",has(("support","help","ticket")))]
    for key,ok in checks:signals.append((key,ok))
    score=round(sum(1 for _,ok in signals if ok)/len(signals)*100)
    missing=[k for k,ok in signals if not ok]
    return {"score":score,"missing":missing,"checks":signals}

async def manifest_growth_advisor(guild,days=30):
    days=max(7,min(90,int(days))); start=(datetime.datetime.now(datetime.timezone.utc)-datetime.timedelta(days=days)).date().isoformat()
    row=await db.one("SELECT COALESCE(SUM(joins),0) joins,COALESCE(SUM(leaves),0) leaves,COALESCE(SUM(messages),0) messages,COALESCE(SUM(unique_users),0) active FROM guild_daily_metrics WHERE guild_id=? AND day>=?",(guild.id,start))
    joins=int(row['joins'] or 0);leaves=int(row['leaves'] or 0);messages=int(row['messages'] or 0);active=int(row['active'] or 0)
    net=joins-leaves; notes=[]
    if joins and leaves/joins>0.6:notes.append("Member loss is high relative to joins; inspect onboarding and early member experience.")
    if messages<days*10:notes.append("Measured text activity is light; events, prompts, or clearer community destinations may help.")
    if not notes:notes.append("No obvious growth warning appears in the currently recorded metrics.")
    return {"days":days,"joins":joins,"leaves":leaves,"net":net,"messages":messages,"active_sum":active,"notes":notes}

async def manifest_support_intelligence_snapshot(guild_id:int):
    """Support operations metrics derived from ticket metadata only; no ticket content is read."""
    now=time.time();gid=int(guild_id)
    row=await db.one("SELECT COUNT(*) total,COALESCE(SUM(CASE WHEN COALESCE(claimed_by,0)=0 THEN 1 ELSE 0 END),0) unclaimed,COALESCE(SUM(CASE WHEN created_at>0 AND created_at<? THEN 1 ELSE 0 END),0) older_48h,COALESCE(SUM(CASE WHEN priority IN ('urgent','high') THEN 1 ELSE 0 END),0) urgent,COALESCE(AVG(CASE WHEN created_at>0 THEN (? - created_at)/3600.0 END),0) avg_age_hours,MIN(NULLIF(created_at,0)) oldest FROM tickets WHERE guild_id=? AND status='open'",(now-48*3600,now,gid))
    staff=await db.all("SELECT claimed_by,COUNT(*) total,COALESCE(SUM(CASE WHEN priority IN ('urgent','high') THEN 1 ELSE 0 END),0) urgent FROM tickets WHERE guild_id=? AND status='open' AND COALESCE(claimed_by,0)<>0 GROUP BY claimed_by ORDER BY total DESC LIMIT 8",(gid,))
    oldest=await db.all("SELECT channel_id,user_id,claimed_by,priority,subject,created_at FROM tickets WHERE guild_id=? AND status='open' ORDER BY CASE priority WHEN 'urgent' THEN 0 WHEN 'high' THEN 1 ELSE 2 END,created_at ASC LIMIT 8",(gid,))
    total=int(row['total'] or 0) if row else 0
    oldest_at=float(row['oldest'] or 0) if row else 0
    return {"open":total,"unclaimed":int(row['unclaimed'] or 0) if row else 0,
            "older_48h":int(row['older_48h'] or 0) if row else 0,
            "urgent":int(row['urgent'] or 0) if row else 0,
            "avg_age_hours":round(float(row['avg_age_hours'] or 0),1) if row else 0,
            "oldest_age_hours":round(max(0,now-oldest_at)/3600,1) if oldest_at else 0,
            "staff":staff,"oldest":oldest}

async def manifest_analytics_snapshot(guild_id:int,days=14):
    """Aggregate engagement and operations; never queries or reveals message bodies."""
    days=max(7,min(90,int(days)));gid=int(guild_id)
    start=(datetime.datetime.now(datetime.timezone.utc)-datetime.timedelta(days=days)).date().isoformat()
    row=await db.one("SELECT COALESCE(SUM(joins),0) joins,COALESCE(SUM(leaves),0) leaves,COALESCE(SUM(messages),0) messages,COALESCE(SUM(tickets_opened),0) tickets_opened,COALESCE(SUM(tickets_closed),0) tickets_closed,COALESCE(SUM(mod_cases),0) mod_cases,COALESCE(SUM(security_events),0) security_events FROM guild_daily_metrics WHERE guild_id=? AND day>=?",(gid,start))
    active=await db.one("SELECT COUNT(DISTINCT user_id) users FROM daily_active_users WHERE guild_id=? AND day>=?",(gid,start))
    channels=await db.all("SELECT channel_id,COALESCE(SUM(messages),0) messages FROM channel_daily_metrics WHERE guild_id=? AND day>=? GROUP BY channel_id ORDER BY messages DESC LIMIT 5",(gid,start))
    hours=await db.all("SELECT hour,COALESCE(SUM(messages),0) messages FROM hourly_activity WHERE guild_id=? AND day>=? GROUP BY hour ORDER BY messages DESC LIMIT 3",(gid,start))
    data={key:int(row[key] or 0) for key in ("joins","leaves","messages","tickets_opened","tickets_closed","mod_cases","security_events")} if row else {key:0 for key in ("joins","leaves","messages","tickets_opened","tickets_closed","mod_cases","security_events")}
    data.update({"days":days,"active_users":int(active['users'] or 0) if active else 0,
                 "net_growth":data["joins"]-data["leaves"],"top_channels":channels,"peak_hours":hours})
    return data

async def manifest_refresh_recommendations(guild):
    health=await server_health_report(guild); journey=await manifest_member_journey(guild); perm=await manifest_permission_intelligence(guild)
    candidates=[]
    for gap in health.get('configuration_gaps',[]):candidates.append(("configuration",f"Add or improve {gap}",f"Manifest's live scan could not identify a clear {gap}.","medium"))
    if not health.get('security',{}).get('anti_raid') or not health.get('security',{}).get('anti_nuke'):candidates.append(("security","Review server protection","Anti-raid or anti-nuke protection is not fully enabled.","high"))
    if journey['missing']:candidates.append(("journey","Improve the new-member path",f"Journey signals missing: {', '.join(journey['missing'])}.","medium"))
    if perm['administrator_roles']:candidates.append(("permissions","Review Administrator roles",f"Administrator is granted to: {', '.join(perm['administrator_roles'][:8])}.","high"))
    support=await manifest_support_intelligence_snapshot(guild.id)
    if support["urgent"]:
        candidates.append(("support","Review urgent support tickets",f"There are {support['urgent']} open high-priority/urgent ticket(s). Rebalance ownership and review the oldest cases.","high"))
    if support["unclaimed"]:
        candidates.append(("support","Assign unclaimed support tickets",f"{support['unclaimed']} of {support['open']} open ticket(s) are currently unclaimed.","medium"))
    if support["older_48h"]:
        candidates.append(("support","Review aging support backlog",f"{support['older_48h']} open ticket(s) are older than 48 hours; average open age is {support['avg_age_hours']} hours.","medium"))
    now=time.time(); touched=[]
    for kind,title,details,severity in candidates:
        fp=_manifest_fp(kind,title,details)
        await db.execute("INSERT INTO manifest_recommendations(guild_id,kind,title,details,severity,fingerprint,status,created_at,updated_at) VALUES(?,?,?,?,?,?,'open',?,?) ON CONFLICT(guild_id,fingerprint) DO UPDATE SET title=excluded.title,details=excluded.details,severity=excluded.severity,status='open',updated_at=excluded.updated_at",(guild.id,kind,title,details,severity,fp,now,now));touched.append(fp)
    # A recommendation is a live finding, not a permanent warning. Close stale
    # generated findings when the current evidence no longer supports them.
    open_rows=await db.all("SELECT fingerprint FROM manifest_recommendations WHERE guild_id=? AND status='open'",(guild.id,))
    stale=[str(r['fingerprint']) for r in open_rows if str(r['fingerprint']) not in set(touched)]
    for fp in stale:
        await db.execute("UPDATE manifest_recommendations SET status='resolved',updated_at=? WHERE guild_id=? AND fingerprint=? AND status='open'",(now,guild.id,fp))
    return await db.all("SELECT * FROM manifest_recommendations WHERE guild_id=? AND status='open' ORDER BY CASE severity WHEN 'high' THEN 0 WHEN 'medium' THEN 1 ELSE 2 END,updated_at DESC LIMIT 12",(guild.id,))

async def manifest_server_brief(guild):
    health=await server_health_report(guild); mode=await manifest_current_mode(guild.id); journey=await manifest_member_journey(guild); growth=await manifest_growth_advisor(guild); recs=await manifest_refresh_recommendations(guild)
    inc=await db.one("SELECT COUNT(*) n FROM security_incidents WHERE guild_id=? AND state NOT IN ('resolved','closed')",(guild.id,))
    tickets=await db.one("SELECT COUNT(*) n FROM tickets WHERE guild_id=? AND status='open'",(guild.id,))
    return {"health":health,"mode":mode,"journey":journey,"growth":growth,"recommendations":recs,"open_incidents":int(inc['n'] or 0),"open_tickets":int(tickets['n'] or 0)}

async def manifest_whole_server_context(guild, viewer=None):
    """Return only context the viewer is entitled to know. Sensitive operational counts are staff-scoped."""
    brief=await manifest_server_brief(guild)
    h=brief['health'];g=brief['growth'];m=brief['mode'];j=brief['journey']
    base=(f"Server operating mode: {m['mode']}. Journey readiness: {j['score']}/100. "
          f"Recorded {g['days']}d growth: joins {g['joins']}, leaves {g['leaves']}, net {g['net']}.")
    privileged=bool(viewer and (viewer.id==guild.owner_id or viewer.guild_permissions.administrator or viewer.guild_permissions.manage_guild))
    if privileged:
        base += f" Operational counts visible to this manager: open support tickets {brief['open_tickets']}, open security incidents {brief['open_incidents']}, open recommendations {len(brief['recommendations'])}."
    return redact_sensitive_text(base)

async def manifest_staff_contribution(guild,member,days=30):
    days=max(7,min(90,int(days)));cut=time.time()-days*86400
    msg=await db.one("SELECT COALESCE(SUM(total),0) n FROM activity_buckets WHERE guild_id=? AND user_id=? AND day>=?",(guild.id,member.id,(datetime.datetime.now(datetime.timezone.utc)-datetime.timedelta(days=days)).date().isoformat()))
    if not msg or not int(msg['n'] or 0):msg=await db.one("SELECT total n FROM message_stats WHERE guild_id=? AND user_id=?",(guild.id,member.id))
    tickets=await db.one("SELECT COUNT(*) n FROM ticket_events WHERE guild_id=? AND actor_id=? AND created_at>=? AND event_type IN ('claimed','closed','resolved')",(guild.id,member.id,cut))
    cases=await db.one("SELECT COUNT(*) n FROM mod_cases WHERE guild_id=? AND moderator_id=? AND created_at>=?",(guild.id,member.id,cut))
    tasks=await db.one("SELECT COUNT(*) n FROM staff_tasks WHERE guild_id=? AND assignee_id=? AND status='completed' AND completed_at>=?",(guild.id,member.id,cut))
    events=await db.one("SELECT COUNT(*) n FROM staff_events WHERE guild_id=? AND user_id=? AND created_at>=?",(guild.id,member.id,cut))
    absence=await active_absence(guild.id,member.id)
    values={"messages":int(msg['n'] or 0) if msg else 0,"tickets":int(tickets['n'] or 0),"cases":int(cases['n'] or 0),"tasks":int(tasks['n'] or 0),"workflow":int(events['n'] or 0)}
    # Bounded operational index: useful for comparison, never a trust/promotion verdict.
    values['index']=min(100,round(min(values['messages'],300)/6 + min(values['tickets'],20)*1.5 + min(values['cases'],20)*1.2 + min(values['tasks'],20)*1.5 + min(values['workflow'],20)*.5))
    values['absence']=absence['kind'] if absence else ''
    values['days']=days
    return values


@server_group.command(name="intelligence",description="Inspect, explain and review Manifest's whole-server intelligence")
@app_commands.choices(action=[app_commands.Choice(name=x[0],value=x[1]) for x in (("Inspect","inspect"),("Evolution","evolution"),("Explain","explain"),("Recommendations","recommendations"),("Next action","next"),("Permission audit","permissions"),("Member journey","journey"),("Growth advisor","growth"),("Server brief","brief"),("Snapshot capture","snapshot_capture"),("Snapshot compare","snapshot_compare"),("Snapshot list","snapshot_list"),("Analytics · 14 days","analytics"),("Support operations","support"),("System quality","system_health"),("Mode status","mode_status"),("Mode: Normal","mode_normal"),("Mode: Event","mode_event"),("Mode: Raid Alert","mode_raid_alert"),("Mode: Maintenance","mode_maintenance"),("Mode: Lockdown","mode_lockdown"),("Mode: Recovery","mode_recovery"))])
async def server_intelligence(i:discord.Interaction,action:app_commands.Choice[str],reason:str="",minutes:app_commands.Range[int,0,10080]=0):
    if not server_manager(i.user):return await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True)
    a=action.value
    if a.startswith('mode_') and a!='mode_status':
        ok,msg=await manifest_set_mode(i.guild_id,a[5:],i.user.id,reason,minutes);return await i.response.send_message(("✅ " if ok else "⚠️ ")+msg,ephemeral=True)
    if a=='mode_status':
        m=await manifest_current_mode(i.guild_id);return await i.response.send_message(f"🧭 **Server mode:** {m['mode'].replace('_',' ').upper()}\nReason: {m['reason'] or 'none'}"+(f"\nExpires: <t:{int(m['expires_at'])}:R>" if m['expires_at'] else ""),ephemeral=True)
    if a=='snapshot_capture':
        sid=await capture_server_snapshot(i.guild,i.user.id,reason or 'manual intelligence baseline');return await i.response.send_message(f"📸 Configuration snapshot **#{sid}** captured. Structure and selected permissions only; no message history.",ephemeral=True)
    if a=='snapshot_compare':return await i.response.send_message((await compare_latest_snapshot(i.guild))[:1900]+"\n\nEvidence only — comparison does not restore or mutate anything.",ephemeral=True)
    if a=='snapshot_list':
        rows=await db.all("SELECT id,created_at,label,triggered_by FROM server_snapshots WHERE guild_id=? ORDER BY id DESC LIMIT 5",(i.guild_id,));lines=[f"`#{r['id']}` <t:{int(r['created_at'])}:R> — {r['label'] or 'snapshot'}" for r in rows];return await i.response.send_message("📸 **Recent configuration snapshots**\n"+("\n".join(lines) if lines else "None yet."),ephemeral=True)
    if a=='permissions':
        d=await manifest_permission_intelligence(i.guild);lines=[f"• **{name}** — {', '.join(flags)}" for name,flags in d['risky']];return await i.response.send_message(("🔐 **Permission Intelligence**\n"+("\n".join(lines) if lines else "No elevated non-managed roles detected.")+f"\n\nRoles at/above Manifest hierarchy: {', '.join(d['above_manifest']) or 'none'}")[:1900],ephemeral=True)
    if a=='journey':
        d=await manifest_member_journey(i.guild);return await i.response.send_message(f"🧭 **Member Journey • {d['score']}/100**\n"+"\n".join(f"{'✅' if ok else '⚠️'} {k.title()}" for k,ok in d['checks'])+(f"\n\nMissing signals: {', '.join(d['missing'])}" if d['missing'] else ""),ephemeral=True)
    if a=='growth':
        d=await manifest_growth_advisor(i.guild);return await i.response.send_message(f"📈 **Growth Advisor • {d['days']} days**\nJoins: **{d['joins']}** • Leaves: **{d['leaves']}** • Net: **{d['net']:+d}** • Messages: **{d['messages']}**\n\n"+"\n".join(f"• {x}" for x in d['notes']),ephemeral=True)
    if a=='analytics':
        d=await manifest_analytics_snapshot(i.guild_id,14)
        channel_lines=[]
        for row in d['top_channels']:
            channel=i.guild.get_channel(int(row['channel_id']))
            channel_lines.append(f"• {getattr(channel,'mention',f'channel:{row['channel_id']}')} · {int(row['messages'] or 0)} messages")
        peak=', '.join(f"{int(x['hour']):02d}:00 ({int(x['messages'])})" for x in d['peak_hours']) or 'Not enough hourly data'
        return await i.response.send_message(f"📊 **Server Analytics · Last 14 Days**\nMessages: **{d['messages']:,}** · Distinct active users: **{d['active_users']:,}**\nJoins: **{d['joins']}** · Leaves: **{d['leaves']}** · Net: **{d['net_growth']:+d}**\nTickets opened/closed: **{d['tickets_opened']} / {d['tickets_closed']}**\nModeration cases: **{d['mod_cases']}** · Security events: **{d['security_events']}**\n\n**Most active channels**\n"+('\n'.join(channel_lines) or 'No channel activity recorded for this period.')+f"\n\n**Peak recorded hours (UTC)**\n{peak}\n\nMetrics are aggregate counts; no message content is inspected by this report.",ephemeral=True)
    if a=='support':
        d=await manifest_support_intelligence_snapshot(i.guild_id)
        staff_lines=[]
        for row in d['staff']:
            member=i.guild.get_member(int(row['claimed_by']))
            staff_lines.append(f"• {getattr(member,'display_name',f'user:{row['claimed_by']}')} · {row['total']} open ({row['urgent']} urgent/high)")
        oldest_lines=[]
        for row in d['oldest'][:6]:
            channel=i.guild.get_channel(int(row['channel_id']))
            age=max(0,time.time()-float(row['created_at'] or time.time()))/3600
            owner=f"<@{int(row['user_id'])}>" if row['user_id'] else 'unknown requester'
            oldest_lines.append(f"• {getattr(channel,'mention',f'ticket:{row['channel_id']}')} · {owner} · {row['priority']} · {age:.1f}h")
        return await i.response.send_message(f"🎧 **Support Operations**\nOpen: **{d['open']}** · Unclaimed: **{d['unclaimed']}** · Urgent/high: **{d['urgent']}**\nOlder than 48h: **{d['older_48h']}** · Average age: **{d['avg_age_hours']}h** · Oldest: **{d['oldest_age_hours']}h**\n\n**Assigned workload**\n"+('\n'.join(staff_lines) or 'No claimed tickets.')+"\n\n**Oldest / highest-priority cases**\n"+('\n'.join(oldest_lines) or 'No open tickets.'),ephemeral=True)
    if a=='system_health':
        q=await manifest_quality_snapshot(i.guild_id)
        success=f"{q['command_rate']}%" if q['commands'] else 'No command samples yet'
        return await i.response.send_message(f"🩺 **Manifest System Quality · 24 Hours**\nCommand success rate: **{success}** ({q['command_success']}/{q['commands']})\nQuality events: **{q['quality_ok']}/{q['events']} successful**\nAverage recorded latency: **{q['avg_ms']} ms**\nOpen runtime incidents: **{q['incidents']}**\n\nThese are measured telemetry records, not an assertion that every external provider or Discord action is currently healthy.",ephemeral=True)
    if a in {'recommendations','next'}:
        rows=await manifest_refresh_recommendations(i.guild)
        if not rows:return await i.response.send_message("✅ Manifest has no open whole-server recommendations from the current scan.",ephemeral=True)
        if a=='next':rows=rows[:1]
        lines=[f"**{r['severity'].upper()} • {r['title']}**\n{r['details']}" for r in rows]
        return await i.response.send_message(("🧠 **Manifest Recommendations**\n\n"+"\n\n".join(lines))[:1900],ephemeral=True)
    brief=await manifest_server_brief(i.guild);h=brief['health'];m=brief['mode'];j=brief['journey'];g=brief['growth']
    if a=='inspect':
        return await i.response.send_message(f"🔎 **Server Inspect**\nHealth: **{h['health_score']}/100** • Mode: **{m['mode'].replace('_',' ').upper()}** • Journey: **{j['score']}/100**\nMembers: **{h['members']}** • Channels: **{h['channels']}** • Roles: **{h['roles']}**\nOpen tickets: **{brief['open_tickets']}** • Open incidents: **{brief['open_incidents']}** • Recommendations: **{len(brief['recommendations'])}**",ephemeral=True)
    if a=='evolution':
        notes=[]
        if h['configuration_gaps']:notes.append("Structure: "+", ".join(h['configuration_gaps']))
        notes.extend(g['notes']);notes.append(f"Member journey readiness is {j['score']}/100.")
        return await i.response.send_message(("🧬 **Server Evolution Review**\n"+"\n".join(f"• {x}" for x in notes))[:1900],ephemeral=True)
    if a=='explain':
        c=await manifest_server_constitution(i.guild_id);return await i.response.send_message(f"🗺️ **How Manifest understands this server**\nTemplate: **{c['template']}** • Complexity: **{c['complexity']}** • Autonomy: **{c['autonomy']}** • Risk policy: **{c['risk_policy']}**\nCurrent mode: **{m['mode']}**\nHealth: **{h['health_score']}/100** • Journey: **{j['score']}/100**\nManifest combines the saved constitution with live Discord structure and measured operational evidence; it does not treat guesses as owner decisions.",ephemeral=True)
    return await i.response.send_message(f"📋 **Unified Server Brief**\nHealth **{h['health_score']}/100** • Mode **{m['mode'].replace('_',' ').upper()}** • Journey **{j['score']}/100**\nOpen tickets **{brief['open_tickets']}** • Security incidents **{brief['open_incidents']}** • Recommendations **{len(brief['recommendations'])}**\n30d growth: **{g['joins']} joins / {g['leaves']} leaves / {g['net']:+d} net**",ephemeral=True)

