@server_group.command(name="constitution",description="View or save Manifest's durable server setup constitution")
@app_commands.choices(template=[app_commands.Choice(name=x.title(),value=x) for x in ("auto","community","gaming","study","creator","support","marketplace")])
@app_commands.choices(complexity=[app_commands.Choice(name=x.title(),value=x) for x in ("simple","balanced","advanced","maximum")])
@app_commands.choices(autonomy=[app_commands.Choice(name=x.title(),value=x) for x in ("assisted","community","full")])
@app_commands.choices(risk_policy=[app_commands.Choice(name=x.title(),value=x) for x in ("safe","managed")])
async def server_constitution(i:discord.Interaction,template:app_commands.Choice[str]|None=None,complexity:app_commands.Choice[str]|None=None,autonomy:app_commands.Choice[str]|None=None,risk_policy:app_commands.Choice[str]|None=None):
    if not i.guild:
        return await i.response.send_message("This setting is only available inside a server.",ephemeral=True)
    if i.user.id!=i.guild.owner_id and i.user.id not in OWNER_IDS:
        return await i.response.send_message("⚠️ Only the server owner or a global Manifest owner can change the Server Constitution.",ephemeral=True)
    current=await manifest_server_constitution(i.guild.id)
    changed=any(x is not None for x in (template,complexity,autonomy,risk_policy))
    if changed:
        current=await save_manifest_constitution(i.guild.id,i.user.id,
            template.value if template else current["template"],
            complexity.value if complexity else current["complexity"],
            autonomy.value if autonomy else current["autonomy"],
            risk_policy.value if risk_policy else current["risk_policy"])
        prefix="✅ **Server Constitution saved permanently.**"
    else:
        prefix="📜 **Server Constitution**"
    bp=await build_manifest_setup_blueprint(i.guild,current["template"],current["complexity"])
    gaps=bp.get("security_gaps") or []
    lines=[prefix,
        f"Template: **{current['template'].title()}**",
        f"Complexity: **{current['complexity'].title()}**",
        f"Autonomy: **{current['autonomy'].title()}**",
        f"Risk policy: **{current['risk_policy'].title()}**",
        f"Setup readiness: **{bp.get('readiness',0)}%**"]
    if gaps: lines += ["", "**Security gaps**"]+[f"• {x}" for x in gaps[:6]]
    lines += ["", "`/server setup` will use these saved preferences when you don't provide overrides."]
    await i.response.send_message("\n".join(lines)[:4000],ephemeral=True)

@server_group.command(name="setup",description="Build or apply a beginner-friendly Manifest server blueprint")
@app_commands.choices(template=[app_commands.Choice(name=x.title(),value=x) for x in ("auto","community","gaming","study","creator","support","marketplace")])
@app_commands.choices(complexity=[app_commands.Choice(name=x.title(),value=x) for x in ("simple","balanced","advanced","maximum")])
@app_commands.describe(apply="Apply the reviewed blueprint. False only previews it.")
async def server_setup(i:discord.Interaction,template:app_commands.Choice[str]|None=None,complexity:app_commands.Choice[str]|None=None,apply:bool=False):
    if not (i.guild and (i.user.id==i.guild.owner_id or i.user.id in OWNER_IDS or i.user.guild_permissions.administrator or i.user.guild_permissions.manage_guild)):
        return await i.response.send_message("Server-owner/authorized Manifest access is required.",ephemeral=True)
    constitution=await manifest_server_constitution(i.guild_id)
    bp=await build_manifest_setup_blueprint(i.guild,template.value if template else constitution["template"],complexity.value if complexity else constitution["complexity"])
    history_id=await save_setup_history(i.guild,i.user.id,bp,"planned")
    await persist_manifest_memory(i.guild_id,"last_setup_template",f"{bp['template']}:{bp['complexity']}","manifest")
    if not apply:
        actions="\n".join(f"• {a['kind']} **{a['name']}**"+(f" → {a['category']}" if a.get('category') else "") for a in bp['actions'][:18]) or "✅ Nothing new is required."
        preserved=bp.get('preserved_integrations') or []
        preserved_text=("\n\n**Existing systems preserved**\n"+"\n".join(f"• {x['system_key'].title()} — {x['provider_type'].replace('_',' ').title()} ({int(float(x.get('confidence') or 0)*100)}% confidence)" for x in preserved)) if preserved else ""
        return await i.response.send_message(f"🧭 **Manifest Setup Blueprint**\nTemplate: **{bp['template'].title()}** • Mode: **{bp['complexity'].title()}**\nReadiness: **{bp['readiness']}%**\n\n**Planned structure**\n{actions}{preserved_text}\n\nNothing has been changed. Re-run with `apply:true` only after reviewing this plan.",ephemeral=True)
    await i.response.defer(ephemeral=True)
    ok,msg,created,snapshot=await apply_manifest_setup_blueprint(i.guild,i.user,bp)
    await db.execute("UPDATE manifest_setup_history SET status=?,snapshot_id=?,applied_at=?,error=? WHERE id=? AND guild_id=?",("applied" if ok else "partial",int(snapshot or 0),time.time(),"" if ok else msg[:1000],history_id,i.guild_id))
    await persist_manifest_memory(i.guild_id,"last_setup_status","applied" if ok else "partial","manifest")
    await i.followup.send(("✅" if ok else "⚠️")+f" **Manifest Setup {'complete' if ok else 'partially applied'}**\n{msg}\n"+(("Created: "+", ".join(created[:12])+"\n") if created else "")+(f"Snapshot: **#{snapshot}**" if snapshot else ""),ephemeral=True)

