@automation_group.command(name="simulate",description="Dry-run a typed automation without executing its action")
async def automation_simulate(i:discord.Interaction,automation_id:int,sample_text:str=""):
    if not server_manager(i.user):return await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True)
    row=await db.one("SELECT * FROM automation_rules WHERE id=? AND guild_id=?",(automation_id,i.guild_id))
    if not row:return await i.response.send_message("That typed automation was not found.",ephemeral=True)
    try:cond=json.loads(row['conditions_json'] or '{}');payload=json.loads(row['payload_json'] or '{}')
    except Exception:return await i.response.send_message("That automation has invalid stored JSON and should be repaired.",ephemeral=True)
    matched=True;why=[];text=(sample_text or '').lower()
    if row['trigger_type']=='keyword':
        needle=str(cond.get('contains_content') or '').lower();matched=bool(needle and needle in text);why.append(f"keyword `{needle}` {'matched' if matched else 'did not match'} sample text")
    elif row['trigger_type']=='member_join':why.append("member_join would match only a real/simulated join event")
    else:why.append(f"trigger `{row['trigger_type']}` evaluated structurally")
    ok,validation=await validate_automation_rule(i.guild,i.user,row['trigger_type'],row['action_type'],payload,cond)
    e=discord.Embed(title=f"Automation simulation • #{automation_id}",color=discord.Color.blurple())
    e.add_field(name="Would trigger",value="Yes" if matched else "No");e.add_field(name="Configuration",value="Valid" if ok else f"Blocked: {validation}")
    e.add_field(name="Evidence",value="; ".join(why)[:1000],inline=False);e.add_field(name="Would execute",value=f"`{row['action_type']}` — simulation never executes actions.",inline=False)
    await i.response.send_message(embed=e,ephemeral=True)

@automation_group.command(name="doctor",description="Find broken or risky automation configurations")
async def automation_doctor(i:discord.Interaction):
    if not server_manager(i.user): return await i.response.send_message("Manage Server or Administrator is required.",ephemeral=True)
    rows=await db.all("SELECT id,name,trigger_type,conditions_json,action_type,enabled FROM automation_rules WHERE guild_id=? ORDER BY id",(i.guild_id,))
    problems=[]
    allowed_triggers=AUTOMATION_TRIGGERS; allowed_actions=AUTOMATION_ACTIONS
    for r in rows:
        if r['trigger_type'] not in allowed_triggers: problems.append(f"#{r['id']} uses unsupported trigger `{r['trigger_type']}`")
        if r['action_type'] not in allowed_actions: problems.append(f"#{r['id']} uses unsupported action `{r['action_type']}`")
        try: cond=json.loads(r['conditions_json'] or '{}')
        except Exception: cond={}; problems.append(f"#{r['id']} has invalid condition JSON")
        if r['trigger_type']=='keyword' and not any(str(k).lower() in {'contains_content','exact_content'} for k in cond): problems.append(f"#{r['id']} keyword trigger has no explicit content condition")
    legacy=await db.all("SELECT id,name,trigger,action,enabled FROM custom_automations WHERE guild_id=? ORDER BY id",(i.guild_id,))
    for r in legacy:
        if r['enabled'] and not (r['trigger'] or '').strip(): problems.append(f"legacy #{r['id']} is enabled with an empty trigger")
    if legacy: problems.append(f"{len(legacy)} legacy automation record(s) still exist; review/migrate them before public launch")
    await i.response.send_message("🧰 **Automation Doctor**\n" + ("\n".join("• "+x for x in problems) if problems else "✅ No obvious typed automation configuration problems found."),ephemeral=True)

