@community_group.command(name="poll",description="Create a simple community poll")
async def community_poll(i:discord.Interaction,question:str,options:str="Yes | No"):
    xs=[x.strip() for x in options.split('|') if x.strip()][:10]
    if len(xs)<2:return await i.response.send_message("Give at least 2 options separated by `|`.",ephemeral=True)
    nums=["1️⃣","2️⃣","3️⃣","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣","🔟"]
    e=discord.Embed(title="📊 Manifest Community Poll",description=question[:1000]+"\n\n"+"\n".join(f"{nums[n]} {x}" for n,x in enumerate(xs)),color=discord.Color.blurple())
    await i.response.send_message(embed=e); msg=await i.original_response()
    for n in range(len(xs)):
        try: await msg.add_reaction(nums[n])
        except discord.HTTPException: break

