async def pwarn(ctx,member:discord.Member,*,reason="No reason provided"):
    ok,why=hierarchy(ctx.author,member)
    if not ok:return await ctx.send(f"⚠️ {why}")
    case_id=await create_case(ctx.guild,member,ctx.author,"warn",reason);await db.execute("INSERT INTO warnings(guild_id,user_id,moderator_id,reason,created_at) VALUES(?,?,?,?,?)",(ctx.guild.id,member.id,ctx.author.id,reason,time.time()))
    row=await db.one("SELECT id FROM warnings WHERE guild_id=? AND user_id=? AND moderator_id=? ORDER BY id DESC LIMIT 1",(ctx.guild.id,member.id,ctx.author.id))
    if row:
        await action_receipt(ctx.guild,ctx.author,"moderation.warn","high",member,True,f"Warning recorded • warning #{row['id']} • case #{case_id}",verification_state="Manifest-verified",evidence_ref=f"warning:{row['id']}",reason=reason,source="prefix_command",request_id=f"message:{ctx.message.id}")
    await elog(ctx.guild,"mod","⚠️ Member Warned",f"Case #{case_id} • {reason}",ctx.author,member);await ctx.send(f"✅ Warned {member.mention} • case **#{case_id}**.")
@bot.command(name="clearwarns")
@commands.has_permissions(moderate_members=True)
async def pclearwarns(ctx,member:discord.Member):
    await db.execute("DELETE FROM warnings WHERE guild_id=? AND user_id=?",(ctx.guild.id,member.id))
    remaining=await db.one("SELECT COUNT(*) c FROM warnings WHERE guild_id=? AND user_id=?",(ctx.guild.id,member.id))
    verified=not remaining or int(remaining['c'] or 0)==0
    try:
        await action_receipt(ctx.guild,ctx.author,"moderation.clear_warnings","high",member,verified,
            "All stored warnings cleared and verified" if verified else "Warning rows remain after delete; result not verified",
            verification_state="Manifest-verified" if verified else "Unverified",evidence_ref=f"warnings-clear:{member.id}",
            reason="Explicit clearwarns command",source="prefix_command",request_id=f"message:{ctx.message.id}")
    except Exception:
        log.exception("clearwarns finished but its action journal write failed")
    if verified:return await ctx.send(f"✅ Cleared warnings for {member.mention}.")
    await ctx.send(f"⚠️ I attempted to clear warnings for {member.mention}, but the database still shows warning records. I won't report that as complete.")
