@bot.command(name="purge",aliases=["clear"])
@commands.has_permissions(manage_messages=True)
async def ppurge(ctx,amount:int):
    amount=max(1,min(amount,100))
    if not ctx.guild.me.guild_permissions.manage_messages:return await ctx.send("⚠️ Manifest needs **Manage Messages** here.")
    try:
        deleted=await ctx.channel.purge(limit=amount+1,reason=f"Manifest purge by {ctx.author} ({ctx.author.id})")
    except discord.Forbidden:
        return await ctx.send("⚠️ Discord denied the purge because Manifest lacks permission in this channel.")
    except discord.HTTPException as ex:
        return await ctx.send(f"⚠️ Discord could not complete the purge (`{getattr(ex,'status','error')}`).")
    # purge() returns the messages Discord confirmed as deleted. The command
    # message may be included, so report the confirmed count truthfully.
    count=len(deleted)
    try: await elog(ctx.guild,"mod","🧹 Purge",f"{count} messages confirmed deleted",ctx.author)
    except Exception: log.exception("Purge succeeded but moderation log failed")
    try:
        await action_receipt(ctx.guild,ctx.author,"moderation.purge","medium",ctx.channel,True,f"Discord confirmed {count} deleted messages",verification_state="Discord-returned",evidence_ref=f"purge:{ctx.channel.id}:{ctx.message.id}",reason=f"Requested purge amount {amount}",source="prefix_command",request_id=f"message:{ctx.message.id}")
    except Exception: log.exception("Purge succeeded but action journal failed")
    await ctx.send(f"✅ Discord confirmed **{count}** deleted message{'s' if count!=1 else ''}.",delete_after=5)
