@bot.command(name="nick")
@commands.has_permissions(manage_nicknames=True)
async def pnick(ctx,member:discord.Member,*,nickname:str):
    if not ctx.guild.me.guild_permissions.manage_nicknames:return await ctx.send("⚠️ Manifest needs **Manage Nicknames**.")
    ok,why=hierarchy(ctx.author,member)
    if not ok:return await ctx.send(f"⚠️ {why}")
    if member.id==ctx.guild.owner_id:return await ctx.send("⚠️ Discord does not allow changing the server owner's nickname this way.")
    if member.top_role>=ctx.guild.me.top_role:return await ctx.send("⚠️ That member is not below Manifest's highest role.")
    new_nick=nickname[:32]
    try: await member.edit(nick=new_nick,reason=f"Manifest nickname change by {ctx.author} ({ctx.author.id})")
    except discord.Forbidden:return await ctx.send("⚠️ Discord denied the nickname change because of permissions or role hierarchy.")
    except discord.HTTPException as ex:return await ctx.send(f"⚠️ Discord could not change the nickname (`{getattr(ex,'status','error')}`).")
    try: fresh=await ctx.guild.fetch_member(member.id)
    except discord.HTTPException:fresh=ctx.guild.get_member(member.id)
    verified=bool(fresh and fresh.nick==new_nick)
    try:
        await action_receipt(ctx.guild,ctx.author,"member.nickname","medium",member,verified,
            f"Nickname verified as {new_nick}" if verified else "Nickname could not be independently verified",
            verification_state="Manifest-verified" if verified else "Unverified",evidence_ref=f"nickname:{member.id}",reason="Explicit nick command",source="prefix_command",request_id=f"message:{ctx.message.id}")
    except Exception: log.exception("Nickname action finished but its journal write failed")
    await ctx.send("✅ Nickname updated and verified." if verified else "⚠️ Discord accepted the nickname change, but I couldn't independently verify it. Check the member before retrying.")
