@community_group.command(name="leaderboard",description="Show message activity leaderboard")
@app_commands.choices(period=[app_commands.Choice(name="daily",value="daily"),app_commands.Choice(name="weekly",value="weekly"),app_commands.Choice(name="monthly",value="monthly"),app_commands.Choice(name="all-time",value="all")])
async def community_leaderboard(i:discord.Interaction,period:app_commands.Choice[str]):
    if period.value=="daily":
        start=datetime.datetime.now(datetime.timezone.utc).date().isoformat()
        rows=await db.all("SELECT user_id,SUM(total) score FROM activity_buckets WHERE guild_id=? AND day>=? GROUP BY user_id ORDER BY score DESC LIMIT 10",(i.guild_id,start))
    elif period.value=="weekly":
        start=(datetime.datetime.now(datetime.timezone.utc)-datetime.timedelta(days=6)).date().isoformat()
        rows=await db.all("SELECT user_id,SUM(total) score FROM activity_buckets WHERE guild_id=? AND day>=? GROUP BY user_id ORDER BY score DESC LIMIT 10",(i.guild_id,start))
    elif period.value=="monthly":
        start=(datetime.datetime.now(datetime.timezone.utc)-datetime.timedelta(days=29)).date().isoformat()
        rows=await db.all("SELECT user_id,SUM(total) score FROM activity_buckets WHERE guild_id=? AND day>=? GROUP BY user_id ORDER BY score DESC LIMIT 10",(i.guild_id,start))
    else:
        rows=await db.all("SELECT user_id,total score FROM message_stats WHERE guild_id=? ORDER BY total DESC LIMIT 10",(i.guild_id,))
    lines=[]
    for n,r in enumerate(rows,1):
        member=i.guild.get_member(r["user_id"])
        lines.append(f"**{n}.** {member.mention if member else '`'+str(r['user_id'])+'`'} — **{r['score']:,}** messages")
    await i.response.send_message(f"🏆 **{period.name.title()} Leaderboard**\n"+("\n".join(lines) or "No activity recorded yet."))

async def find_giveaway_message(channel,giveaway_id:int,created_at:float,*,limit=100):
    """Find a giveaway's original public post using its stable embed footer marker."""
    marker=f"manifest-giveaway:{int(giveaway_id)}"
    scanned=0
    try:
        after=datetime.datetime.fromtimestamp(max(0,float(created_at or time.time())-60),datetime.timezone.utc)
        async for message in channel.history(limit=max(1,min(int(limit),100)),after=after):
            scanned+=1
            if bot.user and getattr(getattr(message,'author',None),'id',0)!=bot.user.id:
                continue
            if any(marker in str(getattr(getattr(embed,'footer',None),'text','') or '') for embed in getattr(message,'embeds',())):
                return message,scanned,True
        return None,scanned,scanned<max(1,min(int(limit),100))
    except Exception:
        log.exception("Could not recover the persistent giveaway post for #%s",giveaway_id)
        return None,scanned,False


class GiveawayEntryView(discord.ui.View):
    def __init__(self,giveaway_id:int):
        super().__init__(timeout=None); self.giveaway_id=int(giveaway_id)
        for child in self.children:
            if isinstance(child,discord.ui.Button): child.custom_id=f"manifest:v4:giveaway:enter:{self.giveaway_id}"
    @discord.ui.button(label="Enter giveaway",emoji="🎉",style=discord.ButtonStyle.success,custom_id="manifest:v4:giveaway:enter")
    async def enter(self,i:discord.Interaction,b:discord.ui.Button):
        if not await claim_interaction_once(i,f'giveaway-toggle:{self.giveaway_id}'):
            return await i.response.send_message("That giveaway interaction was already processed. Your entry state was not changed twice.",ephemeral=True)
        r=await db.one("SELECT * FROM giveaways WHERE id=?",(self.giveaway_id,))
        if not r or r["ended"] or r["ends_at"]<=time.time(): return await i.response.send_message("This giveaway has ended.",ephemeral=True)
        if i.user.bot:return await i.response.send_message("Bots can't enter giveaways.",ephemeral=True)
        req=i.guild.get_role(int(r["required_role_id"] or 0)); blocked=i.guild.get_role(int(r["blocked_role_id"] or 0))
        if req and req not in i.user.roles:return await i.response.send_message(f"You need {req.mention} to enter.",ephemeral=True)
        if blocked and blocked in i.user.roles:return await i.response.send_message("You're not eligible for this giveaway.",ephemeral=True)
        min_level=int(r["min_level"] or 0)
        if min_level:
            lv=await db.one("SELECT xp FROM levels WHERE guild_id=? AND user_id=?",(i.guild_id,i.user.id)); xp=int(lv["xp"] if lv else 0); level=int(math.sqrt(max(0,xp)/100))
            if level<min_level:return await i.response.send_message(f"You need Manifest level **{min_level}** to enter.",ephemeral=True)
        conn=await aiosqlite.connect(db.path,timeout=10)
        try:
            await conn.execute("PRAGMA busy_timeout=10000")
            await conn.execute("BEGIN IMMEDIATE")
            cur=await conn.execute("SELECT 1 FROM giveaway_entries WHERE giveaway_id=? AND user_id=?",(self.giveaway_id,i.user.id))
            old=await cur.fetchone(); await cur.close()
            if old:
                await conn.execute("DELETE FROM giveaway_entries WHERE giveaway_id=? AND user_id=?",(self.giveaway_id,i.user.id))
                entered=False
            else:
                await conn.execute("INSERT INTO giveaway_entries(giveaway_id,user_id,entered_at) VALUES(?,?,?)",(self.giveaway_id,i.user.id,time.time()))
                entered=True
            await conn.commit()
        except Exception:
            try: await conn.rollback()
            except Exception: pass
            raise
        finally:
            await conn.close()
        await i.response.send_message("🎉 You're entered." if entered else "You left the giveaway.",ephemeral=True)

async def giveaway_valid_pool(row,guild,*,exclude_ids=None):
    exclude_ids=set(exclude_ids or ())
    entries=await db.all("SELECT user_id FROM giveaway_entries WHERE giveaway_id=?",(row["id"],))
    req=guild.get_role(int(row["required_role_id"] or 0)); blocked=guild.get_role(int(row["blocked_role_id"] or 0)); min_level=int(row["min_level"] or 0)
    pool=[]
    for er in entries:
        u=guild.get_member(int(er["user_id"]))
        if not u or u.bot or u.id in exclude_ids: continue
        if req and req not in u.roles: continue
        if blocked and blocked in u.roles: continue
        if min_level:
            lv=await db.one("SELECT xp FROM levels WHERE guild_id=? AND user_id=?",(guild.id,u.id)); xp=int(lv["xp"] if lv else 0)
            if int(math.sqrt(max(0,xp)/100))<min_level: continue
        pool.append(u)
    return pool

_giveaway_finish_lock=asyncio.Lock()

async def _persist_giveaway_result_atomic(row,actor_id,event_type,old_winners,new_winners,deadline,content,now):
    """Atomically commit the winner state, event, and announcement outbox row."""
    conn=await aiosqlite.connect(db.path,timeout=10)
    try:
        pragma_cur=await conn.execute("PRAGMA busy_timeout=10000")
        await pragma_cur.close()
        await conn.execute("BEGIN IMMEDIATE")
        if event_type=="ended":
            cur=await conn.execute("UPDATE giveaways SET ended=1,status='ended',winners=?,claim_deadline=? WHERE id=? AND guild_id=? AND ended=0",
                                   (new_winners,deadline,int(row['id']),int(row['guild_id'])))
        else:
            cur=await conn.execute("UPDATE giveaways SET winners=?,claim_deadline=? WHERE id=? AND guild_id=? AND ended=1 AND winners=?",
                                   (new_winners,deadline,int(row['id']),int(row['guild_id']),str(old_winners or "")))
        changed=int(cur.rowcount or 0)==1
        await cur.close()
        if not changed:
            await conn.rollback()
            return None
        if event_type!="ended":
            await conn.execute("DELETE FROM giveaway_claims WHERE giveaway_id=?",(int(row['id']),))
        event_cur=await conn.execute(
            "INSERT INTO giveaway_events(giveaway_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",
            (int(row['id']),int(row['guild_id']),int(actor_id or 0),str(event_type),str(new_winners or ""),float(now))
        )
        event_id=int(event_cur.lastrowid or 0)
        await event_cur.close()
        event_key=f"giveaway:{int(row['id'])}:{event_type}:{event_id}"
        outbox=await conn.execute(
            "INSERT INTO giveaway_announcements(giveaway_id,guild_id,channel_id,event_key,event_type,content,status,created_at,next_attempt_at) VALUES(?,?,?,?,?,?,'pending',?,?)",
            (int(row['id']),int(row['guild_id']),int(row['channel_id']),event_key,str(event_type),str(content),float(now),float(now))
        )
        announcement_id=int(outbox.lastrowid or 0)
        await outbox.close()
        await conn.commit()
        return announcement_id
    except Exception:
        try: await conn.rollback()
        except Exception: pass
        raise
    finally:
        await conn.close()


async def finish_giveaway(row,channel,*,actor_id=0,event_type="ended",exclude_ids=None):
    """Select winners once and atomically persist state + idempotent announcement."""
    async with _giveaway_finish_lock:
        current=await db.one("SELECT * FROM giveaways WHERE id=? AND guild_id=?",(int(row["id"]),int(row["guild_id"])))
        if not current: return None
        if event_type=="ended" and int(current["ended"] or 0): return None
        if event_type!="ended" and not int(current["ended"] or 0): return None
        row=current
        pool=await giveaway_valid_pool(row,channel.guild,exclude_ids=exclude_ids)
        random.SystemRandom().shuffle(pool)
        wins=pool[:max(1,int(row["winner_count"] or 1))]
        ids=",".join(str(u.id) for u in wins); now=time.time()
        old_winners=str(row['winners'] or '')
        deadline=now+86400 if wins else 0
        winners_text=", ".join(u.mention for u in wins) if wins else "No valid entries"
        content=(f"🎉 **Giveaway #{row['id']} {('ended' if event_type=='ended' else 'rerolled')}!** Prize: **{row['prize']}**\n"
                 f"Winner(s): {winners_text}"+("\nWinners have **24 hours** to claim with `/community giveaway_claim`." if wins else ""))
        # State transition, event history and delivery outbox share one SQLite
        # transaction: a crash cannot leave an ended giveaway without its notice.
        announcement_id=await _persist_giveaway_result_atomic(row,actor_id,event_type,old_winners,ids,deadline,content,now)
        if not announcement_id: return None
        delivered=await deliver_giveaway_announcement(announcement_id)
        if delivered: return wins,"delivered"
        delivery_row=await db.one("SELECT status FROM giveaway_announcements WHERE id=?",(announcement_id,))
        state=str(delivery_row['status'] or 'unconfirmed') if delivery_row else 'unconfirmed'
        return wins,"queued" if state in {'pending','retry','sending'} else state

async def create_giveaway(guild,channel,host,prize,duration_seconds,winner_count=1,min_level=0,required_role=None,blocked_role=None):
    ends=time.time()+max(60,int(duration_seconds)); winners=max(1,min(int(winner_count),20))
    cur=await db.execute("INSERT INTO giveaways(guild_id,channel_id,host_id,prize,winner_count,ends_at,min_level,required_role_id,blocked_role_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)",
                         (guild.id,channel.id,host.id,prize[:200],winners,ends,max(0,int(min_level)),getattr(required_role,'id',0),getattr(blocked_role,'id',0),time.time()))
    gid=int(cur.lastrowid)
    req=[]
    if min_level:req.append(f"Level {min_level}+")
    if required_role:req.append(required_role.mention)
    if blocked_role:req.append(f"Not {blocked_role.mention}")
    e=discord.Embed(title="🎉 Giveaway",description=f"**Prize:** {prize[:1000]}\n**Winners:** {winners}\n**Ends:** {discord.utils.format_dt(datetime.datetime.fromtimestamp(ends,datetime.timezone.utc),'R')}"+(f"\n**Requirements:** {' • '.join(req)}" if req else "")+"\n\nUse the button below to enter.",color=discord.Color.gold())
    e.set_footer(text=f"Giveaway #{gid} • Hosted by {host.display_name} • manifest-giveaway:{gid}")
    try:
        msg=await channel.send(embed=e,view=GiveawayEntryView(gid),allowed_mentions=discord.AllowedMentions.none())
    except Exception as ex:
        # An API timeout may occur after Discord accepted the post; locate it by
        # marker before declaring failure or leaving an active orphan in SQLite.
        found,_,complete=await find_giveaway_message(channel,gid,time.time())
        if found:
            msg=found
        else:
            cleanup_confirmed=False
            try:
                await db.execute("UPDATE giveaways SET ended=1,status='failed' WHERE id=? AND ended=0",(gid,))
                failed_row=await db.one("SELECT ended,status FROM giveaways WHERE id=?",(gid,))
                cleanup_confirmed=bool(failed_row and int(failed_row['ended'] or 0)==1 and failed_row['status']=='failed')
            except Exception: log.exception("Giveaway %s failed to create and cleanup metadata could not be persisted",gid)
            try:
                await db.execute("INSERT INTO giveaway_events(giveaway_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(gid,guild.id,host.id,'creation_failed',f'{type(ex).__name__}: {_safe_diag_text(ex,250)}',time.time()))
            except Exception: log.exception("Giveaway %s creation failure event could not be saved",gid)
            if cleanup_confirmed:
                detail=f"Discord did not confirm the giveaway post ({type(ex).__name__}); the giveaway is marked failed and no active giveaway remains."
            else:
                detail=f"Discord did not confirm the giveaway post ({type(ex).__name__}); cleanup state could not be verified. Check Giveaway Status before retrying."
            if not complete: detail+=" Channel history also could not be fully inspected to rule out a partial send."
            return gid,None,detail
    warning=""
    try:
        await db.execute("UPDATE giveaways SET message_id=? WHERE id=?",(msg.id,gid))
    except Exception:
        warning=" The giveaway post was sent, but its message ID could not be saved; Manifest will try to recover the persistent button after restart."
        log.exception("Giveaway %s public post sent but message ID receipt failed",gid)
    try:
        await db.execute("INSERT INTO giveaway_events(giveaway_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(gid,guild.id,host.id,"created",prize[:300],time.time()))
    except Exception: log.exception("Giveaway %s created but event journaling failed",gid)
    return gid,msg,warning

@community_group.command(name="giveaway",description="Start a reaction-based giveaway")
async def community_giveaway(i:discord.Interaction,prize:str,duration_minutes:app_commands.Range[int,1,10080],winner_count:app_commands.Range[int,1,20]=1):
    if not can_manage(i): return await i.response.send_message("Manage Server required.",ephemeral=True)
    await i.response.defer(ephemeral=True)
    gid,msg,warning=await create_giveaway(i.guild,i.channel,i.user,prize,duration_minutes*60,winner_count)
    if not msg:return await i.followup.send(f"❌ Giveaway #{gid} was not created. {warning} No active giveaway remains.",ephemeral=True)
    await i.followup.send(f"Giveaway #{gid} created: {msg.jump_url}{warning}",ephemeral=True)

@community_group.command(name="giveaway_status",description="Show a Manifest giveaway's state and entry count")
async def community_giveaway_status(i:discord.Interaction,giveaway_id:int):
    row=await db.one("SELECT * FROM giveaways WHERE id=? AND guild_id=?",(giveaway_id,i.guild_id))
    if not row:return await i.response.send_message("Giveaway not found.",ephemeral=True)
    count=await db.one("SELECT COUNT(*) n FROM giveaway_entries WHERE giveaway_id=?",(giveaway_id,)); claimed=await db.one("SELECT COUNT(*) n FROM giveaway_claims WHERE giveaway_id=?",(giveaway_id,))
    announcement=await db.one("SELECT status,last_error FROM giveaway_announcements WHERE giveaway_id=? ORDER BY id DESC LIMIT 1",(giveaway_id,))
    winners=[f"<@{x}>" for x in str(row["winners"] or "").split(",") if x]
    delivery=f"\nAnnouncement: **{announcement['status']}**"+(f" — {str(announcement['last_error'] or '')[:180]}" if announcement and announcement['last_error'] else "") if announcement else "\nAnnouncement: **not queued**"
    await i.response.send_message(f"🎉 **Giveaway #{giveaway_id}** • {row['status']}\nPrize: **{row['prize']}**\nEntries: **{count['n']}** • Winners: {', '.join(winners) or 'Not selected'} • Claims: **{claimed['n']}**"+delivery,ephemeral=True,allowed_mentions=discord.AllowedMentions.none())

@community_group.command(name="giveaway_end",description="End a giveaway now and select eligible winners")
async def community_giveaway_end(i:discord.Interaction,giveaway_id:int):
    if not can_manage(i):return await i.response.send_message("Manage Server required.",ephemeral=True)
    row=await db.one("SELECT * FROM giveaways WHERE id=? AND guild_id=?",(giveaway_id,i.guild_id))
    if not row or int(row["ended"]):return await i.response.send_message("That giveaway isn't active.",ephemeral=True)
    ch=i.guild.get_channel(int(row["channel_id"]));
    if not ch:return await i.response.send_message("The giveaway channel no longer exists.",ephemeral=True)
    await i.response.defer(ephemeral=True); result=await finish_giveaway(row,ch,actor_id=i.user.id,event_type="ended")
    if result is None:return await i.followup.send("That giveaway was already ended by another worker. No duplicate result was created.",ephemeral=True)
    wins,announced=result
    delivery_note=("The winner announcement was delivered." if announced=="delivered" else "The winner result is saved and its public announcement is queued for retry." if announced=="queued" else f"The winner result is saved, but announcement delivery is **{announced}**. Check Giveaway Status and arrange manual publication if needed.")
    await i.followup.send(f"Ended giveaway #{giveaway_id}; selected **{len(wins)}** valid winner(s). {delivery_note}",ephemeral=True)

@community_group.command(name="giveaway_reroll",description="Reroll an ended giveaway without selecting the previous winners")
async def community_giveaway_reroll(i:discord.Interaction,giveaway_id:int):
    if not can_manage(i):return await i.response.send_message("Manage Server required.",ephemeral=True)
    row=await db.one("SELECT * FROM giveaways WHERE id=? AND guild_id=?",(giveaway_id,i.guild_id))
    if not row or not int(row["ended"]):return await i.response.send_message("Only an ended giveaway can be rerolled.",ephemeral=True)
    ch=i.guild.get_channel(int(row["channel_id"]));
    if not ch:return await i.response.send_message("The giveaway channel no longer exists.",ephemeral=True)
    previous={int(x) for x in str(row["winners"] or "").split(",") if x.isdigit()}
    await i.response.defer(ephemeral=True); result=await finish_giveaway(row,ch,actor_id=i.user.id,event_type="rerolled",exclude_ids=previous)
    if result is None:return await i.followup.send("The giveaway was changed by another worker. Refresh its status before trying again.",ephemeral=True)
    wins,announced=result
    delivery_note=("The reroll announcement was delivered." if announced=="delivered" else "The new winner result is saved and its public announcement is queued for retry." if announced=="queued" else f"The new winner result is saved, but announcement delivery is **{announced}**. Check Giveaway Status and arrange manual publication if needed.")
    await i.followup.send(f"Rerolled giveaway #{giveaway_id}; selected **{len(wins)}** new valid winner(s). {delivery_note}",ephemeral=True)

@community_group.command(name="giveaway_claim",description="Claim a giveaway you won")
async def community_giveaway_claim(i:discord.Interaction,giveaway_id:int):
    row=await db.one("SELECT * FROM giveaways WHERE id=? AND guild_id=?",(giveaway_id,i.guild_id))
    if not row or not int(row["ended"]):return await i.response.send_message("That giveaway hasn't ended.",ephemeral=True)
    winners={int(x) for x in str(row["winners"] or "").split(",") if x.isdigit()}
    if i.user.id not in winners:return await i.response.send_message("You aren't a current winner of that giveaway.",ephemeral=True)
    if float(row["claim_deadline"] or 0) and time.time()>float(row["claim_deadline"]):return await i.response.send_message("That claim window has expired. Staff can reroll the giveaway.",ephemeral=True)
    cur=await db.execute("INSERT OR IGNORE INTO giveaway_claims(giveaway_id,user_id,claimed_at) VALUES(?,?,?)",(giveaway_id,i.user.id,time.time()))
    inserted=int(getattr(cur,"rowcount",0) or 0)==1
    try: await cur.close()
    except Exception: pass
    if not inserted:
        return await i.response.send_message("✅ Your claim is already recorded. The giveaway host/staff can handle prize delivery.",ephemeral=True)
    await db.execute("INSERT INTO giveaway_events(giveaway_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(giveaway_id,i.guild_id,i.user.id,"claimed",str(i.user.id),time.time()))
    await i.response.send_message("✅ Claim recorded. The giveaway host/staff can now handle prize delivery.",ephemeral=True)

def _role_panel_safe(role:discord.Role,guild:discord.Guild):
    me=guild.me
    if role.is_default() or role.managed or not me or me.top_role<=role:return False,"Manifest can only self-assign ordinary roles below its highest role."
    p=role.permissions
    dangerous=(p.administrator or p.manage_guild or p.manage_roles or p.manage_channels or p.ban_members or p.kick_members or p.moderate_members or p.manage_webhooks)
    if dangerous:return False,"Privileged moderation/management roles cannot be placed in a self-role panel."
    return True,"ok"

async def role_panel_embed(panel_id:int):
    p=await db.one("SELECT * FROM role_panels WHERE id=?",(panel_id,));opts=await db.all("SELECT * FROM role_panel_options WHERE panel_id=? ORDER BY position,label",(panel_id,))
    if not p:return None
    e=manifest_ui_embed(str(p['title'])[:256],str(p['description'] or 'Choose the roles you want to toggle below.')[:4000])
    if opts:e.add_field(name="Available roles",value="\n".join(f"• {str(o['emoji'] or '')} <@&{o['role_id']}> — {str(o['description'] or '')[:100]}" for o in opts)[:1024],inline=False)
    else:e.add_field(name="Available roles",value="No roles have been added yet.",inline=False)
    e.set_footer(text="Manifest verifies role safety and hierarchy again when you select a role.")
    return e

class RolePanelSelect(discord.ui.Select):
    def __init__(self,panel_id:int,options):
        self.panel_id=panel_id
        built=[]
        for o in options[:25]:
            kwargs={"label":str(o['label'])[:100],"value":str(o['role_id']),"description":str(o['description'] or '')[:100] or None}
            emoji=str(o['emoji'] or '').strip()
            if emoji:kwargs['emoji']=emoji
            built.append(discord.SelectOption(**kwargs))
        max_values=max(1,min(len(built),10)) if built else 1
        super().__init__(placeholder="Select role(s) to toggle…",min_values=1,max_values=max_values,options=built or [discord.SelectOption(label="No roles configured",value="none")],custom_id=f"manifest:rolepanel:{panel_id}")
        if not built:self.disabled=True
    async def callback(self,i):
        if not i.guild:return await i.response.send_message("Role panels work inside servers.",ephemeral=True)
        panel=await db.one("SELECT * FROM role_panels WHERE id=? AND guild_id=? AND enabled=1",(self.panel_id,i.guild_id))
        if not panel:return await i.response.send_message("This role panel is no longer active.",ephemeral=True)
        added=[];removed=[];skipped=[]
        fresh=await i.guild.fetch_member(i.user.id)
        current={r.id for r in fresh.roles}
        for raw in self.values:
            if not raw.isdigit():continue
            role=i.guild.get_role(int(raw))
            if not role:skipped.append("deleted role");continue
            ok,why=_role_panel_safe(role,i.guild)
            if not ok:skipped.append(role.name);continue
            try:
                if role.id in current:await fresh.remove_roles(role,reason="Manifest self-role panel");removed.append(role.name);current.discard(role.id)
                else:await fresh.add_roles(role,reason="Manifest self-role panel");added.append(role.name);current.add(role.id)
            except discord.HTTPException:skipped.append(role.name)
        parts=[]
        if added:parts.append("Added: **"+", ".join(added)+"**")
        if removed:parts.append("Removed: **"+", ".join(removed)+"**")
        if skipped:parts.append("Skipped: **"+", ".join(skipped)+"**")
        await i.response.send_message("✅ "+(" · ".join(parts) if parts else "No role changes were needed."),ephemeral=True)

class RolePanelView(discord.ui.View):
    def __init__(self,panel_id:int):
        super().__init__(timeout=None);self.panel_id=panel_id
        # Persistent registration occurs before interaction time, so load options
        # synchronously from the encoded snapshot supplied by refresh() later.
    async def refresh(self):
        self.clear_items();opts=await db.all("SELECT * FROM role_panel_options WHERE panel_id=? ORDER BY position,label",(self.panel_id,));self.add_item(RolePanelSelect(self.panel_id,opts));return self

async def build_role_panel_view(panel_id:int):
    v=RolePanelView(panel_id);return await v.refresh()

async def event_embed(event_id:int):
    r=await db.one("SELECT * FROM events WHERE id=?",(event_id,))
    if not r:return None
    counts={x['status']:int(x['n']) for x in await db.all("SELECT status,COUNT(*) n FROM event_rsvps WHERE event_id=? GROUP BY status",(event_id,))}
    starts=datetime.datetime.fromtimestamp(float(r['starts_at']),datetime.timezone.utc)
    e=manifest_ui_embed(f"📅 {str(r['title'])[:240]}",str(r['description'] or 'No description provided.')[:3500],status="good" if r['status']=='scheduled' else "warn")
    e.add_field(name="Starts",value=discord.utils.format_dt(starts,'F')+"\n"+discord.utils.format_dt(starts,'R'),inline=False)
    e.add_field(name="RSVP",value=f"✅ Going **{counts.get('going',0)}** · 🤔 Maybe **{counts.get('maybe',0)}** · ❌ Can't **{counts.get('cant',0)}**",inline=False)
    e.add_field(name="Reminder",value=f"Opt-in · **{int(r['reminder_default_minutes'] or 60)} min before**",inline=True)
    e.set_footer(text=f"Manifest Event #{event_id} · {str(r['status']).title()}")
    return e

class EventRSVPButton(discord.ui.Button):
    def __init__(self,event_id:int,status:str,label:str,emoji:str,style):
        super().__init__(label=label,emoji=emoji,style=style,custom_id=f"manifest:event:{event_id}:{status}");self.status=status
    async def callback(self,i):await self.view.set_status(i,self.status)

class EventReminderButton(discord.ui.Button):
    def __init__(self,event_id:int):
        super().__init__(label="Remind me",emoji="⏰",style=discord.ButtonStyle.primary,custom_id=f"manifest:event:{event_id}:remind")
    async def callback(self,i):
        r=await db.one("SELECT status,reminder_default_minutes FROM events WHERE id=? AND guild_id=?",(self.view.event_id,i.guild_id))
        if not r or r['status']!='scheduled':return await i.response.send_message("This event is no longer accepting reminders.",ephemeral=True)
        existing=await db.one("SELECT remind_minutes FROM event_rsvps WHERE event_id=? AND user_id=?",(self.view.event_id,i.user.id))
        current=int(existing['remind_minutes'] or 0) if existing else 0
        default_minutes=max(5,min(int(r['reminder_default_minutes'] or 60),1440))
        new=0 if current else default_minutes
        if existing:
            await db.execute("UPDATE event_rsvps SET remind_minutes=?,reminder_sent_at=0,updated_at=? WHERE event_id=? AND user_id=?",(new,time.time(),self.view.event_id,i.user.id))
        else:
            await db.execute("INSERT INTO event_rsvps(event_id,user_id,status,updated_at,remind_minutes,reminder_sent_at) VALUES(?,?,'maybe',?,?,0)",(self.view.event_id,i.user.id,time.time(),new))
        timing=(f"**{new} minutes before**" if new<60 else f"about **{new//60} hour{'s' if new//60!=1 else ''} before**" if new%60==0 else f"**{new} minutes before**")
        await i.response.send_message(f"⏰ Reminder enabled for {timing}." if new else "🔕 Event reminder disabled.",ephemeral=True)

class EventRSVPView(discord.ui.View):
    def __init__(self,event_id:int):
        super().__init__(timeout=None);self.event_id=event_id
        self.add_item(EventRSVPButton(event_id,"going","Going","✅",discord.ButtonStyle.success))
        self.add_item(EventRSVPButton(event_id,"maybe","Maybe","🤔",discord.ButtonStyle.secondary))
        self.add_item(EventRSVPButton(event_id,"cant","Can't go","❌",discord.ButtonStyle.secondary))
        self.add_item(EventReminderButton(event_id))
    async def set_status(self,i,status):
        r=await db.one("SELECT status FROM events WHERE id=? AND guild_id=?",(self.event_id,i.guild_id))
        if not r or r['status']!='scheduled':return await i.response.send_message("This event is no longer accepting RSVPs.",ephemeral=True)
        await db.execute("INSERT INTO event_rsvps(event_id,user_id,status,updated_at) VALUES(?,?,?,?) ON CONFLICT(event_id,user_id) DO UPDATE SET status=excluded.status,updated_at=excluded.updated_at",(self.event_id,i.user.id,status,time.time()))
        e=await event_embed(self.event_id)
        await i.response.edit_message(embed=e,view=self)
        await i.followup.send(f"RSVP saved as **{'Can’t go' if status=='cant' else status.title()}**.",ephemeral=True)


async def event_reminder_tick(now=None):
    now=float(now or time.time())
    rows=await db.all("SELECT e.id,e.guild_id,e.channel_id,e.title,e.starts_at,r.user_id,r.remind_minutes FROM events e JOIN event_rsvps r ON r.event_id=e.id WHERE e.status='scheduled' AND r.status IN ('going','maybe') AND r.remind_minutes>0 AND COALESCE(r.reminder_sent_at,0)=0 AND e.starts_at>? AND e.starts_at-(r.remind_minutes*60)<=? ORDER BY e.starts_at LIMIT 100",(now-300,now))
    for r in rows:
        user=bot.get_user(int(r['user_id']))
        if not user:
            try:user=await bot.fetch_user(int(r['user_id']))
            except Exception:continue
        starts=datetime.datetime.fromtimestamp(float(r['starts_at']),datetime.timezone.utc)
        try:
            await user.send(f"⏰ **Manifest Event Reminder**\n**{str(r['title'])[:180]}** starts {discord.utils.format_dt(starts,'R')}.")
            await db.execute("UPDATE event_rsvps SET reminder_sent_at=? WHERE event_id=? AND user_id=? AND reminder_sent_at=0",(time.time(),int(r['id']),int(r['user_id'])))
        except (discord.Forbidden,discord.HTTPException):
            # DM delivery is optional; never alter an RSVP because DMs are closed.
            continue

