# ========================= V27 PROFESSIONAL CORE =========================

# One predictable path for higher-level conversational operations:
# inspect -> authorize -> assess risk -> execute/preview -> verify -> receipt.
RISK_LEVELS={"read":0,"low":1,"medium":2,"high":3,"destructive":4}

async def action_receipt(guild,user,action,risk,target,verified,details,*,verification_state=None,evidence_ref="",reason="",source="",request_id=""):
    state=verification_state or ("Manifest-verified" if verified else "Unverified")
    await db.execute("INSERT INTO action_receipts(guild_id,user_id,action,risk,target,verified,details,created_at,verification_state,evidence_ref,reason,source,request_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",(guild.id,user.id,action,risk,str(target)[:250],int(bool(verified)),str(details)[:1500],time.time(),str(state)[:40],str(evidence_ref)[:250],str(reason)[:500],str(source)[:40],str(request_id)[:80]))
    await audit_ai_action(guild,user,action,bool(verified),str(details)[:1500])

async def permission_plan(guild, actor, capability):
    req={
        "channels":("manage_channels","Manage Channels"),"roles":("manage_roles","Manage Roles"),
        "moderation":("moderate_members","Moderate Members"),"ban":("ban_members","Ban Members"),
        "kick":("kick_members","Kick Members"),"messages":("manage_messages","Manage Messages"),
        "webhooks":("manage_webhooks","Manage Webhooks"),"audit":("view_audit_log","View Audit Log")}
    key,label=req.get(capability,(None,None))
    if not key:return True,"No special permission required."
    if not manager(actor) and capability in {"channels","roles","webhooks","audit"}:return False,"You need Manage Server for that operation."
    if capability in {"moderation","ban","kick","messages"} and not (moderator(actor) or manager(actor)):return False,f"You need {label}."
    me=guild.me
    if not me or not getattr(me.guild_permissions,key,False):return False,f"Manifest needs **{label}**."
    return True,f"{label} available."

async def server_pulse_report(guild):
    h=await server_health_report(guild); sec=await get_security(guild.id); me=guild.me
    perms=me.guild_permissions if me else None
    recent=await db.one("SELECT COUNT(*) n FROM security_events WHERE guild_id=? AND created_at>?",(guild.id,time.time()-86400))
    open_t=await db.one("SELECT COUNT(*) n FROM tickets WHERE guild_id=? AND status='open'",(guild.id,))
    security=max(0,100-(0 if sec['anti_raid'] else 25)-(0 if sec['anti_nuke'] else 25)-(0 if sec['auto_lockdown'] else 15)-min(35,(recent['n'] if recent else 0)*5))
    config=max(0,100-len(h.get('gaps',[]))*12)
    moderation=100 if perms and perms.moderate_members else 60
    support=100 if any(x in {c.name.lower() for c in guild.text_channels} for x in ('support','help','tickets','ticket')) else 65
    overall=round((security+config+moderation+support)/4)
    return {"overall":overall,"security":security,"configuration":config,"moderation":moderation,"support":support,"events":recent['n'] if recent else 0,"tickets":open_t['n'] if open_t else 0,"gaps":h.get('gaps',[])}

async def server_pulse_text(guild):
    p=await server_pulse_report(guild)
    gaps=', '.join(p['gaps'][:5]) if p['gaps'] else 'No obvious structural gaps.'
    return (f"💓 **Server Pulse — {p['overall']}/100**\n"
            f"🛡️ Security **{p['security']}** · 🔧 Configuration **{p['configuration']}** · "
            f"🔨 Moderation **{p['moderation']}** · 🎫 Support **{p['support']}**\n"
            f"Last 24h: **{p['events']}** security event(s) · **{p['tickets']}** open ticket(s)\n"
            f"**Top check:** {gaps}")

async def clean_server_preview(guild):
    dup=[]; seen={}
    for c in guild.channels:
        k=(type(c).__name__,c.name.lower())
        if k in seen:dup.append(c)
        else:seen[k]=c
    empty_roles=[r for r in guild.roles if not r.is_default() and not r.managed and len(r.members)==0]
    empty_cats=[c for c in guild.categories if not c.channels]
    return dup,empty_roles,empty_cats

async def clean_server_text(guild):
    dup,roles,cats=await clean_server_preview(guild)
    def names(xs):return ', '.join(f'`{x.name}`' for x in xs[:12]) or 'None'
    return ("🧹 **Clean Server — preview only**\n"
            f"Possible duplicate channels: {names(dup)}\n"
            f"Empty non-managed roles: {names(roles)}\n"
            f"Empty categories: {names(cats)}\n\n"
            "Nothing was deleted. Destructive cleanup always needs an explicit target + confirmation.")

async def incident_timeline_text(guild):
    rows=await db.all("SELECT event_type,actor_id,target_id,created_at,details FROM security_events WHERE guild_id=? ORDER BY id DESC LIMIT 12",(guild.id,))
    if not rows:return "🛡️ **Incident Timeline**\nNo recorded security events yet."
    out=[]
    for r in rows:
        ts=discord.utils.format_dt(datetime.datetime.fromtimestamp(r['created_at'],datetime.timezone.utc),'R')
        who=f"<@{r['actor_id']}>" if r['actor_id'] else "unknown actor"
        out.append(f"• {ts} · **{r['event_type'].replace('_',' ').title()}** · {who} · {r['details'][:160]}")
    return fit_discord("🛡️ **Incident Timeline**\n"+'\n'.join(out),1900)

async def start_watch_mode(message,hours=24):
    hours=max(1,min(int(hours),168)); end=time.time()+hours*3600
    await db.execute("INSERT INTO watch_sessions(guild_id,started_by,started_at,ends_at,channel_id,summary) VALUES(?,?,?,?,?,?) ON CONFLICT(guild_id) DO UPDATE SET started_by=excluded.started_by,started_at=excluded.started_at,ends_at=excluded.ends_at,channel_id=excluded.channel_id,summary=''",
                     (message.guild.id,message.author.id,time.time(),end,message.channel.id,''))
    return f"👁️ **Watch Mode active for {hours} hour(s).** I’ll use Manifest’s existing security/event monitoring and keep the session tied to {message.channel.mention}."

async def watch_status_text(guild):
    r=await db.one("SELECT * FROM watch_sessions WHERE guild_id=?",(guild.id,))
    if not r or r['ends_at']<=time.time():return "👁️ Watch Mode is **OFF**."
    end=discord.utils.format_dt(datetime.datetime.fromtimestamp(r['ends_at'],datetime.timezone.utc),'R')
    return f"👁️ Watch Mode is **ON** until {end}."

async def server_vibe_text(guild):
    rows=await db.all("SELECT user_id,total FROM message_stats WHERE guild_id=? ORDER BY total DESC LIMIT 5",(guild.id,))
    total=sum(r['total'] for r in rows); channels=len(guild.text_channels); members=guild.member_count or 0
    if total>3000:vibe="very active and conversation-heavy"
    elif total>500:vibe="active with a solid regular community"
    else:vibe="compact and still building momentum"
    return f"✨ **{guild.name} vibe:** {vibe}. I can see **{members} members** and **{channels} text channels** in the live server state."

async def impress_manifest(message):
    pulse=await server_pulse_text(message.guild); cfg=await get_security(message.guild.id); me=message.guild.me
    abilities=[]
    if me.guild_permissions.manage_channels:abilities.append("build/organize channels")
    if me.guild_permissions.manage_roles:abilities.append("manage roles")
    if me.guild_permissions.moderate_members:abilities.append("moderate members")
    if me.guild_permissions.view_audit_log:abilities.append("inspect audit/security activity")
    abilities += ["diagnose the server","run Server Pulse","preview cleanup","manage tickets","use natural-language actions"]
    return fit_discord(pulse+f"\n\n🧠 **Manifest V{VERSION}**\nI can currently: "+', '.join(abilities)+f".\nShield: anti-raid **{'ON' if cfg['anti_raid'] else 'OFF'}**, anti-nuke **{'ON' if cfg['anti_nuke'] else 'OFF'}**.\n\n**{MANIFEST_SLOGAN}**",1900)

