async def read_only_server_intelligence(message):
    """Narrow compatibility fallback. It must never mutate Discord authority/state."""
    low=clean_mention(message.content).strip().lower()
    if re.search(r"\b(?:check|show|tell me)\b.*\b(?:health|server health)\b",low):
        await manifest_reply(message,"🧠 "+await server_health_text(message.guild)); return True
    if re.search(r"\b(?:scan|map|analyze|inspect|read)\b.*\b(?:server|community)\b|\bserver profile\b",low):
        await scan_server_profile(message.guild,deep=manager(message.author))
        await manifest_reply(message,fit_discord("🧠 **Server Map**\n"+await server_profile_text(message.guild),1900)); return True
    if re.search(r"\b(?:what|check|tell me)\b.*\b(?:server needs|need to improve|needs improvement|server check)\b|\bserver needs\b|\bcheck (?:this )?server\b",low):
        await update_server_needs(message.guild)
        r=await db.one("SELECT summary,recommendations FROM server_needs WHERE guild_id=?",(message.guild.id,))
        await manifest_reply(message,fit_discord(f"🧠 **Server Check**\n{r['summary'] if r else 'Unavailable.'}\n\n{r['recommendations'] if r else 'No recommendations.'}",1900)); return True
    if re.search(r"\b(?:server snapshot|configuration snapshot|blueprint)\b",low):
        # A snapshot request in compatibility mode is intentionally observational:
        # do not persist a new snapshot merely because the AI resolver failed.
        await manifest_reply(message,fit_discord("🧩 "+await server_health_text(message.guild),1900)); return True
    if re.search(r"\bserver changes\b|\bwhat changed\b",low):
        await manifest_reply(message,fit_discord(await compare_latest_snapshot(message.guild),1900)); return True
    return False




# ========================= SERVER INTELLIGENCE / REPAIR / AUTOMATION CORE =========================
SYSTEM_STATES={"not_configured","configuring","operational","degraded","repairing"}

async def record_system_health(guild_id, system_key, state, details="", object_id=0, repairable=False):
    if state not in SYSTEM_STATES: state="degraded"
    await db.execute("""INSERT INTO system_health(guild_id,system_key,state,details,object_id,checked_at,repairable)
        VALUES(?,?,?,?,?,?,?) ON CONFLICT(guild_id,system_key) DO UPDATE SET state=excluded.state,details=excluded.details,
        object_id=excluded.object_id,checked_at=excluded.checked_at,repairable=excluded.repairable""",
        (guild_id,system_key,state,details[:1200],int(object_id or 0),time.time(),int(bool(repairable))))

async def server_system_health(guild):
    """Live dependency health. Missing owner-configured objects become degraded; Manifest never silently recreates them."""
    gs=await db.one("SELECT * FROM guild_settings WHERE guild_id=?",(guild.id,))
    vc=await db.one("SELECT * FROM verification_config WHERE guild_id=?",(guild.id,))
    checks=[]
    def channel_check(key,cid,configured=True):
        if not configured or not cid:return (key,"not_configured","Not configured",0,False)
        ch=guild.get_channel(int(cid))
        if not ch:return (key,"degraded","Configured channel no longer exists",int(cid),True)
        return (key,"operational",f"#{getattr(ch,'name','channel')} is available",int(cid),False)
    if gs:
        checks += [
            channel_check("tickets",gs['ticket_category_id'],bool(gs['ticket_category_id'])),
            channel_check("mod_logs",gs['log_mod_id'],bool(gs['log_mod_id'])),
            channel_check("security_logs",gs['log_security_id'],bool(gs['log_security_id'])),
            channel_check("message_logs",gs['log_message_id'],bool(gs['log_message_id'])),
            channel_check("ticket_logs",gs['log_ticket_id'],bool(gs['log_ticket_id'])),
            channel_check("welcome",gs['welcome_channel_id'],bool(gs['welcome_channel_id'])),
        ]
        if gs['support_role_id']:
            role=guild.get_role(int(gs['support_role_id']))
            checks.append(("support_role","operational" if role else "degraded",f"@{role.name} is available" if role else "Configured support role no longer exists",int(gs['support_role_id']),not bool(role)))
        else: checks.append(("support_role","not_configured","Not configured",0,False))
    if vc and vc['enabled']:
        ch=guild.get_channel(int(vc['channel_id'])) if vc['channel_id'] else None; role=guild.get_role(int(vc['role_id'])) if vc['role_id'] else None
        ok=bool(ch and role); details="Verification dependencies available" if ok else "Verification is enabled but its channel or role is missing"
        checks.append(("verification","operational" if ok else "degraded",details,int(vc['channel_id'] or 0),not ok))
    else: checks.append(("verification","not_configured","Not configured",0,False))
    for x in checks: await record_system_health(guild.id,*x)
    return checks

async def save_config_change(guild_id,actor_id,capability,target_type="",target_id=0,before=None,after=None,inverse=None):
    cur=await db.execute("""INSERT INTO config_history(guild_id,actor_id,capability,target_type,target_id,before_json,after_json,inverse_json,status,created_at)
        VALUES(?,?,?,?,?,?,?,?,?,?)""",(guild_id,actor_id,capability,target_type,int(target_id or 0),json.dumps(before or {},default=str),json.dumps(after or {},default=str),json.dumps(inverse or {},default=str),'committed',time.time()))
    return cur.lastrowid

async def undo_manifest_change(guild,actor,change_id):
    row=await db.one("SELECT * FROM config_history WHERE id=? AND guild_id=?",(change_id,guild.id))
    if not row:return False,"That Manifest change was not found."
    if row['status']!='committed':return False,"That change is no longer undoable."
    try: inv=json.loads(row['inverse_json'] or '{}')
    except Exception:return False,"The saved undo data is damaged."
    kind=inv.get('kind')
    if kind=='delete_created_channel':
        ch=guild.get_channel(int(inv.get('channel_id',0)))
        if not ch:return False,"The channel is already gone; nothing was changed."
        if not isinstance(ch,discord.TextChannel):return False,"That object is no longer a text channel; refusing unsafe undo."
        expected=str(inv.get('expected_name') or '')
        if expected and ch.name!=expected:return False,"The channel was renamed after Manifest created it; refusing to delete later user changes."
        try:
            async for msg in ch.history(limit=25,oldest_first=True):
                if not msg.author.bot:return False,"People have used this channel since it was created; refusing to delete their content."
        except discord.Forbidden:return False,"I can't verify whether the channel contains user messages, so I won't delete it."
        await ch.delete(reason=f"Manifest undo #{change_id} by {actor}")
        if guild.get_channel(ch.id):return False,"Discord did not confirm the channel deletion."
    elif kind=='channel_send_messages':
        ch=guild.get_channel(int(inv.get('channel_id',0)))
        if not ch:return False,"The channel no longer exists."
        expected=inv.get('expected_current')
        current=ch.overwrites_for(guild.default_role).send_messages
        if current is not expected:return False,"The channel permission changed after Manifest's action; refusing to overwrite it."
        ow=ch.overwrites_for(guild.default_role);ow.send_messages=inv.get('restore')
        await ch.set_permissions(guild.default_role,overwrite=ow,reason=f"Manifest undo #{change_id} by {actor}")
        fresh=await guild.fetch_channel(ch.id)
        if fresh.overwrites_for(guild.default_role).send_messages is not inv.get('restore'):return False,"Discord did not confirm the permission restoration."
    elif kind=='delete_created_category':
        ch=guild.get_channel(int(inv.get('channel_id',0)))
        if not ch:return False,"The category is already gone; nothing was changed."
        if not isinstance(ch,discord.CategoryChannel):return False,"That object is no longer a category."
        if ch.name!=str(inv.get('expected_name') or ch.name):return False,"The category was renamed after creation; refusing unsafe undo."
        if ch.channels:return False,"The category now contains channels; refusing unsafe undo."
        await ch.delete(reason=f"Manifest undo #{change_id} by {actor}")
        if guild.get_channel(ch.id):return False,"Discord did not confirm the category deletion."
    elif kind=='delete_created_role':
        role=guild.get_role(int(inv.get('role_id',0)))
        if not role:return False,"The role is already gone; nothing was changed."
        if role.managed:return False,"That role is managed by Discord; refusing unsafe undo."
        if role.name!=str(inv.get('expected_name') or role.name):return False,"The role was renamed after creation; refusing unsafe undo."
        if role.members:return False,"The role is now assigned to members; refusing unsafe undo."
        if guild.me and role>=guild.me.top_role:return False,"The role is no longer below Manifest; refusing unsafe undo."
        await role.delete(reason=f"Manifest undo #{change_id} by {actor}")
        if guild.get_role(role.id):return False,"Discord did not confirm the role deletion."
    elif kind=='rename_channel':
        ch=guild.get_channel(int(inv.get('channel_id',0)))
        if not ch:return False,"The channel no longer exists."
        expected=str(inv.get('expected_current_name') or '')
        if expected and ch.name!=expected:return False,"The channel changed again after Manifest renamed it; refusing to overwrite the newer change."
        await ch.edit(name=str(inv.get('name','channel'))[:100],reason=f"Manifest undo #{change_id} by {actor}")
        if ch.name!=str(inv.get('name','channel'))[:100]:return False,"Discord did not confirm the rename."
    else:return False,"This change does not have a safe automatic inverse."
    await db.execute("UPDATE config_history SET status='undone' WHERE id=?",(change_id,))
    return True,f"Undid Manifest change #{change_id}."

async def repair_server_system(guild,system_key,actor):
    """Repair only known Manifest dependencies. Never recreate an owner-deleted object without this explicit call."""
    await server_system_health(guild)
    row=await db.one("SELECT * FROM system_health WHERE guild_id=? AND system_key=?",(guild.id,system_key))
    if not row:return False,"Unknown system."
    if row['state']!='degraded':return False,f"{system_key} is not currently degraded."
    await record_system_health(guild.id,system_key,'repairing','Explicit repair requested',row['object_id'],True)
    # Safe repair means clear stale references and return the system to an honest unconfigured state.
    mapping={'mod_logs':'log_mod_id','security_logs':'log_security_id','message_logs':'log_message_id','ticket_logs':'log_ticket_id','welcome':'welcome_channel_id'}
    if system_key in mapping:
        await db.execute(f"UPDATE guild_settings SET {mapping[system_key]}=0 WHERE guild_id=?",(guild.id,))
        await record_system_health(guild.id,system_key,'not_configured','Stale destination cleared; choose a new destination.',0,False)
        return True,f"Cleared the broken {system_key.replace('_',' ')} destination. Choose a new channel when ready."
    if system_key=='support_role':
        await db.execute("UPDATE guild_settings SET support_role_id=0 WHERE guild_id=?",(guild.id,))
        await record_system_health(guild.id,system_key,'not_configured','Stale support role cleared.',0,False)
        return True,"Cleared the missing support role reference."
    if system_key=='verification':
        await db.execute("UPDATE verification_config SET enabled=0 WHERE guild_id=?",(guild.id,))
        await record_system_health(guild.id,system_key,'not_configured','Verification disabled because a required dependency was missing.',0,False)
        return True,"Disabled the broken verification flow instead of pretending it still works."
    if system_key=='tickets':
        await db.execute("UPDATE guild_settings SET ticket_category_id=0 WHERE guild_id=?",(guild.id,))
        await record_system_health(guild.id,system_key,'not_configured','Stale ticket category cleared.',0,False)
        return True,"Cleared the missing ticket category reference. Existing ticket records were preserved."
    return False,"This system needs a manual repair plan."

AUTOMATION_ACTIONS={'send_message','add_role','remove_role','create_ticket','notify_staff'}
AUTOMATION_TRIGGERS={'member_join','keyword','level_reached','ticket_priority','warning_count'}

async def validate_automation_rule(guild,creator,trigger_type,action_type,payload,conditions):
    """Validate references and authority at creation time. Runtime rechecks again before every mutation."""
    if trigger_type not in AUTOMATION_TRIGGERS:return False,"Unsupported trigger."
    if action_type not in AUTOMATION_ACTIONS:return False,"Unsupported action."
    if not isinstance(payload,dict) or not isinstance(conditions,dict):return False,"Payload and conditions must be objects."
    if trigger_type=="keyword":
        keys={str(k).lower() for k in conditions}
        if not keys.intersection({"contains_content","exact_content"}):
            return False,"Keyword automations must specify what message content triggers them."
        for key in ("contains_content","exact_content"):
            value=str(conditions.get(key) or "").strip()
            if key in keys and len(value)<3:
                return False,"Keyword triggers must be at least 3 characters long."
    if len(json.dumps(payload,default=str))>6000 or len(json.dumps(conditions,default=str))>4000:return False,"Automation configuration is too large."
    if action_type in {'send_message','notify_staff'}:
        ch=guild.get_channel(int(payload.get('channel_id',0) or 0))
        if not isinstance(ch,discord.TextChannel):return False,"Choose an existing text channel."
        perms=ch.permissions_for(guild.me)
        if not (perms.view_channel and perms.send_messages):return False,"Manifest cannot view/send in that destination."
        if not str(payload.get('text','')).strip():return False,"A message is required."
    elif action_type in {'add_role','remove_role'}:
        role=guild.get_role(int(payload.get('role_id',0) or 0))
        if not role:return False,"That role does not exist."
        if role.is_default() or role.managed:return False,"That role cannot be managed by this automation."
        if not guild.me.guild_permissions.manage_roles or role>=guild.me.top_role:return False,"That role is not safely below Manifest's role."
        if creator.id!=guild.owner_id and (not creator.guild_permissions.manage_roles or role>=creator.top_role):return False,"You cannot create an automation that manages a role at or above your own authority."
    elif action_type=='create_ticket':
        if not str(payload.get('reason','Automation-created ticket')).strip():return False,"Ticket reason cannot be empty."
    return True,"ok"

async def automation_run_event(rule,guild,status,context,details=''):
    await db.execute("INSERT INTO automation_runs(automation_id,guild_id,trigger_type,action_type,status,user_id,details,created_at) VALUES(?,?,?,?,?,?,?,?)",
        (rule['id'],guild.id,rule['trigger_type'],rule['action_type'],status,int(context.get('user_id',0) or 0),str(details)[:1500],time.time()))

async def run_typed_automations(guild,trigger_type,context):
    """Deterministic workflow engine with live authority, hierarchy, verification, cooldowns and event-idempotent dispatch."""
    if trigger_type not in AUTOMATION_TRIGGERS:return 0
    context=dict(context or {})
    event_key=str(context.get('_event_key') or '').strip()
    # These are the two event types currently dispatched by Discord listeners.
    # Require their real event identity; content hashes can collide on legitimate repeated messages.
    if trigger_type in {'keyword','member_join'} and not event_key:
        log.warning("Typed automation %s ignored because its Discord event identity was missing",trigger_type)
        return 0
    rows=await db.all("SELECT * FROM automation_rules WHERE guild_id=? AND trigger_type=? AND enabled=1",(guild.id,trigger_type))
    ran=0; now=time.time()
    # An interrupted action is never automatically replayed: preserve its unique event claim as uncertain.
    try:
        await db.execute("UPDATE automation_dispatches SET status='uncertain',finished_at=?,details=CASE WHEN details='' THEN 'Worker stopped before a terminal receipt; replay suppressed.' ELSE details END WHERE guild_id=? AND status='running' AND started_at>0 AND started_at<=?",(now,guild.id,now-900))
        # Keep dispatch dedupe durable without allowing its index to grow forever.
        await db.execute("DELETE FROM automation_dispatches WHERE guild_id=? AND status IN ('completed','failed') AND finished_at>0 AND finished_at<?",(guild.id,now-90*86400))
        await db.execute("DELETE FROM automation_dispatches WHERE guild_id=? AND status='uncertain' AND finished_at>0 AND finished_at<?",(guild.id,now-180*86400))
    except Exception: log.exception("Could not reconcile/prune automation dispatch claims in guild %s",guild.id)
    for r in rows:
        if now-float(r['last_run'] or 0)<int(r['cooldown_seconds'] or 0):continue
        try: cond=json.loads(r['conditions_json'] or '{}'); payload=json.loads(r['payload_json'] or '{}')
        except Exception:
            try: await automation_run_event(r,guild,'invalid_config',context,'Stored JSON could not be decoded')
            except Exception: log.exception("Could not journal invalid automation #%s",r['id'])
            continue
        if trigger_type=="keyword":
            trigger_values=[str(cond.get(k) or "").strip() for k in ("contains_content","exact_content") if k in cond]
            if not trigger_values or any(len(v)<3 for v in trigger_values):
                try: await automation_run_event(r,guild,'invalid_config',context,'Keyword automation has no safe explicit trigger; skipped for safety')
                except Exception: log.exception("Could not journal invalid keyword automation #%s",r['id'])
                continue
        ok=True
        try:
            for k,v in cond.items():
                actual=context.get(k)
                if k.startswith('min_'):
                    actual=context.get(k[4:]); ok=ok and actual is not None and float(actual)>=float(v)
                elif k.startswith('contains_'):
                    actual=context.get(k[9:]);ok=ok and actual is not None and str(v).lower() in str(actual).lower()
                else: ok=ok and str(actual)==str(v)
        except Exception:ok=False
        if not ok:continue
        claim=None
        if event_key:
            try:
                claim=await db.execute("INSERT OR IGNORE INTO automation_dispatches(automation_id,guild_id,event_key,status,started_at) VALUES(?,?,?,'running',?)",(r['id'],guild.id,event_key,now))
                acquired=int(getattr(claim,'rowcount',0) or 0)==1
                try: await claim.close()
                except Exception: pass
            except Exception:
                log.exception("Could not claim automation #%s for event %s",r['id'],event_key[:100])
                continue
            if not acquired:continue
        action=r['action_type']; success=False; detail=''
        creator=guild.get_member(int(r['creator_id'] or 0))
        try:
            if action=='send_message' or action=='notify_staff':
                ch=guild.get_channel(int(payload.get('channel_id',0))); text=str(payload.get('text','Workflow needs attention.' if action=='notify_staff' else ''))[:1900]
                if isinstance(ch,discord.TextChannel) and ch.permissions_for(guild.me).view_channel and ch.permissions_for(guild.me).send_messages and text:
                    sent=await ch.send(text,allowed_mentions=discord.AllowedMentions.none());success=bool(sent and sent.id);detail=f"message_id={getattr(sent,'id',0)}"
                else:detail='destination missing or Manifest cannot send there'
            elif action in {'add_role','remove_role'}:
                member=guild.get_member(int(context.get('user_id',0))); role=guild.get_role(int(payload.get('role_id',0)))
                if not creator or (creator.id!=guild.owner_id and not creator.guild_permissions.manage_roles):detail='automation creator no longer has Manage Roles'
                elif not member or not role:detail='member or role no longer exists'
                elif role.is_default() or role.managed or not guild.me.guild_permissions.manage_roles or role>=guild.me.top_role:detail='role is no longer safely manageable by Manifest'
                elif creator.id!=guild.owner_id and role>=creator.top_role:detail='role is no longer below automation creator hierarchy'
                elif member.id==guild.owner_id:detail='refusing automated role mutation on the guild owner'
                elif member.top_role>=guild.me.top_role and member.id!=guild.me.id:detail='target member is not below Manifest hierarchy'
                else:
                    if action=='add_role':await member.add_roles(role,reason=f"Manifest automation #{r['id']}")
                    else:await member.remove_roles(role,reason=f"Manifest automation #{r['id']}")
                    fresh=guild.get_member(member.id);present=bool(fresh and role in fresh.roles)
                    success=present if action=='add_role' else not present;detail='verified' if success else 'Discord state did not verify'
            elif action=='create_ticket':
                member=guild.get_member(int(context.get('user_id',0)))
                if member:
                    success,detail,_=await open_ticket_capability(guild,member,reason=str(payload.get('reason','Automation-created ticket'))[:500])
                else:detail='trigger member no longer exists'
            else:detail='unsupported action'
        except discord.Forbidden:detail='Discord denied the automation action'
        except discord.HTTPException as e:detail=f"Discord error {getattr(e,'status','')}"
        except Exception as e:
            detail=f"internal {type(e).__name__}";log.exception("Typed automation #%s",r['id'])
        # The external action is now complete (or definitively failed). Persist the
        # dispatch terminal state before auxiliary run-history/receipt writes.
        if event_key:
            try:
                await db.execute("UPDATE automation_dispatches SET status=?,finished_at=?,details=? WHERE automation_id=? AND event_key=? AND status='running'",('completed' if success else 'failed',time.time(),str(detail)[:1500],r['id'],event_key))
            except Exception:
                log.exception("Automation #%s action finished but dispatch receipt could not be saved; replay remains blocked",r['id'])
        try: await automation_run_event(r,guild,'success' if success else 'failed',context,detail)
        except Exception: log.exception("Automation #%s outcome could not be added to run history",r['id'])
        if success:
            ran+=1
            try: await db.execute("UPDATE automation_rules SET last_run=? WHERE id=?",(now,r['id']))
            except Exception: log.exception("Automation #%s succeeded but its cooldown timestamp could not be saved",r['id'])
            actor=guild.get_member(int(context.get('user_id',0) or 0)) or guild.me
            if actor:
                try:
                    await action_receipt(guild,actor,f"automation.{action}",'low',str(r['id']),1,json.dumps({'context':context,'detail':detail},default=str)[:1500],verification_state="Manifest-verified",evidence_ref=f"automation_runs:{r['id']}",reason=str(detail)[:500],source="automation_engine",request_id=f"automation:{r['id']}:{event_key or int(now)}")
                except Exception: log.exception("Automation #%s succeeded but its action receipt could not be saved",r['id'])
    return ran

# ========================= COMMUNITY / MEMORY / SCHEDULER CORE =========================
REVIVAL_COOLDOWN=6*3600
REVIVAL_MIN_QUIET=60*60
RECOGNITION_COOLDOWN=7*86400

def _tz(name):
    try:return ZoneInfo(name)
    except Exception:return datetime.timezone.utc
async def server_tz(gid):
    row=await db.one("SELECT tz_name FROM server_timezones WHERE guild_id=?",(gid,)); return row["tz_name"] if row else "UTC"
async def user_tz(gid,uid):
    row=await db.one("SELECT tz_name FROM member_timezones WHERE guild_id=? AND user_id=?",(gid,uid)); return row["tz_name"] if row else await server_tz(gid)
async def semantic_channel(guild,purposes):
    rows=await db.all("SELECT object_id,purpose,confidence FROM server_semantic_map WHERE guild_id=? AND object_type='channel' ORDER BY confidence DESC",(guild.id,))
    for r in rows:
        if r["purpose"] in purposes:
            ch=guild.get_channel(r["object_id"])
            if isinstance(ch,discord.TextChannel):return ch
    best=[]
    terms={'community':['general','chat','lounge','talk','community','hangout','alien'],'announcement':['announce','news','update','event'],'security':['security','audit','incident','sentinel','antinuke','mod-log','moderation'],'rules':['rules','protocol','law','read-me'],'manifest':['manifest','bot-log','system']}
    for ch in guild.text_channels:
        text=((ch.name or '')+' '+(ch.topic or '')).lower(); score=sum(1 for p in purposes for x in terms.get(p,[]) if x in text)
        if score:best.append((score,ch))
    return max(best,key=lambda x:x[0])[1] if best else None
async def learn_semantic_map(guild):
    terms={'rules':['rule','protocol','law','read-me'],'security':['security','audit','incident','antinuke','mod-log','moderation'],'announcement':['announcement','news','update','event'],'manifest':['manifest','bot-log','bot-system'],'community':['general','chat','lounge','community','hangout']}
    for ch in guild.text_channels:
        text=((ch.name or '')+' '+(ch.topic or '')).lower()
        for purpose,words in terms.items():
            if any(x in text for x in words):
                await db.execute("INSERT INTO server_semantic_map(guild_id,object_type,object_id,purpose,confidence,source,updated_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(guild_id,object_type,object_id,purpose) DO UPDATE SET confidence=excluded.confidence,updated_at=excluded.updated_at",(guild.id,'channel',ch.id,purpose,.75,'inferred',time.time()))
async def set_afk(guild,member,reason='',until_at=0):
    await db.execute("INSERT INTO afk_status(guild_id,user_id,reason,until_at,set_at) VALUES(?,?,?,?,?) ON CONFLICT(guild_id,user_id) DO UPDATE SET reason=excluded.reason,until_at=excluded.until_at,set_at=excluded.set_at",(guild.id,member.id,reason[:300],until_at,time.time()))
async def clear_afk(guild,uid):await db.execute("DELETE FROM afk_status WHERE guild_id=? AND user_id=?",(guild.id,uid))
async def parse_human_duration(text):
    """Parse human durations without dropping units or silently clamping.
    Supports digits and common English number words through one million.
    Returns seconds or None. Discord moderation callers enforce their own 28-day cap.
    """
    t=(text or '').lower().replace('-', ' ')
    small={
        'zero':0,'a':1,'an':1,'one':1,'two':2,'three':3,'four':4,'five':5,'six':6,'seven':7,'eight':8,'nine':9,'ten':10,
        'eleven':11,'twelve':12,'thirteen':13,'fourteen':14,'fifteen':15,'sixteen':16,'seventeen':17,'eighteen':18,'nineteen':19,
        'twenty':20,'thirty':30,'forty':40,'fifty':50,'sixty':60,'seventy':70,'eighty':80,'ninety':90
    }
    scales={'hundred':100,'thousand':1000,'million':1000000}
    units=r'(seconds?|secs?|s|minutes?|mins?|m|hours?|hrs?|h|days?|d|weeks?|w|months?|mo|years?|yrs?|y)'
    # First handle ordinary numeric expressions, including decimals.
    m=re.search(rf'\b(\d+(?:\.\d+)?)\s*{units}\b',t)
    if m:
        n=float(m.group(1));u=m.group(2)
    else:
        # Parse a short number phrase such as "one week", "twenty eight days",
        # "one hundred twenty minutes". Stop at the first time unit.
        m=re.search(rf'\b(?:for\s+)?((?:a|an|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety|hundred|thousand|million|and)(?:\s+(?:a|an|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety|hundred|thousand|million|and))*?)\s+{units}\b',t)
        if not m:return None
        phrase=m.group(1).strip();u=m.group(2)
        total=0;current=0;seen=False
        for w in phrase.split():
            if w in small:
                current+=small[w];seen=True
            elif w in scales:
                current=max(1,current)*scales[w];total+=current;current=0;seen=True
            elif w=='and':
                continue
            else:
                # Avoid treating arbitrary prose as a number.
                return None
        if not seen:return None
        n=total+current
    ul=u.lower()
    if ul.startswith(('sec','s')):mult=1
    elif ul.startswith(('month','mo')):mult=2592000
    elif ul.startswith(('min','m')):mult=60
    elif ul.startswith(('hour','hr','h')):mult=3600
    elif ul.startswith(('day','d')):mult=86400
    elif ul.startswith(('week','w')):mult=604800
    elif ul.startswith(('year','yr','y')):mult=31536000
    else:return None
    return int(n*mult)

async def schedule_announcement(guild,actor,channel,due_at,message,allow_everyone=False,allow_roles=False,tzname='UTC'):
    if (allow_everyone or allow_roles) and not (actor.id==guild.owner_id or actor.guild_permissions.administrator or actor.guild_permissions.manage_guild):return False,'You need **Manage Server** or **Administrator** for mass mentions.'
    perms=channel.permissions_for(guild.me)
    if not perms.send_messages:return False,'I cannot send messages in that channel.'
    if allow_everyone and not perms.mention_everyone:return False,'I need **Mention Everyone** in that channel.'
    cur=await db.execute("INSERT INTO scheduled_announcements(guild_id,creator_id,channel_id,message,due_at,timezone,allow_everyone,allow_roles,created_at,status) VALUES(?,?,?,?,?,?,?,?,?,?)",(guild.id,actor.id,channel.id,due_at and message[:1900] or message,due_at,tzname,int(allow_everyone),int(allow_roles),time.time(),'scheduled'))
    aid=cur.lastrowid
    await db.execute("INSERT INTO announcement_events(announcement_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(aid,guild.id,actor.id,'scheduled',f'channel={channel.id}; due={due_at}',time.time()))
    return True,aid
async def manifest_channel_context(guild, channel):
    """Resolve a channel's purpose from registered state first, semantics second,
    and conservative name/category/topic hints last. AI never overrides this result.
    """
    if not guild or not channel:
        return "unknown"
    cid=getattr(channel,"id",0)

    # 1) Registered operational state is authoritative.
    try:
        row=await db.one("SELECT status FROM tickets WHERE guild_id=? AND channel_id=?",(guild.id,cid))
        if row:
            return "ticket"
    except Exception:
        pass
    try:
        vc=await db.one("SELECT enabled,channel_id FROM verification_config WHERE guild_id=?",(guild.id,))
        if vc and int(vc['channel_id'] or 0)==cid:
            return "verification"
    except Exception:
        pass
    try:
        gs=await db.one("SELECT * FROM guild_settings WHERE guild_id=?",(guild.id,))
        if gs:
            # Explicitly configured destinations outrank channel names.
            for key in ("log_mod_id","log_arrival_id","log_security_id","log_message_id","log_ticket_id"):
                if key in gs.keys() and int(gs[key] or 0)==cid:
                    return "logs"
            if 'welcome_channel_id' in gs.keys() and int(gs['welcome_channel_id'] or 0)==cid:
                return "welcome"
            if 'autopilot_channel_id' in gs.keys() and int(gs['autopilot_channel_id'] or 0)==cid:
                return "community"
            cat_id=int(gs['ticket_category_id'] or 0) if 'ticket_category_id' in gs.keys() else 0
            if cat_id and getattr(channel,"category_id",0)==cat_id:
                # A configured ticket category is operational even if a ticket DB row
                # was lost or the channel has been renamed.
                return "ticket"
    except Exception:
        pass

    # 2) Owner-confirmed semantic mappings beat automatic guesses.
    try:
        rows=await db.all("SELECT purpose,confidence,source FROM server_semantic_map WHERE guild_id=? AND object_type='channel' AND object_id=? ORDER BY confidence DESC",(guild.id,cid))
        semantic_alias={
            "rules":"rules","protocol":"rules","logs":"logs","log":"logs","security_logs":"logs",
            "announcement":"announcement","announcements":"announcement","updates":"announcement",
            "verification":"verification","welcome":"welcome","community":"community","main_chat":"community",
            "staff":"staff","staff_chat":"staff","support":"ticket","tickets":"ticket","ticket":"ticket",
            "giveaway":"giveaway","giveaways":"giveaway","games":"games","game":"games",
        }
        for r in rows:
            purpose=str(r['purpose'] or '').lower().strip().replace(' ','_')
            mapped=semantic_alias.get(purpose)
            if mapped and float(r['confidence'] or 0)>=.65:
                return mapped
    except Exception:
        pass

    # 3) Conservative fallback only. Never let a vague name turn a private or
    # operational area into a community engagement destination.
    name=(getattr(channel,"name","") or "").lower()
    cat=(getattr(getattr(channel,"category",None),"name","") or "").lower()
    topic=(getattr(channel,"topic","") or "").lower()
    blob=f"{name} {cat} {topic}"
    protected={
        "ticket":("ticket","support","report-","appeal","case-","help-desk"),
        "rules":("rules","rule-","guideline","protocol"),
        "logs":("log","audit","security-log","mod-log","transcript"),
        "announcement":("announcement","updates","news"),
        "verification":("verify","verification","welcome-gate"),
        "staff":("staff-only","staff-chat","moderator-chat","admin-chat","management"),
        "giveaway":("giveaway","giveaways"),
        "games":("games","game-room","minigames","party-games"),
        "welcome":("welcome","introductions"),
    }
    for kind,words in protected.items():
        if any(w in blob for w in words):
            return kind
    return "community"

async def proactive_allowed(guild, channel):
    # Community engagement is intentionally denied in operational/private contexts.
    return await manifest_channel_context(guild,channel)=="community"

async def channel_experience_policy(guild, channel):
    """One deterministic source of truth for how Manifest may behave in a channel.

    This policy is intentionally independent from AI.  AI may understand a request,
    but it cannot turn an operational channel into a community-chat destination.
    """
    kind = await manifest_channel_context(guild, channel)
    operational = kind in {"ticket", "rules", "logs", "announcement", "verification", "staff"}
    return {
        "kind": kind,
        # Unsolicited community behavior is allowed only in a confirmed/general
        # community destination. Games/giveaways may be interactive, but Manifest
        # must not revive them or post generic recognition there.
        "allow_proactive_community": kind == "community",
        "allow_dead_chat": kind == "community",
        "allow_public_recognition": kind == "community",
        "allow_game_suggestions": kind in {"community", "games"},
        # Setup chatter can be cleaned in purpose-built publishing channels when
        # the requester/server policy permits it; operational records stay intact.
        "allow_setup_cleanup": kind in {"community", "announcement", "giveaway", "games"},
        "preserve_conversation": kind in {"ticket", "staff"},
        "quiet_by_default": kind in {"rules", "logs", "announcement", "verification"},
        "operational": operational,
    }

async def proactive_revival(guild,now):
    if not await discord_policy_allows_proactive_engagement(guild,'dead_chat_revival'):return
    if not await db.setting(guild.id,'autopilot_enabled',1) or not await db.setting(guild.id,'dead_chat_enabled',1):return
    row=await db.one("SELECT last_message_at,last_revive_at FROM guild_activity WHERE guild_id=?",(guild.id,))
    if not row or not row['last_message_at']:return
    if now-float(row['last_message_at'])<REVIVAL_MIN_QUIET or now-float(row['last_revive_at'] or 0)<REVIVAL_COOLDOWN:return
    ch=await semantic_channel(guild,['community'])
    if not ch:return
    policy=await channel_experience_policy(guild,ch)
    if not policy["allow_dead_chat"]: return
    online=sum(1 for m in guild.members if not m.bot and m.status!=discord.Status.offline)
    if online<=1 and now-float(row['last_message_at'])<4*3600:return
    profile=await db.one("SELECT topics FROM server_profiles WHERE guild_id=?",(guild.id,)); topics=(profile['topics'] if profile else '') or ''
    starters=["💬 Quiet moment — anyone around? What have you been into lately?","👀 The chat has been quiet for a while. Anyone want to start a conversation?","🎯 Quick community question: what should we talk about today?"]
    if topics:starters.insert(0,f"💬 Anyone around? What do you think about **{topics[:70]}** lately?")
    await ch.send(random.choice(starters),allowed_mentions=discord.AllowedMentions.none())
    await db.execute("UPDATE guild_activity SET last_revive_at=? WHERE guild_id=?",(now,guild.id))
    await db.execute("INSERT INTO revival_history(guild_id,channel_id,reason,topic,created_at) VALUES(?,?,?,?,?)",(guild.id,ch.id,'unusually quiet',topics[:200],now))
async def recognition_tick(guild):
    if not await discord_policy_allows_proactive_engagement(guild,'public_recognition'):return
    state=await db.one("SELECT value FROM delight_state WHERE guild_id=? AND key='recognition_enabled'",(guild.id,))
    # Public recognition is opt-in. Absence of a setting is NOT permission to speak.
    if not state or state['value']!='1':return
    # Recognition is based on contribution signals, not a public popularity contest.
    rows=await db.all("SELECT user_id,total FROM message_stats WHERE guild_id=? AND total>=50 ORDER BY total DESC LIMIT 30",(guild.id,))
    for r in rows:
        m=guild.get_member(r['user_id'])
        if not m or m.bot:continue
        # A steady contributor can receive occasional recognition; no sensitive inference.
        old=await db.one("SELECT score,notified_at FROM recognition_state WHERE guild_id=? AND user_id=? AND key='contributor'",(guild.id,m.id))
        score=float(old['score']) if old else 0
        score += 1
        await db.execute("INSERT INTO recognition_state(guild_id,user_id,key,score,last_awarded,notified_at) VALUES(?,?,?,?,0,0) ON CONFLICT(guild_id,user_id,key) DO UPDATE SET score=excluded.score",(guild.id,m.id,'contributor',score))
        if score>=10 and (not old or time.time()-float(old['notified_at'] or 0)>RECOGNITION_COOLDOWN):
            ch=await semantic_best_channel(guild,'community',.65)
            if ch and (await channel_experience_policy(guild,ch))["allow_public_recognition"]:
                await ch.send(f"🌟 {m.mention} has been a steady positive contributor around here lately. Appreciate it.",allowed_mentions=discord.AllowedMentions(users=True))
                await db.execute("UPDATE recognition_state SET notified_at=?,last_awarded=? WHERE guild_id=? AND user_id=? AND key='contributor'",(time.time(),time.time(),guild.id,m.id))
            # Only one recognition per scan to prevent a burst.
            break
async def deliver_scheduled_announcements(now):
    # A worker interruption after Discord accepted a post must never turn into
    # an automatic duplicate. Stale in-flight sends become explicitly uncertain.
    stale=await db.all("SELECT id FROM scheduled_announcements WHERE delivered=0 AND status='sending' AND delivery_started_at>0 AND delivery_started_at<=?",(now-900,))
    for item in stale:
        try:
            await db.execute("UPDATE scheduled_announcements SET status='uncertain',last_error=? WHERE id=? AND delivered=0 AND status='sending' AND delivery_started_at<=?",
                             ('Delivery outcome is uncertain after an interrupted send. Check the destination channel before retrying.',item['id'],now-900))
        except Exception:
            log.exception("Could not mark interrupted scheduled announcement %s as uncertain",item['id'])

    rows=await db.all("SELECT * FROM scheduled_announcements WHERE delivered=0 AND status IN ('scheduled','retry') AND due_at<=? ORDER BY due_at LIMIT 25",(now,))
    for r in rows:
        # Compare-and-set claim makes this safe across multiple bot workers.
        try:
            claim=await db.execute("UPDATE scheduled_announcements SET status='sending',delivery_started_at=?,attempts=attempts+1,last_error='' WHERE id=? AND delivered=0 AND status IN ('scheduled','retry') AND due_at<=?",
                                   (now,r['id'],now))
            acquired=int(getattr(claim,'rowcount',0) or 0)==1
            try: await claim.close()
            except Exception: pass
        except Exception:
            log.exception("Could not claim scheduled announcement %s",r['id'])
            continue
        if not acquired: continue

        g=bot.get_guild(r['guild_id'])
        ch=g.get_channel(r['channel_id']) if g else None
        if not isinstance(ch,discord.TextChannel):
            try:
                candidate=await bot.fetch_channel(r['channel_id'])
                ch=candidate if isinstance(candidate,discord.TextChannel) else None
            except (discord.NotFound,discord.Forbidden,discord.HTTPException):
                ch=None
        if not isinstance(ch,discord.TextChannel):
            err='destination channel missing or inaccessible'
            try: await db.execute("UPDATE scheduled_announcements SET status='failed',last_error=? WHERE id=? AND status='sending'",(err,r['id']))
            except Exception: log.exception("Could not persist missing destination for scheduled announcement %s",r['id'])
            try: await db.execute("INSERT INTO announcement_events(announcement_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(r['id'],r['guild_id'],0,'failed',err,time.time()))
            except Exception: log.exception("Could not journal missing destination for scheduled announcement %s",r['id'])
            continue

        current=await db.one("SELECT status,delivered FROM scheduled_announcements WHERE id=?",(r['id'],))
        if not current or current['status']!='sending' or current['delivered']:
            continue
        try:
            sent=await ch.send(r['message'],allowed_mentions=discord.AllowedMentions(everyone=bool(r['allow_everyone']),roles=bool(r['allow_roles']),users=False,replied_user=False))
        except (discord.Forbidden,discord.NotFound) as ex:
            err=f'{type(ex).__name__}: {str(ex)[:300]}'
            try: await db.execute("UPDATE scheduled_announcements SET status='failed',last_error=? WHERE id=? AND status='sending'",(err,r['id']))
            except Exception: log.exception("Could not persist rejected scheduled announcement %s",r['id'])
            try: await db.execute("INSERT INTO announcement_events(announcement_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(r['id'],r['guild_id'],0,'failed',err,time.time()))
            except Exception: log.exception("Could not journal rejected scheduled announcement %s",r['id'])
            log.warning("Scheduled announcement %s was rejected: %s",r['id'],type(ex).__name__)
            continue
        except discord.HTTPException as ex:
            err=f'{type(ex).__name__}: {str(ex)[:300]}'
            status='retry' if int(getattr(ex,'status',0) or 0)==429 else ('failed' if 400<=int(getattr(ex,'status',0) or 0)<500 else 'uncertain')
            if status=='retry':
                try: await db.execute("UPDATE scheduled_announcements SET status='retry',due_at=?,last_error=? WHERE id=? AND status='sending'",(time.time()+60,err,r['id']))
                except Exception: log.exception("Could not queue rate-limited scheduled announcement %s",r['id'])
            else:
                detail=err if status=='failed' else err+'; Discord may have accepted the post, so automatic retry was stopped.'
                try: await db.execute("UPDATE scheduled_announcements SET status=?,last_error=? WHERE id=? AND status='sending'",(status,detail,r['id']))
                except Exception: log.exception("Could not persist ambiguous scheduled announcement %s",r['id'])
            try: await db.execute("INSERT INTO announcement_events(announcement_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(r['id'],r['guild_id'],0,status,err,time.time()))
            except Exception: log.exception("Could not journal scheduled announcement failure %s",r['id'])
            log.warning("Scheduled announcement %s did not return a definitive success: %s",r['id'],type(ex).__name__)
            continue
        except Exception as ex:
            err=f'{type(ex).__name__}: {str(ex)[:300]}; delivery outcome is uncertain.'
            try: await db.execute("UPDATE scheduled_announcements SET status='uncertain',last_error=? WHERE id=? AND status='sending'",(err,r['id']))
            except Exception: log.exception("Could not persist uncertain scheduled announcement %s",r['id'])
            try: await db.execute("INSERT INTO announcement_events(announcement_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(r['id'],r['guild_id'],0,'uncertain',err,time.time()))
            except Exception: log.exception("Could not journal uncertain scheduled announcement %s",r['id'])
            log.exception("Scheduled announcement %s has an uncertain delivery outcome",r['id'])
            continue

        # The Discord send is the delivery boundary. A receipt failure leaves
        # the row in 'sending'; the stale-send sweeper will mark it uncertain.
        try:
            await db.execute("UPDATE scheduled_announcements SET delivered=1,status='delivered',delivered_at=?,message_id=?,last_error='' WHERE id=? AND status='sending'",(time.time(),sent.id,r['id']))
        except Exception:
            log.exception("Scheduled announcement %s was sent but its DB receipt could not be saved",r['id'])
            continue
        try:
            await db.execute("INSERT INTO announcement_events(announcement_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(r['id'],r['guild_id'],0,'delivered',f'message_id={sent.id}',time.time()))
        except Exception:
            log.exception("Scheduled announcement %s delivered but its event journal could not be saved",r['id'])
async def birthday_tick(now):
    for g in bot.guilds:
        try:
            local=datetime.datetime.fromtimestamp(now,_tz(await server_tz(g.id)))
            rows=await db.all("SELECT * FROM birthdays WHERE guild_id=? AND enabled=1 AND month=? AND day=?",(g.id,local.month,local.day))
            for r in rows:
                if int(r['last_notified_year'] or 0)==local.year:continue
                m=g.get_member(r['user_id']);ch=g.get_channel(r['channel_id']) if r['channel_id'] else await semantic_channel(g,['community'])
                if m and ch:
                    await ch.send(f"🎂 Happy birthday, {m.mention}! Hope you have an awesome day!",allowed_mentions=discord.AllowedMentions(users=True));await db.execute("UPDATE birthdays SET last_notified_year=? WHERE guild_id=? AND user_id=?",(local.year,g.id,m.id))
        except Exception:log.exception('birthday tick %s',g.id)

# ========================= V37 UNIFIED INTELLIGENCE =========================
# Semantic server understanding, culture, recognition, proactive community care,
# natural scheduling/AFK, and developer operations live here.  IDs are authoritative;
# names are only evidence/presentation.
SEMANTIC_PURPOSES = {
    "community": ["general","chat","lounge","community","hangout","talk","social","offtopic","off-topic","main"],
    "rules": ["rules","rule","protocol","guidelines","guideline","law","readme","read-me","info"],
    "welcome": ["welcome","welcomes","greeting","onboarding","introductions","intro"],
    "announcement": ["announcement","announcements","news","updates","update","events","event","notices"],
    "support": ["support","help","assistance","questions","question","faq","tickets","ticket"],
    "security": ["security","secure","sentinel","antinuke","anti-nuke","raid","incident","incidents","audit","audit-log","security-log","mod-log","moderation-log","staff-log"],
    "message_log": ["message-log","message-logs","messages-log","deleted-messages","deleted-message","message history","chat-log"],
    "ticket_log": ["ticket-log","ticket-logs","tickets-log","support-log"],
    "arrival_log": ["join-log","joins","leave-log","leaves","member-log","arrival-log","welcome-log"],
    "mod_log": ["mod-log","moderation-log","warn-log","warning-log","staff-log","punishment-log"],
    "invite_log": ["invite-log","invites","invite-logs"],
    "economy_log": ["economy-log","economy-logs","coins-log","money-log","transactions"],
    "bot_log": ["bot-log","bot-logs","manifest-log","system-log","system","bot-system"],
    "verification": ["verify","verification","verify-here","verification-gate"],
    "media": ["media","memes","pictures","photos","videos","art"],
}
SEMANTIC_ROLE_PURPOSES = {
    "admin":["admin","administrator","admins","overseer","command","management"],
    "moderator":["mod","moderator","moderators","guardian","guardians","staff","warden","security"],
    "support":["support","helper","helpers","support-team","ticket-staff","staff"],
    "verified":["verified","member","members","trusted"],
}


def _semantic_score(text, terms):
    t=(text or '').lower().replace('_',' ').replace('-',' ')
    score=0
    for term in terms:
        q=term.replace('_',' ').replace('-',' ')
        if re.search(rf'(?<!\w){re.escape(q)}(?!\w)',t): score += 2 if len(q)>4 else 1
    return score

async def _semantic_recent_text(channel, limit=8):
    try:
        msgs=[]
        async for m in channel.history(limit=limit):
            if m.author.bot: continue
            if m.content.strip(): msgs.append(m.content[:250])
        return ' '.join(msgs)
    except (discord.Forbidden,discord.HTTPException):
        return ''

async def rebuild_semantic_map(guild, deep=False):
    """Build a stable ID-based semantic map from names, topics, categories and recent public text.
    Deep scans are limited so ordinary servers do not generate API storms.
    """
    await db.ensure(guild.id)
    now=time.time()
    # Channels: use explicit names/topics first, then a small recent-message sample when allowed.
    candidates=guild.text_channels[:80]
    for ch in candidates:
        base=' '.join(x for x in [ch.name,ch.topic or '',getattr(ch.category,'name','')] if x)
        recent=await _semantic_recent_text(ch,6) if deep and ch.position < 80 else ''
        evidence=(base+' '+recent).lower()
        for purpose,terms in SEMANTIC_PURPOSES.items():
            score=_semantic_score(evidence,terms)
            # Topic/recent content gets a little extra weight for arbitrary channel names.
            if ch.topic and _semantic_score(ch.topic,terms): score += 2
            if recent and _semantic_score(recent,terms): score += 1
            if score<=0: continue
            confidence=min(.98,.50 + score*.06)
            source='topic+recent' if recent else ('topic/name' if ch.topic else 'name')
            await db.execute("""INSERT INTO server_semantic_map(guild_id,object_type,object_id,purpose,confidence,source,updated_at)
                VALUES(?,?,?,?,?,?,?) ON CONFLICT(guild_id,object_type,object_id,purpose)
                DO UPDATE SET confidence=excluded.confidence,source=excluded.source,updated_at=excluded.updated_at""",
                (guild.id,'channel',ch.id,purpose,confidence,source,now))
    # Roles: IDs are stable even if the role is renamed later.
    for role in guild.roles:
        if role.is_default() or role.managed: continue
        for purpose,terms in SEMANTIC_ROLE_PURPOSES.items():
            score=_semantic_score(role.name,terms)
            if score:
                await db.execute("""INSERT INTO server_semantic_map(guild_id,object_type,object_id,purpose,confidence,source,updated_at)
                    VALUES(?,?,?,?,?,?,?) ON CONFLICT(guild_id,object_type,object_id,purpose)
                    DO UPDATE SET confidence=excluded.confidence,source=excluded.source,updated_at=excluded.updated_at""",
                    (guild.id,'role',role.id,purpose,min(.98,.55+score*.08),'role-name',now))
    await db.execute("INSERT INTO delight_state(guild_id,key,value,updated_at) VALUES(?,?,?,?) ON CONFLICT(guild_id,key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at",(guild.id,'semantic_last_scan',str(now),now))
    return now

async def semantic_targets(guild,purpose,object_type='channel',minimum=.62):
    rows=await db.all("SELECT object_id,confidence,source FROM server_semantic_map WHERE guild_id=? AND object_type=? AND purpose=? ORDER BY confidence DESC LIMIT 8",(guild.id,object_type,purpose))
    out=[]
    for r in rows:
        obj=guild.get_channel(r['object_id']) if object_type=='channel' else guild.get_role(r['object_id'])
        if obj and float(r['confidence'])>=minimum: out.append((obj,float(r['confidence']),r['source']))
    return out

async def semantic_best_channel(guild,purpose,minimum=.70):
    hits=await semantic_targets(guild,purpose,'channel',minimum)
    if hits:return hits[0][0]
    # One cheap rebuild before saying we do not know.
    await rebuild_semantic_map(guild,deep=False)
    hits=await semantic_targets(guild,purpose,'channel',minimum)
    return hits[0][0] if hits else None

async def _set_semantic_channel(guild,purpose,channel):
    await db.execute("INSERT INTO server_semantic_map(guild_id,object_type,object_id,purpose,confidence,source,updated_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(guild_id,object_type,object_id,purpose) DO UPDATE SET confidence=excluded.confidence,source=excluded.source,updated_at=excluded.updated_at",(guild.id,'channel',channel.id,purpose,.99,'owner-configured',time.time()))
    column={
        'security':'log_security_id','message_log':'log_message_id','ticket_log':'log_ticket_id','arrival_log':'log_arrival_id','mod_log':'log_mod_id','welcome':'welcome_channel_id'
    }.get(purpose)
    if column: await db.execute(f"UPDATE guild_settings SET {column}=? WHERE guild_id=?",(channel.id,guild.id))
    if purpose=='security': await db.execute("UPDATE security_config SET log_channel_id=? WHERE guild_id=?",(channel.id,guild.id))

async def _semantic_channel_report(guild,purpose):
    hits=await semantic_targets(guild,purpose,'channel',.55)
    if not hits:
        await rebuild_semantic_map(guild,deep=False); hits=await semantic_targets(guild,purpose,'channel',.55)
    if not hits:return f"I don't have a confident **{purpose.replace('_',' ')}** channel mapped yet. Tell me which channel it is and I'll remember the channel ID, not just its name."
    return "\n".join(f"• {c.mention} — **{round(conf*100)}% confidence** ({src})" for c,conf,src in hits[:5])

async def _clear_semantic_channel(guild,purpose,channel=None):
    params=[guild.id,purpose]
    q="DELETE FROM server_semantic_map WHERE guild_id=? AND object_type='channel' AND purpose=?"
    if channel is not None:q+=" AND object_id=?";params.append(channel.id)
    await db.execute(q,tuple(params))
    column={'security':'log_security_id','message_log':'log_message_id','ticket_log':'log_ticket_id','arrival_log':'log_arrival_id','mod_log':'log_mod_id'}.get(purpose)
    if column:
        if channel is None or int(await db.setting(guild.id,column,0) or 0)==channel.id:
            await db.execute(f"UPDATE guild_settings SET {column}=0 WHERE guild_id=?",(guild.id,))
    if purpose=='security':
        row=await db.one("SELECT log_channel_id FROM security_config WHERE guild_id=?",(guild.id,))
        if row and (channel is None or row['log_channel_id']==channel.id):await db.execute("UPDATE security_config SET log_channel_id=0 WHERE guild_id=?",(guild.id,))

async def semantic_log_action(message):
    """Goal-aware logging configuration. Never assumes the current channel unless user says here/this channel."""
    low=clean_mention(message.content).lower().strip()
    purpose=None
    patterns={
        'security':r'\b(?:security|antinuke|anti[- ]?raid|incident|audit)\s+(?:log|logs|logging|channel)',
        'ticket_log':r'\b(?:ticket|tickets|support)\s+(?:log|logs|logging)',
        'message_log':r'\b(?:message|messages|deleted message|deleted messages)\s+(?:log|logs|logging|channel)',
        'arrival_log':r'\b(?:join|joins|leave|leaves|arrival|member)\s+(?:log|logs|logging|channel)',
        'mod_log':r'\b(?:mod|moderation|warning|warnings|warn|staff)\s+(?:log|logs|logging|channel)',
        'invite_log':r'\b(?:invite|invites)\s+(?:log|logs|logging|channel)',
        'economy_log':r'\b(?:economy|coins|money|transactions?)\s+(?:log|logs|logging|channel)',
        'bot_log':r'\b(?:bot|manifest|system)\s+(?:log|logs|logging|channel)',
    }
    for p,pat in patterns.items():
        if re.search(pat,low):purpose=p;break
    generic_logs=bool(re.search(r'\b(?:make|create|setup|set up|configure)\b.*\blogs?\s+channel\b|\blogs?\s+channel\b.*\b(?:setup|set up|configure)\b',low))
    if not purpose and generic_logs:purpose='message_log'
    if not purpose:return False
    removal=bool(re.search(r'\b(?:remove|clear|unset|disable|stop using|no longer use)\b',low))
    setup=bool(re.search(r'\b(?:make|create|setup|set up|configure|use|set|put)\b',low))
    if not (removal or setup):
        await manifest_reply(message,await _semantic_channel_report(message.guild,purpose));return True
    if not server_manager(message.author):await manifest_reply(message,'You need **Manage Server** to change log destinations.');return True
    # Resolve an explicit channel mention first; only "here/this channel" selects the current channel.
    ch=next((c for c in message.channel_mentions if isinstance(c,discord.TextChannel)),None)
    if ch is None and re.search(r'\b(?:this channel|here)\b',low) and isinstance(message.channel,discord.TextChannel):ch=message.channel
    if removal:
        await _clear_semantic_channel(message.guild,purpose,ch)
        await manifest_reply(message,f"Removed the **{purpose.replace('_',' ')}** destination"+(f" from {ch.mention}." if ch else "."));return True
    if ch is None and re.search(r'\b(?:make|create|setup|set up)\b',low):
        if not message.guild.me.guild_permissions.manage_channels:await manifest_reply(message,'Manifest needs **Manage Channels** to create the log channel.');return True
        base={'message_log':'message-logs','ticket_log':'ticket-logs','security':'security-logs','arrival_log':'member-logs','mod_log':'mod-logs','invite_log':'invite-logs','economy_log':'economy-logs','bot_log':'manifest-logs'}.get(purpose,'logs')
        ch=discord.utils.get(message.guild.text_channels,name=base)
        if ch is None:ch=await message.guild.create_text_channel(base,reason=f"Manifest logging setup by {message.author}")
    if ch is None:
        await manifest_reply(message,"Which channel should I use? Mention it, or say **this channel**.");return True
    await _set_semantic_channel(message.guild,purpose,ch)
    await manifest_reply(message,f"Set {ch.mention} as the **{purpose.replace('_',' ')}** destination.");return True

async def culture_learn(guild):
    """Learn server-level culture signals only: structure, terminology and recurring topics."""
    profile=await db.one("SELECT topics,culture_notes FROM server_profiles WHERE guild_id=?",(guild.id,))
    topics=(profile['topics'] if profile else '') or ''
    if topics:
        await db.execute("INSERT INTO culture_signals(guild_id,key,value,score,updated_at) VALUES(?,?,?,?,?) ON CONFLICT(guild_id,key) DO UPDATE SET value=excluded.value,score=excluded.score,updated_at=excluded.updated_at",(guild.id,'topics',topics[:800],.7,time.time()))
    # Owner/admin explicit terminology can be saved through normal brain memory; do not infer sensitive traits.
    await db.execute("INSERT INTO culture_signals(guild_id,key,value,score,updated_at) VALUES(?,?,?,?,?) ON CONFLICT(guild_id,key) DO UPDATE SET value=excluded.value,score=excluded.score,updated_at=excluded.updated_at",(guild.id,'channels',str(len(guild.text_channels)),1,time.time()))
    return topics

async def recognition_message(guild,user_id,kind='contributor'):
    m=guild.get_member(user_id)
    ch=await semantic_best_channel(guild,'community',.65)
    if not m or not ch:return False
    policy=await channel_experience_policy(guild,ch)
    if not policy["allow_public_recognition"]: return False
    key=f'recognized:{kind}'
    old=await db.one("SELECT value FROM delight_state WHERE guild_id=? AND key=?",(guild.id,key))
    # A single recognition per person/type per 14 days keeps this meaningful.
    stamp=float(old['value']) if old and old['value'] else 0
    if time.time()-stamp<14*86400:return False
    texts={
        'contributor':f"🌟 {m.mention} has been a steady positive contributor around here lately. Appreciate it.",
        'helper':f"🛠️ {m.mention} has been helping people out around the server. Nice work.",
        'welcome':f"🤝 {m.mention} has been doing a good job helping new people feel welcome.",
    }
    await ch.send(texts.get(kind,texts['contributor']),allowed_mentions=discord.AllowedMentions(users=True))
    await db.execute("INSERT INTO delight_state(guild_id,key,value,updated_at) VALUES(?,?,?,?) ON CONFLICT(guild_id,key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at",(guild.id,key,str(time.time()),time.time()))
    return True

async def community_activity_score(guild):
    now=time.time(); day=datetime.datetime.now(datetime.timezone.utc)
    # Compare the current hour's activity with the same recent weekday/hour buckets.
    rows=await db.all("SELECT day,total FROM activity_buckets WHERE guild_id=? ORDER BY day DESC LIMIT 14",(guild.id,))
    recent=sum(int(r['total']) for r in rows)
    online=sum(1 for m in guild.members if not m.bot and m.status!=discord.Status.offline)
    return recent,online

async def _parse_clock(text,gid,uid=None):
    m=re.search(r'\b(?:at|until|around)\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\b',text,re.I)
    if not m:return None
    h=int(m.group(1));mi=int(m.group(2) or 0);ap=(m.group(3) or '').lower()
    if ap:
        if h==12:h=0
        if ap=='pm':h+=12
    if not 0<=h<=23 or not 0<=mi<=59:return None
    z=_tz(await user_tz(gid,uid) if uid else await server_tz(gid)); now=datetime.datetime.now(z); target=now.replace(hour=h,minute=mi,second=0,microsecond=0)
    if target<=now:target+=datetime.timedelta(days=1)
    return target.timestamp()

async def deterministic_personal_state_action(message):
    """Low-risk personal state actions migrated out of the legacy all-purpose action router.

    This path can only change the requesting member's AFK/birthday state. It cannot
    mutate Discord roles, channels, permissions, moderation state, or another user.
    """
    if not message.guild: return False
    text=message.content or ""; low=text.lower(); gid=message.guild.id
    if re.search(r"\b(?:i am|i'm|im|going)\s+afk\b|\bset\s+(?:me\s+)?afk\b",low):
        dur=await parse_human_duration(low); until=time.time()+dur if dur else 0
        rm=re.search(r'\bbecause\s+(.+)$',text,re.I); reason=rm.group(1).strip() if rm else ''
        await set_afk(message.guild,message.author,reason,until)
        await manifest_reply(message,"💤 AFK set. I'll tell people you're away when they mention you and clear it when you return.")
        return True
    if re.search(r"\b(?:remove|clear|cancel)\s+(?:my\s+)?afk\b|\bi(?:'m| am)\s+back\b",low):
        await clear_afk(message.guild,message.author.id)
        await manifest_reply(message,"👋 Welcome back. Your AFK status is cleared.")
        return True
    bm=re.search(r'\b(?:birthday|birth date)\b.*?\b(\d{1,2})[/-](\d{1,2})(?:[/-](\d{4}))?\b',low)
    if bm and re.search(r'\b(?:set|remember|add)\b',low):
        mo,da,yr=int(bm.group(1)),int(bm.group(2)),int(bm.group(3) or 0)
        try:
            # Leap-day remains valid without requiring a year.
            datetime.date(2000 if not yr else yr,mo,da)
        except ValueError:
            await manifest_reply(message,'⚠️ That birthday date does not look valid.')
            return True
        await db.execute("INSERT INTO birthdays(guild_id,user_id,month,day,year,channel_id) VALUES(?,?,?,?,?,?) ON CONFLICT(guild_id,user_id) DO UPDATE SET month=excluded.month,day=excluded.day,year=excluded.year,channel_id=excluded.channel_id,enabled=1",(gid,message.author.id,mo,da,yr,message.channel.id))
        await manifest_reply(message,f"🎂 Got it. I'll remember your birthday as **{mo:02d}/{da:02d}**.")
        return True
    return False

async def natural_scheduler_action(message):
    """Natural-language reminders/announcements. Exact message text is preserved."""
    low=message.content.lower(); gid=message.guild.id
    if not re.search(r'\b(?:remind|schedule|scheduled|at \d|tomorrow|next (?:monday|tuesday|wednesday|thursday|friday|saturday|sunday))\b',low):return False
    # Personal reminder: "remind me tomorrow to finish project" / "remind me at 8 to...".
    if re.search(r'\bremind me\b',low):
        note=re.sub(r'^.*?\bremind me\b','',message.content,flags=re.I).strip()
        due=None
        z=_tz(await user_tz(gid,message.author.id))
        now=datetime.datetime.now(z)
        tm=await _parse_clock(message.content,gid,message.author.id)
        if tm: due=tm
        elif re.search(r'\btomorrow\b',low):
            due=(now+datetime.timedelta(days=1)).replace(hour=9,minute=0,second=0,microsecond=0).timestamp()
        else:
            dur=await parse_human_duration(low)
            if dur is not None:
                due=time.time()+dur
        if due is None:return False
        note=re.sub(r'\b(?:tomorrow|at\s+\d{1,2}(?::\d{2})?\s*(?:am|pm)?)\b','',note,flags=re.I)
        note=re.sub(r'\bin\s+\d+(?:\.\d+)?\s*(?:seconds?|minutes?|hours?|days?|weeks?)\b','',note,flags=re.I).strip(' :,-')
        note=re.sub(r'^to\s+','',note,flags=re.I).strip()
        if not note:note='your reminder'
        cur=await db.execute("INSERT INTO reminders(guild_id,user_id,channel_id,message,due_at,created_at,status) VALUES(?,?,?,?,?,?,?)",(gid,message.author.id,message.channel.id,note[:1000],due,time.time(),'pending'))
        await manifest_reply(message,f"⏰ Reminder **#{cur.lastrowid}** set for <t:{int(due)}:F> (<t:{int(due)}:R>).")
        return True
    # Targeted reminder: "remind @Alex about the birthday on Friday".
    if re.search(r'\bremind\s+<@!?\d+>\b',low) and message.mentions:
        target=next((u for u in message.mentions if not u.bot),None)
        wd=re.search(r'\b(?:on|this|next)\s+(monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b',low)
        if target and wd:
            z=_tz(await user_tz(gid,target.id));now=datetime.datetime.now(z); names=['monday','tuesday','wednesday','thursday','friday','saturday','sunday'];want=names.index(wd.group(1));delta=(want-now.weekday())%7
            if delta==0 and wd.group(0).lower().startswith('next '):delta=7
            due=(now+datetime.timedelta(days=delta)).replace(hour=9,minute=0,second=0,microsecond=0).timestamp()
            note=re.sub(r'^.*?\bremind\s+<@!?\d+>\s*','',message.content,flags=re.I)
            note=re.sub(r'\b(?:on|this|next)\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b','',note,flags=re.I).strip(' :,-')
            if note.lower().startswith('about '):note=note[6:].strip()
            await db.execute("INSERT INTO reminders(guild_id,user_id,channel_id,message,due_at,created_at,status) VALUES(?,?,?,?,?,?,?)",(gid,target.id,message.channel.id,note[:1000] or 'your reminder',due,time.time(),'pending'))
            await manifest_reply(message,f"⏰ Reminder set for {target.mention} on **{wd.group(1).title()}** at 9:00 AM.")
            return True

    # Mass or channel announcement: require Manage Server for everyone/here/role mentions.
    if re.search(r'\b(?:send|post|announce|ping|remind)\b',low) and re.search(r'\b(?:everyone|@everyone|@here|all members|all of us)\b',low):
        tm=await _parse_clock(message.content,gid)
        if tm is None:
            dur=await parse_human_duration(low)
            if dur is not None:tm=time.time()+dur
        if tm is None:return False
        mass=True
        if not server_manager(message.author):
            await manifest_reply(message,'⚠️ Scheduling a server-wide mention requires **Manage Server** or **Administrator**. Personal reminders do not.');return True
        mention='@here' if '@here' in low else '@everyone'
        em=re.search(r'\b(?:say|send|post|type|message)\s+(?:this\s+|exactly\s+)?["“]?(.+?)["”]?$',message.content,re.I)
        content=em.group(1).strip() if em else re.sub(r'^.*?\b(?:everyone|@everyone|@here|all members|all of us)\b\s*','',message.content,flags=re.I).strip(' :,-')
        if not content:content='Scheduled server announcement.'
        # Preserve exactly what the requester supplied after the scheduling phrase.
        content=content[:1900]
        ok,res=await schedule_announcement(message.guild,message.author,message.channel,tm,content,allow_everyone=True,allow_roles=False,tzname=await server_tz(gid))
        if ok:
            await manifest_reply(message,f"✅ Scheduled **{mention}** for <t:{int(tm)}:F> (<t:{int(tm)}:R>). Message preserved exactly as provided.")
        else:await manifest_reply(message,'❌ '+str(res))
        return True
    return False

async def discord_policy_allows_proactive_engagement(guild, feature):
    """Fail-closed gate for automated engagement-generation behavior.

    Discord policy prohibits automated messages whose purpose is to maintain or
    manufacture server activity. Useful user-requested, moderation, support,
    reminder, event and operational automation remains available elsewhere.
    """
    return False


async def proactive_culture_action(guild,now):
    # Never automate messages for the purpose of maintaining/manufacturing Discord
    # engagement. Keep this feature fail-closed while policy requires it.
    if not await discord_policy_allows_proactive_engagement(guild,'culture_revival'):return
    if not await db.setting(guild.id,'autopilot_enabled',1):return
    # Avoid repeated unsolicited messages. The server's normal activity still decides whether to speak.
    state=await db.one("SELECT value FROM delight_state WHERE guild_id=? AND key='last_proactive_at'",(guild.id,))
    if state and now-float(state['value'])<8*3600:return
    recent,online=await community_activity_score(guild)
    row=await db.one("SELECT last_message_at,last_revive_at FROM guild_activity WHERE guild_id=?",(guild.id,))
    if not row:return
    quiet=now-float(row['last_message_at'] or 0)
    # If only one person is around, do not pressure them just because chat is quiet.
    if online<=1:return
    if quiet<90*60:return
    ch=await semantic_best_channel(guild,'community',.70)
    if not ch:return
    policy=await channel_experience_policy(guild,ch)
    if not policy["allow_proactive_community"]:return
    # One low-pressure prompt, no mass ping, no fake activity.
    topics=await culture_learn(guild)
    prompt=f"💬 Quiet here for a bit — anyone around?" if not topics else f"💬 Quiet moment — anyone want to talk about **{topics.split(',')[0][:60]}**?"
    await ch.send(prompt,allowed_mentions=discord.AllowedMentions.none())
    await db.execute("INSERT INTO delight_state(guild_id,key,value,updated_at) VALUES(?,?,?,?) ON CONFLICT(guild_id,key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at",(guild.id,'last_proactive_at',str(now),now))


async def semantic_role_report(guild,purpose=None):
    if purpose:
        hits=await semantic_targets(guild,purpose,'role',.55)
        if hits:return "\n".join(f"• {r.mention} — **{round(conf*100)}% confidence**" for r,conf,_ in hits[:8])
        await rebuild_semantic_map(guild,False);hits=await semantic_targets(guild,purpose,'role',.55)
        return "\n".join(f"• {r.mention} — **{round(conf*100)}% confidence**" for r,conf,_ in hits[:8]) or "No confident role mapping yet."
    rows=await db.all("SELECT DISTINCT purpose FROM server_semantic_map WHERE guild_id=? AND object_type='role' ORDER BY purpose",(guild.id,))
    return "\n".join(f"• **{r['purpose'].replace('_',' ').title()}**" for r in rows) or "No role meanings mapped yet."

async def culture_teach_action(message):
    if not server_manager(message.author):return False
    t=message.content.strip()
    low=t.lower()
    # "Protocol is our rules channel" / "Protocol is the rules channel".
    m=re.search(r'^\s*["“]?([^"“”]+?)["”]?\s+is\s+(?:our|the)\s+(?:rules?|protocol)\s+channel\s*\.?$',t,re.I)
    if m:
        name=m.group(1).strip().lstrip('#');ch=discord.utils.find(lambda c:c.name.lower()==name.lower(),message.guild.text_channels)
        if not ch:await manifest_reply(message,f"I couldn't find a channel named **#{name}**. Tell me which channel you mean and I'll map its ID.");return True
        await _set_semantic_channel(message.guild,'rules',ch);await manifest_reply(message,f"🧠 Got it. {ch.mention} is your **rules/protocol** channel. I'll remember the channel ID if it gets renamed.");return True
    # "We call moderators Guardians" / "Our mods are Guardians".
    m=re.search(r'\b(?:we|our server)\s+(?:call|name)\s+(?:our\s+)?(?:mods?|moderators?|staff)\s+(?:the\s+)?["“]?([^"”]+?)["”]?\s*\.?$',t,re.I)
    if m:
        label=m.group(1).strip();await db.execute("INSERT INTO culture_signals(guild_id,key,value,score,updated_at) VALUES(?,?,?,?,?) ON CONFLICT(guild_id,key) DO UPDATE SET value=excluded.value,score=excluded.score,updated_at=excluded.updated_at",(message.guild.id,'moderator_term',label,.99,time.time()));await manifest_reply(message,f"🧠 Understood. I'll recognize **{label}** as your server's term for moderators.");return True
    return False

async def manifest_safe_repairs(guild):
    """Only repair stale references; never delete or overwrite user content."""
    repairs=[]
    row=await db.one("SELECT * FROM guild_settings WHERE guild_id=?",(guild.id,))
    if row:
        for label,col in LOGS.items():
            cid=int(row[col] or 0)
            if cid and not guild.get_channel(cid):
                await db.execute(f"UPDATE guild_settings SET {col}=0 WHERE guild_id=?",(guild.id,));repairs.append(f"Cleared stale {label} log reference")
    sec=await db.one("SELECT log_channel_id FROM security_config WHERE guild_id=?",(guild.id,))
    if sec and sec['log_channel_id'] and not guild.get_channel(sec['log_channel_id']):
        await db.execute("UPDATE security_config SET log_channel_id=0 WHERE guild_id=?",(guild.id,));repairs.append("Cleared stale security log reference")
    await rebuild_semantic_map(guild,deep=False)
    return repairs

