@manifest_ops_group.command(name="schedule_cancel",description="Cancel a pending scheduled announcement")
async def manifest_schedule_cancel(i:discord.Interaction,announcement_id:int):
    if not await manifest_server_operator(i.user):return await i.response.send_message("⚠️ Manifest operator access required.",ephemeral=True)
    r=await db.one("SELECT * FROM scheduled_announcements WHERE id=? AND guild_id=?",(announcement_id,i.guild_id))
    if not r or r['status'] not in ('scheduled','retry','failed','uncertain'):return await i.response.send_message("That announcement cannot be cancelled while it is being delivered or after delivery.",ephemeral=True)
    cur=await db.execute("UPDATE scheduled_announcements SET status='cancelled' WHERE id=? AND guild_id=? AND delivered=0 AND status IN ('scheduled','retry','failed','uncertain')",(announcement_id,i.guild_id))
    changed=int(getattr(cur,'rowcount',0) or 0)==1
    try: await cur.close()
    except Exception: pass
    if not changed:return await i.response.send_message("The announcement state changed before cancellation; refresh the scheduler and check its status.",ephemeral=True)
    try: await db.execute("INSERT INTO announcement_events(announcement_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(announcement_id,i.guild_id,i.user.id,'cancelled','',time.time()))
    except Exception: log.exception("Cancelled scheduled announcement %s but could not save its event",announcement_id)
    await i.response.send_message(f"🛑 Scheduled announcement `#{announcement_id}` cancelled.",ephemeral=True)

@manifest_ops_group.command(name="schedule_retry",description="Retry a failed or uncertain scheduled announcement")
async def manifest_schedule_retry(i:discord.Interaction,announcement_id:int,confirm_possible_duplicate:bool=False):
    if not await manifest_server_operator(i.user):return await i.response.send_message("⚠️ Manifest operator access required.",ephemeral=True)
    r=await db.one("SELECT status FROM scheduled_announcements WHERE id=? AND guild_id=?",(announcement_id,i.guild_id))
    if not r or r['status'] not in ('failed','uncertain'):
        return await i.response.send_message("Only failed or uncertain announcements can be retried.",ephemeral=True)
    if r['status']=='uncertain' and not confirm_possible_duplicate:
        return await i.response.send_message("⚠️ Delivery is uncertain. First check the destination channel for the original post. Set `confirm_possible_duplicate` to **True** only when you accept the possibility of a duplicate.",ephemeral=True)
    cur=await db.execute("UPDATE scheduled_announcements SET status='retry',due_at=?,last_error='',delivery_started_at=0 WHERE id=? AND guild_id=? AND delivered=0 AND status=?",(time.time(),announcement_id,i.guild_id,r['status']))
    changed=int(getattr(cur,'rowcount',0) or 0)==1
    try: await cur.close()
    except Exception: pass
    if not changed:return await i.response.send_message("The announcement changed state before retry was queued; refresh the scheduler.",ephemeral=True)
    try: await db.execute("INSERT INTO announcement_events(announcement_id,guild_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(announcement_id,i.guild_id,i.user.id,'retry_queued','duplicate-risk acknowledgement=' + str(bool(confirm_possible_duplicate)),time.time()))
    except Exception: log.exception("Scheduled announcement %s retry queued but its audit event could not be saved",announcement_id)
    await i.response.send_message(f"🔁 Announcement `#{announcement_id}` queued for retry.",ephemeral=True)

