# ========================= NATURAL-LANGUAGE ROUTING =========================
def continuation_action_request(text):
    """High-confidence follow-ups that should stay in the action pipeline when context exists."""
    t=(text or "").strip().lower()
    return bool(re.fullmatch(r"(?:yes[, ]*)?(?:confirm|confirm it|do it|go ahead|proceed|try|try again|retry|again|now try|undo|undo that)[.!]?",t,re.I))

class _ActionMessageProxy:
    """Read-only message wrapper used when AI normalizes wording for deterministic handlers.
    It changes only .content; Discord objects, author, guild, mentions and channel remain original.
    """
    def __init__(self, original, content):
        self._original=original
        self.content=content
    def __getattr__(self,name):
        return getattr(self._original,name)

async def ai_resolve_execution_plan(message):
    """AI understands varied wording but returns typed operations, never rewritten commands.
    Only capabilities implemented by the central executor are accepted. Every target is
    grounded against live Discord objects from the original message/context before execution.
    """
    if not activation_context_for(message):
        return False
    if not message.guild or (not xai and not ai) or ai_rate_limited(message):
        return False
    raw_text=clean_mention(message.content).strip()
    if not raw_text:return False
    g=message.guild
    channel_ids={c.id for c in getattr(message,'channel_mentions',[]) or []}
    member_ids={u.id for u in getattr(message,'mentions',[]) or [] if not bot.user or u.id!=bot.user.id}
    role_ids={r.id for r in getattr(message,'role_mentions',[]) or []}
    prompt=(
        "You are Manifest's intent resolver, not an executor. Convert an explicit Discord action request into typed operations. "
        "Return ONLY JSON with keys operations, confidence, clarification. Never rewrite the request into another English command. "
        "Allowed capabilities ONLY: channel.delete, channel.rename, channel.lock, channel.unlock, channel.slowmode, channel.create, category.create, role.create, role.assign, role.remove, moderation.ban, moderation.kick, moderation.timeout, moderation.warn. "
        "Each operation: {capability,target_id,target_type,params}. Use target_id=0 only for creation. "
        "For channel/member/role targets, use only IDs supplied in AVAILABLE TARGETS. Never invent IDs. "
        "For role.assign/remove, target_id is member ID and params.role_id must be an available role ID. "
        "For timeout, params.minutes must be an integer 1..40320. Preserve all requested targets: never collapse multiple targets to one. "
        "For channel.create/category.create/role.create, params.name must come from a name explicitly supplied by the user; compound goals like 'make logs and set them up' are NOT literal creation and should return no operations with clarification. "
        "If the request is a larger system goal (tickets/logging/security/rules/welcome/setup), unsupported by these atomic operations, return no operations so its dedicated system handler can own it. "
        "If essential information is missing or ambiguous, operations must be empty and clarification should be a short question. "
        f"AVAILABLE CHANNEL IDS: {sorted(channel_ids)}\nAVAILABLE MEMBER IDS: {sorted(member_ids)}\nAVAILABLE ROLE IDS: {sorted(role_ids)}\n"
        f"REQUEST: {raw_text[:1600]}"
    )
    raw=await model_text([{"role":"system","content":prompt},{"role":"user","content":raw_text[:1600]}],500)
    if not raw:return False
    try:
        import json
        mm=re.search(r'\{.*\}',raw,re.S);data=json.loads(mm.group(0)) if mm else {}
    except Exception:return False
    if float(data.get('confidence',0) or 0)<0.82:return False
    rows=data.get('operations') or []
    if not isinstance(rows,list) or not rows:
        q=str(data.get('clarification') or '').strip()
        if q:
            await manifest_reply(message,q[:500]);return True
        return False
    allowed={"channel.delete","channel.rename","channel.lock","channel.unlock","channel.slowmode","channel.create","category.create","role.create","role.assign","role.remove","moderation.ban","moderation.kick","moderation.timeout","moderation.warn"}
    ops=[]
    for row in rows[:12]:
        if not isinstance(row,dict):return False
        cap=str(row.get('capability') or '')
        if cap not in allowed:return False
        try:tid=int(row.get('target_id') or 0)
        except Exception:return False
        params=row.get('params') if isinstance(row.get('params'),dict) else {}
        typ=str(row.get('target_type') or '')
        if cap.startswith('channel.') and cap!='channel.create':
            # 'this channel' may resolve to the active channel; otherwise ID must be explicitly available.
            if tid==0 and re.search(r'\b(?:this|current)\s+channel\b',raw_text,re.I):tid=message.channel.id
            if tid not in channel_ids and tid!=message.channel.id:return False
            ch=g.get_channel(tid)
            if not ch:return False
            params.setdefault('name',ch.name)
        elif cap in {'moderation.ban','moderation.kick','moderation.timeout','moderation.warn'}:
            if tid not in member_ids:return False
            m=g.get_member(tid)
            if not m:return False
            params.setdefault('name',m.display_name)
            if cap=='moderation.timeout':
                try:mins=int(params.get('minutes',0))
                except Exception:return False
                if not 1<=mins<=40320:return False
                params['minutes']=mins
        elif cap in {'role.assign','role.remove'}:
            if tid not in member_ids:return False
            try:rid=int(params.get('role_id') or 0)
            except Exception:return False
            if rid not in role_ids:return False
            member=g.get_member(tid);role=g.get_role(rid)
            if not member or not role:return False
            params['role_id']=rid;params.setdefault('name',member.display_name);params.setdefault('label',f"{member.display_name} / {role.name}")
        elif cap in {'channel.create','category.create','role.create'}:
            name=str(params.get('name') or '').strip()
            if not name or len(name)>100:return False
            # Refuse suspicious trailing prose that used to become channel names.
            if re.search(r'\b(?:and set|and setup|and configure|set it up|configure it)\b',name,re.I):return False
            params['name']=name
        ops.append(ExecutionOperation(cap,tid,typ,params))
    if not ops:return False
    await audit_ai_action(g,message.author,'typed_intent_resolver',True,f"{raw_text[:500]} -> {[o.capability for o in ops]}")
    return await _queue_or_execute(message,ops,raw_text)


def explicit_action_request(text):
    """Strong signal that a message asks Manifest to perform an action.
    This lets authorized users use natural language outside the configured AI channel
    without turning ordinary conversation into commands.
    """
    t=(text or '').lower().strip()
    if not t: return False
    # Discord mentions are typed targets. <#...> is unambiguously a channel, so
    # natural requests like "delete <#123>" must not fall through to chat merely
    # because the user omitted the redundant noun "channel".
    if re.search(r"<#\d+>", t) and re.search(r"\b(?:delete|remove|rename|move|lock|unlock|slowmode|use|configure|set|change)\b", t, re.I):
        return True
    # Only verbs that can reasonably represent an explicit request to Manifest
    # belong here. Conversational verbs such as "tell", "show", "play", "say",
    # "choose" and "send" caused ordinary chat to look like commands.
    verbs=r"(?:create|make|build|set up|setup|configure|enable|disable|turn on|turn off|add|remove|give|assign|take|delete|rename|move|lock|unlock|slowmode|purge|clear|ban|kick|timeout|warn|unban|announce|schedule|start|stop|scan|inspect|analyze|fix|repair|apply|execute|run|organize|improve|remind|forget|remember|set|change|restore|close|claim|open)"
    objects=r"(?:channel|category|role|server|member|user|message|messages|ticket|autopilot|security|rules|welcome|support|event|announcement|setup|permissions|permission|slowmode|poll|giveaway|reminder|warnings|warning|invites|leaderboard|rank|avatar|profile|doctor|blueprint|verification|verify|lockdown|unlock|personality|automation|autoresponder|waitlist|boost|economy|coins|balance|daily|game|coin|dice|8ball|chess|snake|connect|tic|afk|birthday|birthdays|schedule|scheduled|everyone|culture|recognition|deadchat|activity)"
    return bool(re.search(rf"\b{verbs}\b.*\b{objects}\b",t,re.I) or re.search(rf"\b{verbs}\b\s+(?:this|the|my|our)?\s*{objects}\b",t,re.I))

async def build_owner_startup_report():
    """Owner-only boot intelligence. Failure to collect a metric never blocks readiness."""
    gateway=round(bot.latency*1000); guilds=len(bot.guilds); users=sum((g.member_count or 0) for g in bot.guilds)
    source=manifest_source_sha256()[:12]
    values={"incidents":0,"tickets":0,"uncertain":0,"pending":0}
    queries={
        "incidents":"SELECT COUNT(*) c FROM runtime_incidents WHERE status='open'",
        "tickets":"SELECT COUNT(*) c FROM tickets WHERE status IN ('open','claimed')",
        "uncertain":"SELECT (SELECT COUNT(*) FROM reminders WHERE status='uncertain') + (SELECT COUNT(*) FROM scheduled_announcements WHERE status='uncertain') c",
        "pending":"SELECT (SELECT COUNT(*) FROM reminders WHERE status IN ('pending','retry')) + (SELECT COUNT(*) FROM scheduled_announcements WHERE status IN ('scheduled','retry')) c",
    }
    for key,q in queries.items():
        try:
            row=await db.one(q);values[key]=int(row['c'] or 0) if row else 0
        except Exception:log.exception("Startup metric failed: %s",key)
    configured_ai=sum(bool(x) for x in (ai,(CLOUDFLARE_API_TOKEN and CLOUDFLARE_ACCOUNT_ID),xai,OPENROUTER_API_KEY))
    attention=[]
    if values['incidents']:attention.append(f"{values['incidents']} open runtime incident(s)")
    if values['uncertain']:attention.append(f"{values['uncertain']} uncertain delivery record(s)")
    state="Healthy" if not attention else "Attention recommended"
    lines=[
        f"**{BUILD_LABEL}** is ready.",
        ("Your latest Manifest build came up clean." if not attention else "Manifest is online, but there are a few things worth reviewing."),
        f"State: **{state}** · Gateway: **{gateway}ms** · Database: **ready**",
        f"Reach: **{guilds} guild(s)** · ~**{users} members**",
        f"AI routes configured: **{configured_ai}** · Source: `{source}`",
        f"Support: **{values['tickets']} active ticket(s)** · Scheduled work: **{values['pending']} pending**",
        f"Diagnostics: **{values['incidents']} open incident(s)** · **{values['uncertain']} uncertain delivery(s)**",
        "",
        "**This build changed**",
        *[f"• {x}" for x in RELEASE_HIGHLIGHTS[:4]],
        "",
        "Use `/manifest home`, `/manifest updates changelog`, or `/manifest hub` for the full control surfaces.",
    ]
    return "\n".join(lines)[:3900]

# ========================= EVENTS =========================
@bot.event
async def on_ready():
    for g in bot.guilds:
        try:
            await db.ensure(g.id)
            try: invite_cache[g.id]={x.code:x.uses for x in await g.invites()}
            except discord.HTTPException: invite_cache[g.id]={}
            row=await db.one("SELECT scanned,announced FROM guild_onboarding WHERE guild_id=?",(g.id,))
            if not row or not row["scanned"]:
                await update_server_needs(g)
            # Never announce startup in an arbitrary writable channel. Readiness is operational, not community content.
            if not row or not row["announced"]:
                await db.execute("INSERT INTO guild_onboarding(guild_id,announced,scanned,updated_at) VALUES(?,?,?,?) ON CONFLICT(guild_id) DO UPDATE SET announced=1,scanned=1,updated_at=excluded.updated_at",(g.id,1,1,time.time()))
        except Exception: log.exception("Ready bootstrap failed for guild %s",g.id)
    try:
        await startup_reconcile_state()
        rr=await db.one("SELECT value FROM manifest_runtime_state WHERE key='pending_restart'")
        if rr and rr['value']:
            data=json.loads(rr['value'])
            checks=await deep_health_snapshot()
            blocking=[name for name,state,_ in checks if state=='unavailable' and name in {'gateway','database'}]
            data['ready_at']=time.time(); data['health']=checks
            data['completed']=not blocking
            if data['completed']:
                data['completed_at']=time.time()
                log.info("Restart receipt %s completed after ready + core health checks",data.get('receipt','unknown'))
            else:
                data['completion_error']='core health unavailable: '+', '.join(blocking)
                log.error("Restart receipt %s reached ready but failed core health gate: %s",data.get('receipt','unknown'),blocking)
            await db.execute("UPDATE manifest_runtime_state SET value=?,updated_at=? WHERE key='pending_restart'",(json.dumps(data),time.time()))
    except Exception as ex:
        log.exception("Restart receipt completion failed")
        try: await diag_issue('runtime',ex,'error',trace_id='')
        except Exception: pass
    log.info("Manifest V%s online as %s | %s guilds | ownership: %s",VERSION,bot.user,len(bot.guilds),OWNER_NAMES)
    await ensure_release_note()
    try:
        await manifest_notify_owners('health',await build_owner_startup_report(),subject='🟢 Manifest Ready · Creator Control',dedupe_key=f'boot:{RELEASE_ID}:{int(time.time()//3600)}',cooldown=3600)
    except Exception:
        log.exception('Owner startup notification failed')
    # Warm Groq model discovery outside the first user reply. This is best-effort
    # and intentionally does not block Discord readiness.
    if ai:
        async def _warm_ai_provider():
            try: await resolve_groq_model()
            except Exception: log.exception("AI provider warm-up failed")
        supervise_task(_warm_ai_provider(),name='ai-provider-warmup')
    estimated_users=sum((g.member_count or 0) for g in bot.guilds)
    if estimated_users>=10000 and intents.message_content:
        log.warning("Discord privileged-intent review threshold may apply: estimated reachable users >= 10,000. Review current Discord requirements before scaling further.")

@bot.event
async def on_member_join(m):
    # Autopilot welcome is combined with invite/anti-raid handling so Discord only registers one join handler.
    try:
        c=await db.one("SELECT * FROM autopilot_config WHERE guild_id=?",(m.guild.id,))
        if c and c['welcome_enabled']:
            # Welcome messages are proactive content: never guess an arbitrary writable
            # destination. No explicitly configured welcome channel means silence.
            ch=m.guild.get_channel(c['welcome_channel_id']) if c['welcome_channel_id'] else None
            if isinstance(ch,discord.TextChannel):
                msg=c['welcome_message'] or "👋 Welcome {user} to **{server}**!"
                msg=msg.replace("{user}",m.mention).replace("{server}",m.guild.name)
                await ch.send(msg[:1900],allowed_mentions=discord.AllowedMentions(users=True,roles=False,everyone=False))
    except Exception:log.exception("Autopilot welcome failed")
    now=time.time();desc=f"{m.mention} joined."
    try:
        now_invites=await m.guild.invites();before=invite_cache.get(m.guild.id,{})
        used=next((x for x in now_invites if x.uses>before.get(x.code,0)),None);invite_cache[m.guild.id]={x.code:x.uses for x in now_invites}
        if used and used.inviter:
            desc+=f"\nInvited by {used.inviter.mention}."
            await db.execute("INSERT INTO invites VALUES(?,?,1) ON CONFLICT(guild_id,user_id) DO UPDATE SET uses=uses+1",(m.guild.id,used.inviter.id))
            await db.execute("INSERT INTO invite_events(guild_id,inviter_id,member_id,event_type,created_at) VALUES(?,?,?,?,?)",(m.guild.id,used.inviter.id,m.id,'join',now))
            try: await reconcile_invite_reward(m.guild,used.inviter.id)
            except Exception: log.exception('Invite reward reconciliation')
    except discord.HTTPException:pass
    day=datetime.datetime.now(datetime.timezone.utc).date().isoformat()
    await db.execute("INSERT INTO guild_daily_metrics(guild_id,day,joins) VALUES(?,?,1) ON CONFLICT(guild_id,day) DO UPDATE SET joins=joins+1",(m.guild.id,day))
    await db.execute("INSERT INTO member_presence_events(guild_id,user_id,event_type,created_at) VALUES(?,?,?,?)",(m.guild.id,m.id,'join',now))
    await elog(m.guild,"arrival","📥 Member Joined",desc,target=m)
    # Anti-raid: count joins in a rolling window; owners/admins are never punished by this detector.
    try:
        c=await get_security(m.guild.id)
        q=join_burst[m.guild.id];q.append(now)
        jq=join_burst_members[m.guild.id];jq.append((now,m.id))
        while q and now-q[0]>c['join_window']:q.popleft()
        while jq and now-jq[0][0]>c['join_window']:jq.popleft()
        if c['anti_raid'] and len(q)>=c['join_limit']:
            cohort=[]
            for _,uid in list(jq):
                member=m.guild.get_member(uid)
                if member:cohort.append(member)
            await security_event(m.guild,'raid_detected',target_id=m.id,details=f"{len(q)} joins in {c['join_window']} seconds")
            await elog(m.guild,'security','🚨 Anti-Raid Triggered',f"{len(q)} joins detected in {c['join_window']} seconds. Manifest entered quarantine-first protection.",target=m)
            incident_id=await open_security_incident(m.guild,f"Anti-Raid detected {len(q)} joins in {c['join_window']} seconds.",'high',m.id,bot.user.id if bot.user else 0,'watch',f"join_burst={len(q)} window={c['join_window']}s cohort={len(cohort)}")
            # The incident starts as evidence; only successful containment advances it.
            if len(q)>=c['join_limit']*2:
                await guardian_escalate_incident(m.guild,incident_id,"Join burst doubled the configured anti-raid threshold.","restrict")
            contained=await guardian_raid_cohort(m.guild,incident_id,cohort,f"Anti-Raid quarantine: {len(q)} joins in {c['join_window']} seconds")
            # If evidence is not strong enough for cohort quarantine, contain only the trigger member.
            if not contained and m.id!=m.guild.owner_id and not m.bot:
                ok,msg=await quarantine_member(m.guild,m,incident_id,bot.user.id if bot.user else 0,f"Anti-Raid trigger quarantine: {len(q)} joins in {c['join_window']} seconds")
                await incident_action(incident_id,m.guild.id,bot.user.id if bot.user else 0,'raid_quarantine' if ok else 'raid_quarantine_failed',m.id,msg)
            # Lockdown is an escalation for an active raid, not the punishment mechanism.
            if c['auto_lockdown'] and (len(q)>=c['join_limit']*2 or contained>=3):
                await lockdown(m.guild,f"Anti-Raid escalation: {len(q)} joins in {c['join_window']} seconds; {contained} suspicious accounts quarantined")
    except Exception:log.exception("Anti-raid join detection")
    # Typed workflow automations run independently of AI.
    try: await run_typed_automations(m.guild,'member_join',{'user_id':m.id,'account_age_days':max(0,(discord.utils.utcnow()-m.created_at).days),'_event_key':f"member_join:{m.id}:{int(m.joined_at.timestamp()) if m.joined_at else int(now)}"})
    except Exception: log.exception('Typed member-join automations')
    # Custom join automations.
    try:
        rows=await db.all("SELECT * FROM custom_automations WHERE guild_id=? AND enabled=1 AND action IN ('join_message','join_ping')",(m.guild.id,))
        for a in rows:
            if a['trigger'] and a['trigger'].lower() not in ('*','join'):continue
            payload=a['payload'].replace('{user}',m.mention).replace('{server}',m.guild.name)
            if a['action']=='join_ping':
                ch=m.guild.get_channel(int(a['trigger'])) if str(a['trigger']).isdigit() else m.guild.system_channel
                if isinstance(ch,discord.TextChannel):await ch.send(payload[:1900],allowed_mentions=discord.AllowedMentions(users=True))
            else:
                ch=m.guild.system_channel
                if isinstance(ch,discord.TextChannel):await ch.send(payload[:1900],allowed_mentions=discord.AllowedMentions(users=True))
    except Exception:log.exception("Join automations")
