@tasks.loop(minutes=2)
async def quarantine_reconciliation_loop():
    """Reconcile temporary timeout quarantine without restoring roles automatically.

    Discord owns timeout expiry. Manifest records when the timeout is no longer
    active, distinguishing a live member fetch from an absent local cache. This
    does not assume whether a cleared timeout was manually removed or expired.
    Role-based quarantines remain active until authorized recovery.
    """
    try:
        now=time.time()
        rows=await db.all("SELECT * FROM quarantine_snapshots WHERE status IN ('active','partial') AND containment_mode='timeout' ORDER BY id ASC LIMIT 100")
        for snap in rows:
            try:
                guild=bot.get_guild(int(snap['guild_id']))
                # A cold member cache is not evidence that the member left or
                # that a timeout expired. Only a live fetch can establish this.
                if not guild:
                    continue
                ending_reason=""
                try:
                    member=await guild.fetch_member(int(snap['user_id']))
                except discord.NotFound:
                    expired=True;ending_reason="member is no longer in the server"
                except (discord.Forbidden,discord.HTTPException):
                    continue
                else:
                    until=getattr(member,'communication_disabled_until',None)
                    if until is None:
                        expired=True;ending_reason="timeout is no longer active (it may have expired or been cleared)"
                    elif until.timestamp() <= now:
                        expired=True;ending_reason="temporary timeout naturally expired"
                    else:
                        expired=False
                if not expired:
                    continue
                await db.execute("UPDATE quarantine_snapshots SET status='expired',restored_at=COALESCE(restored_at,?) WHERE id=? AND status IN ('active','partial')",(now,snap['id']))
                await incident_action(int(snap['incident_id']),guild.id,bot.user.id if bot.user else 0,'quarantine_expired',int(snap['user_id']),f"Temporary timeout containment ended: {ending_reason}. No roles were restored automatically.")
                await guardian_recovery_review(guild,int(snap['incident_id']))
            except Exception:
                log.exception("Quarantine reconciliation failed for snapshot %s",snap.get('id'))
        incidents=await db.all("SELECT id,guild_id FROM security_incidents WHERE state IN ('quarantine','restrict','lockdown') ORDER BY id DESC LIMIT 50")
        for inc in incidents:
            guild=bot.get_guild(int(inc['guild_id']))
            if guild: await guardian_recovery_review(guild,int(inc['id']))
    except Exception as e:
        await _record_loop_failure('quarantine_reconciliation_loop',e)

@quarantine_reconciliation_loop.error
async def quarantine_reconciliation_loop_error(error): await _record_loop_failure('quarantine_reconciliation_loop',error)

@quarantine_reconciliation_loop.before_loop
async def quarantine_reconciliation_before(): await bot.wait_until_ready()

@tasks.loop(minutes=2)
async def diagnostics_loop():
    """Low-noise internal watchdog. It records health/errors; it never mutates guild roles or permissions."""
    try:
        checks=await deep_health_snapshot()
        integrity_ok,integrity_findings=await cross_system_integrity_snapshot()
        health_payload={"health":checks,"integrity":{"passed":len(integrity_ok),"findings":integrity_findings[:25]}}
        await db.execute("INSERT INTO manifest_runtime_state(key,value,updated_at) VALUES('last_health',?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at",(json.dumps(health_payload,separators=(',',':')),time.time()))
        # Fold buffered ERROR/CRITICAL lines into a persistent grouped inbox.
        seen=set()
        for line in list(OP_LOGS)[-120:]:
            if '| ERROR |' not in line and '| CRITICAL |' not in line: continue
            fp=hashlib.sha256(line.encode()).hexdigest()[:20]
            if fp in seen or fp in DIAG_INGESTED: continue
            seen.add(fp); DIAG_INGESTED.add(fp)
            if len(DIAG_INGESTED)>2000: DIAG_INGESTED.clear(); DIAG_INGESTED.add(fp)
            await diag_issue('runtime_log',line,'critical' if '| CRITICAL |' in line else 'error')
        # Bound detailed traces while keeping grouped issue history.
        await db.execute("DELETE FROM diagnostic_traces WHERE created_at<?",(time.time()-86400*14,))
        await db.execute("DELETE FROM manifest_quality_events WHERE created_at<?",(time.time()-86400*30,))
    except Exception as ex:
        log.exception("Diagnostics watchdog failed")
        try: await diag_issue('diagnostics',ex,'critical')
        except Exception: pass

async def _record_loop_failure(loop_name:str,error:BaseException):
    """tasks.loop error sink: persist failures instead of leaving a dead worker invisible."""
    try:
        tid=await diag_trace_start('background_task',loop_name)
        await diag_trace_stage(tid,'background loop',False,type(error).__name__)
        await diag_issue(loop_name,error,'critical',trace_id=tid)
    except Exception:
        log.exception("Could not persist %s loop failure",loop_name)

@diagnostics_loop.error
async def diagnostics_loop_error(error): await _record_loop_failure('diagnostics_loop',error)

@diagnostics_loop.before_loop
async def diagnostics_before(): await bot.wait_until_ready()

@tasks.loop(minutes=5)
async def autopilot_loop():
    now=time.time()
    for cache in (ai_cooldowns, adaptive_context):
        for k,v in list(cache.items()):
            stamp=v if isinstance(v,(int,float)) else (v[1] if isinstance(v,tuple) and len(v)>1 else now)
            if now-stamp>ADAPTIVE_CONTEXT_TTL: cache.pop(k,None)
    # Keep security history bounded; this prevents SQLite growth from becoming the new bottleneck.
    try:
        await db.execute("DELETE FROM security_events WHERE created_at<?",(now-86400*7,))
    except Exception:log.exception("Security cleanup")
    for g in bot.guilds:
        try:
            await db.execute("INSERT OR IGNORE INTO autopilot_config(guild_id) VALUES(?)",(g.id,))
            needs=await db.one("SELECT updated_at FROM server_needs WHERE guild_id=?",(g.id,))
            if not needs or now-needs["updated_at"]>21600:
                await update_server_needs(g)
            await learn_semantic_map(g)
            try: await rebuild_semantic_map(g,deep=False)
            except Exception: log.exception("Semantic map %s",g.id)
            await proactive_revival(g,now)
            await proactive_culture_action(g,now)
            await culture_learn(g)
            await recognition_tick(g)
        except Exception:log.exception("Autopilot guild %s",g.id)

    try:
        await deliver_scheduled_announcements(now)
        await birthday_tick(now)
        await event_reminder_tick(now)
    except Exception:log.exception("Scheduler/community tick failed")

@autopilot_loop.before_loop
async def autopilot_before():await bot.wait_until_ready()

@tasks.loop(seconds=20)
async def giveaway_loop():
    await process_giveaway_announcement_outbox()
    rows=await db.all("SELECT * FROM giveaways WHERE ended=0 AND ends_at<=?",(time.time(),))
    for r in rows:
        try:
            ch=bot.get_channel(r["channel_id"])
            if not ch: continue
            await finish_giveaway(r,ch,actor_id=0,event_type="ended")
        except Exception:log.exception("Giveaway %s",r["id"])

async def deliver_giveaway_announcement(announcement_id:int):
    """Deliver one giveaway result with a leased, restart-safe idempotency marker."""
    row=await db.one("SELECT * FROM giveaway_announcements WHERE id=?",(int(announcement_id),))
    if not row: return False
    if row['status']=='delivered': return True
    if row['status'] in {'failed','uncertain'}: return False
    now=time.time(); token=uuid.uuid4().hex; prior_attempts=int(row['attempts'] or 0)
    cur=await db.execute(
        "UPDATE giveaway_announcements SET status='sending',attempts=attempts+1,lease_until=?,claim_token=? "
        "WHERE id=? AND ((status IN ('pending','retry') AND next_attempt_at<=?) OR (status='sending' AND lease_until<=?))",
        (now+90,token,int(announcement_id),now,now)
    )
    claimed=int(getattr(cur,'rowcount',0) or 0)==1
    try: await cur.close()
    except Exception: pass
    if not claimed: return False

    async def set_state(status,error='',*,message_id=0,delay=0):
        try:
            await db.execute(
                "UPDATE giveaway_announcements SET status=?,last_error=?,message_id=CASE WHEN ?>0 THEN ? ELSE message_id END,"
                "delivered_at=CASE WHEN ?='delivered' THEN ? ELSE delivered_at END,next_attempt_at=?,lease_until=0,claim_token='' "
                "WHERE id=? AND claim_token=?",
                (status,str(error)[:500],int(message_id or 0),int(message_id or 0),status,time.time(),time.time()+max(0,int(delay)),int(announcement_id),token)
            )
        except Exception:
            log.exception("Could not persist giveaway announcement state id=%s status=%s",announcement_id,status)

    channel=bot.get_channel(int(row['channel_id']))
    if not channel:
        try: channel=await bot.fetch_channel(int(row['channel_id']))
        except discord.NotFound:
            await set_state('failed','Giveaway announcement channel no longer exists.')
            return False
        except discord.Forbidden:
            await set_state('failed','Manifest cannot access the giveaway announcement channel.')
            return False
        except Exception as ex:
            delay=min(3600,30*(2**min(prior_attempts,7)))
            await set_state('retry',f'{type(ex).__name__}: {_safe_diag_text(ex,350)}',delay=delay)
            return False

    marker=f"Manifest giveaway delivery · {row['event_key']}"
    # On every retry/recovery, look for the unique footer before sending. This
    # closes the crash window where Discord accepted the message but SQLite did
    # not save the returned message ID/status.
    if prior_attempts>0:
        try:
            scanned=0; found=None
            after=datetime.datetime.fromtimestamp(max(0,float(row['created_at'] or now)-30),datetime.timezone.utc)
            async for message in channel.history(limit=100,after=after):
                scanned+=1
                if bot.user and getattr(getattr(message,'author',None),'id',0)!=bot.user.id: continue
                if any(marker in str(getattr(getattr(embed,'footer',None),'text','') or '') for embed in getattr(message,'embeds',())):
                    found=message; break
            if found:
                await set_state('delivered','Recovered by finding the already-sent announcement.',message_id=found.id)
                return True
            if scanned>=100:
                await set_state('uncertain','More than 100 recent messages were found; duplicate delivery cannot be ruled out safely.')
                return False
        except Exception as ex:
            await set_state('uncertain',f'Could not inspect channel history before retry: {type(ex).__name__}: {_safe_diag_text(ex,300)}')
            return False

    try:
        title=f"Giveaway #{row['giveaway_id']} {'ended' if row['event_type']=='ended' else 'rerolled'}"
        embed=discord.Embed(title=title,description=str(row['content'])[:4000],color=discord.Color.gold())
        embed.set_footer(text=marker[:200])
        message=await channel.send(embed=embed,allowed_mentions=discord.AllowedMentions(users=True))
    except (discord.Forbidden,discord.NotFound) as ex:
        await set_state('failed',f'{type(ex).__name__}: {_safe_diag_text(ex,350)}')
        return False
    except discord.HTTPException as ex:
        status_code=int(getattr(ex,'status',0) or 0)
        if 400<=status_code<500 and status_code!=429:
            await set_state('failed',f'{type(ex).__name__} {status_code}: {_safe_diag_text(ex,350)}')
        else:
            delay=min(3600,30*(2**min(prior_attempts,7)))
            await set_state('retry',f'{type(ex).__name__} {status_code or "unknown"}: {_safe_diag_text(ex,350)}',delay=delay)
        return False
    except Exception as ex:
        delay=min(3600,30*(2**min(prior_attempts,7)))
        await set_state('retry',f'{type(ex).__name__}: {_safe_diag_text(ex,350)}',delay=delay)
        return False

    # Once channel.send returns, Discord has accepted the announcement. If the
    # receipt write fails, leave the lease in place so the next worker can find
    # the marker in channel history instead of blindly sending it again.
    try:
        await set_state('delivered','',message_id=message.id)
    except Exception:
        log.exception("Giveaway %s announcement sent but receipt persistence failed",row['giveaway_id'])
        return False
    return True


async def process_giveaway_announcement_outbox(limit=20):
    now=time.time()
    rows=await db.all(
        "SELECT id FROM giveaway_announcements WHERE (status IN ('pending','retry') AND next_attempt_at<=?) "
        "OR (status='sending' AND lease_until<=?) ORDER BY created_at LIMIT ?",
        (now,now,max(1,min(int(limit),50)))
    )
    for row in rows:
        try: await deliver_giveaway_announcement(int(row['id']))
        except Exception: log.exception("Giveaway announcement outbox item %s failed",row['id'])


