@tasks.loop(seconds=20)
async def reminder_loop():
    now=time.time()
    # A worker crash or lost DB receipt after a possible send must not cause an
    # automatic duplicate. Stale in-flight deliveries become explicitly uncertain.
    stale=await db.all("SELECT id FROM reminders WHERE delivered=0 AND status='sending' AND delivery_started_at>0 AND delivery_started_at<=?",(now-900,))
    for item in stale:
        try:
            await db.execute("UPDATE reminders SET status='uncertain',last_error=? WHERE id=? AND delivered=0 AND status='sending' AND delivery_started_at<=?",
                             ('Delivery outcome is uncertain after an interrupted send. Check the original channel before retrying.',item['id'],now-900))
        except Exception: log.exception("Could not mark interrupted reminder %s as uncertain",item['id'])

    rows=await db.all("SELECT * FROM reminders WHERE delivered=0 AND status IN ('pending','retry') AND due_at<=? ORDER BY due_at LIMIT 25",(now,))
    for r in rows:
        # Cross-process compare-and-set: only one worker can start this delivery.
        try:
            claim=await db.execute("UPDATE reminders SET status='sending',delivery_started_at=?,attempts=attempts+1,last_error='' WHERE id=? AND delivered=0 AND status IN ('pending','retry') AND due_at<=?",
                                   (now,r['id'],now))
            acquired=int(getattr(claim,'rowcount',0) or 0)==1
            try: await claim.close()
            except Exception: pass
        except Exception:
            log.exception("Could not claim reminder delivery %s",r['id'])
            continue
        if not acquired: continue

        ch=bot.get_channel(r['channel_id'])
        if not ch:
            try: ch=await bot.fetch_channel(r['channel_id'])
            except (discord.NotFound,discord.Forbidden,discord.HTTPException): ch=None
        if not ch:
            err='original channel missing or inaccessible'
            try: await db.execute("UPDATE reminders SET status='failed',last_error=? WHERE id=? AND status='sending'",(err,r['id']))
            except Exception: log.exception("Could not persist missing-channel reminder failure %s",r['id'])
            try: await db.execute("INSERT INTO reminder_events(reminder_id,guild_id,user_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(r['id'],r['guild_id'],r['user_id'],'failed',err,time.time()))
            except Exception: log.exception("Could not journal failed reminder %s",r['id'])
            continue

        # Do not send if the owner cancelled while this delivery was being claimed.
        current=await db.one("SELECT status,delivered FROM reminders WHERE id=?",(r['id'],))
        if not current or current['status']!='sending' or current['delivered']:
            continue
        try:
            await ch.send(f"<@{r['user_id']}> ⏰ {r['message']}",allowed_mentions=discord.AllowedMentions(users=True))
        except (discord.Forbidden,discord.NotFound) as ex:
            err=f'{type(ex).__name__}: {str(ex)[:300]}'
            try: await db.execute("UPDATE reminders SET status='failed',last_error=? WHERE id=? AND status='sending'",(err,r['id']))
            except Exception: log.exception("Could not persist failed reminder send %s",r['id'])
            try: await db.execute("INSERT INTO reminder_events(reminder_id,guild_id,user_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(r['id'],r['guild_id'],r['user_id'],'failed',err,time.time()))
            except Exception: log.exception("Could not journal failed reminder %s",r['id'])
            log.warning("Reminder delivery rejected: %s (%s)",r['id'],type(ex).__name__)
            continue
        except discord.HTTPException as ex:
            err=f'{type(ex).__name__}: {str(ex)[:300]}'
            status='failed' if 400<=int(getattr(ex,'status',0) or 0)<500 else 'uncertain'
            message=err if status=='failed' else err+'; delivery may have reached Discord, so automatic retry was stopped.'
            try: await db.execute("UPDATE reminders SET status=?,last_error=? WHERE id=? AND status='sending'",(status,message,r['id']))
            except Exception: log.exception("Could not persist ambiguous reminder send %s",r['id'])
            try: await db.execute("INSERT INTO reminder_events(reminder_id,guild_id,user_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(r['id'],r['guild_id'],r['user_id'],status,message,time.time()))
            except Exception: log.exception("Could not journal ambiguous reminder %s",r['id'])
            log.warning("Reminder delivery did not return a definitive success: %s (%s)",r['id'],type(ex).__name__)
            continue
        except Exception as ex:
            err=f'{type(ex).__name__}: {str(ex)[:300]}; delivery outcome is uncertain.'
            try: await db.execute("UPDATE reminders SET status='uncertain',last_error=? WHERE id=? AND status='sending'",(err,r['id']))
            except Exception: log.exception("Could not persist uncertain reminder send %s",r['id'])
            try: await db.execute("INSERT INTO reminder_events(reminder_id,guild_id,user_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(r['id'],r['guild_id'],r['user_id'],'uncertain',err,time.time()))
            except Exception: log.exception("Could not journal uncertain reminder %s",r['id'])
            log.exception("Reminder %s has an uncertain delivery outcome",r['id'])
            continue

        # Successful send is the delivery boundary. A DB receipt failure must
        # leave the row in 'sending' (later 'uncertain'), never pending for resend.
        try:
            await db.execute("UPDATE reminders SET delivered=1,status='delivered',delivered_at=?,last_error='' WHERE id=? AND status='sending'",(time.time(),r['id']))
        except Exception:
            log.exception("Reminder %s was sent but its delivery receipt could not be saved; automatic resend is blocked",r['id'])
            continue
        try:
            await db.execute("INSERT INTO reminder_events(reminder_id,guild_id,user_id,event_type,details,created_at) VALUES(?,?,?,?,?,?)",(r['id'],r['guild_id'],r['user_id'],'delivered','reminder delivered',time.time()))
        except Exception: log.exception("Reminder %s was delivered but its event journal failed",r['id'])

    await db.execute("DELETE FROM afk_status WHERE until_at>0 AND until_at<=?",(now,))

@reminder_loop.before_loop
async def reminder_before():await bot.wait_until_ready()

