@reminder_loop.error
async def reminder_loop_error(error): await _record_loop_failure('reminder_loop',error)

MANIFEST_HTML = """<!doctype html>
<html lang=\"en\">
<head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manifest — Discord Server Intelligence</title>
<style>body{margin:0;background:#080b12;color:#eef2ff;font-family:Inter,system-ui,sans-serif}a{color:#8fb7ff;text-decoration:none}.wrap{max-width:1050px;margin:auto;padding:56px 22px}.hero{padding:38px;border:1px solid #20283a;border-radius:24px;background:#0d1220}.pill{display:inline-block;padding:7px 11px;border:1px solid #2a3854;border-radius:999px;color:#9db8e8}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin-top:20px}.card{padding:22px;border:1px solid #20283a;border-radius:18px;background:#0b101b}.nav{display:flex;gap:18px;flex-wrap:wrap;margin:24px 0}.muted{color:#9aa6bd}.btn{display:inline-block;padding:11px 15px;border-radius:10px;background:#eef2ff;color:#0a0d14;font-weight:700;margin-right:8px}</style></head>
<body><div class=\"wrap\"><div class=\"nav\"><a href=\"/\">Manifest</a><a href=\"/dashboard\">Dashboard</a><a href=\"/security\">Security</a><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/team\">Team</a><a href=\"/status\">Status</a><a href=\"/capabilities\">Capabilities</a></div>{content}</div></body></html>"""

def page(title, body):
    return web.Response(text=MANIFEST_HTML.replace('{content}', f'<h1>{title}</h1>'+body),content_type='text/html')

async def home_page(_):
    return page('Manifest', '<p class=\"muted\">AI-powered Discord server management, security, automation and community tooling.</p><p><a class=\"btn\" href=\"/dashboard\">Open Dashboard</a><a class=\"btn\" href=\"/security\">Security</a></p><div class=\"grid\"><div class=\"card\"><h2>🛡️ Security</h2><p>Anti-raid, anti-nuke, verification, monitoring and lockdown tooling.</p></div><div class=\"card\"><h2>🤖 AI</h2><p>Natural-language server assistance with permission-aware execution.</p></div><div class=\"card\"><h2>⚙️ Management</h2><p>Channels, roles, moderation, tickets, automation and server health.</p></div></div>')

async def dashboard_page(_):
    client_id=os.getenv('DISCORD_CLIENT_ID','').strip()
    invite=''
    if client_id:
        invite=f'<a class=\"btn\" href=\"https://discord.com/oauth2/authorize?client_id={client_id}&permissions={os.getenv('MANIFEST_INVITE_PERMISSIONS','0')}&scope=bot%20applications.commands\">Add Manifest</a>'
    return page('Manifest Dashboard', f'<p class=\"muted\">A transparent control center for server owners. Discord OAuth is only linked when configured by the deployment.</p><div class=\"grid\"><div class=\"card\"><h2>🛡️ Security</h2><p>Anti-Raid · Anti-Nuke · Verification · Lockdown</p></div><div class=\"card\"><h2>🤖 AI & Autopilot</h2><p>Natural language controls, server health and owner-defined automation.</p></div><div class=\"card\"><h2>🎫 Support</h2><p>Tickets, reports, forms and support workflows.</p></div><div class=\"card\"><h2>📊 Server Health</h2><p>Configuration gaps, missing permissions and security status.</p></div></div><p>{invite}</p>')

async def security_page(_):
    return page('Manifest Security', '<p class=\"muted\">Manifest is designed to respect Discord permissions and verify actions rather than pretending an action succeeded.</p><div class=\"grid\"><div class=\"card\"><h3>Anti-Raid</h3><p>Join-spike detection, configurable thresholds and optional lockdown.</p></div><div class=\"card\"><h3>Anti-Nuke</h3><p>Monitor high-risk server changes and record security events.</p></div><div class=\"card\"><h3>Recovery</h3><p>Snapshots and lockdown backups can help restore Manifest-managed configuration.</p></div></div>')

async def privacy_page(_):
    return page('Manifest Privacy', '<p>Manifest only uses Discord data needed to provide its configured functionality. Personal memory is opt-in where supported, and users can clear stored personal memory.</p><div class=\"card\"><h3>Data principles</h3><ul><li>No hidden psychological profiling.</li><li>No claiming access to private information Manifest cannot actually access.</li><li>AI is used to assist functionality, not as a secret training dataset of Discord messages.</li><li>Server owners control server configuration and automation.</li><li>Permissions are checked before server mutations.</li></ul></div><p class=\"muted\">Deployment operators should update this page with their actual retention periods, subprocessors and contact details before production use.</p>')

async def terms_page(_):
    return page('Manifest Terms', '<p>Use Manifest only in servers where you are authorized to configure or moderate the server. Server owners and staff remain responsible for the actions they authorize.</p><p class=\"muted\">This is a product placeholder and should be reviewed for your actual legal entity, jurisdiction and policies before public launch.</p>')

async def team_page(_):
    return page('Manifest Team', '<div class=\"grid\"><div class=\"card\"><h2>thunderxstorms5_.</h2><p>Creator</p></div><div class=\"card\"><h2>alemorci</h2><p>Co-Owner</p></div><div class=\"card\"><h2>Configured Developer</h2><p>Developer access is deployment-configured</p></div></div>')

async def capabilities_page(_):
    body='<div class="grid">'+''.join(f'<div class="card"><h3>{k}</h3><p>{v}</p></div>' for k,v in HELP_CATEGORIES.items())+'</div>'
    return page('Manifest Capabilities',body)

async def status_page(_):
    state='Operational' if bot.is_ready() else 'Starting'
    return page('Manifest Status',f'<div class="card"><h2>{state}</h2><p>Version {VERSION} · {len(bot.guilds)} connected server(s) · Discord latency {round(bot.latency*1000)} ms</p></div>')

async def health(_):
    return web.json_response({"status":"ready" if bot.is_ready() else "starting","version":VERSION,"guilds":len(bot.guilds),"latency_ms":round(bot.latency*1000)},status=200 if bot.is_ready() else 503)
async def health_server():
    app=web.Application()
    # The Discord bot is the current product. Keep only the machine health route
    # by default; the future Manifest website/workspace is a separate project.
    app.router.add_get("/health",health)
    if MANIFEST_PUBLIC_WEB_EXPERIMENTAL:
        app.router.add_get("/",home_page)
        app.router.add_get("/dashboard",dashboard_page)
        app.router.add_get("/security",security_page)
        app.router.add_get("/privacy",privacy_page)
        app.router.add_get("/terms",terms_page)
        app.router.add_get("/team",team_page)
        app.router.add_get("/status",status_page)
        app.router.add_get("/capabilities",capabilities_page)
    r=web.AppRunner(app);await r.setup();await web.TCPSite(r,"0.0.0.0",PORT).start();return r
async def main():
    r=await health_server()
    try:await bot.start(TOKEN,reconnect=True)
    finally:await r.cleanup()
if __name__=="__main__":asyncio.run(main())
